-- ============================================================
-- Seed de conteúdo editorial — Ervatório
-- ============================================================
-- GERADO POR scripts/dump-content.mjs. Não edite à mão: rode o
-- script de novo para atualizar.
--
-- Serve a dois propósitos:
--   1. Cópia do catálogo dentro do Git. Sem este arquivo, as
--      fichas, produtos, blends e vetores existiriam só dentro do
--      banco, sem como reconstruir se o projeto for perdido.
--   2. Semente de branches do Supabase — o CLI roda seed.sql
--      depois das migrations, então um staging nasce com o
--      conteúdo completo.
--
-- Cada bloco só insere se a tabela estiver vazia, então reaplicar
-- é seguro e não sobrescreve edição feita pelo admin.
--
-- Sem dado pessoal: a allowlist do script cobre só conteúdo
-- editorial. user_profiles, orders, newsletter_subscribers e
-- product_reviews ficam de fora por construção.
--
-- chazerias e admin_suppliers não estão aqui — já vivem em
-- migrations versionadas.
-- ============================================================

-- admin_herb_fichas: 110 linhas
DO $do$
BEGIN
IF (SELECT count(*) FROM public.admin_herb_fichas) > 0 THEN
  RAISE NOTICE 'admin_herb_fichas já populada — seed ignorado';
ELSE
  INSERT INTO public.admin_herb_fichas
  SELECT * FROM jsonb_populate_recordset(
    NULL::public.admin_herb_fichas,
    $seed$[{"id":"4f197e86-6290-4262-aa00-bbdd42a960fd","slug":"jabuticaba","herb_id":null,"herb_latin_name":"Plinia cauliflora","schema_version":"1.1","ficha":{"slug":"jabuticaba","cultura":{"brasil":"A jabuticaba é o fruto que mais representa o \"brasileiro que não se valoriza\" — um superalimento com antocianinas superiores ao mirtilo importado, vendido por R$ 10/kg em feiras, enquanto o mirtilo (blueberry) importado é vendido a R$ 50+/100g em mercados premium. O Ervatório pode e deve narrar essa injustiça de valorização.","historia":"A jabuticaba só existe no Brasil — e não existe fora dele. O fruto é tão perecível (fermenta em 3–4 dias após colhido) que nunca pôde ser exportado fresco para mercados distantes. Essa perecibilidade construiu uma identidade cultural absoluta: para comer jabuticaba, você precisa estar no Brasil, perto de uma jabuticabeira, no tempo certo. É o fruto da presença — do aqui e agora.  A jabuticabeira produz frutos diretamente no tronco e nos galhos grossos (caulifloria) — comportamento botânico raro que cria uma das imagens mais surrealistas do mundo vegetal: uma árvore coberta de uvas negras brotando direto da madeira, sem hastes nem cachos.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Hibisco · Açaí · Pitanga (blends roxos antioxidantes da Mata Atlântica)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A uva que nasce no tronco — fruto endêmico do Brasil com antocianinas superiores ao mirtilo, resveratrol documentado e uma das identidades gastronômicas mais singulares do mundo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutificação: setembro–outubro e fevereiro–março (duas safras)","status_anvisa":"Alimento. Potencial Novel Food para exportação UE em processo.","eixo_botanico_tpc":"Alimento funcional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Jabuticaba","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Jabuticaba · jaboticaba · jabuticabeira","Brazilian grape tree (inglês) · Jaboticaba (espanhol/francês)","Uso único no Brasil — sem equivalente cultural externo"],"parte_usada":"Fruto (polpa e casca); casca seca em infusão; casca em vinho/licor.","tipo_botanico":"Alimento funcional antioxidante / anti-inflamatório","nome_cientifico":"Plinia cauliflora (Mart.) Kausel (sin.: Myrciaria cauliflora)","familia_botanica":"Myrtaceae"},"caracterizacao":{"aroma":"Frutado-floral intenso, uva-jasmim, fermento suave.","notas":"","intensidade":"3/5 (fruto) — 2/5 (infusão de casca).","cor_da_infusao":"","bioma_de_origem":"Mata Atlântica — endêmica do Brasil; SP, MG, RJ, PR, MS, GO.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Plinia cauliflora (Mart.) Kausel (sin.: Myrciaria cauliflora)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antioxidante máximo (antocianinas superiores ao mirtilo em alguns estudos)","Anti-inflamatório","Cardioprotetor (resveratrol + antocianinas)","Antidiarreico (casca — taninos)","Hipoglicemiante leve","Antimicrobiano","Componentes ativos:","Contraindicações: Sem contraindicações relevantes. Casca em excesso: constipação (taninos)."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"ANTOCIANINAS (delfinidina-3-glucosídeo, cianidina-3-glucosídeo)","texto":"Altas na casca — Antioxidante, anti-inflamatório, cardioprotetor"},{"label":"RESVERATROL","texto":"Casca e sementes — Cardioprotetor, neuroprotetor, antienvelhecimento"},{"label":"ÁCIDO ELÁGICO","texto":"Presente — Antioxidante, antiproliferativo"},{"label":"TANINOS","texto":"Casca — Adstringente, antimicrobiano, antidiarreico"},{"label":"VITAMINA C","texto":"Alta — Antioxidante, imunidade"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"14fb7a9f-c3b8-4822-b673-0df48e573967","slug":"camu-camu","herb_id":null,"herb_latin_name":"Myrciaria dubia","schema_version":"1.1","ficha":{"slug":"camu-camu","cultura":{"brasil":"O camu-camu é o superfruto amazônico mais estudado internacionalmente depois do açaí — com enorme mercado no Japão (onde é usado como suplemento de vitamina C natural), Europa e EUA. O Japão importa a maior parte da produção peruana e brasileira como pó liofilizado para suplementos premium.  O paradoxo: o camu-camu cresce nos igapós do AM e AC, é colhido por populações ribeirinhas em canoas, e a maior parte do valor é capturada no Japão e na Europa — não nas comunidades de origem. O Ervatório pode construir uma narrativa de rastreabilidade e comércio justo em torno dessa cadeia.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A vitamina C da Amazônia — fruto com a maior concentração de vitamina C de qualquer alimento conhecido, suplantando a acerola, com evidências anti-inflamatórias e antidepressivas únicas.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutificação: novembro–março (AM)","status_anvisa":"Alimento. Pó liofilizado como suplemento — regulamentado.","eixo_botanico_tpc":"Alimento funcional amazônico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Camu-Camu","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Camu-camu · caçari · araca-d'água","Camu camu (inglês/universal) · Caçari (AM)"],"parte_usada":"Fruto (polpa e casca); pó liofilizado.","tipo_botanico":"Alimento funcional / suplemento vitamínico natural","nome_cientifico":"Myrciaria dubia (Kunth) McVaugh","familia_botanica":"Myrtaceae"},"caracterizacao":{"aroma":"Cítrico-frutado intenso, framboesa ácida, frutas vermelhas tropicais.","notas":"","intensidade":"5/5 para acidez — uso quase sempre misturado.","cor_da_infusao":"","bioma_de_origem":"Amazônia — margem de rios e igapós; AM, PA, AC, RO.","sabor_dominante":"Intensamente ácido — o mais ácido do catálogo. Cítrico extremo, fruta vermelha ácida, levemente adstringente. Difícil puro — misturado com mel ou suco, a acidez vira qualidade.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Myrciaria dubia (Kunth) McVaugh","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Vitamina C excepcional (até 3.000 mg/100g — 50x a laranja)","Antioxidante máximo","Anti-inflamatório (redução de PCR documentada em estudo japonês)","Antidepressivo (melhora de humor — estudo com inibição de MAO)","Imunomodulador","Cardioprotetor","Componentes ativos:","Contraindicações: Cálculo renal de oxalato — vitamina C em excesso aumenta oxalato urinário. Gestação: vitamina C natural em doses alimentares é segura."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"VITAMINA C (ácido ascórbico)","texto":"1.500–3.000 mg/100g (polpa fresca) — Antioxidante máximo, imunidade, colágeno"},{"label":"ANTOCIANINAS (delfinidina, cianidina)","texto":"Casca — Antioxidante, anti-inflamatório"},{"label":"ELLAGITANINOS","texto":"Presentes — Antioxidante, antiproliferativo"},{"label":"FLAVONÓIDES","texto":"Presentes — Anti-inflamatório, antioxidante"},{"label":"SERINA, VALINA (aminoácidos)","texto":"Presentes — Nutritivo"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"e4a39903-771a-4122-b171-c4fe531a056b","slug":"acafroa","herb_id":null,"herb_latin_name":"Carthamus tinctorius","schema_version":"1.1","ficha":{"slug":"acafroa","cultura":{"brasil":"A açafroa é a \"mentira nobre\" da culinária brasileira — o \"açafrão\" da paella nordestina, do arroz amarelo mineiro e das moquecas capixabas é quase sempre cártamo, não Crocus sativus. Essa substituição é praticada há séculos não por adulteração intencional, mas por adaptação culinária pragmática — o cártamo tem o visual do açafrão (cor amarela) por fração do custo. O Ervatório tem a missão de esclarecer, não condenar — o cártamo tem valor próprio que merece ser narrado honestamente.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O pseudoaçafrão universal — especiaria floral que substituiu o açafrão verdadeiro em culinários por séculos, com óleo de alto valor nutricional e ação anti-inflamatória crescentemente documentada.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Floração: verão","status_anvisa":"Uso alimentar. Óleo: amplamente comercializado.","eixo_botanico_tpc":"Alimento funcional / fitoterápico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Açafroa","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Açafroa · cártamo · açafrão-bastardo · falso-açafrão","Safflower (inglês) · Carthame (francês) · Saflor (alemão)","Kusumbha (sânscrito)"],"parte_usada":"Flores (pétalas secas — corante e especiaria); sementes (óleo).","tipo_botanico":"Especiaria aromática / óleo funcional / corante","nome_cientifico":"Carthamus tinctorius L.","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Floral-seco, feno, levemente aromático.","notas":"","intensidade":"2/5 — corante mais que sabor.","cor_da_infusao":"Amarelo intenso a laranja-avermelhado. #E89020 — corante natural intenso.","bioma_de_origem":"","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Carthamus tinctorius L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Corante natural (cartamina — laranja; safraflor amarelo)","Anti-inflamatório (flores e óleo)","Cardioprotetor (óleo — ácido linoleico)","Hipoglicemiante (estudos com extrato)","Emenagogo (flores — uso tradicional)","Componentes ativos (flores):","Contraindicações: Gestação — emenagogo. Alergia à Asteraceae."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"72bceda9-dd0e-4b7d-b73b-1844de50376f","slug":"flor-de-laranjeira","herb_id":null,"herb_latin_name":"Citrus aurantium","schema_version":"1.1","ficha":{"slug":"flor-de-laranjeira","cultura":{"brasil":"","historia":"A água de flor de laranjeira é o mais antigo perfume do mundo ocidental com uso medicinal documentado — produzida por destilação em países árabes desde o séc. X, usada em culinária, cosmética e medicina. No casamento europeu, a noiva usa flor de laranjeira como símbolo de pureza e fertilidade — tradição que remonta à Espanha moura.  Na culinária portuguesa e brasileira, a água de flor de laranjeira aromatiza rabanadas, biscoitos e licores — herança direta da influência árabe na culinária ibérica.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"2–4 g flores secas para 250 ml.","reinfusoes":"","combina_com":"Camomila · Melissa · Lavanda · Maracujá · Mel (blends florais do sono)","melhor_momento":"Noite (ansiolítico/sedativo) — ritual do sono.","tempo_de_infusao":"","temperatura_ideal":"80–85 °C (linalol muito volátil)."},"tagline":"O neroli da farmácia popular — a flor branca da laranja-amarga com o mais elegante dos aromas florais-cítricos e ação ansiolítica e sedativa documentada em múltiplos sistemas.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use para ansiedade e insônia.","status_fda":"","sazonalidade":"Floração: primavera (setembro–novembro no Brasil)","status_anvisa":"Uso reconhecido.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Flor de Laranjeira","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Flor de laranjeira · tília-de-laranjeira · água de flor de laranjeira","Orange blossom (inglês) · Fleur d'oranger (francês) · Orangenblüte (alemão)","Neroli (quando OE destilado por vapor) — nome vem da princesa italiana Anna Maria de La Trémoille, princesa de Nerola"],"parte_usada":"Flores secas (tília de laranjeira) — da laranja-amarga (C. aurantium), não da laranja-doce (C. sinensis).","tipo_botanico":"Fitoterápico ansiolítico / sedativo / aromático","nome_cientifico":"Citrus aurantium L. (laranja-amarga)","familia_botanica":"Rutaceae (família dos cítricos)"},"caracterizacao":{"aroma":"Neroli — floral-cítrico-amadeirado, o mais elegante do catálogo floral. Limoneno + linalol + antranilato de metila = perfume de luxo em flor.","notas":"","intensidade":"2/5 — suave e elegante.","cor_da_infusao":"Amarelo-pálido a dourado discreto. #F0E890","bioma_de_origem":"","sabor_dominante":"Floral-cítrico suave e elegante, levemente amargo-herbáceo, mel floral.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Citrus aurantium L. (laranja-amarga)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico suave (linalol — modulação GABAérgica)","Sedativo leve","Antiespasmódico","Cardioprotetor (redução de FC em estresse)","Antimicrobiano suave","Componentes ativos:","Contraindicações: Sem contraindicações relevantes em doses usuais. Gestação: uso moderado tolerado."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"LINALOL","texto":"Ansiolítico, sedativo (GABA), antimicrobiano"},{"label":"ANTRANILATO DE METILA","texto":"Aromático floral — neroli"},{"label":"LIMONENO","texto":"Antimicrobiano, antidepressivo leve"},{"label":"GERANIOL","texto":"Ansiolítico, antimicrobiano"},{"label":"FLAVONÓIDES (naringenina, hesperidina)","texto":"Anti-inflamatório, cardioprotetor"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"f745dcf8-53fb-4fee-a428-c4bc810c6439","slug":"tilia","herb_id":null,"herb_latin_name":"Tilia cordata","schema_version":"1.1","ficha":{"slug":"tilia","cultura":{"brasil":"A tília é praticamente desconhecida na medicina popular brasileira — chegou timidamente via lojas de produtos naturais importados e farmácias de manipulação. Tem potencial de crescimento no mercado de chás premium para sono, onde a diferenciação aromática (floral-mel) a distingue da valeriana (aroma desafiador) e da camomila (já massificada).","historia":"Os tilos são as árvores das praças e boulevards da Europa continental — em Paris, Berlim, Viena, Amsterdam. Sob os tilos, as comunidades europeias se reuniam para discutir assuntos públicos, negociar casamentos, celebrar festas. A tília era a árvore da comunidade por excelência na Alemanha medieval — a palavra alemã para praça central de vila era frequentemente \"Unter der Linde\" (embaixo do tilo).  O \"tilleul\" francês é a infusão noturna de referência da France inteira — mais consumida que qualquer outro chá calmante no país. Marcel Proust descreveu a madeleine mergulhada no tilleul como o portal de volta ao passado na abertura de \"Em Busca do Tempo Perdido\" — a infusão mais literária da história.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta, preferencialmente em bule com tampa dupla.","quantidade":"2–3 g flores e brácteas secas para 250 ml.","reinfusoes":"","combina_com":"Camomila · Melissa · Lavanda · Valeriana · Mel · Flor de laranjeira","melhor_momento":"Noite — ritual do sono europeu clássico.","tempo_de_infusao":"","temperatura_ideal":"80–85 °C (farnesol e linalol voláteis)."},"tagline":"A calmante dos boulevards — a flor dos tilos europeus com o perfume mais suave de qualquer infusão e ação sedativa gentil que a tradição europeia preserva há séculos nos chás noturnos.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use para ansiedade e insônia.","status_fda":"","sazonalidade":"Floração: junho–julho (Europa). Produto importado seco.","status_anvisa":"Uso reconhecido.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Tília","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Tília · tilo · tília-europeia","Linden / Lime tree (inglês) · Tilleul (francês) · Linde (alemão)","Linden tea — a tisana de referência da Europa continental para sono e ansiedade"],"parte_usada":"Flores e brácteas secas.","tipo_botanico":"Fitoterápico ansiolítico / sedativo / diaforético","nome_cientifico":"Tilia cordata Mill. (tília-de-folhas-pequenas) / T. platyphyllos Scop. (tília-de-folhas-grandes)","familia_botanica":"Malvaceae (antes Tiliaceae)"},"caracterizacao":{"aroma":"Floral-mel intenso, néctar de abelha, feno florido europeu. Das mais agradáveis do catálogo.","notas":"","intensidade":"1–2/5 — a infusão mais delicada entre os sedativos.","cor_da_infusao":"Amarelo-pálido a dourado-mel. #F0E070","bioma_de_origem":"","sabor_dominante":"Floral-mel delicado, levemente herbáceo, mucilaginoso suave, doce natural. O sabor mais gentil entre os sedativos do catálogo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Tilia cordata Mill. (tília-de-folhas-pequenas) / T. platyphyllos Scop. (tília-de-folhas-grandes)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico suave","Sedativo leve (indutor de sono)","Diaforético (estimula transpiração em estados febris)","Antiespasmódico","Demulcente (mucilagens)","Cardioprotetor (flavonóides — tiliroside)","Componentes ativos:","Contraindicações: Sem contraindicações relevantes em doses usuais. Uso excessivo prolongado: associado a cardiotoxicidade em relatos históricos não confirmados modernamente."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"FARNESOL","texto":"Sedativo, ansiolítico"},{"label":"LINALOL","texto":"Ansiolítico, sedativo"},{"label":"TILIROSIDE (flavonoide)","texto":"Cardioprotetor, anti-inflamatório"},{"label":"MUCILAGENS","texto":"Demulcente, expectorante suave"},{"label":"ÁCIDO CLOROGÊNICO","texto":"Antioxidante"},{"label":"P-CUMARINA","texto":"Diaforético"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"d6c22ccb-6ed5-4279-b522-d433af107c8b","slug":"manjericao","herb_id":null,"herb_latin_name":"Ocimum basilicum","schema_version":"1.1","ficha":{"slug":"manjericao","cultura":{"brasil":"","historia":"Basilikos em grego significa \"real\" ou \"do rei\" — o manjericão era planta de reis. Na Grécia antiga, era cultivado apenas em jardins reais. Na Índia, cada casa hindu tem uma planta sagrada de tulsi (O. tenuiflorum, parente próximo) — e o manjericão carrega essa aura sagrada por toda a tradição mediterrânea.  Em Itália, oferecer um ramo de manjericão a alguém era declaração de amor. Em Roma, a serva que colocava manjericão na janela sinalizava que estava disponível para um pretendente. A planta do amor, da realeza e da cozinha — tudo ao mesmo tempo.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A erva do amor mediterrâneo — aromático culinário universal com ação antimicrobiana potente, adaptogênica leve e perfil sensorial que é simultaneamente o mais famoso e o menos explorado medicinalmente do catálogo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Disponível o ano todo (cultivo perene tropical)","status_anvisa":"Uso alimentar.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Manjericão","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Manjericão · alfavaca · alfavaca-cravo","Basil (inglês) · Basilic (francês) · Basilikum (alemão)","Tulsi-não-sagrado (diferenciação popular do tulsi O. tenuiflorum)"],"parte_usada":"Folhas frescas ou secas; flores.","tipo_botanico":"Especiaria aromática / antimicrobiana / adaptogênica leve","nome_cientifico":"Ocimum basilicum L.","familia_botanica":"Lamiaceae"},"caracterizacao":{"aroma":"Linalol-floral + metilchavicol-anisado + eugenol-apimentado — aroma que evoca imediatamente Itália, Provence, cozinha de verão.","notas":"","intensidade":"3/5 — aromático presente.","cor_da_infusao":"Verde-pálido claro. #C8DC78","bioma_de_origem":"","sabor_dominante":"Aromático-floral-apimentado complexo, levemente anisado (metilchavicol), pimentado (eugenol), herbáceo fresco. Sabor que define a culinária mediterrânea e italiana.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Ocimum basilicum L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antimicrobiano potente (linalol + eugenol)","Antifúngico (Candida — eugenol)","Adaptogênico leve (OE — modulação de estresse)","Antioxidante","Anti-inflamatório","Carminativo","Antidepressivo leve (linalol)","Componentes ativos:","Contraindicações: Estragol (metilchavicol) — genotóxico em doses altas de OE (culinária: seguro). Gestação em doses de OE."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"Quimiotipo","texto":"Componente dominante — Perfil"},{"label":"Europeu (linalol)","texto":"Linalol (60%) — Floral, ansiolítico"},{"label":"Tropical (metilchavicol)","texto":"Metilchavicol (estragol) (80%) — Anisado, mais picante"},{"label":"Cravo (eugenol)","texto":"Eugenol (70%) — Apimentado, antimicrobiano forte"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"b0cf62ee-fcfe-4363-b108-bb3ec8e7783e","slug":"erva-de-santa-barbara","herb_id":null,"herb_latin_name":"Artemisia vulgaris","schema_version":"1.1","ficha":{"slug":"erva-de-santa-barbara","cultura":{"brasil":"","historia":"A artemísia é a planta dedicada à deusa Ártemis — deusa da lua, da caça e do parto. Na mitologia grega, Ártemis protegia as mulheres no trabalho de parto — e a artemísia era dada para facilitar o nascimento. A planta das mulheres por excelência da Europa antiga.  O maior feito farmacológico moderno ligado ao gênero Artemisia é a descoberta da artemisinina por Tu Youyou (Nobel de Medicina 2015) — isolada de A. annua (qinghao, espécie chinesa diferente da vulgaris). A artemisinina é o antipalúdico mais eficaz do mundo e salvou centenas de milhões de vidas. O prêmio Nobel foi para uma pesquisa baseada em textos de medicina tradicional chinesa do séc. IV d.C. — o caso mais eloquente de etnobotânica validada que a história científica registra.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"1–2 g/250 ml","reinfusoes":"","combina_com":"","melhor_momento":"Pré-menstrual (emenagogo) ou pós-refeições (digestivo).","tempo_de_infusao":"","temperatura_ideal":"85–90 °C | Tempo: 5 min (não mais — tujona aumenta) | Quantidade: 1–2 g/250 ml"},"tagline":"A mãe de todas as ervas — a artemísia europeia, planta das mulheres e das viagens, com a mais longa história de uso medicinal do mundo ocidental e princípios ativos que incluem a base da artemisinina, o maior avanço antipalúdico do século XX.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use para dismenorreia e dispepsia.","status_fda":"","sazonalidade":"Partes aéreas: pré-floração (verão)","status_anvisa":"Não monografado.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Erva-de-Santa-Bárbara","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Artemísia · losna-menor · erva-de-santa-bárbara · artemísia-comum","Mugwort (inglês) · Armoise (francês) · Beifuß (alemão)","DISTINÇÃO: A. vulgaris ≠ A. absinthium (losna — Ficha 18) ≠ A. annua (qinghao — artemisinina antipalúdica)"],"parte_usada":"Partes aéreas (antes da floração), secas.","tipo_botanico":"Fitoterápico emenagogo / digestivo amargo / anti-inflamatório","nome_cientifico":"Artemisia vulgaris L. (artemísia-comum)","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Herbáceo-camforáceo, artemísia típica, leve defumado.","notas":"","intensidade":"3/5 — medicinal.","cor_da_infusao":"Verde-amarelado a âmbar. #B8B048","bioma_de_origem":"","sabor_dominante":"Amargo-herbáceo moderado, levemente tujona, artemísia característico.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Artemisia vulgaris L. (artemísia-comum)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Emenagogo (regula ciclo menstrual)","Digestivo amargo","Antiparasitário leve","Diaforético","Moxabustão (uso externo em MTC — aquecimento de pontos de acupuntura)","⚠️ TUJONA — mesmos alertas da losna (Ficha 18): Doses baixas em infusão curta: seguras. OE interno: contraindicado.","Contraindicações: Gestação — contraindicada (emenagoga, possível abortiva). Epilepsia — tujona pró-convulsivante."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"07df721f-081f-4e05-a0d5-545c61a2dea1","slug":"camomila-romana","herb_id":null,"herb_latin_name":"Chamaemelum nobile","schema_version":"1.1","ficha":{"slug":"camomila-romana","cultura":{"brasil":"","historia":"A camomila-romana é a camomila dos jardins de ervas formais ingleses e franceses — cultivada em monastérios e castelos medievais como tapete aromático (as flores esmagadas sob os pés liberam o aroma). Nos jardins formais do Castelo de Sissinghurst e de Versailles, a camomila-romana forma \"tapetes\" históricos que perfumam os passeios.  Para o Ervatório, a distinção entre camomila-alemã (popular, acessível, bem documentada) e camomila-romana (premium, rara, mais aromática) é oportunidade de narrativa sobre qualidade e especificidade — duas plantas com o mesmo nome popular mas identidades distintas.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"1–2 g/250 ml","reinfusoes":"","combina_com":"Lavanda · Melissa · Mel · Flores de laranjeira (blend de sono premium)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":"85–90 °C | Tempo: 5–8 min coberto | Quantidade: 1–2 g/250 ml"},"tagline":"A prima nobre da camomila — mais intensa, mais densa em princípios ativos e mais rara que a camomila-alemã, com uso privilegiado em perfumaria de luxo e aromaterapia de alta precisão.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use.","status_fda":"","sazonalidade":"Floração: junho–agosto (Europa). Produto majoritariamente importado.","status_anvisa":"Uso reconhecido — distinção de Matricaria chamomilla feita na regulação.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Camomila-Romana","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Camomila-romana · camomila-inglesa · camomila-nobre","Roman chamomile (inglês) · Camomille romaine (francês) · Römische Kamille (alemão)","DISTINÇÃO ESSENCIAL: Chamaemelum nobile (camomila-romana) ≠ Matricaria chamomilla (camomila-alemã — Ficha 01). Ambas são \"camomila\" mas são espécies distintas com química diferente."],"parte_usada":"Flores secas.","tipo_botanico":"Fitoterápico ansiolítico / anti-inflamatório / aromático","nome_cientifico":"Chamaemelum nobile (L.) All. (sin.: Anthemis nobilis)","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Maçã verde mais intensa e quente que a alemã, floral-frutado profundo, éster-frutado característico (isobutirato de isobutila). Mais complexa e \"adulta\" que a camomila-alemã.","notas":"","intensidade":"3/5 — mais intensa que a camomila-alemã.","cor_da_infusao":"Amarelo-pálido a âmbar. #E8D068","bioma_de_origem":"","sabor_dominante":"Amargo-floral intenso, maçã verde mais pronunciada que a camomila-alemã, frutado-herbáceo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Chamaemelum nobile (L.) All. (sin.: Anthemis nobilis)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico (isobutirato de isobutila + ésteres aromáticos)","Anti-inflamatório (mais potente que a camomila-alemã em alguns estudos)","Antiespasmódico","Sedativo leve","Antifúngico","Componentes ativos:","Contraindicações: Alergia à família Asteraceae. Gestação em doses altas — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"ISOBUTIRATO DE ISOBUTILA","texto":"Aromático característico, ansiolítico"},{"label":"METIL-2-METILBUTIRATO","texto":"Aromático frutado"},{"label":"ALFA-BISABOLOL","texto":"Anti-inflamatório (mesma molécula da camomila-alemã)"},{"label":"ÁCIDO ANGÉLICO (ésteres)","texto":"Anti-inflamatório, antiespasmódico"},{"label":"CHAMAZULENO","texto":"Anti-inflamatório (menor concentração que na camomila-alemã)"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"bb23b2db-8135-4d22-8a08-d66cd328766e","slug":"verbena","herb_id":null,"herb_latin_name":"Verbena officinalis","schema_version":"1.1","ficha":{"slug":"verbena","cultura":{"brasil":"","historia":"A verbena foi planta sagrada dos druidas celtas e dos sacerdotes romanos — usada em purificações, juramentos e rituais de paz. Os romanos chamavam qualquer planta sagrada de herba sacra — e a verbena era a erba sacra por excelência. Enviar um ramo de verbena era sinal de aliança e boa fé entre grupos em conflito.  Os alquimistas medievais incluíam verbena em elixires de transmutação. John Gerard (séc. XVII) atribuiu-lhe poderes contra fantasmas e malefícios. Toda essa mitologia encobre uma planta com farmacologia real — os iridóides verbenalin e hastatoside têm ação neuroprotetora e anti-inflamatória documentada.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A erva sagrada dos druidas — tônico nervoso e anti-inflamatório europeu com história pré-cristã de uso ritual e ação farmacológica crescentemente confirmada para sistema nervoso e fígado.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use","status_fda":"","sazonalidade":"Partes aéreas: floração (verão)","status_anvisa":"Uso popular reconhecido","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Verbena","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Verbena · gervão-europeu · erva-sagrada","Vervain (inglês) · Verveine (francês — ATENÇÃO: \"verveine\" no comércio francês frequentemente = Lippia citriodora, verbena-limão, não V. officinalis) · Eisenkraut (alemão)"],"parte_usada":"Partes aéreas (folhas e flores), secas.","tipo_botanico":"Fitoterápico tônico nervoso / hepatoprotetor / anti-inflamatório","nome_cientifico":"Verbena officinalis L.","familia_botanica":"Verbenaceae"},"caracterizacao":{"aroma":"Herbáceo discreto, neutro.","notas":"","intensidade":"2/5 — suave.","cor_da_infusao":"Verde-amarelado. #C4BC50","bioma_de_origem":"","sabor_dominante":"Amargo-herbáceo moderado, levemente adstringente, terroso.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Verbena officinalis L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Tônico nervoso (neuroproteg — verbenalin)","Hepatoprotetor","Anti-inflamatório","Ansiolítico leve","Emenagogo","Galactogogo (estimula leite — uso popular europeu)","Componentes ativos:","Contraindicações: Gestação — emenagoga. Lactação: stimula leite (uso popular europeu para desmame inverso — aumentar lactação)."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"VERBENALIN (iridóide)","texto":"Tônico nervoso, anti-inflamatório, hepatoprotetor"},{"label":"HASTATOSIDE (iridóide)","texto":"Anti-inflamatório"},{"label":"ÁCIDO CAFEICO","texto":"Antioxidante, anti-inflamatório"},{"label":"FLAVONÓIDES (luteolina)","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ac7e3682-ba15-4425-9ded-ba8832a7f5aa","slug":"erva-principe","herb_id":null,"herb_latin_name":"Cymbopogon nardus","schema_version":"1.1","ficha":{"slug":"erva-principe","cultura":{"brasil":"A citronela é a planta repelente por excelência do Brasil tropical — cultivada em quintais, plantada em vasos nas janelas, queimada em velas aromáticas nas variedades comerciais. Com o avanço da dengue, zika e chikungunya, a citronela tornou-se tema de saúde pública, com pesquisas nacionais documentando sua eficácia como repelente natural de baixo custo para populações vulneráveis.  A centésima ficha do catálogo — fechando em uma gramínea humilde de quintal que protege corpos, calma nervos e perfuma ambientes — é um registro do princípio que o Ervatório sempre defendeu: a planta mais comum pode ter o valor mais profundo.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A citronela completa — a gramínea repelente que também é ansiolítica, antimicrobiana e aromatizante, com o perfil de uso mais multifuncional entre todas as gramíneas aromáticas do catálogo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Disponível o ano todo (tropical perene)","status_anvisa":"Uso tradicional reconhecido. OE em repelentes: regulamentado.","eixo_botanico_tpc":"Funcional global / tropical","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Erva-Príncipe","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Citronela · erva-príncipe · capim-citronela","Citronella grass (inglês) · Citronnelle (francês)","DISTINÇÃO: C. nardus (citronela de Ceilão — citronelal dominante) ≠ C. winterianus (citronela de Java — geraniol dominante) ≠ C. citratus (capim-limão — citral dominante, Ficha 59)"],"parte_usada":"Partes aéreas frescas ou secas; óleo essencial.","tipo_botanico":"Repelente natural / aromático / ansiolítico","nome_cientifico":"Cymbopogon nardus (L.) Rendle","familia_botanica":"Poaceae (gramíneas)"},"caracterizacao":{"aroma":"Citronelal dominante — cítrico-floral-terroso, levemente geraniol. O aroma que repele mosquitos.","notas":"","intensidade":"2/5 — aromático suave.","cor_da_infusao":"Verde-pálido a amarelado. #D8E070","bioma_de_origem":"","sabor_dominante":"Cítrico-limão com nota terrosa-defumada, mais \"capim\" que o capim-limão.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Cymbopogon nardus (L.) Rendle","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Repelente de insetos (citronelal — comprovado contra Aedes, Anopheles, Culex)","Ansiolítico leve (citronelal — modulação GABAérgica)","Antimicrobiano (citronelal + geraniol)","Antifúngico","Anti-inflamatório","Carminativo","Componentes ativos:","Contraindicações: OE tópico em crianças < 2 anos — usar produtos regulamentados específicos. Gestação: infusão moderada segura; OE — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"CITRONELAL","texto":"30–45% — Repelente, ansiolítico"},{"label":"GERANIOL","texto":"20–25% — Repelente, antimicrobiano"},{"label":"CITRONELOL","texto":"12–15% — Repelente, aromático"},{"label":"LIMONENO","texto":"Presente — Antimicrobiano"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"6ec74463-3028-4fbf-883f-105d91e15bf4","slug":"camomila","herb_id":null,"herb_latin_name":"Matricaria chamomilla L.","schema_version":"1.1","ficha":{"slug":"camomila","cultura":{"brasil":["No Brasil, a camomila é uma das ervas mais consumidas em xícara — provavelmente a mais vendida em sachê no varejo. O cultivo comercial está concentrado no Sul (Paraná e Rio Grande do Sul), onde comunidades de imigração europeia mantêm produção familiar com conhecimento herbalista transmitido por gerações.","Na medicina popular, a camomila é associada ao sono das crianças, à cólica do bebê, ao alívio da ansiedade leve — usos que coincidem com as indicações monografadas pela Farmacopeia. É raro ver, no Brasil, uma erva com tamanho alinhamento entre uso popular e evidência farmacológica.","A dimensão cultural-afetiva da camomila no Brasil é forte: associada a figuras maternas, ao cuidado, à infância. Em blends comerciais, raramente falta. No Ervatório, é a porta de entrada ideal para leitores leigos, pela aceitação sensorial quase universal."],"historia":["A camomila é uma das plantas medicinais mais antigas da farmacopeia ocidental. Os egípcios dedicavam a flor ao deus-sol Rá e usavam-na em rituais de cura e embalsamamento. Plínio, o Velho (séc. I), descreveu-a detalhadamente em sua Historia Naturalis, atribuindo o nome \"chamaemelon\" (maçã do chão) pelo aroma característico das flores esmagadas.","Durante toda a Idade Média, a camomila foi protagonista em jardins monásticos europeus. Na tradição anglo-saxã, era uma das \"nove ervas sagradas\" do poema medieval Lacnunga. Hildegarda de Bingen (séc. XII) recomendou-a para distúrbios digestivos e nervosos.","A ciência moderna incorporou a camomila no final do século XIX, com isolamento do alfa-bisabolol e do camazuleno. Monografias oficiais surgiram em todas as principais farmacopeias do século XX."],"cerimonial":"A camomila não tem cerimônia codificada única, mas atravessa rituais domésticos em todas as culturas em que a planta é usada: o \"cházinho antes de dormir\" da avó brasileira, o \"Kamillentee\" da mãe alemã que cura tudo, a manzanilla espanhola oferecida a crianças com dor de barriga. É a erva do cuidado cotidiano, invisível por ser ubíqua.","curiosidade":"A cor azul-cobalto intensa do óleo essencial de camomila é devida ao camazuleno — molécula que NÃO existe na flor fresca. Ela só surge durante a destilação ou infusão quente, por transformação térmica da matricina. A flor branco-amarela produz um pigmento azul que jamais viu a luz na própria planta. É uma alquimia química real, não metáfora."},"preparo":{"metodo":"Infusão simples, coberta.","quantidade":"1 colher de chá (~1,5 g) de flores secas para 150 ml. A Farmacopeia Brasileira indica 3 g para uso externo.","reinfusoes":"1–2 reinfusões possíveis, cada uma mais suave.","combina_com":"Melissa (clássico calmante) · Lavanda · Erva-doce · Capim-limão · Mel · Maracujá","melhor_momento":"Final de tarde, noite (30–60 minutos antes de dormir). Compatível com uso diurno leve também.","tempo_de_infusao":"5–10 minutos coberto (cobrir é essencial para reter óleos voláteis).","temperatura_ideal":"90–95 °C. Suporta ebulição mas 90 °C preserva óleos essenciais."},"tagline":"A margarida ansiolítica mais estudada do mundo — Matricária na ANVISA, Chamomilla no EMA, a mesma flor em todas as farmacopeias.","receitas":[{"nome":"Infusão do Sono Pampeano","slug":"infusao-do-sono-pampeano","proposito":null},{"nome":"Garganta-Boa (Bochecho)","slug":"garganta-boa-bochecho","proposito":null},{"nome":"Infusão da Cólica Menstrual","slug":"infusao-da-colica-menstrual","proposito":null},{"nome":"Gastrite Acalmada","slug":"gastrite-acalmada","proposito":null},{"nome":"Mente Serena","slug":"mente-serena","proposito":null},{"nome":"Calmante Infantil (6 meses+)","slug":"calmante-infantil-6-meses","proposito":null}],"destaques":[{"label":"Eixo botânico","texto":"Phyto-ANVISA + Funcional global"},{"label":"Tipo","texto":"Infusão herbal monografada"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Monografia HMPC publicada (well-established use)"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-15","revisor_tecnico":"A designar","revisor_cultural":"A designar","status_editorial":"Publicado (ficha-piloto Fase C1)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Monografia HMPC publicada. Categoria \"well-established use\" para dispepsia funcional e distúrbios de sono leve. \"Traditional use\" para afecções da mucosa oral.","status_fda":"GRAS para uso alimentar.","sazonalidade":"Floração entre outubro e janeiro no Hemisfério Sul. Colheita de capítulos completamente abertos, pela manhã.","status_anvisa":"Monografia oficial no Formulário de Fitoterápicos (Anvisa, 2011). Indicações: ansiolítico e sedativo leve (uso interno); anti-inflamatório em afecções da cavidade oral (uso externo).","eixo_botanico_tpc":"Phyto-ANVISA + Funcional global","produtor_parceiro":"A definir — priorizar pequenas cooperativas familiares do Sul brasileiro com certificação orgânica.","status_japao_china":"Uso alimentar e fitoterápico permitido.","certificacao_organica":"Ampla oferta — no Brasil, produção orgânica no Sul (RS, SC, PR); internacional, Egito e Alemanha são fornecedores principais."},"marketplace":{"formatos":"Flores secas inteiras (preferível — preserva aromáticos), flores partidas, sachê, extrato padronizado.","fornecedores":"Curadoria dupla: produção brasileira familiar + importação de terroirs europeus (Egito, Alemanha) para comparação sensorial.","faixa_de_preco":"Flores secas convencional: R$ 30–60/100 g. Orgânica premium: R$ 80–150/100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Camomila","usos_topicos":{"evidencia":"Moderada para uso antisséptico em mucosa oral e cicatrizante de pele; forte para aplicação em cólica de lactentes.","aplicacoes":[{"texto":"Infusão forte (2 colheres de chá para 150 ml), morna, bochecho 30 s após escovação, 3 vezes ao dia. Anti-inflamatório de mucosa oral com boa evidência clínica — usado inclusive em protocolos de mucosite induzida por quimioterapia.","titulo":"Bochecho para gengivite e mucosite oral"},{"texto":"Infusão forte resfriada, gaze embebida, 15 minutos na área afetada 2x ao dia. Ação anti-inflamatória e cicatrizante do alfa-bisabolol e do óxido de bisabolol. Evidência moderada.","titulo":"Compressa para pele irritada, dermatite leve, queimaduras de sol"},{"texto":"Dois punhados de flores secas em infusão forte adicionada à banheira morna. Uso tradicional europeu e brasileiro.","titulo":"Banho aromático para bebês"},{"texto":"Infusão muito fraca e extremamente bem filtrada, resfriada. Aplicada em gaze estéril sobre olhos fechados por 10 min. CUIDADO com contaminação — muitos profissionais desaconselham por risco de infecção secundária.","titulo":"Compressa ocular para conjuntivite leve"},{"texto":"Flores secas em água fervente, toalha sobre a cabeça, 5 min. Evidência tradicional para rinite alérgica leve.","titulo":"Inalação de vapor para congestão nasal"}],"contraindicacoes":"Uso tópico amplamente seguro. Principal contraindicação: alergia à família Asteraceae (5–10% da população sensível)."},"docx_filename":"Ficha_Camomila_v11.docx","identificacao":{"slug_url":"camomila","sinonimos":["Camomila-alemã · camomila-comum · macela-galega (uso tradicional português)","Chamomile (inglês) · Matricaire (francês) · Manzanilla (espanhol)","ATENÇÃO: não confundir com camomila-romana (Chamaemelum nobile), espécie distinta com usos parecidos mas química diferente"],"parte_usada":"Inflorescências secas (capítulos florais), colhidas em pleno florescimento.","nome_popular":"Camomila","tipo_botanico":"Infusão herbal monografada","nome_cientifico":"Matricaria chamomilla L. (sinônimo aceito: Matricaria recutita L.)","familia_botanica":"Asteraceae (família do girassol, alcachofra, dente-de-leão)"},"caracterizacao":{"aroma":"Maçã verde madura (daí o nome grego \"kamai melon\" = \"maçã do chão\"), feno doce, flor seca.","notas":"Cabeça: floral doce-maçã · Corpo: herbáceo suave · Fundo: leve amargor breve","intensidade":"2/5 — uma das infusões mais suaves do catálogo, ideal para crianças e sensíveis.","cor_da_infusao":"Amarelo-ouro pálido a âmbar claro. #E0CF7A","bioma_de_origem":"Europeu temperado. Nativa do sul e leste da Europa, naturalizada globalmente em climas temperados.","sabor_dominante":"Doce-floral suave com leve amargor herbáceo, nota de maçã verde no fundo. Perfil amável e de aceitação universal.","distribuicao_geografica":["Cultivo comercial em todo o mundo temperado e subtropical de altitude.","Principais produtores mundiais: Egito, Alemanha, Hungria, Argentina.","No Brasil: cultivo comercial concentrado no Rio Grande do Sul (Mandirituba, Palotina) e Santa Catarina. Produção familiar em Minas Gerais e São Paulo."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Matricaria chamomilla L.","perfil_sensorial":{"tatil":"Corpo muito leve, quase etéreo. Persistência baixa. É a infusão-silêncio: chega, se dissolve, não deixa memória sensorial pronunciada. Essa é exatamente sua virtude clínica — não sobrecarrega sistema sensorial de quem busca descanso.","gustativo":[{"dimensao":"Doce","observacao":"Presente e caracteristicamente suave; lembra maçã verde","intensidade":"2/3"},{"dimensao":"Amargo","observacao":"Levíssimo, no final","intensidade":"1/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Muito baixa","molecula":"Taninos em quantidade mínima","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: floral-frutal com fundo herbáceo suave","descricao_integrada":"A camomila é o arquétipo da infusão que faz silêncio sensorial. Nenhum receptor trigeminal é ativado. O paladar registra apenas uma doçura gentil e um amargor quase imperceptível. O olfato traz maçã verde e feno — descritores que a memória coletiva associa instintivamente a \"descanso\". Essa ausência de agressão é o que torna a camomila clinicamente eficaz: ela não exige do sistema nervoso, ela relaxa. A apigenina, sua molécula-estrela, cruza a barreira hematoencefálica e se liga a receptores GABA-A — os mesmos dos ansiolíticos farmacêuticos — mas com afinidade muito menor. O resultado é um \"acalmar\" sem \"desligar\". É a única erva do catálogo em que o perfil sensorial e o perfil farmacológico convergem perfeitamente: ambos dizem a mesma coisa em linguagens diferentes.","olfativo_descritores":["Maçã verde madura","Feno doce","Flor seca ao sol","Leve nuance mel cru","Fundo herbáceo pálido"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — monografia oficial de Matricaria chamomilla","EMA/HMPC — Community herbal monograph on Matricaria recutita L., flos","Amsterdam et al. — A randomized, double-blind, placebo-controlled trial of oral Matricaria recutita (chamomile) extract therapy for generalized anxiety disorder (J Clin Psychopharmacol, 2009)","Mars, Brigitte — Healing Herbal Teas (Basic Health, 2006)","Gaylard, Linda — The Tea Book (DK, 2015)"],"evidencia":[{"evidencia":"Moderada","indicacao":"Ansiedade leve a moderada","populacao":"Adultos"},{"evidencia":"Moderada-forte","indicacao":"Cólica de lactentes","populacao":"Lactentes sob orientação"},{"evidencia":"Moderada","indicacao":"Insônia leve","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Antiespasmódico digestivo","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Mucosite oral (bochecho)","populacao":"Pacientes oncológicos"}],"interacoes":[{"label":"Sedativos e benzodiazepínicos","texto":"potencialização leve por ação GABAérgica"},{"label":"Varfarina","texto":"interação teórica leve — monitorar em uso regular"},{"label":"Ciclosporina","texto":"cautela — citocromo P450"}],"dose_maxima":"2–4 xícaras/dia é considerado seguro para adultos. Em lactentes, apenas sob orientação pediátrica, em doses muito diluídas.","alerta_critico":null,"acoes_principais":["Ansiolítico e sedativo leve","Antiespasmódico digestivo","Anti-inflamatório (uso interno e tópico)","Carminativo","Cicatrizante cutâneo","Antimicrobiano leve","Indutor suave de sono"],"contraindicacoes":["Alergia conhecida à família Asteraceae","Em uso concomitante com sedativos fortes (efeito aditivo)","Gestantes e lactantes: uso moderado em infusão é tolerado; evitar doses altas de extratos concentrados"],"efeitos_adversos":"Em doses usuais: raros. Em alérgicos à Asteraceae: prurido, urticária, broncoespasmo em sensíveis.","componentes_ativos":[{"label":"Alfa-bisabolol","texto":"Sesquiterpeno — principal agente anti-inflamatório e antisséptico"},{"label":"Óxido de bisabolol A e B","texto":"Anti-inflamatórios secundários"},{"label":"Camazuleno","texto":"Pigmento azul intenso — surge apenas no processamento térmico. Anti-inflamatório potente."},{"label":"Apigenina","texto":"Flavonoide com afinidade por receptores GABA-A — responsável pela ação ansiolítica"},{"label":"Apigenina-7-glicosídeo","texto":"Forma mais abundante no capítulo floral"},{"label":"Matricina","texto":"Precursora do camazuleno"},{"label":"Quercetina, luteolina","texto":"Antioxidantes adicionais"},{"label":"Mucilagens","texto":"Efeito demulcente na mucosa gástrica"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"5bde150b-f1b6-4d14-b847-c13da9d3f930","slug":"cha-verde-matcha","herb_id":null,"herb_latin_name":"Camellia sinensis (L.) Kuntze","schema_version":"1.1","ficha":{"slug":"cha-verde-matcha","cultura":{"brasil":["O Brasil tem uma história pouco conhecida de cultivo de chá verde. Em 1812, imigrantes chineses foram trazidos para introduzir o cultivo no Rio de Janeiro — experiência que fracassou.","O cultivo se consolida em 1930, quando Okuhara Katsuzo, imigrante japonês, inicia a produção de chá verde no Vale do Ribeira (SP), em Registro. A comunidade japonesa da região estabelece fazendas familiares que produzem Sencha, Bancha e outras variedades até hoje — atravessando quatro gerações.","A produção brasileira é pequena (dezenas de toneladas/ano) comparada à China (mais de 2 milhões) ou ao Japão (90 mil). Mas é a única produção comercial estável de Camellia sinensis no Hemisfério Sul ocidental, e representa um patrimônio técnico-cultural importante."],"historia":["A lenda chinesa atribui a descoberta do chá ao imperador Shennong em 2.737 a.C. A narrativa é apócrifa, mas marca a antiguidade: o chá como bebida cultivada está na China desde pelo menos o primeiro milênio a.C.","Na dinastia Tang (618–907), Lu Yu escreve o Cha Jing, primeiro grande manual da cultura do chá. Na dinastia Song (960–1279), o chá em pó (precursor do Matcha) domina. Com a dinastia Ming (1368–1644), volta-se para a folha inteira.","O chá chega ao Japão no século IX, trazido por monges budistas. Eisai, monge zen do período Kamakura (XII–XIII), estabelece o cultivo japonês sério — escreve o Kissa Yōjōki (1211), associando chá verde, saúde e prática zen. Ali nasce a tradição que culminará no Chanoyu."],"cerimonial":"Chanoyu (\"água quente para chá\") é a cerimônia meditativa japonesa centrada no Matcha. Refinado por Sen no Rikyū no século XVI, codifica quatro princípios: wa (harmonia), kei (respeito), sei (pureza), jaku (tranquilidade). Chakai: encontro informal com Usucha. Chaji: cerimônia formal de 4 horas com Koicha e refeição kaiseki. No lado chinês, o Gongfu Cha usa folhas inteiras em infusões curtas no bule yixing, com foco na evolução do sabor ao longo das infusões.","curiosidade":"Os samurais medievais bebiam Matcha antes de batalha — não por adrenalina, mas pelo contrário. A combinação de cafeína + L-teanina produz um estado neurológico raro: foco relaxado. Cafeína eleva o alerta; L-teanina produz ondas cerebrais alfa. O resultado é atenção aguda sem ansiedade — exatamente o estado desejado por quem está prestes a tomar decisões letais e precisas. A neurociência contemporânea confirma o que o Zen japonês sabia há 800 anos."},"preparo":{"metodo":"Infusão curta, estilos diferentes (japonês em kyusu; chinês em gaibei ou copo alto)","quantidade":"1,5 colher de chá (~3 g) para 200 ml","reinfusoes":"Sim, parte essencial. 2ª infusão: 30 s. 3ª: 1 min. Total 3–4 reinfusões.","combina_com":"Normalmente solo. Em blend: jasmim (clássico chinês), casca de laranja leve.","melhor_momento":"Manhã até meio da tarde. Evitar após 16h.","tempo_de_infusao":"1–2 minutos (Sencha); 2–3 minutos (Gyokuro).","temperatura_ideal":"70–75 °C (Sencha). Gyokuro: 50–60 °C. Jamais ebulição."},"tagline":"O único chá verdadeiro — da dinastia Tang ao Vale do Ribeira brasileiro, do Chanoyu zen ao foco relaxado dos samurais.","receitas":[{"nome":"Antioxidante do Fim de Tarde","slug":"antioxidante-do-fim-de-tarde","proposito":null}],"destaques":[{"label":"Eixo botânico","texto":"Funcional global (principal) · Sensorial"},{"label":"Tipo","texto":"Chá verdadeiro — único tipo com direito à designação \"chá\""},{"label":"Status EMA","texto":"Monografia HMPC publicada (traditional use)"},{"label":"Recorte Brasil","texto":"Vale do Ribeira (SP) — produção japonesa desde 1930 · ausente do Gaylard"}],"metadados":{"nota":"Pode ser desmembrada em duas (Chá Verde + Matcha) na Fase C3.","autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar — familiaridade em polifenóis e biodisponibilidade","revisor_cultural":"Sugerido — tea sommelier STI ou consultor da comunidade japonesa do Vale do Ribeira","status_editorial":"Publicado (ficha-piloto Fase C1)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Monografia HMPC publicada. \"Traditional use\" para fadiga temporária.","status_fda":"GRAS. Extratos têm monitoramento hepático por casos de hepatotoxicidade de EGCG isolado em alta dose.","sazonalidade":["Japão: 1ª colheita (shincha) abril–maio. 2ª (nibancha) jun–jul. 3ª (sanbancha) setembro.","Brasil (Vale do Ribeira): colheita principal set–dez, pico out–nov.","Matcha: apenas 1ª colheita, sombreada 2–3 semanas."],"status_anvisa":"Não consta na Farmacopeia Brasileira como monografia fitoterápica específica; é alimento consolidado. Extratos concentrados exigem registro.","eixo_botanico_tpc":"Funcional global (principal) · Sensorial","produtor_parceiro":"A definir — priorizar produtores brasileiros do Vale do Ribeira.","status_japao_china":"Pharmacopoeia oficial. Alimento cotidiano.","certificacao_organica":["Ampla oferta internacional e brasileira.","Vale do Ribeira (SP): Registro, Juquiá, Pariquera-Açu.","Japão: Uji, Shizuoka, Kagoshima. China: Zhejiang."]},"marketplace":{"formatos":"Folha inteira a granel, sachê em nitrogênio, Matcha em lata metálica opaca (obrigatório), Matcha em stick.","fornecedores":"Oportunidade editorial: priorizar produtores brasileiros do Vale do Ribeira.","faixa_de_preco":["Sencha comum: R$ 40–80/100 g","Gyokuro ou Long Jing premium: R$ 150–400/100 g","Matcha culinário: R$ 60–120/30 g","Matcha cerimonial (Usucha): R$ 150–400/30 g","Matcha cerimonial premium (Koicha): R$ 500–1500/30 g"],"disponivel_a_venda":"A definir"},"nome_popular":"Chá Verde (Matcha)","usos_topicos":{"evidencia":"Moderada para ação antioxidante e anti-inflamatória dermatológica; forte para catequinas in vitro sobre pele.","aplicacoes":[{"texto":"Infusão padrão esfriada, aplicada com algodão. Rico em EGCG.","titulo":"Tônico facial de chá verde frio"},{"texto":"Dois sachês usados resfriados, 10 min. Cafeína vasoconstritora + taninos + antioxidantes.","titulo":"Compressa fria para olhos cansados"},{"texto":"Pó culinário + mel ou iogurte, 10 min.","titulo":"Máscara facial de Matcha"},{"texto":"Infusão fria, 30 s. EGCG contra S. mutans.","titulo":"Bochecho de chá verde para higiene oral"}],"contraindicacoes":"Uso tópico amplamente seguro. Pele muito sensível ou rosácea: testar em área pequena."},"docx_filename":"Ficha_Cha_Verde_Matcha_v11.docx","identificacao":{"slug_url":"cha-verde","sinonimos":["Lǜ chá (mandarim) · Ryokucha (japonês) · Nokcha (coreano)","Variedades: Matcha · Sencha · Gyokuro · Bancha · Hojicha · Genmaicha","Long Jing / Dragon Well · Bi Luo Chun · Anji Bai Cha"],"parte_usada":"Folhas jovens e brotos. Matcha usa folhas sombreadas (tencha), moídas em pó.","nome_popular":"Chá verde (com menção especial ao Matcha)","tipo_botanico":"Chá verdadeiro — único tipo com direito à designação \"chá\"","nome_cientifico":["Camellia sinensis (L.) Kuntze","var. sinensis (arbusto pequeno, folha miúda, climas temperados)","var. assamica (arbusto maior, folha larga, tropical)"],"familia_botanica":"Theaceae (família das camélias)"},"caracterizacao":{"aroma":"Grama recém-cortada, algas marinhas (Japão), castanhas torradas (China), manteiga derretida, ervilha fresca.","notas":"Cabeça: vegetal fresco · Corpo: umami, castanha · Fundo: doçura persistente","intensidade":"3/5 (folha); 4/5 (Matcha)","cor_da_infusao":"Verde-amarelado pálido a verde-amarelo vivo. Long Jing #D9DC8A · Gyokuro #B8CE5E · Matcha #8FCC3D","bioma_de_origem":"Asiático temperado a subtropical. Ladeiras montanhosas entre 400 e 2.450 m.","sabor_dominante":"Vegetal-herbáceo fresco, com camadas de doçura sutil, umami, adstringência moderada. Long Jing chinês = \"castanhas, arroz tostado\"; Gyokuro japonês = \"algas, umami oceânico\"; Sencha = \"folha verde fresca\".","distribuicao_geografica":["Origem no sudoeste da China (Yunnan), ~4.000 anos atrás.","Principais produtores: China, Japão, Taiwan, Coreia do Sul, Vietnã, Sri Lanka.","No Brasil: produção pequena no Vale do Ribeira (SP), famílias japonesas desde 1930. Registro é principal cidade produtora."]},"preparo_ritual":{"texto":"Matcha: peneirar 1/2 a 1 colher de chá na tigela (chawan), aquecer 60–80 ml a 70–75 °C, formar pasta com chasen (batedor de bambu), acrescentar resto, bater em M ou W até espuma fina (15–30 s). Beber em 2–3 goles. Kouridashi: folha inteira em jarra com água fria a 5–10 °C por 4–6 h na geladeira. Rende bebida umami intensa, quase sem amargor.","titulo":"Preparo cerimonial · Matcha (Usucha) e Kouridashi"},"schema_version":"1.1","nome_cientifico":"Camellia sinensis (L.) Kuntze","perfil_sensorial":{"tatil":"Corpo leve, textura sedosa em chás de alta qualidade. No Matcha: pastosa, aveludada, quase cremosa pela suspensão de micropartículas de folha moída.","gustativo":[{"dimensao":"Umami","observacao":"Estruturante; intensifica em Gyokuro e Matcha","intensidade":"2/3"},{"dimensao":"Amargo","observacao":"Presente; cresce rapidamente se superaquecido","intensidade":"2/3"},{"dimensao":"Doce","observacao":"Sutil, final de boca; indica qualidade","intensidade":"1/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Baixa","molecula":"Traços de compostos voláteis; efeito muito suave","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Média","molecula":"Catequinas (EGCG dominante) — \"seca e breve\"","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: vegetal-marinho (Japão) ou vegetal-torrado (China)","descricao_integrada":"O chá verde é o contrário da camomila: onde a camomila faz silêncio sensorial, o chá verde faz comunicação completa entre os três sistemas. O umami registra primeiro, como presença oceânica. A doçura aparece em seguida, como confirmação. A adstringência chega por último. No Matcha, a textura multiplica tudo — o pó em suspensão cobre a boca como um véu verde, e a L-teanina começa a agir antes mesmo da cafeína, produzindo o estado paradoxal dos monges zen: alerta tranquilo. Foi esse estado que fez os samurais medievais beberem Matcha antes da batalha.","olfativo_descritores":["Algas marinhas (nori, wakame) — estilo japonês","Grama recém-cortada","Ervilha fresca, vagem nova","Castanhas torradas — estilo chinês","Arroz basmati recém-cozido","Manteiga derretida (Gyokuro e Matcha premium)"]},"acoes_e_seguranca":{"fontes":["EMA/HMPC — Community herbal monograph on Camellia sinensis (L.) Kuntze, non-fermentatum folium","Cochrane Database — Green tea for the prevention of cancer (Boehm et al., 2009)","Weiss & Anderton — Green tea EGCG and anti-inflammatory effects (Crit Rev Food Sci Nutr, 2019)","Gaylard, Linda — The Tea Book (DK, 2015)","Lovelace, Virginia Utermohlen — Three Basic Teas (2017)","Mars, Brigitte — Healing Herbal Teas (Basic Health, 2006)"],"evidencia":[{"evidencia":"Forte lab / Moderada clínica","indicacao":"Ação antioxidante sistêmica","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Redução modesta LDL/triglicérides","populacao":"Dislipidemia leve"},{"evidencia":"Moderada","indicacao":"Coadjuvante termogênico","populacao":"Adultos"},{"evidencia":"Moderada observacional","indicacao":"Redução risco cardiovascular","populacao":"Alto consumo"},{"evidencia":"Moderada","indicacao":"Ação flora oral (bochecho)","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Efeito cognitivo (alerta + calma)","populacao":"Adultos"},{"evidencia":"Preliminar/controversa","indicacao":"Prevenção de cânceres","populacao":"Inconclusivo"}],"interacoes":[{"label":"Ferro oral","texto":"taninos reduzem absorção"},{"label":"Varfarina e outros anticoagulantes","texto":"monitorar INR"},{"label":"Estimulantes","texto":"aditivos"},{"label":"Lítio, IMAO","texto":"cautela"}],"dose_maxima":"Chá verde em folha: 3–5 xícaras/dia (150–250 mg cafeína total). Matcha: 1–2 porções/dia (2–4 g de pó), 120–160 mg cafeína.","alerta_critico":null,"acoes_principais":["Antioxidante de alto potencial — catequinas (EGCG, EGC, ECG, EC)","Termogênico leve — sinergia cafeína + EGCG","Estimulante cognitivo com efeito calmante paradoxal — cafeína + L-teanina","Hepatoprotetor e coadjuvante em dislipidemias leves","Cardioprotetor (observacional)","Antimicrobiano sobre flora oral","Modulador de glicemia pós-prandial leve"],"contraindicacoes":["Anemia ferropriva (polifenóis reduzem absorção de ferro — evitar com refeições)","Ansiedade severa, insônia crônica, hipertireoidismo (cafeína)","Gestação (limitar consumo; EGCG+cafeína alta dose podem afetar ácido fólico)","Crianças pequenas sem orientação","Em uso de anticoagulantes (vitamina K)","Doença hepática ativa (suplementos de EGCG; chá em bebida é seguro)"],"efeitos_adversos":"Em doses usuais (1–5 xícaras/dia): raros. Em excesso: insônia, irritabilidade, azia, dor de cabeça, constipação.","componentes_ativos":[{"label":"EGCG (epigalocatequina-galato)","texto":"Principal polifenol. Maior no Matcha. Potente antioxidante com atividade antitumoral em modelos experimentais."},{"label":"Cafeína","texto":"25–50 mg/xícara de chá verde; 60–80 mg/porção de Matcha"},{"label":"L-teanina","texto":"Aminoácido exclusivo do chá. Produz ondas alfa (alerta relaxado). Alta em Matcha e Gyokuro."},{"label":"Teobromina, teofilina","texto":"Estimulantes menores"},{"label":"Catequinas adicionais","texto":"EC, ECG, EGC"},{"label":"Flavonoides","texto":"Quercetina, kaempferol"},{"label":"Minerais","texto":"Manganês, potássio, zinco"},{"label":"Fluoreto","texto":"Naturalmente presente em teores relevantes"},{"label":"Vitamina C","texto":"Preservada nas folhas sombreadas (Matcha)"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"f6feca0b-e22b-4467-ab9f-ae23bdfd99d0","slug":"copaiba","herb_id":null,"herb_latin_name":"Copaifera reticulata","schema_version":"1.1","ficha":{"slug":"copaiba","cultura":{"brasil":"A copaíba é a erva amazônica mais estudada pelas universidades brasileiras para desenvolvimento de medicamentos fitoterápicos. UFAM, UFPA, UFRN e USP publicam regularmente estudos com formações galênicas inovadoras — géis dentários, nanoemulsões, óvulos vaginais. É também um dos produtos da sociobioeconomia amazônica com maior potencial de exportação regulamentada para mercados europeu e asiático.","historia":"O padre Cristóbal de Acuña (1641) foi o primeiro europeu a documentar sistematicamente o uso do óleo de copaíba pelos povos amazônicos — descreveu-o como \"bálsamo que cura todas as feridas sem deixar cicatriz\". Durante os séculos XVII-XIX, o óleo de copaíba foi exportado em larga escala para a Europa, onde era usado em farmácias como antigonoréico e cicatrizante — aparece nas farmacopeias britânica, francesa e alemã do século XIX.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção (casca); diluição em líquido (óleo-resina).","quantidade":"10 g de casca seca para 500 ml. O óleo-resina: 2–5 ml em água morna ou mel (uso oral clínico).","reinfusoes":"","combina_com":"Mel (para palatabilidade) · Andiroba · Sangue-de-dragão (uso tópico combinado)","melhor_momento":"Uso medicinal prescrito — manhã em jejum ou conforme orientação.","tempo_de_infusao":"","temperatura_ideal":"Decocção — água em ebulição suave (95–98 °C)."},"tagline":"A resina sagrada da floresta — anti-inflamatório natural com milênios de uso indígena e crescente validação científica global.","receitas":[],"regulacao":{"status_ema":"Não monografado. Uso cosmético regulamentado na UE.","status_fda":"","sazonalidade":"Extração de resina: ano todo (melhor no período seco, junho–outubro)","status_anvisa":"Memento Fitoterápico — uso tradicional reconhecido. Monografia em elaboração.","eixo_botanico_tpc":"Fitoterápico tradicional amazônico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Copaíba","usos_topicos":{"evidencia":"","aplicacoes":["Pomada cicatrizante: Óleo-resina diluído em vaselina ou manteiga de cupuaçu — aplicado sobre feridas limpas, queimaduras de 1° grau, úlceras varicosas. Mecanismo: beta-cariofileno inibe COX-2 localmente.","Tratamento de psoríase e dermatites: Uso tópico de óleo diluído (5–10% em óleo carreador) — evidência moderada em estudos piloto. Uso tradicional amazônico amplamente documentado.","Repelente natural: Combinação com andiroba e citronela — DEET natural com menor toxicidade. Uso disseminado na Amazônia.","Antifúngico (candidíase vulvovaginal): Óvulos e géis com extrato de copaíba — estudos clínicos brasileiros com resultados promissores (UFRN, UFAM)."],"contraindicacoes":""},"identificacao":{"sinonimos":["Copaíba · copaibeira · pau-d'óleo · marimari (AM)","Copaib balsam (inglês) · baume de copahu (francês)","Mais de 70 espécies no gênero; 16 no Brasil — química variável por espécie"],"parte_usada":"Óleo-resina extraído do tronco por incisão (uso principal); casca em decocção (uso popular); folhas em infusão (uso secundário).","tipo_botanico":"Óleo-resina medicinal; infusão de casca (uso popular)","nome_cientifico":"Copaifera reticulata Ducke (C. langsdorffii Desf. — espécie de cerrado e transição)","familia_botanica":"Fabaceae / Leguminosae (família do feijão, da acácia, do jatobá)"},"caracterizacao":{"aroma":"Bálsamo de resina quente, amadeirado profundo, pinho tropical, fundo de pimenta-do-reino.","notas":"","intensidade":"5/5 — presença esmagadora. Uso medicinal, não de prazer sensorial.","cor_da_infusao":"","bioma_de_origem":"Amazônia (espécies reticulata, multijuga, officinalis) e Cerrado/transição (langsdorffii).","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Copaifera reticulata Ducke (C. langsdorffii Desf. — espécie de cerrado e transição)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Infecções bacterianas de pele","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Candidíase (tópico)","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Leishmaniose cutânea (adjuvante)","populacao":"Estudos brasileiros"},{"evidencia":"Moderada","indicacao":"Inflamação gengival (bochecho)","populacao":"Adultos"},{"evidencia":"Preliminar","indicacao":"Úlceras gástricas (uso interno)","populacao":"Modelos experimentais"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Anti-inflamatório potente (inibição de COX-2 e LOX)","Antimicrobiano de amplo espectro","Cicatrizante e regenerador tecidual","Antifúngico (Candida spp.)","Antiparasitário (Leishmania)","Broncodilatador (uso pulmonar tradicional)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação (pode ser uterotônico em doses altas)","Hepatopatias (metabolismo hepático intenso)","Crianças menores de 6 anos (uso interno)","Alergia a bálsamos (reação cruzada possível)"],"contraindicacoes":["Gestação (pode ser uterotônico em doses altas)","Hepatopatias (metabolismo hepático intenso)","Crianças menores de 6 anos (uso interno)","Alergia a bálsamos (reação cruzada possível)"],"efeitos_adversos":"","componentes_ativos":[{"label":"BETA-CARIOFILENO (sesquiterpeno)","texto":"Anti-inflamatório principal — inibição COX-2 e CB2"},{"label":"ÁCIDO COPÁLICO (diterpeno)","texto":"Antimicrobiano, antiparasitário"},{"label":"ÁCIDO KAURENOICO","texto":"Antimicrobiano, antifúngico"},{"label":"BIFORMENO, BISABOLENO","texto":"Aromáticos balsâmicos"},{"label":"COPAÁLIO","texto":"Sesquiterpeno — ação neurológica discutida"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"280e9c3b-04af-4603-8584-e096aabd3e52","slug":"rooibos","herb_id":null,"herb_latin_name":"Aspalathus linearis (Burm.f.) R.Dahlgren","schema_version":"1.1","ficha":{"slug":"rooibos","cultura":{"brasil":["A presença brasileira do rooibos é contemporânea e restrita a cafeterias especializadas e redes premium (Tea Connection, Tea Shop Brasil, Emporium São Paulo). Não tem tradição caboclo-europeia nem indígena — chegou ao país pela globalização do chá nos anos 2000-2010.","O consumidor brasileiro encontra o rooibos tipicamente em blends aromatizados (rooibos com baunilha, rooibos com cacau, rooibos com frutas vermelhas) — raramente puro, como é tradição sul-africana.","Oportunidade editorial Ervatório: posicionar o rooibos como planta exótica com identidade, sem desrespeitar sua origem cultural. É o tipo de ingrediente em que a curadoria brasileira tem papel pedagógico — trazer informação sobre origem, produtor, distinguir do honeybush, explicar o processo de fermentação."],"historia":["Os povos Khoisan — caçadores-coletores do sul da África — conheciam e colhiam o rooibos silvestre há séculos antes do contato europeu. Usavam a planta como infusão cotidiana e para usos medicinais tradicionais em feridas, eczemas e desordens digestivas.","O contato colonial europeu com a planta data do final do século XVII, mas a domesticação comercial só aconteceu no início do século XX. O botânico sueco-russo Carl Humberg, em 1772, documentou a planta cientificamente. Mas foi Benjamin Ginsberg, imigrante russo estabelecido na África do Sul no início do século XX, quem iniciou a comercialização sistemática do rooibos entre 1902-1930.","Durante a Segunda Guerra Mundial, com a interrupção do suprimento de chá asiático à Europa, o rooibos ganhou visibilidade internacional como substituto do chá. A consolidação como commodity global aconteceu a partir dos anos 1990, com redescoberta pela comunidade científica dos compostos antioxidantes únicos (aspalatina, nothofagina)."],"cerimonial":"O rooibos não tem cerimônia codificada — é bebida cotidiana, não cerimonial. Na África do Sul contemporânea, ocupa o lugar do \"chá das 4 da tarde\" britânico, adaptado para clima e gosto local. É bebida familiar, servida a crianças, consumida ao longo do dia.","curiosidade":"O rooibos é uma das poucas plantas comercialmente bem-sucedidas do mundo com distribuição endêmica absoluta. Apesar de décadas de tentativas, não foi domesticado fora da região Cederberg — exige combinação específica de clima (verões secos quentes, invernos frios), solo (arenoso-ácido) e microbiota (rhizobium específico das raízes). Biólogos comparam ao champanhe ou à cachaça de alambique: terroir estrito. O rooibos é beber um pedaço da África do Sul que, literalmente, não pode existir em outro lugar."},"preparo":{"metodo":"Infusão simples. Reinfunde bem, aguenta \"esquecimento\" no bule.","quantidade":"1 colher de sopa (~3 g) para 200 ml.","reinfusoes":"Sim, 2–3 reinfusões possíveis, cada uma mais suave.","combina_com":"Leite (rooibos latte é bebida clássica) · Baunilha · Canela · Cardamomo · Casca de laranja · Chocolate (sobremesa)","melhor_momento":"Qualquer hora — sem cafeína. Ideal para noite (não perturba sono) e para crianças (ausência de estimulantes).","tempo_de_infusao":"5–8 minutos coberto. Pode ser mais longo (até 10 min) sem amargor.","temperatura_ideal":"95–100 °C. Uma das poucas infusões herbais que toleram fervura plena — as folhas são robustas e não amargam."},"tagline":"Endemia sul-africana sem equivalente global — sem cafeína, sem ansiedade, com cor de terra vermelha e doçura única.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Funcional global + Sensorial"},{"label":"Tipo","texto":"Infusão herbal exclusiva — endêmica sul-africana"},{"label":"Status ANVISA","texto":"Não monografada — alimento funcional"},{"label":"Status EMA","texto":"Sem monografia específica; reconhecida como alimento consolidado"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar — farmacêutico ou fitoterapeuta com familiaridade em polifenóis","revisor_cultural":"Sugerido — consultor da cultura sul-africana contemporânea OU botânico especialista em endemismos sul-africanos","status_editorial":"Publicado (ficha-piloto Fase C1)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia específica. Alimento de uso tradicional europeu crescente.","status_fda":"GRAS para uso alimentar.","sazonalidade":"Colheita entre dezembro e abril na África do Sul (verão do Hemisfério Sul). Processamento: corte, oxidação (\"fermentação\") ao sol por 8–24h, secagem final.","status_anvisa":"Não monografada no Formulário de Fitoterápicos. Alimento consolidado, uso permitido.","eixo_botanico_tpc":"Funcional global + Sensorial","produtor_parceiro":"A definir — priorizar importação direta de cooperativas sul-africanas com selo Fair Trade. Oportunidade de rastreabilidade por fazenda para catálogo premium.","status_japao_china":"Uso alimentar permitido; consumo crescente em mercado asiático de alta renda.","certificacao_organica":"Ampla oferta certificada — produção sul-africana organizada em cooperativas, com selos Fair Trade (SANBS, Rainforest Alliance, UEBT)."},"marketplace":{"formatos":"Folhas cortadas (padrão comercial), folhas longas premium (\"long cut\"), rooibos verde, rooibos orgânico certificado.","fornecedores":"Importação direta de cooperativas sul-africanas — oportunidade de histórias de fazenda e rastreabilidade.","faixa_de_preco":"Rooibos vermelho commodity: R$ 40–80/100 g. Rooibos verde (raro): R$ 100–200/100 g. Rooibos orgânico Fair Trade: R$ 80–150/100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Rooibos","usos_topicos":{"evidencia":"Moderada para ação antioxidante tópica; limitada para outras aplicações.","aplicacoes":[{"texto":"Infusão forte fria, aplicada com algodão. Rico em aspalatina e nothofagina (polifenóis únicos), com ação antioxidante documentada em estudos dermatológicos. Uso cosmético contemporâneo.","titulo":"Tônico facial antioxidante"},{"texto":"Sachês usados, resfriados, aplicados sobre olhos fechados por 10 min. Ação antioxidante + temperatura. Uso popular sul-africano.","titulo":"Compressa para olhos cansados"},{"texto":"Infusão diluída em banho — prática sul-africana tradicional. A ausência de cafeína e a composição suave tornam o rooibos adequado onde outros chás são evitados.","titulo":"Banho suave para bebês e peles sensíveis"}],"contraindicacoes":"Uso tópico é amplamente seguro. Pode manchar tecidos claros — cor pigmentante."},"docx_filename":"Ficha_Rooibos_v11.docx","identificacao":{"slug_url":"rooibos","sinonimos":["Red bush / arbusto vermelho · rooibos-tea · chá-vermelho (designação imprecisa — chá é exclusivo de Camellia sinensis)","Rooibosthee (africâner) · Rooibostee (inglês) · Honeybush é planta aparentada distinta (Cyclopia spp.), frequentemente confundida"],"parte_usada":"Folhas e ramos finos, cortados e fermentados (processo oxidativo que gera cor e sabor característicos) ou verdes (rooibos verde, menos fermentado).","nome_popular":"Rooibos","tipo_botanico":"Arbusto perene endêmico.","nome_cientifico":"Aspalathus linearis (Burm.f.) R.Dahlgren","familia_botanica":"Fabaceae (Leguminosae — família da soja, feijão, ervilha)"},"caracterizacao":{"aroma":"Amadeirado doce, mel cru, frutas vermelhas secas, leve nuance de fumaça (em rooibos tradicional fermentado ao sol).","notas":"Cabeça: doce-amadeirado · Corpo: mel cru · Fundo: suave retro-nasal sem persistência agressiva","intensidade":"3/5 — equilibrado, versátil, combina com leite.","cor_da_infusao":"Vermelho-âmbar intenso no rooibos fermentado; dourado no rooibos verde. #A84A2E (vermelho) · #C9A253 (verde)","bioma_de_origem":"Africano — endêmica das montanhas Cederberg, província de Western Cape, África do Sul.","sabor_dominante":"Doce natural suave, ligeiramente amadeirado, notas de mel cru, sem amargor, sem adstringência. Perfil excepcionalmente \"fácil\" — o que explica o sucesso comercial global.","distribuicao_geografica":["Endêmica absoluta da região Cederberg, África do Sul. Todo rooibos comercial do mundo vem dessa região — aproximadamente 500.000 hectares.","Tentativas de cultivo fora da África do Sul (Austrália, Chile, Argentina) têm rendimentos limitados e perfil sensorial diferente.","Ausência completa no Brasil enquanto cultivo. Toda presença brasileira é via importação."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Aspalathus linearis (Burm.f.) R.Dahlgren","perfil_sensorial":{"tatil":"Corpo médio, levemente aveludado. Sem adstringência. Persistência suave — o perfil doce-amadeirado permanece no retronasal por 1–2 minutos, sem agressividade. É a infusão \"mais fácil\" do catálogo: não ofende, não exige, não pede atenção.","gustativo":[{"dimensao":"Doce","observacao":"Natural, sem necessidade de adoçar — diferencial do rooibos","intensidade":"2/3"},{"dimensao":"Umami","observacao":"Sutil, amadeirado-adocicado","intensidade":"1/3"},{"dimensao":"Amargo","observacao":"Ausente — característica rara entre infusões escuras","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Muito baixa","molecula":"Taninos em quantidade mínima — característica marcante","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: amadeirada-adocicada","descricao_integrada":"O rooibos é o contrário do chá verde e da erva-mate em termos sensoriais. Onde estes carregam cafeína, adstringência, complexidade e exigência, o rooibos oferece apenas doçura natural, aroma amadeirado-adocicado e ausência quase total de estímulos trigeminais. Essa simplicidade é justamente sua força comercial global: é a infusão que o ocidente médio aceita \"sem aprender a gostar\". A ausência de amargor e adstringência torna o rooibos compatível com leite, açúcar, especiarias, xaropes — versatilidade que chá verde genuíno não permite. É a única infusão herbal do catálogo em que o perfil sensorial convida, em vez de desafiar.","olfativo_descritores":["Mel cru","Madeira de cedro","Frutas vermelhas secas (ameixa, tâmara)","Leve caramelo","Fundo terroso suave (rooibos vermelho tradicional)"]},"acoes_e_seguranca":{"fontes":["Joubert & de Beer — Rooibos (Aspalathus linearis) beyond the farm gate (S Afr J Bot, 2011)","Marnewick et al. — Effects of rooibos (Aspalathus linearis) on oxidative stress and biochemical parameters in adults at risk for cardiovascular disease (J Ethnopharmacol, 2011)","Mars, Brigitte — Healing Herbal Teas (Basic Health, 2006)","Gaylard, Linda — The Tea Book (DK, 2015)"],"evidencia":[{"evidencia":"Forte laboratorial / Moderada clínica","indicacao":"Ação antioxidante sistêmica","populacao":"Adultos"},{"evidencia":"Forte (característica factual)","indicacao":"Alternativa sem cafeína","populacao":"Todas as populações"},{"evidencia":"Preliminar","indicacao":"Efeito cardiovascular benéfico","populacao":"Adultos"},{"evidencia":"Preliminar","indicacao":"Controle glicêmico (experimental)","populacao":"Estudos animais, início de clínicos"}],"interacoes":[{"label":"Medicamentos CYP3A4","texto":"alteração teórica — poucos dados clínicos"},{"label":"Outros","texto":"Nenhuma interação clinicamente relevante documentada"}],"dose_maxima":"Sem dose máxima estabelecida — consumo de 5+ xícaras/dia é documentado culturalmente na África do Sul sem evidência de dano.","alerta_critico":null,"acoes_principais":["Antioxidante de alto potencial (aspalatina, nothofagina — compostos exclusivos do rooibos)","Sem cafeína (vantagem funcional relevante para gestantes, crianças, pessoas sensíveis)","Anti-inflamatório leve","Cardioprotetor (evidência preliminar)","Modulador de glicose sanguínea (aspalatina — estudos experimentais)","Hidratante (uso como substituto de água aromatizada)"],"contraindicacoes":["Em uso de medicamentos metabolizados pela CYP3A4 (interação teórica — cautela)","Raríssimo: alergia documentada em indivíduos sensíveis a leguminosas","Muito poucas contraindicações — isso é um diferencial do rooibos"],"efeitos_adversos":"Raríssimos. O rooibos tem um dos perfis de segurança mais limpos entre as infusões herbais do mundo.","componentes_ativos":[{"label":"Aspalatina","texto":"Di-hidrochalcona única do rooibos. Antioxidante potente, com atividade antidiabética em modelos animais."},{"label":"Nothofagina","texto":"Outra di-hidrochalcona exclusiva do rooibos; antioxidante"},{"label":"Quercetina, luteolina, rutina","texto":"Flavonoides clássicos — antioxidantes"},{"label":"Minerais (cálcio, manganês, zinco, ferro)","texto":"Em quantidades modestas"},{"label":"Ausência completa de cafeína","texto":"Característica distintiva"},{"label":"Ácidos fenólicos (cafeico, clorogênico)","texto":"Antioxidantes secundários"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"b2d19c8a-a966-48ec-a6f4-df8873800fe8","slug":"erva-baleeira","herb_id":null,"herb_latin_name":"Cordia verbenacea DC.","schema_version":"1.1","ficha":{"slug":"erva-baleeira","cultura":{"brasil":["A erva-baleeira é o caso mais bem-sucedido de desenvolvimento científico-industrial de fitoterápico brasileiro. O Acheflan®, produzido pelo Aché Laboratórios, foi o primeiro fitoterápico nacional aprovado pela Anvisa com estudos clínicos de fase III.","O cultivo comercial concentra-se em São Paulo e Espírito Santo, com integração à indústria farmacêutica.","Para o Ervatório, a erva-baleeira é ficha que mostra o pleno ciclo possível da fitoterapia brasileira: conhecimento caboclo-caiçara → pesquisa acadêmica → produto industrial registrado → uso hospitalar amplo → retorno ao uso popular com embasamento científico."],"historia":["A erva-baleeira é planta da farmácia caiçara do litoral atlântico brasileiro. Os caiçaras, pescadores tradicionais do litoral paulista-fluminense, usavam a planta para tratar ferimentos, contusões e inflamações durante a atividade pesqueira — especialmente durante a caça à baleia que ocorreu no litoral até o século XIX (daí o nome \"baleeira\").","O conhecimento foi preservado por gerações caiçaras e caboclas até os anos 1990, quando pesquisadores da Universidade Federal de Santa Catarina e Aché Laboratórios iniciaram estudo científico sistemático. O desenvolvimento do Acheflan® (2004) foi marco — primeiro fitoterápico brasileiro com desenvolvimento clínico completo.","A entrada na Farmacopeia Brasileira (2011) consolidou o uso popular externo da infusão em compressa. Hoje a planta atravessa duas esferas: uso tradicional caboclo-caiçara (compressas caseiras) e uso industrial farmacêutico (creme Acheflan® em farmácias)."],"cerimonial":"Não tem cerimônia codificada, mas tem dimensão ritual cotidiana em comunidades caiçaras litorâneas — \"fazer compressa de baleeira\" é gesto transmitido geracionalmente. Em terreiros de Umbanda litorâneos, a planta às vezes entra em banhos de limpeza corporal.","curiosidade":"O beta-cariofileno da erva-baleeira é um dos pouquíssimos fitoquímicos identificados que age via receptor canabinoide CB2 — mesmo sistema de sinalização celular que os canabinoides da Cannabis. A diferença: enquanto o THC age em CB1 (produzindo efeitos psicoativos), o beta-cariofileno age em CB2 (modulando inflamação sem efeitos no cérebro). A planta caiçara brasileira tem canabinoide legal, sem efeito psicoativo, sem restrição."},"preparo":{"metodo":"Infusão para compressa local. USO EXTERNO é o principal.","quantidade":"3 g de folhas secas para 150 ml (uso externo).","reinfusoes":"Não aplicável.","combina_com":"Uso isolado na monografia oficial.","melhor_momento":"Aplicação em compressa 3 vezes ao dia sobre área inflamada.","tempo_de_infusao":"10 minutos coberto.","temperatura_ideal":"95 °C."},"tagline":"Do litoral atlântico ao primeiro fitoterápico brasileiro patenteado — a Acheflan nasceu desta planta caiçara e fez o caminho da farmácia caboclo à indústria farmacêutica.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Mata Atlântica (litoral) + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão + pomada fitoterápica monografada (uso externo)"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial (uso externo). Primeiro fitoterápico brasileiro com pesquisa clínica completa (Acheflan®)."},{"label":"Status EMA","texto":"Sem monografia"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar — farmacêutico com familiaridade na pesquisa do Acheflan","revisor_cultural":"Sugerido — comunidade caiçara do litoral SP/ES","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco 2)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia.","status_fda":"Sem reconhecimento específico.","sazonalidade":"Colheita de folhas ao longo do ano.","status_anvisa":"Monografia oficial (Anvisa, 2011). Acheflan® registrado como fitoterápico. Indicação: anti-inflamatório tópico.","eixo_botanico_tpc":"Mata Atlântica (litoral) + Phyto-ANVISA","produtor_parceiro":"A definir — priorizar produtores com rastreabilidade industrial.","status_japao_china":"Uso restrito.","certificacao_organica":"Cultivo organizado no litoral SP/ES, com produção ligada à indústria farmacêutica brasileira."},"marketplace":{"formatos":"Folhas secas (para compressa tradicional), creme fitoterápico Acheflan®.","fornecedores":"Produção litorânea SP/ES.","faixa_de_preco":"Folhas secas: R$ 40 a 90 por 100 g. Creme Acheflan®: produto farmacêutico registrado.","disponivel_a_venda":"A definir"},"nome_popular":"Erva-Baleeira","usos_topicos":{"evidencia":"FORTE — erva-baleeira é o caso mais bem documentado de fitoterápico brasileiro com pesquisa clínica completa de registro (Acheflan®, primeiro fitoterápico brasileiro com pesquisa industrial de nível farmacêutico).","aplicacoes":[{"texto":"USO PRIMÁRIO MONOGRAFADO — infusão forte morna em compressa na região afetada, 3 vezes ao dia. Evidência clínica robusta.","titulo":"Compressa anti-inflamatória para entorses, contusões e dor articular"},{"texto":"Formulação farmacêutica (Acheflan®, creme a 5% de óleo essencial). Indicado para tendinites, bursites, dor lombar e cervical inflamatória, entorses.","titulo":"Pomada/creme para inflamações articulares crônicas"},{"texto":"Folhas frescas amassadas localmente — uso popular caiçara tradicional.","titulo":"Aplicação tópica para picadas de insetos"}],"contraindicacoes":"Uso tópico amplamente seguro. Suspender em caso de alergia local."},"docx_filename":"Ficha_Erva_Baleeira_v11.docx","identificacao":{"slug_url":"erva-baleeira","sinonimos":["Maria-preta · maria-milagrosa · catinga-de-mulata · salicéria · baleeira","Sinonímia botânica: Varronia curassavica Jacq.","Nome popular \"baleeira\" vem do uso tradicional por caiçaras que ficavam expostos a ferimentos e inflamações articulares durante a caça à baleia nos séculos XVIII-XIX no litoral paulista e fluminense."],"parte_usada":"Folhas secas — 3 g para 150 ml (uso externo em compressa, conforme monografia). Óleo essencial das folhas é a base do medicamento fitoterápico Acheflan®.","nome_popular":"Erva-baleeira","tipo_botanico":"Arbusto perene de 1 a 2,5 m, com folhas ásperas e flores brancas pequenas em cachos.","nome_cientifico":"Cordia verbenacea DC.","familia_botanica":"Boraginaceae"},"caracterizacao":{"aroma":"Herbáceo-resinoso característico, com notas de alfa-humuleno (mesmo composto do lúpulo) e leve canforado.","notas":"Cabeça: resinoso-herbáceo · Corpo: leve canforado · Fundo: amadeirado","intensidade":"3/5 (via aromática)","cor_da_infusao":"Verde-amarelado. #BFC676","bioma_de_origem":"Mata Atlântica litorânea brasileira.","sabor_dominante":"USO EXTERNO — perfil sensorial de aplicação tópica. Se preparada em infusão: aromático-herbáceo com leve amargor.","distribuicao_geografica":["Brasil: litoral e Mata Atlântica do ES, RJ, SP, PR, SC.","Ocorrência também em outras regiões de América Central e tropical.","Cultivo comercial organizado em SP e ES, parcialmente ligado à indústria farmacêutica (produção para Acheflan®)."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Cordia verbenacea DC.","perfil_sensorial":{"tatil":"Aplicação tópica: sensação imediata de resfrescamento leve seguida de calor suave — típica dos sesquiterpenos anti-inflamatórios.","gustativo":[{"dimensao":"Amargo","observacao":"Via oral, leve","intensidade":"1/3"},{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Baixa","molecula":"Terpenos em traços","receptor":"TRPM8 (frescor)"},{"ativacao":"Baixa","molecula":"Nuance leve","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Baixa","molecula":"Taninos em quantidade moderada","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: resinosa-herbácea com nuance canforada","descricao_integrada":"A erva-baleeira é um dos casos mais importantes de trânsito entre saber popular e ciência industrial no Brasil. A planta que caiçaras paulistas usaram por séculos em compressas para inflamação muscular virou, nos anos 2000, o Acheflan® — primeiro fitoterápico brasileiro com desenvolvimento industrial-clínico completo equivalente aos medicamentos sintéticos. A molécula-estrela (alfa-humuleno) é a mesma que dá amargor à cerveja artesanal via lúpulo — parente botânico distante que compartilha a química. Outro ponto notável: o trans-cariofileno da erva-baleeira age via receptor canabinoide CB2, mostrando que a Cordia verbenacea tem ação anti-inflamatória pelo mesmo sistema que os canabinoides da Cannabis — sem efeitos psicoativos e sem restrição legal. O Ervatório tem oportunidade de narrar esta planta como caso-modelo de fitoterapia brasileira de alta qualidade científica.","olfativo_descritores":["Alfa-humuleno (similar ao lúpulo)","Resina litorânea","Folha áspera amassada","Leve canforado","Fundo amadeirado"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografia oficial","Acheflan® — primeiro fitoterápico brasileiro com desenvolvimento clínico completo (Aché Laboratórios, 2004). Estudos de fase III em periódicos indexados.","Passos et al. — Anti-inflammatory and anti-allergic properties of the essential oil and active compounds from Cordia verbenacea (J Ethnopharmacol, 2007)","Fernandes et al. — Anti-inflammatory effects of compounds alpha-humulene and (-)-trans-caryophyllene isolated from the essential oil of Cordia verbenacea (Eur J Pharmacol, 2007)"],"evidencia":[{"evidencia":"Forte","indicacao":"Tendinites e bursites","populacao":"Adultos"},{"evidencia":"Forte","indicacao":"Dor lombar e cervical inflamatória","populacao":"Adultos"},{"evidencia":"Forte","indicacao":"Entorses e contusões","populacao":"Adultos"},{"evidencia":"Moderada-forte","indicacao":"Dor articular crônica","populacao":"Adultos"}],"interacoes":[{"label":"Não há interações documentadas em uso tópico conforme monografia"}],"dose_maxima":"Uso externo: compressa 3 vezes ao dia. Acheflan®: aplicar creme 3 vezes ao dia, por até 21 dias.","alerta_critico":null,"acoes_principais":["Anti-inflamatório tópico — ação monografada e clinicamente documentada","Analgésico local","Antimicrobiano tópico","Cicatrizante coadjuvante"],"contraindicacoes":["Alergia conhecida a compostos terpenoides","Uso interno não recomendado (a monografia é especificamente para uso externo)","Pele com lesões abertas extensas: usar com cautela"],"efeitos_adversos":"Raros. Dermatite de contato em sensíveis.","componentes_ativos":[{"label":"Alfa-humuleno","texto":"Sesquiterpeno anti-inflamatório potente — é o mesmo composto do lúpulo. Principal princípio ativo do Acheflan®."},{"label":"Trans-cariofileno","texto":"Sesquiterpeno com ação anti-inflamatória via receptor canabinoide CB2 (descoberta relevante — atuação similar a canabinoides sem efeitos psicoativos)"},{"label":"Óleo essencial complexo","texto":"Componentes aromáticos múltiplos"},{"label":"Flavonoides","texto":"Antioxidantes"},{"label":"Ácido rosmarínico","texto":"Anti-inflamatório adicional"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"2ec41291-7ca5-4982-aeea-7b25d8168558","slug":"aroeira-da-praia","herb_id":null,"herb_latin_name":"Schinus terebinthifolius Raddi","schema_version":"1.1","ficha":{"slug":"aroeira-da-praia","cultura":{"brasil":["A aroeira-da-praia é planta emblemática do litoral brasileiro — reconhecida do Maranhão ao Rio Grande do Sul. Tem presença tão difusa em restingas e mangues que frequentemente é considerada invasora em áreas de reflorestamento mal planejado.","O uso medicinal é praticamente universal em comunidades ribeirinhas, pescadoras, e afro-brasileiras litorâneas. O uso gourmet (pimenta-rosa) é mais urbano e recente. Para o Ervatório, há oportunidade editorial em valorizar o uso medicinal histórico contra a mercantilização gourmet que apaga o saber tradicional.","A pesquisa científica brasileira sobre Schinus terebinthifolius é robusta — universidades do Nordeste e Sudeste produziram trabalhos importantes sobre ação anti-inflamatória e antimicrobiana. A monografia oficial da Anvisa é baseada parcialmente nessa pesquisa nacional."],"historia":["A aroeira-da-praia é planta central da farmacopeia caboclo-litorânea brasileira desde tempos pré-coloniais. Povos indígenas tupinambás do litoral usavam a casca para feridas, para problemas ginecológicos, para ferimentos de guerra. O conhecimento foi transmitido aos colonos portugueses e depois africanos que chegaram ao litoral brasileiro.","No século XIX, a aroeira tornou-se ingrediente de preparações farmacêuticas populares — \"garrafadas\" litorâneas, chás de lavagem, banhos femininos. A entrada na Farmacopeia Brasileira moderna consolidou oficialmente o uso ginecológico externo.","Paralelamente, nos anos 1970-1980, o fruto da mesma árvore foi descoberto pela gastronomia internacional — a Schinus terebinthifolius virou \"pimenta-rosa\" ou \"pink peppercorn\", commodity gourmet vendida em mercados europeus e norte-americanos. Hoje há conflito regulatório porque o fruto tem potencial alérgico (família Anacardiaceae) e alguns países baniram seu uso alimentar."],"cerimonial":"A aroeira-da-praia tem dimensão ritual forte em tradições afro-brasileiras — entra em banhos de descarrego, banhos de cura, em preparações de terreiro de Candomblé e Umbanda. É folha associada a orixás específicos em algumas tradições (ligada a Oxóssi em algumas casas baianas, a Obaluaiê em outras). Essa dimensão ritual convive com o uso ginecológico medicinal em comunidades negras litorâneas.","curiosidade":"A aroeira-da-praia produz o fruto que o mundo gourmet chama de \"pimenta-rosa\" por motivo puramente comercial: não é Piper (gênero da pimenta-do-reino), não tem piperina, e tecnicamente não é \"pimenta\" em sentido botânico algum. É uma fruta da família do cajueiro — Anacardiaceae — compartilhando ancestralidade com a manga e com o umbu. O \"tempero chique\" que frequenta restaurantes europeus caros é prima-irmã da fruta do caju. Essa ironia é especialmente cortante porque a pimenta-rosa europeia frequentemente é vendida por dez vezes o preço do caju brasileiro, que tem mais nutrientes, mais história, e mais fruta."},"preparo":{"metodo":"Decocção (cascas em fervura), diferente da infusão padrão.","quantidade":"1 g de cascas secas para 150 ml, conforme monografia oficial.","reinfusoes":"Não aplicável.","combina_com":"Usada isolada na monografia oficial; em tradição popular, combina com barbatimão para cicatrização.","melhor_momento":"Uso externo — aplicação terapêutica específica (banhos de assento, compressas).","tempo_de_infusao":"Decocção — fervura branda por 10 a 15 minutos.","temperatura_ideal":"Fervura plena para decocção (100 °C)."},"tagline":"Pimenta-rosa brasileira virou cicatrizante ginecológico oficial — a mesma árvore que dá tempero gourmet internacional cura inflamações há séculos no litoral brasileiro.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Mata Atlântica + Phyto-ANVISA"},{"label":"Tipo","texto":"Decocção herbal monografada (uso externo)"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial (uso externo)"},{"label":"Status EMA","texto":"Sem monografia"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar — farmacêutico ou ginecologista com experiência em fitoterapia","revisor_cultural":"Sugerido — herbalista afro-brasileiro litorâneo ou parteira tradicional","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco 1)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia específica. Uso gourmet do fruto questionado em alguns países europeus (risco alérgico).","status_fda":"Restrições à comercialização do fruto em alguns anos (1982-1990) por risco alérgico; hoje permitido com avisos.","sazonalidade":"Cascas podem ser colhidas ao longo do ano (com manejo adequado para não matar a árvore). Frutos entre junho e agosto no Hemisfério Sul.","status_anvisa":"Monografia oficial no Formulário de Fitoterápicos (Anvisa, 2011). Indicação: anti-inflamatório e cicatrizante ginecológico (USO EXTERNO).","eixo_botanico_tpc":"Mata Atlântica (litoral) + Phyto-ANVISA","produtor_parceiro":"A definir — priorizar comunidades ribeirinhas e pescadoras com tradição de uso. Avaliar parceria com terreiros de Candomblé/Umbanda litorâneos com tradição da planta.","status_japao_china":"Uso gourmet crescente; uso medicinal pouco difundido.","certificacao_organica":"Coleta extrativista em restingas litorâneas com manejo sustentável. Produção ainda não industrializada para uso medicinal."},"marketplace":{"formatos":"Cascas secas trituradas (para decocção), tintura, extrato fluido. Uso ginecológico específico.","fornecedores":"Curadoria de extrativistas litorâneos com manejo sustentável.","faixa_de_preco":"Cascas secas: R$ 40 a 100 por 100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Aroeira-da-Praia","usos_topicos":{"evidencia":"FORTE para uso externo em afecções ginecológicas — a monografia é específica para esse uso. Moderada para outras aplicações tópicas cutâneas.","aplicacoes":[{"texto":"USO PRIMÁRIO MONOGRAFADO — decocção da casca, morna, banho de assento de 10 a 15 minutos, 3 a 4 vezes ao dia. Ação anti-inflamatória e cicatrizante documentada. Uso tradicional e oficial em corrimento inflamatório, cicatrização pós-parto e pós-cirúrgico ginecológico.","titulo":"Banho de assento em afecções ginecológicas"},{"texto":"Decocção morna aplicada em compressa sobre feridas pequenas, 2 a 3 vezes ao dia. Uso popular litorâneo com plausibilidade farmacológica pela ação adstringente dos taninos.","titulo":"Compressa para feridas cutâneas"},{"texto":"Decocção diluída, morna, bochechar 30 segundos. Uso tradicional nordestino.","titulo":"Bochecho para gengivite"},{"texto":"USO NÃO RECOMENDADO sem orientação oftalmológica, apesar da presença na tradição popular — risco de irritação.","titulo":"Lavagem de olhos com conjuntivite"}],"contraindicacoes":"USO INTERNO NÃO É RECOMENDADO pela monografia oficial. Em caso de alergia ou irritação cutânea, suspender uso."},"docx_filename":"Ficha_Aroeira_Praia_v11.docx","identificacao":{"slug_url":"aroeira-da-praia","sinonimos":["Aroeira-vermelha · aroeira-mansa · aroeira-pimenta · pimenta-rosa · pimenta-brasileira","No comércio internacional gourmet: Brazilian pepper, pink peppercorn","Atenção: existem outras plantas chamadas \"aroeira\" no Brasil — Myracrodruon urundeuva (aroeira-do-sertão, aroeira-preta, com madeira nobre) e Astronium spp. A Schinus terebinthifolius é a \"aroeira-mansa\" ou \"aroeira-da-praia\", com uso medicinal externo."],"parte_usada":"Cascas do caule secas — 1 g para 150 ml, decocção, uso externo, conforme monografia.","nome_popular":"Aroeira-da-praia","tipo_botanico":"Árvore perene de 5 a 10 m, com folhas compostas e pequenos frutos vermelhos vibrantes em cachos (os \"pimenta-rosa\" da culinária).","nome_cientifico":"Schinus terebinthifolius Raddi","familia_botanica":"Anacardiaceae (mesma família da mangueira, cajueiro, umbuzeiro)"},"caracterizacao":{"aroma":"Resinoso-amadeirado característico das cascas, com nota levemente doce-pimentada lembrando a pimenta-rosa gourmet.","notas":"Cabeça: resinoso · Corpo: amadeirado · Fundo: pimentado-doce","intensidade":"N/A (uso externo)","cor_da_infusao":"Vermelho-amarronzado a âmbar escuro. #8B4A2F","bioma_de_origem":"Mata Atlântica litorânea brasileira — restingas, mangues, bordas de mata costeira.","sabor_dominante":"USO EXTERNO — não destinado a consumo oral na monografia. Perfil sensorial em aplicação tópica: amadeirado-resinoso.","distribuicao_geografica":["Brasil: ocorrência natural abundante em todo o litoral — MA, CE, RN, PB, PE, AL, SE, BA, ES, RJ, SP, PR, SC, RS.","Expansão para áreas interioranas do Sudeste e Sul.","Exportação global como \"pimenta-rosa\" gourmet — presente em cozinhas do mundo inteiro.","Naturalizada em outros países tropicais (Flórida, onde é considerada invasora)."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Schinus terebinthifolius Raddi","perfil_sensorial":{"tatil":"Aplicação tópica: sensação de \"fechamento\" dos tecidos pela ação adstringente dos taninos. Persistência alta — o efeito anti-inflamatório dura horas.","gustativo":[{"dimensao":"Amargo","observacao":"Taninos — percebido como adstringência forte","intensidade":"2/3"},{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Baixa","molecula":"Traços terpênicos","receptor":"TRPM8 (frescor)"},{"ativacao":"Baixa-moderada","molecula":"Nuance pimentada da tradição culinária","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Alta","molecula":"Taninos em concentração muito alta — sensação pronunciada","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: resinosa-amadeirada","descricao_integrada":"A aroeira-da-praia é um caso exemplar de como a mesma planta pode ter duas identidades paralelas no imaginário global. Nas cozinhas gourmets do mundo, a Schinus terebinthifolius é \"pimenta-rosa\" — grão decorativo, aromático, caro, usado em pratos refinados. Nas farmácias populares do litoral brasileiro, a mesma árvore é cura séria para inflamação ginecológica, com monografia oficial e evidência clínica robusta. A distância entre essas duas identidades é brutal: o cozinheiro italiano usa o fruto pequeno sem saber que a casca da mesma árvore cura mulheres brasileiras há séculos. O Ervatório tem oportunidade de fazer pedagogia dessa dupla vida, conectando o tempero exótico que vai ao risoto com a planta medicinal que vai ao banho de assento de quem pariu ontem. É a mesma árvore, são as duas faces do Brasil.","olfativo_descritores":["Madeira de aroeira recém-cortada","Pimenta-rosa gourmet","Resina litorânea","Fundo levemente doce de restinga","Nuance salina (origem costeira)"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografia oficial de Schinus terebinthifolius","Lima et al. — Anti-inflammatory activity of Schinus terebinthifolius Raddi (J Ethnopharmacol, 2009)","Jain et al. — Antimicrobial activity of Schinus terebinthifolius essential oil (Fitoterapia, 2008)"],"evidencia":[{"evidencia":"Forte","indicacao":"Afecções ginecológicas inflamatórias","populacao":"Adultos (banho de assento)"},{"evidencia":"Moderada-forte","indicacao":"Cicatrização pós-parto","populacao":"Mulheres no puerpério"},{"evidencia":"Moderada","indicacao":"Feridas cutâneas pequenas","populacao":"Uso tópico"},{"evidencia":"Forte in vitro","indicacao":"Ação antimicrobiana tópica","populacao":"Uso externo"}],"interacoes":[{"label":"Não há interações documentadas para uso externo"}],"dose_maxima":"Conforme a monografia: decocção com 1 g de casca para 150 ml de água. Banho de assento 3 a 4 vezes ao dia.","alerta_critico":null,"acoes_principais":["Anti-inflamatório tópico — ação monografada","Cicatrizante ginecológico — ação monografada","Adstringente potente (alto teor de taninos)","Antimicrobiano de amplo espectro","Antifúngico"],"contraindicacoes":["Alergia conhecida à família Anacardiaceae (mangueira, cajueiro — mesma família)","USO INTERNO NÃO RECOMENDADO pela Farmacopeia Brasileira","Aplicação em mucosa ocular sem orientação profissional"],"efeitos_adversos":"Raros em uso externo em doses recomendadas. Em alérgicos à Anacardiaceae: dermatite de contato.","componentes_ativos":[{"label":"Taninos condensados (proantocianidinas)","texto":"Concentração alta — responsáveis pela ação adstringente e cicatrizante"},{"label":"Óleo essencial (alfa-pineno, beta-pineno, limoneno, carofileno)","texto":"Responsável pelo aroma e com ação antimicrobiana"},{"label":"Ácidos triterpênicos (ácido terebintifolílico, schinol)","texto":"Anti-inflamatórios"},{"label":"Flavonoides","texto":"Antioxidantes"},{"label":"Resinas","texto":"Conferem proteção mecânica sobre tecidos inflamados"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"58fcafbd-a54f-4b85-879d-be5e3a1496f7","slug":"boldo-brasileiro","herb_id":null,"herb_latin_name":"Plectranthus barbatus Andrews","schema_version":"1.1","ficha":{"slug":"boldo-brasileiro","cultura":{"brasil":["O P. barbatus é planta da identidade cotidiana brasileira — poucas ervas têm presença tão difusa no território nacional. Está em quintais rurais e jardineiras de apartamento, em chás caseiros e em receitas comerciais, atravessando a distinção entre fitoterapia oficial e medicina popular.","O cultivo é praticamente sempre doméstico ou familiar — a planta se multiplica com facilidade por estaquia e não há produção industrial expressiva. Para o Ervatório, isso pode significar uma estratégia de produção distribuída via pequenos produtores agroecológicos, não via monocultura.","A dupla face do \"boldo\" no Brasil — oficial (P. boldus chileno, importado, raramente consumido na prática) vs. popular (P. barbatus, africano por origem, brasileiro por adoção, onipresente) — é um caso exemplar de como o nome popular pode desencontrar da taxonomia científica. O Ervatório faz papel pedagógico ao documentar com precisão a diferença."],"historia":["O Plectranthus barbatus é originário do leste da África (região de Etiópia, Quênia, Tanzânia). Foi introduzido no Brasil provavelmente via rotas de comércio atlântico entre os séculos XVII e XVIII, junto com as diásporas africanas forçadas. A adaptação ao clima brasileiro foi tão bem-sucedida que a planta tornou-se praticamente naturalizada — cresce espontaneamente em muitos estados.","A apropriação do nome \"boldo\" no Brasil aconteceu provavelmente no século XIX, quando o boldo-do-chile (Peumus boldus) já era conhecido na farmácia brasileira por importação andina. A semelhança de função (digestivo pós-refeição) e talvez a aparência da folha resultaram na transferência do nome popular — o P. barbatus, que é o que existe nos quintais, passou a ser chamado \"boldo\" mesmo não tendo relação botânica com o boldo oficial.","A entrada na Farmacopeia Brasileira (Formulário de Fitoterápicos, 2011) oficializou o Plectranthus barbatus como espécie medicinal nacional — reconhecendo a planta como está efetivamente usada no Brasil, separadamente do Peumus boldus."],"cerimonial":"O boldo-brasileiro não tem cerimônia codificada, mas tem densidade ritualística doméstica enorme. \"Tomar chá de boldo depois do almoço\" é um dos gestos herbalistas mais praticados no Brasil contemporâneo — em todas as regiões, em todas as classes sociais. A folha fresca do quintal é colhida, amassada entre as mãos, posta na xícara, coberta com água quente. Gestos simples repetidos por milhões de pessoas, todos os dias.","curiosidade":"A forskolina, diterpeno característico do Plectranthus barbatus, é vendida em todo o mundo como suplemento \"queimador de gordura\" em academias. O paradoxo é que a molécula, isolada pela pesquisa indiana nos anos 1970, vem de uma planta que no Brasil é avó herbalista gentil servida à mesa de almoço. A indústria de suplementos vende a mesma planta em cápsulas caras que o jardineiro brasileiro tem de graça no quintal — e a tradição brasileira usa a planta de forma muito mais sábia: não para queimar gordura, mas para ajudar a digerir a comida que já foi comida com prazer."},"preparo":{"metodo":"Infusão coberta. Folha fresca amassada levemente para liberar óleos essenciais.","quantidade":"1 a 3 g de folhas secas (1 a 3 folhas frescas inteiras) para 150 ml — proporção oficial.","reinfusoes":"Não recomendado.","combina_com":"Hortelã-pimenta · Erva-doce · Camomila · Carqueja (sinergia digestiva, usar com cautela por causa dos alertas combinados)","melhor_momento":"Após refeições pesadas, 2 a 3 vezes ao dia conforme a monografia.","tempo_de_infusao":"5 a 10 minutos coberto.","temperatura_ideal":"95 °C."},"tagline":"O boldo do quintal brasileiro — planta africana que virou remédio caboclo nacional, confundida com o boldo-do-chile mas com farmacologia própria e gentil.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Funcional global (origem africana) + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão herbal monografada"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Sem monografia específica"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar","revisor_cultural":"Sugerido — herbalista ou jardineiro com prática doméstica de boldo-brasileiro","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco 1)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia específica.","status_fda":"Uso como suplemento alimentar permitido (foco em forskolina isolada).","sazonalidade":"Folhas colhidas ao longo do ano em clima tropical-subtropical.","status_anvisa":"Monografia oficial no Formulário de Fitoterápicos (Anvisa, 2011). Indicação: antidispéptico.","eixo_botanico_tpc":"Funcional global (origem africana) + Phyto-ANVISA","produtor_parceiro":"A definir — estratégia de produção distribuída via pequenos produtores agroecológicos em todas as regiões.","status_japao_china":"Uso tradicional na Medicina Ayurvédica indiana documentado.","certificacao_organica":"Principalmente produção doméstica familiar. Há pequena produção orgânica certificada em MG e SP."},"marketplace":{"formatos":"Folhas frescas (preferível — planta disponível em quintal), folhas secas, sachê.","fornecedores":"Potencial distribuído — pequenos produtores orgânicos brasileiros em múltiplas regiões.","faixa_de_preco":"Folhas secas: R$ 20 a 50 por 100 g (produção artesanal).","disponivel_a_venda":"A definir"},"nome_popular":"Boldo-Brasileiro","usos_topicos":{"evidencia":"Limitada — uso primordialmente oral.","aplicacoes":[{"texto":"Folhas frescas amassadas envolvidas em pano, aplicação local. Uso tradicional caboclo-brasileiro.","titulo":"Compressa fria em dor articular leve"},{"texto":"Folhas frescas em água fervente, inalação de vapor 5 min. Uso tradicional popular.","titulo":"Inalação em congestão nasal leve"}],"contraindicacoes":"Uso tópico seguro em pele íntegra."},"docx_filename":"Ficha_Boldo_Brasileiro_v11.docx","identificacao":{"slug_url":"boldo-brasileiro","sinonimos":["Boldo-africano · boldo-nacional · boldo-de-jardim · falso-boldo · malva-santa","Sinonímia botânica: Coleus barbatus (Andrews) Benth.","ALERTA CRÍTICO DE NOMENCLATURA: no Brasil, \"boldo\" refere-se popularmente a três plantas diferentes: (1) Peumus boldus (boldo-do-chile, andino), (2) Plectranthus barbatus (esta ficha — boldo-brasileiro), (3) Vernonia condensata (boldo-baiano). As três têm farmacologia distinta. Confusão botânica tem impacto clínico real."],"parte_usada":"Folhas secas — 1 a 3 g para 150 ml, conforme monografia oficial.","nome_popular":"Boldo-brasileiro","tipo_botanico":"Arbusto perene de 60 cm a 2 m, com caules quadrangulares e folhas opostas grandes, aveludadas, aromáticas ao amassar.","nome_cientifico":"Plectranthus barbatus Andrews","familia_botanica":"Lamiaceae (família da hortelã, alecrim, sálvia)"},"caracterizacao":{"aroma":"Herbáceo-canforado suave, com notas de sálvia e hortelã aquecida. Folha fresca amassada libera aroma característico inconfundível.","notas":"Cabeça: herbáceo fresco · Corpo: amargor suave · Fundo: canforado discreto","intensidade":"3/5 — moderada, muito mais acessível que o P. boldus.","cor_da_infusao":"Verde-amarelado pálido a amarelo esverdeado. #CED47A","bioma_de_origem":"Planta de origem africana (leste da África), naturalizada no Brasil há séculos.","sabor_dominante":"Amargo-aromático suave, muito mais gentil que o boldo-do-chile. Notas herbáceas da família Lamiaceae, leve canforado, sem a intensidade medicinal do P. boldus chileno.","distribuicao_geografica":["Originária do leste da África (Etiópia, Quênia, Tanzânia).","Naturalizada e amplamente cultivada no Brasil — presente em praticamente todos os quintais brasileiros com clima tropical ou subtropical.","Planta tão integrada ao cotidiano brasileiro que muitos não sabem que é de origem africana.","Também cultivada na Índia, Sudeste Asiático, e Caribe."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Plectranthus barbatus Andrews","perfil_sensorial":{"tatil":"Corpo leve. Sensação gentil, muito distante da intensidade do boldo-do-chile. Persistência média.","gustativo":[{"dimensao":"Amargo","observacao":"Suave, diferente do amargor cortante do P. boldus chileno","intensidade":"2/3"},{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Baixa","molecula":"Traços de mentol e eucaliptol","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Baixa","molecula":"Taninos em baixa concentração","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: herbácea-canforada da Lamiaceae","descricao_integrada":"O boldo-brasileiro é a versão domesticada, gentil e familiar do boldo oficial — planta que imigrou da África, adotou o nome do primo chileno, e se instalou nos quintais brasileiros como avó herbalista que todos reconhecem. O perfil sensorial é deliberadamente acessível: onde o Peumus boldus ataca com canforado medicinal intenso, o Plectranthus barbatus apenas sugere — amargor moderado, aromático herbáceo, um toque canforado que lembra sálvia-aquecida. Essa gentileza sensorial tem consequência clínica direta: o boldo-brasileiro é muito mais tolerado para uso doméstico casual do que o chileno, e por isso acabou sendo a planta que efetivamente ocupa o imaginário brasileiro de \"chá de boldo\". A ironia botânica é profunda: quando a avó brasileira serve \"chá de boldo depois do almoço\", quase sempre está servindo uma planta africana com nome chileno, cuja farmacologia é mais suave que a da planta original homônima.","olfativo_descritores":["Sálvia verde aquecida","Hortelã leve com cânfora","Folha aveludada amassada","Jardim brasileiro após chuva","Fundo resinoso suave"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografia oficial de Plectranthus barbatus","Lukhoba et al. — Plectranthus: A review of ethnobotanical uses (J Ethnopharmacol, 2006)","Alasbahi & Melzig — Plectranthus barbatus: a review of phytochemistry, ethnobotanical uses and pharmacology (Planta Med, 2010)"],"evidencia":[{"evidencia":"Moderada","indicacao":"Dispepsia funcional","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Desconforto digestivo pós-refeição","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Suporte hepático leve","populacao":"Adultos"}],"interacoes":[{"label":"Metronidazol","texto":"INTERAÇÃO IMPORTANTE — advertência expressa da monografia. Não usar concomitantemente."},{"label":"Dissulfiram","texto":"INTERAÇÃO IMPORTANTE — advertência expressa."},{"label":"Depressores do SNC (benzodiazepínicos, opiáceos)","texto":"INTERAÇÃO — advertência expressa."},{"label":"Anti-hipertensivos","texto":"INTERAÇÃO — advertência expressa da monografia."},{"label":"Anticoagulantes","texto":"cautela"}],"dose_maxima":"Conforme a monografia: 150 ml do infuso (1 a 3 g de folhas secas), 2 a 3 vezes ao dia, logo após o preparo. Uso limitado, não prolongado.","alerta_critico":null,"acoes_principais":["Antidispéptico — ação monografada","Colagogo leve","Hepatoativo suave","Antiespasmódico digestivo","Anti-inflamatório leve"],"contraindicacoes":["CONTRAINDICADO em gestantes (advertência expressa da Farmacopeia Brasileira)","CONTRAINDICADO em lactantes (advertência expressa)","CONTRAINDICADO em crianças (advertência expressa)","CONTRAINDICADO em hipertensos (advertência expressa)","CONTRAINDICADO em portadores de obstrução das vias biliares","NÃO USAR concomitantemente com metronidazol ou dissulfiram (advertência expressa)","NÃO USAR concomitantemente com depressores do SNC ou anti-hipertensivos"],"efeitos_adversos":"Em doses recomendadas e por tempo limitado: raros. Doses excessivas ou uso prolongado podem causar irritação gástrica (advertência expressa).","componentes_ativos":[{"label":"Forskolina (coleonol)","texto":"Diterpeno característico do gênero Plectranthus — ativa enzima adenilato-ciclase, com efeitos fisiológicos diversos. Base de suplementos comerciais de \"forskolina pura\"."},{"label":"Óleo essencial (alfa-pineno, canfeno, gama-terpineno)","texto":"Contribui para aroma e tem ação leve anti-inflamatória"},{"label":"Flavonoides (quercetina, kaempferol)","texto":"Antioxidantes"},{"label":"Rosmarinic acid","texto":"Antioxidante e antialérgico"},{"label":"Taninos","texto":"Adstringência leve"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"069cb115-9d8f-4407-a25f-06bb753709c1","slug":"chamba","herb_id":null,"herb_latin_name":"Justicia pectoralis Jacq.","schema_version":"1.1","ficha":{"slug":"chamba","cultura":{"brasil":["O chambá é planta emblemática do Ceará medicinal — associado ao programa Farmácias Vivas, uma das experiências pioneiras de fitoterapia pública no Brasil. O professor Francisco Matos (UFC) e sua equipe estabeleceram o chambá como modelo de planta fitoterápica cultivada localmente em Unidades Básicas de Saúde.","O cultivo é expressivo em pequena escala no Ceará, Pernambuco e Paraíba. A planta também cresce em jardins domésticos urbanos em várias regiões do Nordeste.","Para o Ervatório, o chambá é ficha que carrega história de fitoterapia pública brasileira — o SUS como fonte de conhecimento herbalista acumulado."],"historia":["O chambá é planta da tradição fitoterápica nordestina com raízes amazônicas. Povos indígenas amazônicos (especialmente shipibo-conibo no Peru) usam a Justicia pectoralis em preparações rituais com ayahuasca há séculos — a planta é conhecida como \"pirí-pirí\" em algumas tradições.","No Nordeste brasileiro, o chambá foi incorporado à farmácia caboclo-sertaneja desde o século XIX, com forte presença no Ceará e Pernambuco. A planta ganhou destaque nacional quando o programa Farmácias Vivas, criado pelo professor Francisco José de Abreu Matos na UFC nos anos 1980, elegeu-a como uma das ervas-base para produção local de fitoterápicos no SUS.","A entrada na Farmacopeia Brasileira (2011) consolidou o status oficial. O chambá é hoje um dos fitoterápicos mais distribuídos no SUS cearense e pernambucano, em xaropes produzidos localmente."],"cerimonial":"Na Amazônia ocidental, o chambá (pirí-pirí) tem dimensão ritual forte em cerimônias de ayahuasca — considerado planta aliada que \"limpa a voz\" do xamã durante cantos ícaros. Essa dimensão ritual é preservada por comunidades indígenas peruanas e brasileiras amazônicas.","curiosidade":"O chambá e o guaco compartilham a mesma molécula aromática (cumarina), mas pertencem a famílias botânicas completamente diferentes — Justicia está em Acanthaceae (mesma família da manjericão-roxa), Mikania está em Asteraceae (mesma família do girassol). Duas linhagens evolutivas distintas convergiram para produzir a mesma molécula de baunilha como resposta a pressões ecológicas similares. Convergência química entre família do girassol e família das acantáceas: a evolução inventa a mesma receita duas vezes."},"preparo":{"metodo":"Infusão coberta, logo após o preparo.","quantidade":"5 g de partes aéreas secas (colher de sopa cheia) para 150 ml — proporção da Farmacopeia.","reinfusoes":"Não recomendado.","combina_com":"Guaco (ambos têm cumarina, sinergia expectorante) · Mel · Limão · Gengibre","melhor_momento":"Em quadros de tosse: 2 a 3 vezes ao dia. Pediatria permitida conforme monografia (3-7 anos: 35 ml; 7-12 anos: 75 ml; adultos: 150 ml).","tempo_de_infusao":"10 minutos coberto.","temperatura_ideal":"95 °C."},"tagline":"Erva do Nordeste com aroma de baunilha e ação expectorante oficial — trevo-cumaru que atravessou três continentes e virou fitoterápico do SUS no Ceará.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Amazônia-Nordeste + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão herbal monografada"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Sem monografia"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar — pesquisador da UFC ou farmacêutico da rede Farmácias Vivas","revisor_cultural":"Sugerido — consultor da tradição shipibo-conibo para dimensão amazônica","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco 2)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia.","status_fda":"Sem reconhecimento específico.","sazonalidade":"Cultivo contínuo em clima tropical. Colheita de partes aéreas antes da floração.","status_anvisa":"Monografia oficial (Anvisa, 2011). Indicação: expectorante.","eixo_botanico_tpc":"Amazônia-Nordeste + Phyto-ANVISA","produtor_parceiro":"A definir — parceria com Programa Farmácias Vivas/UFC; cooperativas agroecológicas do CE.","status_japao_china":"Uso restrito.","certificacao_organica":"Pequena produção orgânica no CE e PE, integrada a programas de fitoterapia pública."},"marketplace":{"formatos":"Partes aéreas secas, sachê, xarope oficial de fitoterapia pública.","fornecedores":"Produtores orgânicos do CE com vínculo ao programa Farmácias Vivas.","faixa_de_preco":"Partes aéreas secas: R$ 30 a 80 por 100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Chambá","usos_topicos":{"evidencia":"Limitada para uso tópico — planta primordialmente oral.","aplicacoes":[{"texto":"Infusão padrão morna, gargarejar 30 segundos, 3 vezes ao dia. Uso tradicional nordestino.","titulo":"Gargarejo para faringite"},{"texto":"Infusão forte morna em compressa local. Uso tradicional caboclo.","titulo":"Compressa para hematomas leves"}],"contraindicacoes":"Uso tópico amplamente seguro."},"docx_filename":"Ficha_Chamba_v11.docx","identificacao":{"slug_url":"chamba","sinonimos":["Chachambá · trevo-cumaru · anador · camarú-da-folha-miúda","Sinonímia botânica: Dianthera pectoralis (Jacq.) J.F. Gmel., Ecbolium pectorale (Jacq.) Kuntze, Justicia stuebelii Lindau","O nome \"trevo-cumaru\" refere-se ao aroma característico de cumarina, semelhante à fava-tonka (Dipteryx odorata). Essa é a assinatura sensorial da planta."],"parte_usada":"Partes aéreas secas — 5 g para 150 ml, conforme monografia oficial. Uso permitido em crianças acima de 3 anos (única monografia brasileira com essa amplitude de faixa etária).","nome_popular":"Chambá","tipo_botanico":"Erva perene de 30 a 60 cm, com folhas opostas lanceoladas e flores pequenas brancas ou róseas.","nome_cientifico":"Justicia pectoralis Jacq.","familia_botanica":"Acanthaceae"},"caracterizacao":{"aroma":"Baunilha-cumarina, feno doce, leve nuance floral — aroma acolhedor, reconhecível do primeiro gole.","notas":"Cabeça: baunilha-aromática · Corpo: doce-amadeirado · Fundo: amargor sutil","intensidade":"3/5 — aromaticamente rica, gustativamente leve.","cor_da_infusao":"Amarelo-esverdeado pálido. #D6D890","bioma_de_origem":"Tropical americano — Amazônia, Caribe, América Central.","sabor_dominante":"Doce-aromático com nota pronunciada de baunilha e feno doce — perfil muito similar ao guaco, também pela cumarina. Amargor discreto de fundo, adstringência baixa.","distribuicao_geografica":["Brasil: cultivo e ocorrência em todo o Nordeste (CE, PB, PE, BA, MA), Amazônia, partes do Centro-Oeste e Sudeste.","América Central: Honduras, Nicarágua, Cuba, Jamaica.","Amazônia peruana e equatoriana: uso tradicional pelos povos shipibo-conibo em preparações rituais com ayahuasca (dimensão ritual específica amazônica).","Cultivo comercial expressivo no Ceará — planta foi integrada ao programa Farmácias Vivas da UFC (Universidade Federal do Ceará), referência nacional em fitoterapia do SUS."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Justicia pectoralis Jacq.","perfil_sensorial":{"tatil":"Corpo leve. Perfil sensorial acolhedor, persistência aromática média.","gustativo":[{"dimensao":"Doce","observacao":"Doçura aromática da cumarina","intensidade":"2/3"},{"dimensao":"Amargo","observacao":"Sutil","intensidade":"1/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Muito baixa","molecula":"Taninos mínimos","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: doce-aromática com baunilha (similar ao guaco)","descricao_integrada":"O chambá é o parceiro nordestino do guaco — ambos compartilham a cumarina como assinatura aromática e a ação expectorante como função principal. A diferença é geográfica e cultural: o guaco é planta do Sudeste-Sul associada a comunidades ítalo-luso-caboclas, enquanto o chambá é planta do Ceará associada à fitoterapia negra-indígena do Nordeste e ao programa Farmácias Vivas da UFC. Ambos são baunilha em forma de chá, ambos tratam tosse, ambos representam vias paralelas de pesquisa fitoterápica nacional. O chambá tem uma particularidade monográfica única: a Farmacopeia Brasileira explicitamente autoriza uso em crianças acima de 3 anos — raríssimo entre as ervas oficiais brasileiras, a maioria das quais é restrita a maiores de 12.","olfativo_descritores":["Baunilha (cumarina)","Feno doce","Trevo-cumaru fresco","Leve nota floral","Fundo herbáceo suave"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografia oficial de Justicia pectoralis","Programa Farmácias Vivas — Universidade Federal do Ceará (UFC)","Leal et al. — Phytochemical and pharmacological studies of Justicia pectoralis (Rev Bras Farmacogn, 2000)"],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Tosse produtiva","populacao":"Adultos e crianças acima de 3 anos"},{"evidencia":"Moderada","indicacao":"Bronquite aguda coadjuvante","populacao":"Adultos"},{"evidencia":"Preliminar","indicacao":"Ansiedade leve","populacao":"Adultos"}],"interacoes":[{"label":"Anticoagulantes (varfarina)","texto":"INTERAÇÃO IMPORTANTE — advertência expressa"},{"label":"Analgésicos (AINEs, paracetamol em dose alta)","texto":"INTERAÇÃO — advertência expressa"},{"label":"Aspirina","texto":"aumento do risco de sangramento"}],"dose_maxima":"Conforme a monografia: 35 ml (3-7 anos), 75 ml (7-12 anos e idosos), 150 ml (adultos e 12+), 2 a 3 vezes ao dia.","alerta_critico":null,"acoes_principais":["Expectorante — ação monografada","Broncodilatador leve","Antitussígeno suave","Anti-inflamatório respiratório","Antiespasmódico brônquico","Ansiolítico leve (estudos preliminares pela cumarina)"],"contraindicacoes":["CONTRAINDICADO em distúrbios de coagulação (advertência expressa da Farmacopeia)","CONTRAINDICADO em uso concomitante com anticoagulantes (advertência expressa)","CONTRAINDICADO em uso concomitante com analgésicos (advertência expressa)","Pré-cirúrgico (suspender 2 semanas antes)","Gestação e lactação: sob orientação"],"efeitos_adversos":"Raros em doses recomendadas. Em doses excessivas: alterações de coagulação, náusea.","componentes_ativos":[{"label":"Cumarina","texto":"Princípio ativo aromático principal — mesmo composto do guaco, responsável pelo aroma de baunilha e pela ação expectorante"},{"label":"Justicidina","texto":"Lignana característica do gênero Justicia, com ação anti-inflamatória"},{"label":"Flavonoides (quercetina, kaempferol)","texto":"Antioxidantes e anti-inflamatórios"},{"label":"Óleo essencial","texto":"Contribui para aroma e leve ação antimicrobiana"},{"label":"Saponinas","texto":"Ação expectorante por estímulo de secreção brônquica"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"b9cf7181-e750-44ec-8e0a-f0e44e84c0f2","slug":"carqueja","herb_id":null,"herb_latin_name":"Baccharis trimera","schema_version":"1.1","ficha":{"slug":"carqueja","cultura":{"brasil":"A carqueja é a erva amarga popular do Sul e Sudeste — equivalente ao boldo europeu na farmacopeia caseira brasileira. \"Chá de carqueja pra limpar o fígado\" é receita de avó em qualquer família do interior paulista, catarinense ou gaúcho. O uso popular antecede qualquer validação científica — e a pesquisa universitária, quando chegou, encontrou uma base sólida de princípios ativos coerentes com o uso popular.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples. Maceração a frio (12h) preserva princípios amargos.","quantidade":"2–3 g de ramos secos para 250 ml.","reinfusoes":"","combina_com":"Alcachofra · Boldo · Dente-de-leão · Funcho (blends depurativos hepáticos)","melhor_momento":"20–30 minutos antes das refeições (estimula produção de bílis e digestão).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"A amarga guardiã do fígado — depurativa hepática do Sul e Sudeste com décadas de pesquisa e um dos perfis de amargura mais limpos do catálogo.","receitas":[{"nome":"Emagrecimento Cerradão","slug":"emagrecimento-cerradao","proposito":null}],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Colheita: setembro–março (período vegetativo)","status_anvisa":"Uso tradicional reconhecido — Memento Fitoterápico.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Carqueja","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Carqueja · carqueja-amarga · carquejinha · vassoura-de-soldado","Carqueja (Argentina, Uruguai — uso idêntico)","Tres espigas (espanhol popular)"],"parte_usada":"Ramos alados secos (parte aérea — sem raiz, sem folhas diferenciadas).","tipo_botanico":"Fitoterápico depurativo hepático / digestivo amargo","nome_cientifico":"Baccharis trimera (Less.) DC.","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Herbáceo seco, feno verde, levemente resinoso. Simples e direto.","notas":"","intensidade":"3/5 — amargo intenso, mas perfil limpo.","cor_da_infusao":"Verde-amarelado a âmbar-verdoso. #8BAF5A","bioma_de_origem":"Mata Atlântica e Pampas — espécie do Sul e Sudeste do Brasil, Argentina e Uruguai.","sabor_dominante":"Amargo puro, intenso, limpo — sem notas aromáticas que distraiam. É a amargura de referência do catálogo. Paradoxalmente, é uma amargura \"boa\" — apreciadíssima por quem gosta de amargos.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Baccharis trimera (Less.) DC.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Colagogo/colerético (estimula produção e fluxo de bílis)","Hepatoprotetor","Digestivo amargo (estimula secreções digestivas)","Hipoglicemiante (evidência moderada)","Anti-inflamatório","Antioxidante","Componentes ativos:","Contraindicações:","Gestação — contraindicada (abortiva em doses altas documentado em modelos animais)","Lactação — evitar","Obstrução biliar — contraindicada (estimula fluxo biliar)","Hepatite aguda ativa — cautela (uso apenas sob orientação)"],"contraindicacoes":["Gestação — contraindicada (abortiva em doses altas documentado em modelos animais)","Lactação — evitar","Obstrução biliar — contraindicada (estimula fluxo biliar)","Hepatite aguda ativa — cautela (uso apenas sob orientação)"],"efeitos_adversos":"","componentes_ativos":[{"label":"LACTONAS DITERPÊNICAS (carquejol)","texto":"Amargo digestivo, colagogo"},{"label":"FLAVONÓIDES (quercetina, nepetina)","texto":"Anti-inflamatório, antioxidante"},{"label":"SAPONINAS TRITERPÊNICAS","texto":"Hepatoprotetor"},{"label":"ÁCIDO CAFEOILQUÍNICO","texto":"Antioxidante, hepatoprotetor"},{"label":"TANINOS","texto":"Adstringente, antimicrobiano"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"68ae8e67-bb02-41f6-ab8f-9b1d9f85947a","slug":"macela-gaucha","herb_id":null,"herb_latin_name":"Achyrocline satureioides","schema_version":"1.1","ficha":{"slug":"macela-gaucha","cultura":{"brasil":"","historia":"A macela é a erva do Rio Grande do Sul como o guaraná é do Amazonas — elemento de identidade regional. No Sul do Brasil e no Prata (Argentina, Uruguai), a macela é o \"digestivo de família\" — tomada após almoços fartos, especialmente após churrasco. A tradição de colher macela na véspera de São João (23 de junho) — quando a planta está em plena floração no hemisfério sul — é prática folclórica documentada em comunidades rurais gaúchas.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples, coberta.","quantidade":"1–2 colheres de chá (1–3 g) de flores secas para 150 ml.","reinfusoes":"","combina_com":"Camomila · Erva-mate tostada · Carqueja · Erva-cidreira","melhor_momento":"Pós-refeições (digestivo) ou noite (ansiolítico leve).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"A camomila dos Pampas — digestiva e anti-inflamatória da tradição gaúcha com pesquisa uruguaia e argentina entre as mais extensas da fitoterapia sul-americana.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Floração: maio–agosto (inverno sulino)","status_anvisa":"Monografia oficial. Indicação: antiespasmódico digestivo.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Macela-Gaúcha","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Macela · macela-gaúcha · marcela · marcela-do-campo","Macela (Argentina/Uruguai) · marcela (Paraguai)","Yerba-de-la-vida (espanhol popular)"],"parte_usada":"Inflorescências (capítulos florais), preferencialmente colhidas antes da abertura total.","tipo_botanico":"Fitoterápico digestivo / anti-inflamatório","nome_cientifico":"Achyrocline satureioides (Lam.) DC.","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Floral-herbáceo, feno seco do pampa, discretamente mielado.","notas":"","intensidade":"2/5 — suave, de uso cotidiano.","cor_da_infusao":"Amarelo-palha a âmbar claro. #D4B86A","bioma_de_origem":"Pampas (RS) e Mata Atlântica interior (SC, PR) — espécie característica dos campos sulinos.","sabor_dominante":"Amargo-herbáceo suave, floral discreto, levemente resinoso. Mais palatável que a carqueja — amargura gentil.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Achyrocline satureioides (Lam.) DC.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antiespasmódico digestivo","Anti-inflamatório","Ansiolítico leve (flavonóides GABAérgicos)","Antimicrobiano (estafilococos, E. coli)","Antifúngico","Antiviral (estudos in vitro)","Componentes ativos:","Contraindicações: Alergia à família Asteraceae. Gestação — cautela (dados insuficientes). Uso simultâneo com sedativos — potencialização leve."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"QUERCETINA, 3-METOXIQUERCETINA","texto":"Anti-inflamatório, antioxidante, GABAérgico"},{"label":"LUTEOLINA","texto":"Anti-inflamatório"},{"label":"3-O-METILQUERCETINA","texto":"Antiespasmódico"},{"label":"ÁCIDO CLOROGÊNICO","texto":"Antioxidante"},{"label":"ÓLEOS ESSENCIAIS (beta-cariófileno, alfa-pineno)","texto":"Antimicrobiano, anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"5cd53cbc-adf9-42df-9b7f-e7ea47a49272","slug":"erva-cidreira","herb_id":null,"herb_latin_name":"Lippia alba","schema_version":"1.1","ficha":{"slug":"erva-cidreira","cultura":{"brasil":"A erva-cidreira é provavelmente a erva medicinal mais cultivada em quintais do Brasil — presente de Oiapoque ao Chuí. Não há classe social, região ou geração que não conheça o \"chá de cidreira\" para nervos. É a erva que democratiza a fitoterapia — não precisa de farmácia ou ervanário. Está na janela, no vaso, no fundo do quintal.  Essa onipresença popular e acessibilidade fazem da erva-cidreira um dos maiores desafios do Ervatório: o usuário acha que \"já sabe tudo\" sobre ela. A ficha completa revela que não sabe — os quimiotipos de Lippia alba variam enormemente, a química dos óleos essenciais é complexa, e a confusão com melissa europeia é universal.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples coberta — imprescindível cobrir para reter citral.","quantidade":"3–5 folhas frescas (ou 2 g de folha seca) para 150 ml.","reinfusoes":"1 possível.","combina_com":"Melissa · Camomila · Hortelã · Lavanda · Maracujá · Mel · Limão (potencializa perfil cítrico)","melhor_momento":"Qualquer hora — especialmente noite para ansiedade/sono.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (não ferver — óleos essenciais voláteis)."},"tagline":"O ansiolítico de quintal — a mais acessível das ervas calmantes brasileiras, presente em quintais de Norte a Sul, com química surpreendentemente complexa.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo (cultivo perene)","status_anvisa":"Uso tradicional reconhecido. Em análise para Formulário de Fitoterápicos.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Erva-Cidreira","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Erva-cidreira · cidreira-brava · falsa-melissa · cidró · chá-de-tabuleiro","ATENÇÃO: NÃO confundir com melissa (Melissa officinalis) — espécie europeia com quimiotipos e química distintos. A \"erva-cidreira\" brasileira é Lippia alba, não melissa."],"parte_usada":"Folhas frescas ou secas; ramos finos.","tipo_botanico":"Fitoterápico ansiolítico / antiespasmódico","nome_cientifico":"Lippia alba (Mill.) [N.E.Br](http://N.E.Br).","familia_botanica":"Verbenaceae"},"caracterizacao":{"aroma":"Limão-cítrico fresco, citral intenso, levemente mentolado no fundo (quimiotipos ricos em citral).","notas":"","intensidade":"2/5 — suave, perfil cítrico agradável.","cor_da_infusao":"Verde-amarelado pálido a amarelo-claro. #E8D86A","bioma_de_origem":"Mata Atlântica, Cerrado, Caatinga, Pampas — espécie de ampla distribuição, adaptada a múltiplos climas.","sabor_dominante":"Limão-cítrico fresco, levemente amargo herbáceo, aromático agradável. Uma das infusões mais palatáveis do catálogo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Lippia alba (Mill.) [N.E.Br](http://N.E.Br).","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico (ação GABAérgica do citral)","Antiespasmódico (digestivo e brônquico)","Sedativo leve","Antiviral (linalol, citral)","Antimicrobiano","Carminativo (flatulência)","Componentes ativos:","Contraindicações: Gestação — cautela com óleos essenciais concentrados (citral). Uso moderado em infusão é tolerado. Crianças < 2 anos — evitar óleos essenciais concentrados."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"CITRAL (geranial + neral)","texto":"Ansiolítico — modulação GABA-A, antiviral"},{"label":"LINALOL","texto":"Sedativo, antimicrobiano"},{"label":"CARVONA","texto":"Antiespasmódico, carminativo"},{"label":"LIMONENO","texto":"Antidepressivo leve, antimicrobiano"},{"label":"TIMOL (quimiotipos)","texto":"Antimicrobiano potente"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"14fe3936-0d8e-4549-b350-2c6fa7eca8d3","slug":"losna","herb_id":null,"herb_latin_name":"Artemisia absinthium","schema_version":"1.1","ficha":{"slug":"losna","cultura":{"brasil":"A losna ocupa um nicho cultural específico — é a erva dos descendentes europeus do Sul, não da tradição indígena ou africana. Seu uso popular é geograficamente concentrado e etnicamente marcado, o que a torna um documento cultural sobre a pluralidade da fitoterapia brasileira.","historia":"A losna é a planta mais carregada de história cultural do catálogo. Os egípcios a usavam como antiparasitário e afrodisíaco. Hipócrates a prescrevia para icterícia e gota. É mencionada no Apocalipse de João como \"Absinto\" — a estrela amarga que cai no fim dos tempos e envenena as águas.  Nos séculos XVIII e XIX, o absinto — destilado de Artemisia absinthium com teor alcoólico de 45–75% — tornou-se a bebida da boêmia europeia. Van Gogh, Verlaine, Toulouse-Lautrec, Oscar Wilde, Ernest Hemingway — todos eram bebedores de absinto. A loucura do genial foi atribuída à thujona do absinto (hoje sabe-se que o álcool era o principal responsável). O absinto foi proibido em quase toda a Europa de 1905 a 1990.  Na Serra Gaúcha (RS), os descendentes de imigrantes italianos e alemães mantêm a tradição de digestivos amargos com losna — chamados localmente de \"amargo\" ou \"amargo-gaúcho\".","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples, curta.","quantidade":"0,5–1 g de partes aéreas secas para 250 ml. Dose baixa é essencial.","reinfusoes":"","combina_com":"Gengibre · Hortelã · Funcho (suaviza o amargo) · Mel","melhor_momento":"20–30 minutos antes das refeições (digestivo amargo). Não usar à noite (estimulante).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"A rainha dos amargos — digestivo mítico europeu naturalizado no Sul do Brasil, base do absinto e do vermouth, com uma das histórias culturais mais ricas do catálogo.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use para dispepsia.","status_fda":"","sazonalidade":"Partes aéreas coletadas em floração (verão sulino — novembro–março)","status_anvisa":"Não monografado. Regulação como fitoterápico em discussão.","eixo_botanico_tpc":"Funcional global / uso tradicional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Losna","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Losna · absinto · erva-santa · artemísia-amarga","Wormwood (inglês) · Absinth (alemão) · Absinthe (francês) · Ajenjo (espanhol)"],"parte_usada":"Partes aéreas (folhas e ramos finos), secas.","tipo_botanico":"Digestivo amargo / antiparasitário / tônico estomacal","nome_cientifico":"Artemisia absinthium L.","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Mentolado-resinoso, herbáceo intenso, levemente defumado-feno. Característico e inconfundível.","notas":"","intensidade":"5/5 para amargura; 4/5 para aroma. Infusão de presença esmagadora.","cor_da_infusao":"Verde-prateado a verde-amarelado. #7A9B5C","bioma_de_origem":"","sabor_dominante":"O mais amargo do catálogo — amargor intenso, persistente, com nota mentolada fria e fundo resinoso. Só apreciável por amantes de amargos ou em uso medicinal.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Artemisia absinthium L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Digestivo amargo (estimula secreções gástricas, pancreáticas e biliares)","Antiparasitário intestinal (Ascaris, Enterobius)","Antimicrobiano","Antipirético","Tônico estomacal","Anti-inflamatório","Componentes ativos:","⚠️ ATENÇÃO — THUJONA:","Contraindicações:","Gestação — contraindicada (abortiva, neurotóxica ao feto)","Epilepsia — contraindicada (pró-convulsivante)","Lactação — evitar","Uso prolongado (>4 semanas) sem orientação","Crianças — contraindicada","Álcool em excesso — sinergismo de toxicidade"],"contraindicacoes":["Gestação — contraindicada (abortiva, neurotóxica ao feto)","Epilepsia — contraindicada (pró-convulsivante)","Lactação — evitar","Uso prolongado (>4 semanas) sem orientação","Crianças — contraindicada","Álcool em excesso — sinergismo de toxicidade"],"efeitos_adversos":"","componentes_ativos":[{"label":"ABSINTINA, ARTABSINA (lactonas sesquiterpênicas)","texto":"Amargo digestivo intenso"},{"label":"THUJONA (alfa e beta)","texto":"Neurotóxica em dose alta; aromatizante em dose baixa"},{"label":"AZULENO","texto":"Anti-inflamatório"},{"label":"CHAMAZULENO","texto":"Anti-inflamatório (semelhante à camomila)"},{"label":"ÁCIDO CLOROGÊNICO","texto":"Antioxidante"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório, antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"f451b375-27ab-4831-97e2-7337e7dd197a","slug":"cambara","herb_id":null,"herb_latin_name":"Vochysia divergens","schema_version":"1.1","ficha":{"slug":"cambara","cultura":{"brasil":"O cambará tem paradoxo ecológico único: é uma espécie nativa do pantanal que se tornou invasora da própria paisagem — sua proliferação excessiva em áreas de campo alagado altera o bioma. Esse fenômeno, estudado pela UFMT, revela como mudanças climáticas e alterações hidrológicas transformam espécies nativas em desequilibradores de seus próprios ecossistemas. Do ponto de vista medicinal, é uma das poucas ervas do pantanal com pesquisa farmacológica documentada por universidades do Mato Grosso.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta ou decocção leve.","quantidade":"2–5 g de folhas secas para 250 ml.","reinfusoes":"","combina_com":"Mel · Gengibre · Eucalipto · Guaco (blends respiratórios)","melhor_momento":"Manhã e tarde em episódios de tosse/bronquite.","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"O expectorante do pantanal — árvore invasora que floriu como medicamento, com tradição mato-grossense de uso respiratório e pesquisa universitária crescente.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo; melhor colheita no período seco","status_anvisa":"Uso tradicional reconhecido — em processo de avaliação para Formulário","eixo_botanico_tpc":"Fitoterápico tradicional regional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Cambará","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Cambará · cambará-do-pantanal · cambará","ATENÇÃO: há diversas espécies chamadas \"cambará\" no Brasil — Vochysia divergens é a espécie do pantanal; Lantana camara e Moquiniastrum polymorphum são chamadas cambará no Sul com usos diferentes."],"parte_usada":"Folhas secas; casca em decocção.","tipo_botanico":"Fitoterápico expectorante / broncodilatador","nome_cientifico":"Vochysia divergens Pohl","familia_botanica":"Vochysiaceae"},"caracterizacao":{"aroma":"Resinoso suave, eucalipto-like, herbáceo fresco.","notas":"","intensidade":"3/5 — uso medicinal tolerável.","cor_da_infusao":"Amarelo-esverdeado a âmbar. #B0A850","bioma_de_origem":"Pantanal — espécie característica e atualmente invasora das planícies inundáveis de MT e MS.","sabor_dominante":"Amargo-resinoso moderado, herbáceo, levemente mentolado. Palatável com mel.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Vochysia divergens Pohl","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Expectorante (fluidifica secreções brônquicas)","Broncodilatador leve","Antitussígeno","Anti-inflamatório das vias aéreas","Antimicrobiano","Componentes ativos:","Contraindicações: Gestação — dados insuficientes. Crianças < 6 anos — usar com cautela. Asma grave — não substituir broncodilatadores farmacológicos."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"FLAVONÓIDES (luteolina, apigenina)","texto":"Anti-inflamatório, broncodilatador"},{"label":"SAPONINAS TRITERPÊNICAS","texto":"Expectorante"},{"label":"TANINOS","texto":"Adstringente, antimicrobiano"},{"label":"ÓLEOS ESSENCIAIS","texto":"Broncodilatador, antisséptico"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"912fbf28-d4b8-49dd-bf37-21982d2fffb9","slug":"mangava-brava","herb_id":null,"herb_latin_name":"Lafoensia pacari","schema_version":"1.1","ficha":{"slug":"mangava-brava","cultura":{"brasil":"A planta é cultivada ornamentalmente pelo florescimento espetacular (flores brancas perfumadas, à noite) — seu valor estético é reconhecido antes do medicinal. Poucos moradores de cidades do Centro-Oeste que têm um dedaleiro no jardim sabem que têm, à mão, um gastroprotetor com evidência clínica.","historia":"A mangava-brava é a erva do pantanal que poucos conhecem fora da região — mas que carrega décadas de pesquisa farmacológica pela UFMT (Cuiabá) e UFMS (Campo Grande). O uso popular pelos povos ribeirinhos do pantanal como \"remédio para o estômago\" levou pesquisadores à descoberta de uma das mais ricas fontes de ácido elágico e punicalagins do cerrado-pantanal — compostos com atividade antiulcerosa confirmada em modelos animais e estudos piloto humanos.  A mangava-brava é o exemplo mais eloquente do catálogo do Ervatório sobre o ciclo perfeito da fitoterapia brasileira: uso popular observado → pesquisa universitária regional → validação farmacológica → ficha Ervatório. É a descoberta que o Ervatório existe para fazer circular.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção.","quantidade":"3–5 g de casca seca para 500 ml.","reinfusoes":"","combina_com":"Espinheira-santa · Alcaçuz · Camomila (blends gastroprotetores)","melhor_momento":"30 minutos antes das refeições, 2–3x ao dia.","tempo_de_infusao":"","temperatura_ideal":"Decocção a 95–98 °C."},"tagline":"O segredo gastroprotetor do pantanal — cicatrizante de mucosa gástrica com evidência clínica sólida e uma das fichas mais surpreendentes para quem não conhece o bioma.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Casca coletada no período seco; floração setembro–novembro","status_anvisa":"Uso tradicional reconhecido. Memento Fitoterápico.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Mangava-Brava","usos_topicos":{"evidencia":"","aplicacoes":["Bochecho para úlceras orais e mucosite: Decocção fraca (2 g/200 ml), morna. Ação adstringente-cicatrizante de mucosa.","Compressa cicatrizante: Decocção resfriada, gaze, aplicação local em feridas superficiais."],"contraindicacoes":""},"identificacao":{"sinonimos":["Mangava-brava · dedaleiro · pacari · mangaveira-brava","Dedaleiro (uso no cerrado) · pacari (Mato Grosso)"],"parte_usada":"Casca do caule, seca e pulverizada.","tipo_botanico":"Fitoterápico gastroprotetor / cicatrizante de mucosa","nome_cientifico":"Lafoensia pacari [A.St](http://A.St).-Hil.","familia_botanica":"Lythraceae (família da romã)"},"caracterizacao":{"aroma":"Casca seca, terroso discreto, levemente resinoso.","notas":"","intensidade":"3/5 — medicinal com palatabilidade aceitável.","cor_da_infusao":"Marrom-avermelhado claro. #9B5535","bioma_de_origem":"Pantanal e Cerrado — MT, MS, GO, MG, SP.","sabor_dominante":"Adstringente moderado, amargo suave, terroso. Mais palatável que barbatimão ou aroeira.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Lafoensia pacari [A.St](http://A.St).-Hil.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Gastrite e úlcera gástrica","populacao":"Jorge et al. (UFMT)"},{"evidencia":"Moderada","indicacao":"Cicatrização de mucosa oral","populacao":"Pesquisa regional"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Gastroprotetor (proteção e cicatrização da mucosa gástrica)","Antiulceroso","Anti-inflamatório gástrico","Antioxidante","Antimicrobiano (H. pylori — pesquisa em andamento)","Cicatrizante (mucosa e pele)","Componentes ativos:","Indicações com evidência:","Contraindicações: Gestação — dados insuficientes. Lactação — evitar. Obstrução biliar — cautela com taninos em alta dose."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"TANINOS TOTAIS (elágicos e condensados)","texto":"Gastroprotetor, adstringente, cicatrizante"},{"label":"ÁCIDO ELÁGICO","texto":"Antiulceroso, antioxidante, antiproliferativo"},{"label":"PUNICALAGINS","texto":"Antioxidante potente, antimicrobiano"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório, antioxidante"},{"label":"SAPONINAS","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"533cee88-57a0-4fe1-8022-e4689f6e7f44","slug":"acai","herb_id":null,"herb_latin_name":"Euterpe oleracea","schema_version":"1.1","ficha":{"slug":"acai","cultura":{"brasil":"O açaí é o produto da bioeconomia amazônica com maior sucesso comercial global — e também o exemplo mais complexo de tensão entre mercado e território. O preço do açaí no mercado internacional elevou tanto o preço local que famílias ribeirinhas pobres do Marajó, que sempre comeram açaí como alimento básico, hoje não conseguem mais comprá-lo. É o paradoxo da mercantilização do sagrado.","historia":"O açaí é alimento-base de populações ribeirinhas do estuário amazônico há milênios. A \"dieta do açaí\" — farinha de tapioca + açaí + peixe seco — foi e ainda é o sustento calórico diário de famílias marajoaras. Para o ribeirinho, o açaí não é superalimento; é comida. A reframagem ocidental como \"superfood\" inverte a lógica: o que era cotidiano vira extraordinário; o que era barato vira premium.  O açaí chegou ao Brasil urbano na Bahia dos anos 1970, trazido por lutadores de jiu-jitsu paraenses que o usavam como fonte de energia pré-treino. A academia de Gracie Barra em São Paulo popularizou o \"tigela de açaí\" nos anos 1990. Dos tatames cariocas para os mercados globais — em 30 anos.","cerimonial":"Na cultura ribeirinha, o \"açaí das 6 da tarde\" é ritual diário de comunhão — a família se reúne em torno da tigela de açaí após o trabalho. Sem açaí, não há refeição completa. Essa dimensão cultural — invisível na exportação como \"superfood\" — é o que o Ervatório precisa narrar.","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Cacau · Guaraná · Banana · Mel · Goji berry (blends antioxidantes) · Cumaru · Castanha-do-pará","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O superfruto que saiu do igapó para conquistar o mundo — antioxidante máximo da Amazônia, alimento sagrado ribeirinho e o maior fenômeno de exportação de um alimento funcional brasileiro.","receitas":[],"regulacao":{"status_ema":"","status_fda":"GRAS para uso alimentar","sazonalidade":"Safra principal: julho–dezembro (Pará). Segunda safra: fevereiro–abril.","status_anvisa":"Regulado como alimento. Polpa liofilizada como suplemento — RDC 240/2018.","eixo_botanico_tpc":"Alimento funcional / Fitoterápico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Açaí","usos_topicos":{"evidencia":"","aplicacoes":["Sérum anti-aging: Óleo de açaí (prensagem a frio) em formulações dermocosméticas — alto ORAC, ácido oleico e palmítico em proporção favorável. Marca brasileira Natura exporta para Europa com açaí como ingrediente flagship.","Máscara capilar nutritiva: Óleo de açaí + manteiga de cupuaçu — hidratação profunda para cabelos crespos e cacheados. Segmento em crescimento acelerado no mercado afro-beauty global.","Protetor solar natural (adjuvante): Óleo de açaí em formulações com FPS — antocianinas absorvem UV-B. Evidência moderada como co-protetor."],"contraindicacoes":""},"identificacao":{"sinonimos":["Açaí · açaizeiro · juçara (espécie diferente, E. edulis, Mata Atlântica)","Acai (inglês/francês/espanhol — grafia sem cedilha no exterior)","Manaka (línguas indígenas do estuário)","ATENÇÃO: Euterpe oleracea (açaí-do-pará, touceira, estuário) ≠ Euterpe precatoria (açaí-solteiro, Amazônia ocidental) — perfis nutricionais similares mas ecologias distintas."],"parte_usada":"Polpa do fruto (principal); palmito (alimentar); folhas (infusão popular); óleo do fruto (cosmético e medicinal).","tipo_botanico":"Alimento funcional antioxidante / fitoterápico","nome_cientifico":"Euterpe oleracea Mart.","familia_botanica":"Arecaceae (família das palmeiras)"},"caracterizacao":{"aroma":"Cacau selvagem, fruta vermelha concentrada, terra úmida de várzea, leve fermentado nobre.","notas":"Cabeça: frutado-roxo concentrado | Corpo: terroso-cacauado profundo | Fundo: amargo limpo, tanino suave | BIOMA: Amazônia de várzea e igapó — florestas inundáveis do estuário amazônico. PA, AM, AP, MA. | DISTRIBUIÇÃO GEOGRÁFICA:","intensidade":"4/5 — presença marcante, perfil denso.","cor_da_infusao":"Roxo-escuro a preto-violeta intenso. #2A0A2E","bioma_de_origem":"Amazônia de várzea e igapó — florestas inundáveis do estuário amazônico. PA, AM, AP, MA.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Euterpe oleracea Mart.","perfil_sensorial":{"tatil":"Polpa: textura densa, quase cremosa, que reveste a boca — propriedade única no catálogo frutal. Infusão de folhas: mais leve, sem a densidade da polpa. O açaí é o único ingrediente do catálogo que muda fundamentalmente de expressão entre a forma fruta e a forma fitoterápica — são quase dois produtos distintos em termos de experiência sensorial.","gustativo":[{"dimensao":"Doce","observacao":"Presente na polpa madura","intensidade":"1/3"},{"dimensao":"Amargo","observacao":"Tanino suave, característico","intensidade":"2/3"},{"dimensao":"Umami","observacao":"Notas terrosas profundas","intensidade":"1/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Adstringência","observacao":"Taninos condensados","intensidade":"Moderada"}],"trigeminal":[],"olfativo_familia":"- Fruta vermelha concentrada (amora, mirtilo selvagem)","descricao_integrada":"","olfativo_descritores":["Fruta vermelha concentrada (amora, mirtilo selvagem)","Cacau amargo cru","Terra úmida de floresta de várzea","Leve fermentado nobre (como vinho jovem)","Fundo mineral"]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte","indicacao":"Redução de estresse oxidativo","populacao":"Schauss et al., 2006"},{"evidencia":"Moderada","indicacao":"Melhora de perfil lipídico","populacao":"Rocha et al., 2007"},{"evidencia":"Preliminar","indicacao":"Neuroproteção cognitiva","populacao":"Poulose et al., 2012"},{"evidencia":"Moderada","indicacao":"Anti-inflamatório sistêmico","populacao":"Mullen et al., 2002"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Antioxidante de altíssimo ORAC (Oxygen Radical Absorbance Capacity)","Antiinflamatório (inibição de COX-1/COX-2)","Cardioprotetor (melhora perfil lipídico)","Neuroprotetor (antocianinas atravessam barreira hematoencefálica)","Hipoglicemiante leve","Imunomodulador","Energético (lipídeos de cadeia média)","Componentes ativos:","Indicações com evidência:","Contraindicações: Sem contraindicações conhecidas em doses alimentares. Alergia ao pólen de palmeira (rara — reação cruzada possível). Evitar combinação com anticoagulantes em doses suplementares altas."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"ANTOCIANINAS (cianidina-3-glucosídeo)","texto":"3.190 mg/100 g ORAC — Antioxidante máximo, neuroprotetor"},{"label":"ÁCIDO OLEICO (C18:1)","texto":"56% do óleo — Cardioprotetor"},{"label":"ÁCIDO PALMÍTICO (C16:0)","texto":"24% — Emoliente"},{"label":"RESVERATROL","texto":"Presente — Cardioprotetor, anti-aging"},{"label":"QUERCETINA, CATEQUINAS","texto":"Presentes — Antioxidante, anti-inflamatório"},{"label":"VITAMINA E (tocoferóis)","texto":"Alta — Antioxidante lipossolúvel"},{"label":"FIBRAS DIETÉTICAS","texto":"44 g/100 g (polpa seca) — Prebiótico, saciedade"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"fc232a7d-b406-4214-acad-1b938be27182","slug":"cumaru","herb_id":null,"herb_latin_name":"Dipteryx odorata","schema_version":"1.1","ficha":{"slug":"cumaru","cultura":{"brasil":"","historia":"O cumaru é a semente que nomeou uma molécula — o químico Vogel, ao isolar em 1820 o composto aromático da fava de cumaru, nomeou-o \"cumarina\" (coumarin). A partir daí, a cumarina tornou-se molécula-referência em química orgânica e uma das mais usadas em perfumaria do século XX.  A fava tonka (cumaru) é ingrediente histórico da perfumaria europeia de luxo — Chanel Nº5 e Guerlain Shalimar têm cumarina como nota de fundo. Durante décadas, perfumistas compravam favas de cumaru do Brasil para destilar cumarina sintética — hoje usam cumarina sintética, mas a fava natural tem mercado premium crescente.  Na cozinha, o cumaru é o \"truffe noire da Amazônia\" — chefs de alta gastronomia como Alex Atala (D.O.M., São Paulo) popularizaram a fava de cumaru ralada sobre sobremesas, risotos e drinks, elevando um produto extrativista amazônico a ingrediente de elite gastronômica global.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta de semente ralada fina (microplaina). Decocção curta da casca.","quantidade":"0,5–1 g de semente ralada para 250 ml (poderoso — dose baixa).","reinfusoes":"","combina_com":"Cacau · Canela · Cardamomo · Açaí · Guaraná · Baunilha · Mel (blends amazônico-premium)","melhor_momento":"Noite (sedativo leve) ou pós-refeições (digestivo aromático).","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (cumarina é volátil — não ferver)."},"tagline":"A baunilha da floresta — semente aromática amazônica com cumarina intensa, uso histórico em perfumaria europeia e potencial gastronômico e fitoterápico ainda subutilizado.","receitas":[],"regulacao":{"status_ema":"","status_fda":"Proibido como aditivo alimentar nos EUA (mas fava inteira permitida como especiaria)","sazonalidade":"Colheita de sementes: agosto–novembro","status_anvisa":"Regulado como especiaria alimentar. Limite de cumarina em alimentos: EFSA 0,1 mg/kg/dia","eixo_botanico_tpc":"Aromático / Funcional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Cumaru","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Cumaru · cumarú · fava-tonka · fava de cumaru","Tonka bean (inglês/francês — nome do mercado de perfumaria)","Coumarou (francês histórico — origem da palavra \"cumarina\")","ATENÇÃO: a cumarina presente no cumaru é a mesma substância da imburana-de-cheiro (Amburana cearensis) — mas em concentração muito maior na fava de cumaru."],"parte_usada":"Semente seca (fava de cumaru / tonka bean); casca do fruto (uso popular).","tipo_botanico":"Especiaria aromática / fitoterápico","nome_cientifico":"Dipteryx odorata (Aubl.) Willd.","familia_botanica":"Fabaceae / Papilionoideae"},"caracterizacao":{"aroma":"Baunilha bourbon madura, cumarina cristalizada, amêndoa torrada, caramelo, leve almíscar de madeira. Perfume de luxo em semente.","notas":"","intensidade":"4/5 — aroma dominante, sabor inconfundível.","cor_da_infusao":"Âmbar-dourado a marrom-mel. #C8882A","bioma_de_origem":"Amazônia — floresta de terra firme. AM, PA, RO, AC, também Guianas e Venezuela.","sabor_dominante":"Doce-baunilha intensíssimo, cumarina pura, amêndoa tostada, caramelo, fava de baunilha bourbon com nota de almíscar. Um dos sabores mais complexos e sedutores do catálogo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Dipteryx odorata (Aubl.) Willd.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antiespasmódico","Broncodilatador leve (cumarina)","Sedativo suave","Anticoagulante fraco","Aromático (perfumaria, cosmética)","Analgésico tópico","Componentes ativos:","⚠️ ATENÇÃO — CUMARINA EM ALTA CONCENTRAÇÃO:","Contraindicações:","Gestação — cumarina uterotônica","Anticoagulados — potencialização significativa","Hepatopatias — hepatotóxico em doses altas","Uso diário intenso por períodos prolongados"],"contraindicacoes":["Gestação — cumarina uterotônica","Anticoagulados — potencialização significativa","Hepatopatias — hepatotóxico em doses altas","Uso diário intenso por períodos prolongados"],"efeitos_adversos":"","componentes_ativos":[{"label":"CUMARINA","texto":"1–3% (semente seca) — Broncodilatador, antiespasmódico, anticoagulante fraco"},{"label":"ÁCIDO CUMÁRICO","texto":"Presente — Antioxidante"},{"label":"FLAVONÓIDES","texto":"Presentes — Anti-inflamatório"},{"label":"ALCALÓIDES (traços)","texto":"Traços — Tonificante leve"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"a44a923c-3f7c-4f95-93f5-3f00bf896acd","slug":"unha-de-gato","herb_id":null,"herb_latin_name":"Uncaria tomentosa","schema_version":"1.1","ficha":{"slug":"unha-de-gato","cultura":{"brasil":"Amplamente vendida em farmácias de manipulação e ervanários. O produto importado do Peru (mais pesquisado) compite com a produção nacional. É um dos itens mais vendidos em lojas de produtos naturais brasileiras para \"imunidade\".","historia":"A unha-de-gato é a planta medicinal peruana mais estudada internacionalmente — o Instituto Nacional de Saúde do Peru (INS) dedicou décadas à sua pesquisa. O nome vem dos espinhos curvos em forma de garra que a planta usa para trepar — morfologia que se tornou ícone visual de sua identidade.  Conhecida pelos Ashaninka e Shipibo-Conibo do Peru como \"uña de gato\" e usada ritualmente por xamãs para fortalecer o sistema imune antes de expedições e rituais. A etnobotânica documental dos povos amazônicos peruanos foi o ponto de partida para toda a pesquisa farmacológica moderna.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção (alcalóides oxindólicos extraídos melhor por decocção que infusão).","quantidade":"3–5 g de casca seca para 500 ml.","reinfusoes":"","combina_com":"Mel · Gengibre · Cúrcuma · Echinacea (blends imunidade global)","melhor_momento":"Manhã em jejum (imunomodulador) ou 2x ao dia em uso terapêutico.","tempo_de_infusao":"","temperatura_ideal":"Decocção a 95–98 °C."},"tagline":"A garra da imunidade — adaptógeno amazônico com um dos maiores portfólios de pesquisa internacional entre as ervas do catálogo; monografada em 4 continentes.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Casca coletada no período seco","status_anvisa":"Uso tradicional reconhecido. Em avaliação para Formulário.","eixo_botanico_tpc":"Phyto-ANVISA + Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Unha-de-Gato","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Unha-de-gato · cat's claw · uña de gato (espanhol)","Vilcacora (quéchua — Peru)","ATENÇÃO: Uncaria tomentosa ≠ Uncaria guianensis — espécie irmã com alcalóides distintos. A maioria das pesquisas clínicas é com U. tomentosa."],"parte_usada":"Casca do caule (entrecasca) e raiz.","tipo_botanico":"Fitoterápico imunomodulador / anti-inflamatório / adaptógeno","nome_cientifico":"Uncaria tomentosa (Willd. ex Schult.) DC.","familia_botanica":"Rubiaceae (família do café, do quínio)"},"caracterizacao":{"aroma":"Casca de madeira tropical, terroso limpo, leve resina.","notas":"","intensidade":"3/5 — medicinal, de uso regular possível.","cor_da_infusao":"Marrom-avermelhado a âmbar escuro. #8B4A22","bioma_de_origem":"Amazônia — floresta tropical úmida de terra firme. Peru, Bolívia, Brasil (AM, PA, AC).","sabor_dominante":"Amargo moderado, terroso-resinoso, levemente adstringente. Não é desagradável — palatável com mel.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Uncaria tomentosa (Willd. ex Schult.) DC.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Artrite reumatoide (adjuvante)","populacao":"Mur et al., 2002"},{"evidencia":"Moderada","indicacao":"Osteoartrite joelho","populacao":"Piscoya et al., 2001"},{"evidencia":"Moderada","indicacao":"Imunoestimulação (quimioterapia adjuvante)","populacao":"Sheng et al., 2000"},{"evidencia":"Preliminar","indicacao":"Proteção do DNA contra radiação","populacao":"Modelos in vitro"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Imunomodulador (estimula e regula função imune)","Anti-inflamatório potente (inibição NF-κB)","Antioxidante","Antimutagênico (proteção do DNA)","Antiviral","Antiartrítico (redução de dor e inflamação articular)","Gastroprotetor leve","Componentes ativos:","Indicações com evidência:","Contraindicações:","Transplantados — imunomodulação pode conflitar com imunossupressão","Gestação — alcalóides controversos","Uso concomitante com anticoagulantes — cautela","Hipertensão — monitorar (alcalóides vasoativos)"],"contraindicacoes":["Transplantados — imunomodulação pode conflitar com imunossupressão","Gestação — alcalóides controversos","Uso concomitante com anticoagulantes — cautela","Hipertensão — monitorar (alcalóides vasoativos)"],"efeitos_adversos":"","componentes_ativos":[{"label":"ALCALÓIDES OXINDÓLICOS (pteropodina, isorincofila, mitrfilina)","texto":"Imunomodulação — ativação macrófagos e linfócitos"},{"label":"ALCALÓIDES TETRACÍCLICOS (rincofila, isorincofila)","texto":"Regulação nervosa, anti-inflamatório"},{"label":"GLICOSÍDEOS DO ÁCIDO QUINÓVICO","texto":"Anti-inflamatório, antiviral"},{"label":"CATEQUINAS, EPICATEQUINAS","texto":"Antioxidante, anti-inflamatório"},{"label":"BETA-SITOSTEROL, ESTIGMASTEROL","texto":"Anti-inflamatório, imunomodulador"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ec19d59c-0bfe-43a1-a26b-056b75c73b34","slug":"jatoba","herb_id":null,"herb_latin_name":"Hymenaea courbaril","schema_version":"1.1","ficha":{"slug":"jatoba","cultura":{"brasil":"A farinha de jatobá é o alimento funcional \"esquecido\" do Brasil — extremamente nutritiva (ferro, cálcio, proteína, amido resistente de baixo índice glicêmico), produzida por comunidades extrativistas do cerrado e amazônia, mas praticamente ausente do mercado urbano. É uma das grandes oportunidades de produção alimentar sustentável da bioeconomia brasileira.","historia":"A resina de jatobá — chamada copal pelos povos mesoamericanos — é uma das substâncias rituais mais antigas das Américas. Queimada como incenso em rituais maias e astecas; usada como verniz em instrumentos musicais coloniais no Brasil; vendida em farmácias europeias do século XIX como \"copaline\". O âmbar brasileiro pré-histórico é fossilização de resina de ancestrais do jatobá — insetos extintos foram preservados em resina de jatobá por dezenas de milhões de anos.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Mel · Gengibre · Guaco (blends respiratórios) · Açaí (blends energéticos)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A árvore-farmácia da floresta — resina milenar usada desde os maias até os quilombolas, com ação energética, respiratória e antimicrobiana comprovadas.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutos: outubro–março (cerrado); colheita de casca: ano todo","status_anvisa":"Uso tradicional reconhecido. Farinha de jatobá — alimento.","eixo_botanico_tpc":"Fitoterápico tradicional amazônico e atlântico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Jatobá","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Jatobá · jatobá-da-mata · jataí · copal (México/C.A.)","Courbaril · West Indian locust (inglês caribenho)","Jutaí (AM) · jataúba (PA)"],"parte_usada":"Casca do caule (decocção); resina (uso medicinal e ritual); polpa do fruto (farinha energética); folhas (infusão popular).","tipo_botanico":"Fitoterápico energético / expectorante / antimicrobiano","nome_cientifico":"Hymenaea courbaril L. / H. stigonocarpa Mart. ex Hayne (cerrado)","familia_botanica":"Fabaceae / Caesalpinioideae"},"caracterizacao":{"aroma":"Resina balsâmica quente, âmbar, leve baunilha, amadeirado profundo.","notas":"","intensidade":"4/5 (decocção de casca) / 2/5 (polpa em água).","cor_da_infusao":"","bioma_de_origem":"Amazônia e Cerrado — ampla distribuição em todo o Brasil extra-pampeano.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Hymenaea courbaril L. / H. stigonocarpa Mart. ex Hayne (cerrado)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Expectorante e broncodilatador","Energético (amido de digestão lenta + ferro)","Antimicrobiano (fungos e bactérias)","Antifúngico (candidíase)","Anti-inflamatório","Gastroprotetor (resina)","Componentes ativos:","Contraindicações: Sem contraindicações relevantes em uso moderado. Gestação — cautela com decocção concentrada."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"DITERPENOS (ácido courbarílico, jatereosídeos)","texto":"Anti-inflamatório, antimicrobiano"},{"label":"RESINA (copal)","texto":"Antifúngico, cicatrizante"},{"label":"AMIDO RESISTENTE","texto":"Prebiótico, energético de baixo IG"},{"label":"FERRO, CÁLCIO, MAGNÉSIO","texto":"Nutritivo — polpa"},{"label":"FLAVONÓIDES","texto":"Antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"979d4eab-8e50-461c-aff2-bd8f9e495214","slug":"rompe-pedra","herb_id":null,"herb_latin_name":"Phyllanthus niruri","schema_version":"1.1","ficha":{"slug":"rompe-pedra","cultura":{"brasil":"O rompe-pedra é uma das plantas medicinais mais consumidas no nordeste e norte do Brasil — praticamente todo portador de cálculo renal no interior do nordeste já tomou ou conhece o \"chá de quebra-pedra\". Essa planta ruderal que cresce em calçadas de Fortaleza, Recife e Salvador é simultaneamente erva daninha e farmácia de bairro.  A pesquisa brasileira com rompe-pedra, especialmente pela UFCE (Fortaleza), é das mais citadas internacionalmente no campo de litíase renal fitoterápica — exemplo notável de ciência desenvolvida a partir do conhecimento popular nordestino.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples coberta.","quantidade":"2–5 g de partes aéreas secas para 250 ml.","reinfusoes":"","combina_com":"Cavalinha · Uva-ursina · Dente-de-leão (blends diuréticos/renais)","melhor_momento":"Manhã e tarde (diurético — evitar à noite).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"O dissolve-pedras do nordeste — diurético e litolítico com uma das melhores evidências clínicas do catálogo para cálculo renal, estudado por dezenas de universidades no mundo todo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Colheita de partes aéreas em floração/frutificação","status_anvisa":"Monografia oficial. Indicação: diurético, coadjuvante em litíase renal.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Rompe-Pedra","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Rompe-pedra · quebra-pedra · arrebenta-pedra · erva-pombinha","Stonebreaker / chanca piedra (espanhol — Peru)","Leafflower (inglês)"],"parte_usada":"Partes aéreas secas (erva toda — ramos, folhas, frutos).","tipo_botanico":"Fitoterápico diurético / litolítico / hepatoprotetor","nome_cientifico":"Phyllanthus niruri L. / P. amarus Schumach. & Thonn. (sinonímia parcial aceita)","familia_botanica":"Phyllanthaceae (antes Euphorbiaceae)"},"caracterizacao":{"aroma":"Folha verde seca, herbáceo suave, levemente resinoso.","notas":"","intensidade":"2/5 — infusão gentil, de uso cotidiano possível.","cor_da_infusao":"Verde-amarelado a âmbar claro. #C4B84A","bioma_de_origem":"Caatinga, Cerrado, Mata Atlântica — espécie ruderal de ampla distribuição, cresce em calçadas, quintais, terrenos baldios de Norte a Sul do Brasil.","sabor_dominante":"Levemente amargo, herbáceo-vegetal, adstringente suave. Um dos mais palatáveis do catálogo medicinal.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Phyllanthus niruri L. / P. amarus Schumach. & Thonn. (sinonímia parcial aceita)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Litíase renal (prevenção e dissolução)","populacao":"Barros et al. (UFCE)"},{"evidencia":"Moderada","indicacao":"Hepatite B (adjuvante)","populacao":"Thyagarajan et al., 1988"},{"evidencia":"Preliminar","indicacao":"Hipertensão renal leve","populacao":"Estudos animais"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Litolítico (dissolve e previne cálculos renais de oxalato e urato)","Diurético","Hepatoprotetor (anti-hepatite B — estudos pioneiros)","Anti-inflamatório","Antiviral (HIV, hepatite B — pesquisa em andamento)","Antiespasmódico uretral (alivia cólica renal)","Hipoglicemiante leve","Componentes ativos:","Indicações com evidência:","Contraindicações: Gestação — diurético intenso; evitar. Crianças — cautela. Uso concomitante com anticoagulantes — monitorar."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"FILANTINA (lignana)","texto":"Hepatoprotetor, antiviral"},{"label":"HIPOFILANTINA","texto":"Litolítico — inibe cristalização de oxalato"},{"label":"ÁCIDO ELÁGICO","texto":"Antioxidante, litolítico"},{"label":"QUERCETINA, RUTINA","texto":"Anti-inflamatório, antioxidante"},{"label":"GERANINA (elagitanino)","texto":"Antiviral (HIV, hepatite), antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"9cdf649b-ee0c-4440-a5c8-09ae0d111f59","slug":"angico","herb_id":null,"herb_latin_name":"Anadenanthera colubrina","schema_version":"1.1","ficha":{"slug":"angico","cultura":{"brasil":"O angico é a árvore do sertão nordestino mais usada em garrafadas — preparados compostos de múltiplas cascas em água ou aguardente que rezadeiras e raizeiros do interior nordestino prescrevem para \"tosse, catarro e peito cheio\". A casca de angico é ingrediente obrigatório dessas fórmulas tradicionais. Sua madeira é a mais densa do Brasil — usada em estacas, construção e carvão de altíssimo poder calorífico.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"5 g de casca seca para 500 ml.","reinfusoes":"","combina_com":"Mel · Propólis · Gengibre (blends antissépticos respiratórios)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":"Decocção a 98 °C."},"tagline":"A casca da respiração sertaneja — expectorante e antisséptico da caatinga com tradição nordestina secular e ação confirmada contra infecções respiratórias.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Casca coletada no período seco","status_anvisa":"Uso popular reconhecido. Sementes: bufotenina é substância controlada.","eixo_botanico_tpc":"Fitoterápico tradicional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Angico","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Angico · angico-do-cerrado · angico-branco · curupay (Argentina/Paraguai)","Cebil (espanhol sul-americano)","ATENÇÃO: sementes de angico contêm bufotenina (5-HO-DMT) — substância psicoativa controlada. Sementes são usadas ritualmente em contexto indígena; uso recreativo é ilegal."],"parte_usada":"Casca do caule (entrecasca); goma (exsudato resinoso).","tipo_botanico":"Fitoterápico expectorante / antisséptico","nome_cientifico":"Anadenanthera colubrina (Vell.) Brenan var. cebil (Griseb.) Altschul","familia_botanica":"Fabaceae / Mimosoideae"},"caracterizacao":{"aroma":"Madeira sertaneja seca, tanino, leve balsâmico.","notas":"","intensidade":"4/5 — medicinal intenso.","cor_da_infusao":"Marrom-avermelhado escuro. #7A3020","bioma_de_origem":"Caatinga e Cerrado — CE, RN, PB, PE, BA, PI, MG.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Anadenanthera colubrina (Vell.) Brenan var. cebil (Griseb.) Altschul","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Expectorante (fluidifica muco)","Antisséptico de mucosa respiratória e oral","Antimicrobiano (bactérias gram+ — especialmente estreptococos)","Adstringente","Anti-inflamatório de vias aéreas","Componentes ativos:","Contraindicações: Gestação — dados insuficientes. Sementes: contraindicadas (psicoativas)."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"TANINOS CONDENSADOS","texto":"Adstringente, antimicrobiano"},{"label":"SAPONINAS","texto":"Expectorante"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório"},{"label":"GOMA ARÁBICA (exsudato)","texto":"Demulcente, emoliente"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"3b545cb3-1683-47ee-bdda-dc523be68689","slug":"mastruz","herb_id":null,"herb_latin_name":"Dysphania ambrosioides","schema_version":"1.1","ficha":{"slug":"mastruz","cultura":{"brasil":"O mastruz é o vermífugo de quintal de boa parte do Brasil. \"Suco de mastruz com mel e leite\" para verme em criança é prática popular documentada em todo o Nordeste — e discutida entre pediatras e fitoterapeutas pela estreita margem entre dose terapêutica e tóxica. No México, a planta (epazote) é ingrediente culinário obrigatório em feijões e quesadillas — uso que reduz flatulência e tem ação antiparasitária preventiva sutil.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta (interno — dose baixa). Decocção (tópico — cicatrizante).","quantidade":"2–3 g de partes aéreas frescas ou 1–2 g de secas para 200 ml.","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (ascaridol volátil — não ferver para uso interno; ferver para uso tópico)."},"tagline":"O antiparasitário do quintal — vermífugo popular de distribuição pantropical com ação confirmada e uma das plantas mais usadas na medicina doméstica do Nordeste.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"","status_anvisa":"Uso tradicional reconhecido com ressalvas de segurança. Óleo essencial: proibido para uso interno.","eixo_botanico_tpc":"Fitoterápico tradicional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Mastruz","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Mastruz · mastruço · erva-de-santa-maria · quenopódio","Epazote (México) · Wormseed (inglês)","Hierba santa (espanhol popular)"],"parte_usada":"Partes aéreas frescas ou secas (folhas, ramos); sementes (uso mais intenso — mais tóxico).","tipo_botanico":"Antiparasitário intestinal / cicatrizante","nome_cientifico":"Dysphania ambrosioides (L.) Mosyakin & Clemants (sin.: Chenopodium ambrosioides L.)","familia_botanica":"Amaranthaceae"},"caracterizacao":{"aroma":"Mentolado-resinoso intenso, terpenóide pungente, feno aromático, levemente petrolado (ascaridol).","notas":"","intensidade":"4/5 — aroma invasivo, uso medicinal declarado.","cor_da_infusao":"Verde-amarelado a âmbar-verdoso. #8A9B40","bioma_de_origem":"Pantropical ruderal — Caatinga, Cerrado, Mata Atlântica — quintais, terrenos, ambientes antropizados de Norte a Sul.","sabor_dominante":"Forte, aromático-pungente, levemente amargo, resinoso-herbáceo intenso. Aroma que divide opiniões radicalmente — quem cresceu com mastruz ama; quem não conhece, estranha.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Dysphania ambrosioides (L.) Mosyakin & Clemants (sin.: Chenopodium ambrosioides L.)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antiparasitário intestinal (Ascaris, Ancilostoma, Enterobius)","Cicatrizante (uso tópico)","Antimicrobiano","Anti-inflamatório","Expectorante leve","Componentes ativos:","⚠️ ATENÇÃO — ASCARIDOL:","Contraindicações:","Gestação — contraindicado (abortivo em doses moderadas)","Lactação — evitar","Crianças < 2 anos — contraindicado","Hepatopatias e nefropatias — contraindicado","Óleo essencial: contraindicado em qualquer forma de uso interno"],"contraindicacoes":["Gestação — contraindicado (abortivo em doses moderadas)","Lactação — evitar","Crianças < 2 anos — contraindicado","Hepatopatias e nefropatias — contraindicado","Óleo essencial: contraindicado em qualquer forma de uso interno"],"efeitos_adversos":"","componentes_ativos":[{"label":"ASCARIDOL","texto":"Antiparasitário potente — peróxido terpênico — TÓXICO em dose alta"},{"label":"P-CIMENO","texto":"Antimicrobiano, antifúngico — —"},{"label":"LIMONENO","texto":"Antimicrobiano, carminativo — —"},{"label":"ÁCIDO ASCÓRBICO","texto":"Nutritivo — Vitamina C"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório — —"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"82d983e6-2ea8-45fd-aa87-9b5d1c04b3cf","slug":"umbu","herb_id":null,"herb_latin_name":"Spondias tuberosa","schema_version":"1.1","ficha":{"slug":"umbu","cultura":{"brasil":"O umbu é a fruta que o Nordeste mais ama e que o Brasil quase não conhece. São Paulo e Rio consomem manga, açaí, graviola — mas o umbu, endêmico da caatinga, nunca cruzou o Nordeste em escala comercial. A polpa congelada existe em nichos, mas o fruto fresco é quase impossível de encontrar fora da caatinga. Isso é oportunidade e missão para o Ervatório.","historia":"O umbuzeiro é a árvore sagrada do sertão nordestino. João Guimarães Rosa descreveu o encontro com o umbuzeiro como o encontro com o próprio sertão. A árvore é objeto de proteção cultural informal — sertanejos não derrubam umbuzeiro mesmo em terra degradada. Sua raiz tuberosa (xilopódio) armazena até 3.000 litros de água — mecanismo de adaptação à seca que também serviu como fonte de água para viajantes e animais em séculos de exploração do sertão.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O sabor do sertão — fruto endêmico da caatinga com vitamina C excepcional, adaptação extrema à seca e uma identidade cultural nordestina insubstituível.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutificação: dezembro–março (pico de umidificação da caatinga)","status_anvisa":"Regulado como alimento","eixo_botanico_tpc":"Alimento funcional / Fitoterápico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Umbu","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Umbu · imbu · imbuzeiro (árvore)","Umbuzeiro (arvore sagrada do sertão)"],"parte_usada":"Fruto (polpa e suco); folhas (infusão); casca (decocção); raiz tuberosa (reservatório de água — uso de sobrevivência indígena).","tipo_botanico":"Alimento funcional / fitoterápico","nome_cientifico":"Spondias tuberosa Arruda","familia_botanica":"Anacardiaceae (família da manga, do caju)"},"caracterizacao":{"aroma":"Cítrico tropical intenso, manga jovem, frutas amarelas, levemente fermentado agradável.","notas":"","intensidade":"","cor_da_infusao":"","bioma_de_origem":"Caatinga — endêmico. CE, RN, PB, PE, AL, SE, BA, PI, MG.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Spondias tuberosa Arruda","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antioxidante (vitamina C excepcional — até 3x a laranja)","Anti-inflamatório (folhas)","Antidiarreico (casca adstringente)","Vitamínico e nutritivo","Hidratante (fruto rico em água — adaptação ao bioma)","Componentes ativos:","Contraindicações: Sem contraindicações relevantes em uso alimentar. Casca: gestação — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"VITAMINA C (ácido ascórbico)","texto":"Antioxidante, imunidade — concentração excepcional"},{"label":"CAROTENÓIDES (beta-caroteno)","texto":"Antioxidante, pró-vitamina A"},{"label":"TANINOS (casca/folhas)","texto":"Antidiarreico, anti-inflamatório"},{"label":"ÁCIDOS ORGÂNICOS (cítrico, málico)","texto":"Digestivo, acidulante natural"},{"label":"FLAVONÓIDES","texto":"Antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ef063131-862d-4f47-bb9c-feae09b7e7a6","slug":"sucupira","herb_id":null,"herb_latin_name":"Pterodon pubescens","schema_version":"1.1","ficha":{"slug":"sucupira","cultura":{"brasil":"A sucupira é o anti-inflamatório articular do cerrado — usada por populações rurais do Brasil Central para \"reumatismo\", \"artrose\" e \"dor nos ossos\" há gerações. O óleo de sucupira em azeite, macerado em casa, é preparação caseira passada de avó a neto no interior de Goiás e Minas Gerais. A pesquisa da USP e UFG validou farmacologicamente o mecanismo de ação — furanoditerpenos inibindo vias inflamatórias articulares.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Cúrcuma · Gengibre · Arnica (blends anti-inflamatórios articulares)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O anti-inflamatório do cerrado — semente aromática com ação articular documentada e uma das melhores evidências clínicas brasileiras para doenças osteoarticulares.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Sementes: março–julho (pós-floração do cerrado)","status_anvisa":"Uso tradicional reconhecido. Em análise para Formulário Fitoterápico.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Sucupira","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Sucupira · sucupira-branca · faveiro · sucupira-do-cerrado","Sucupira-preta (Bowdichia virgilioides — espécie diferente com usos semelhantes)"],"parte_usada":"Sementes (principal); casca em decocção secundária.","tipo_botanico":"Fitoterápico anti-inflamatório articular","nome_cientifico":"Pterodon pubescens Benth. / P. emarginatus Vogel","familia_botanica":"Fabaceae / Papilionoideae"},"caracterizacao":{"aroma":"Terpênico-resinoso, pimenta-do-cerrado, balsâmico amadeirado.","notas":"","intensidade":"4/5 — uso medicinal declarado.","cor_da_infusao":"","bioma_de_origem":"Cerrado — GO, MG, MS, MT, SP, TO, BA.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Pterodon pubescens Benth. / P. emarginatus Vogel","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Osteoartrite (adjuvante)","populacao":"Tamião et al. (USP)"},{"evidencia":"Moderada","indicacao":"Dor articular crônica","populacao":"Estudos clínicos nacionais"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Anti-inflamatório articular (osteoartrite, artrite reumatoide — adjuvante)","Analgésico","Antirreumático","Antifúngico","Imunomodulador leve","Componentes ativos:","Indicações com evidência:","Contraindicações: Gestação — dados insuficientes. Hepatopatias — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"FURANODITERPENOS (geranilgeraniol, vouacapan)","texto":"Anti-inflamatório — inibição NF-κB e COX-2"},{"label":"ISOFLAVONAS","texto":"Anti-inflamatório, imunomodulador"},{"label":"ÁCIDOS GRAXOS (oleico, linoleico)","texto":"Emoliente, anti-inflamatório"},{"label":"TERPENOS SESQUITERPENÓIDES","texto":"Aromático, antimicrobiano"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"be7a001e-f3b1-407e-b9a0-6f9319159445","slug":"fava-de-anta","herb_id":null,"herb_latin_name":"Dimorphandra mollis","schema_version":"1.1","ficha":{"slug":"fava-de-anta","cultura":{"brasil":"A fava-de-anta é o exemplo mais eloquente de matéria-prima brasileira transformada em princípio ativo farmacêutico europeu sem que o Brasil capture o valor. A rutina extraída de Dimorphandra mollis é a rutina de referência usada em dezenas de medicamentos venoprotetores europeus (Daflon, Venoruton e similares). A maior parte da produção é exportada como pó bruto — processada na Europa como matéria-prima farmacêutica. O Brasil é o maior produtor mundial da maior fonte natural de rutina e não tem um único medicamento venoprotetor nacional de fava-de-anta no mercado.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples coberta.","quantidade":"2–3 g/250 ml","reinfusoes":"","combina_com":"Castanha-da-índia · Mirtilo · Uva (blends venovasculares)","melhor_momento":"2x ao dia (venoprotetor — manhã e tarde).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C | Tempo: 8–10 min | Quantidade: 2–3 g/250 ml"},"tagline":"A rutina do cerrado — cardioprotetor vascular com concentração de rutina superior a qualquer outra fonte vegetal conhecida e cadeia produtiva estruturada no Brasil Central.","receitas":[],"regulacao":{"status_ema":"Rutina: monografada em diversas farmacopeias europeias como PA venoprotetor","status_fda":"","sazonalidade":"Frutos imaturos: novembro–fevereiro","status_anvisa":"Uso tradicional reconhecido. Rutina como PA: ampla regulação.","eixo_botanico_tpc":"Phyto-ANVISA + Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Fava-de-Anta","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Fava-de-anta · faveira · barbatimão-do-cerrado (confusão popular)","Dimorphandra (farmacológico)"],"parte_usada":"Frutos imaturos (maior concentração de rutina); sementes; flores.","tipo_botanico":"Fitoterápico cardiovascular / venoprotetor","nome_cientifico":"Dimorphandra mollis Benth.","familia_botanica":"Fabaceae / Caesalpinioideae"},"caracterizacao":{"aroma":"Tanino seco, leguminosa torrada suave.","notas":"","intensidade":"3/5 — medicinal, palatável.","cor_da_infusao":"Amarelo-esverdeado a âmbar. #C8B84A","bioma_de_origem":"Cerrado — GO, MG, MS, MT, BA, PI, TO.","sabor_dominante":"Amargo-adstringente moderado, tanino discreto, herbáceo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Dimorphandra mollis Benth.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte (rutina)","indicacao":"Insuficiência venosa crônica","populacao":"Múltiplas farmacopeias europeias"},{"evidencia":"Forte","indicacao":"Fragilidade capilar","populacao":"EMA — rutina como PA"},{"evidencia":"Moderada","indicacao":"Varizes (preventivo)","populacao":"Estudos europeus com rutina"},{"evidencia":"Moderada","indicacao":"Hemorroidas","populacao":"Revisões sistemáticas"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Venoprotetor (fortalece paredes capilares e venosas)","Antivaricoso (reduz fragilidade capilar)","Anti-inflamatório vascular","Antioxidante (captador de radicais livres vasculares)","Cardioprotetor","Antitrombótico fraco","Componentes ativos:","Indicações com evidência:","Contraindicações: Anticoagulados — cautela (rutina tem ação antiagregante fraca). Gestação — dados insuficientes."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"RUTINA","texto":"15–25% dos frutos secos — maior fonte mundial conhecida — Venoprotetor, antioxidante capilar"},{"label":"QUERCETINA","texto":"Produto de hidrólise da rutina — Anti-inflamatório, antioxidante"},{"label":"KAEMPFEROL","texto":"Presente — Cardioprotetor"},{"label":"TANINOS","texto":"Presentes — Adstringente, antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"443ca96f-d6d6-4497-a7a1-c907628b7683","slug":"mangaba","herb_id":null,"herb_latin_name":"Hancornia speciosa","schema_version":"1.1","ficha":{"slug":"mangaba","cultura":{"brasil":"A mangaba é a fruta-símbolo de Sergipe — estado que a adotou como identidade cultural, com festival anual da mangaba, artesanato e culinária centrados no fruto. A mangabeira em Sergipe é objeto de disputa de terras complexa: as \"catadoras de mangaba\" — mulheres extrativistas das restingas — travam há décadas batalhas judiciais contra empreendimentos imobiliários que destroem os mangabeirais nativos. Em 2011, o IPHAN reconheceu o extrativismo da mangaba como patrimônio cultural imaterial.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Caju · Siriguela · Cajá (blends de frutas nordestinas-cerrado)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A fruta que chora leite — hipoglicemiante do cerrado e semiárido com potencial farmacológico crescente e identidade cultural sergipana insubstituível.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutificação: outubro–janeiro (cerrado) / julho–setembro (nordeste)","status_anvisa":"Alimento. Folhas: uso tradicional reconhecido.","eixo_botanico_tpc":"Alimento funcional / Fitoterápico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Mangaba","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Mangaba · mangabeira","Mangaba (uso único — sem tradução estabelecida em outros idiomas)"],"parte_usada":"Fruto (alimentar); folhas (infusão medicinal); casca (decocção); látex do caule (antimicrobiano tópico).","tipo_botanico":"Alimento funcional / hipoglicemiante / antihipertensivo","nome_cientifico":"Hancornia speciosa Gomes","familia_botanica":"Apocynaceae (família do congo, da frangipani)"},"caracterizacao":{"aroma":"","notas":"","intensidade":"","cor_da_infusao":"","bioma_de_origem":"Cerrado costeiro, Caatinga, Restinga — distribuição litoral-cerrado; SE, BA, AL, PE, GO, MT, MA.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Hancornia speciosa Gomes","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Hipoglicemiante (folhas — inibição de alfaglicosidase)","Antihipertensivo (vasodilatação por flavonóides)","Anti-inflamatório","Antimicrobiano (látex)","Antioxidante (fruto — alto ORAC)","Nutritivo (vitamina C, ferro)","Componentes ativos:","Contraindicações: Hipoglicemia — cautela com hipoglicemiantes orais. Alergia ao látex (reação cruzada possível com látex da arvore)."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"FLAVONÓIDES (folhas)","texto":"Hipoglicemiante, antihipertensivo"},{"label":"BORRACHOL (látex)","texto":"Antimicrobiano, cicatrizante"},{"label":"VITAMINA C","texto":"Antioxidante"},{"label":"ÁCIDOS ORGÂNICOS","texto":"Digestivo, antioxidante"},{"label":"TERPENOS","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"5d2d4323-b663-4906-9a48-5f28c2aacf16","slug":"macela","herb_id":null,"herb_latin_name":"Achyrocline satureioides (Lam.) DC.","schema_version":"1.1","ficha":{"slug":"macela","cultura":{"brasil":["A macela é a maior embaixadora herbalista do Sul brasileiro — mais reconhecida regionalmente do que a carqueja, embora menos estudada cientificamente. Está amarrada à identidade rural-tradicional gaúcha de forma intensa.","A produção comercial é pequena e quase toda extrativa — pequenos produtores rurais gaúchos e uruguaios colhem sumidades floridas em campos nativos. A certificação orgânica é incipiente mas crescente. Algumas cooperativas agroecológicas do Rio Grande do Sul começaram a produzir macela cultivada com rastreabilidade.","Para o Ervatório, a macela é a ficha que carrega mais densidade de ritual codificado: o preparo cerimonial da Sexta-Feira Santa, os travesseiros aromáticos, a dimensão religioso-herbalista do Sul brasileiro. É a face tradicional-cerimonial da fitoterapia nacional."],"historia":["A macela é uma das ervas mais antigas da farmácia caboclo-gaúcha. Os povos charrúa e guarani-kaiowá do Sul e do pampa argentino já usavam a planta para distúrbios digestivos e como aromático protetor antes do contato europeu. Os colonos açorianos e italianos no Rio Grande do Sul incorporaram a planta à medicina rural desde o século XVIII, adaptando usos indígenas às suas próprias práticas europeias.","A tradição da colheita na Sexta-Feira Santa é sincretismo católico-herbalista consolidado no século XIX — representa fusão entre o calendário religioso cristão e o conhecimento indígena-rural sobre sazonalidade das plantas. Em algumas regiões do Uruguai e da Argentina, a tradição é preservada quase idêntica, indicando origem comum no mundo rioplatense pré-nacional.","A pesquisa científica moderna começou na UFRGS nos anos 1970-1980, com trabalhos pioneiros do Grupo de Plantas Medicinais da Faculdade de Farmácia. A planta entrou na Farmacopeia Brasileira via Formulário de Fitoterápicos (2011), confirmando oficialmente o uso popular."],"cerimonial":"O ritual da colheita na Sexta-Feira Santa é a cerimônia codificada mais preservada entre as ervas brasileiras. Em famílias gaúchas tradicionais, há gestos precisos: colher antes do sol nascer, em silêncio, pedir licença à planta, cortar as sumidades floridas sem arrancar a raiz. Secagem à sombra em feixes pendurados. Os travesseiros feitos com essa macela são presenteados em casamentos, em nascimentos, em enfermidades. A tradição é viva em interior sulino até hoje, embora diluída em famílias urbanas.","curiosidade":"A flor da macela é tecnicamente uma inflorescência composta — cada \"flor\" amarela que vemos é, na verdade, um capítulo com dezenas de flores microscópicas. Quando se colhe um punhado de macela, está-se colhendo centenas de flores verdadeiras, diminutas, cada uma completa em si mesma. A mesma estrutura do girassol, da camomila, da margarida: a família Asteraceae inteira é feita de ilusões florais, flores que parecem uma e são muitas. Beber um chá de macela é beber uma floresta mínima em cada xícara."},"preparo":{"metodo":"Infusão coberta. Beber logo após o preparo.","quantidade":"1,5 g de sumidades floridas secas (cerca de 1 colher de chá cheia) para 150 ml de água — proporção da Farmacopeia Brasileira.","reinfusoes":"Não recomendado — princípios voláteis em primeira infusão.","combina_com":"Camomila (ampliação do perfil floral-digestivo) · Carqueja (potencialização amarga digestiva) · Erva-doce · Hortelã-pimenta · Mel (harmoniza amargor)","melhor_momento":"Após refeições (digestivo), antes de dormir (leve ansiolítico pelos flavonoides). 2 a 3 vezes ao dia conforme a monografia.","tempo_de_infusao":"5 a 10 minutos coberto.","temperatura_ideal":"95 °C. Tolera ebulição branda."},"tagline":"Flor amarela do pampa colhida na Sexta-Feira Santa — a erva mais ritualizada do Sul brasileiro, com uso digestivo e travesseiro que guarda a tradição gaúcha.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Cerrado-Mata Atlântica (campos sulinos) + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão herbal monografada"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Sem monografia — uso essencialmente sul-americano"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar — farmacêutico ou fitoterapeuta com familiaridade em flavonoides","revisor_cultural":"Sugerido — herbalista gaúcho ou uruguaio com tradição da Sexta-Feira Santa preservada","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco 1)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia específica — uso essencialmente sul-americano.","status_fda":"Sem reconhecimento específico.","sazonalidade":"Floração entre março e maio no Hemisfério Sul. Colheita ideal na Sexta-Feira Santa quando calendário coincide com pico de floração — tradição preservada e tecnicamente justificada.","status_anvisa":"Monografia oficial no Formulário de Fitoterápicos (Anvisa, 2011). Indicações: antidispéptico, antiespasmódico e anti-inflamatório.","eixo_botanico_tpc":"Cerrado-Mata Atlântica (campos sulinos) + Phyto-ANVISA","produtor_parceiro":"A definir — priorizar cooperativas agroecológicas do RS e Uruguai. Avaliar parceria com comunidades charrúa uruguaias com tradição extrativa.","status_japao_china":"Uso restrito, planta exótica nestes mercados.","certificacao_organica":["Cultivo orgânico incipiente no Rio Grande do Sul (região serrana, Vale do Taquari).","Coleta extrativista em campos nativos sulinos com manejo sustentável (Bioma Pampa).","Produção uruguaia certificada crescente."]},"marketplace":{"formatos":"Sumidades floridas secas inteiras (preferível, preserva flavonoides voláteis), travesseiros aromáticos, sachê filtrante, tintura.","fornecedores":"Curadoria de produtores gaúchos e uruguaios com selo orgânico e história da colheita tradicional.","faixa_de_preco":"Sumidades floridas secas: R$ 40 a 90 por 100 g (produção artesanal gaúcha).","disponivel_a_venda":"A definir"},"nome_popular":"Macela","usos_topicos":{"evidencia":"Moderada para uso compressivo digestivo; tradicional para banhos e travesseiros aromáticos.","aplicacoes":[{"texto":"Infusão forte morna, pano embebido aplicado sobre ventre por 15 a 20 minutos. Uso tradicional sulino com plausibilidade farmacológica pela ação antiespasmódica dos flavonoides.","titulo":"Compressa morna sobre abdômen em cólicas"},{"texto":"Sumidades floridas secas em saquinho de algodão, colocado na fronha. Uso tradicional gaúcho preservado até hoje — a aromaterapia dos flavonoides voláteis atua por via olfativa.","titulo":"Travesseiro aromático para sono"},{"texto":"Uso tradicional em algumas regiões do Sul — banho com macela forte após o parto, para cicatrização e relaxamento. Evidência popular sem estudos clínicos dedicados.","titulo":"Banho aromático pós-parto"},{"texto":"Infusão padrão morna, 30 segundos após escovação. Ação adstringente e anti-inflamatória dos flavonoides.","titulo":"Bochecho para gengivite leve"}],"contraindicacoes":"Uso tópico amplamente seguro. Alérgicos à família Asteraceae devem testar antes."},"docx_filename":"Ficha_Macela_v11.docx","identificacao":{"slug_url":"macela","sinonimos":["Marcela · marcela-do-campo · macela-amarela · camomila-nacional · losna-do-mato","Sinonímia botânica: Achyrocline candicans (Kunth) DC.","Em português rioplatense/espanhol sul-americano: marcela, marcelita"],"parte_usada":"Sumidades floridas secas — 1,5 g para 150 ml de água, conforme a monografia oficial.","nome_popular":"Macela","tipo_botanico":"Erva perene de até 60 cm, com flores amarelas em capítulos pequenos agrupados em inflorescências densas.","nome_cientifico":"Achyrocline satureioides (Lam.) DC.","familia_botanica":"Asteraceae (mesma família da camomila)"},"caracterizacao":{"aroma":"Floral-herbáceo quente, com notas de camomila rústica, mel seco e campo exposto ao sol. Aroma característico do pampa.","notas":"Cabeça: floral-solar · Corpo: amargor herbáceo · Fundo: doçura suave persistente","intensidade":"3/5 — equilibrada, entre camomila e carqueja.","cor_da_infusao":"Amarelo-dourado a âmbar claro. #D9BE55","bioma_de_origem":"Campos sulinos brasileiros e pampa argentino-uruguaio.","sabor_dominante":"Amargo-aromático suave, com notas herbáceas quentes e leve nuance de camomila mais acentuada. Menos amargo que a carqueja, mais amargo que a camomila clássica.","distribuicao_geografica":["Brasil: ocorrência natural abundante no RS, SC, PR e SP — campos altos e bordas de mata.","Cone Sul: Argentina (pampa), Uruguai, Paraguai, Bolívia.","Cultivo comercial ainda limitado — a maior parte da produção vem de coleta extrativista em campos nativos sulinos, com manejo sustentável regulamentado."]},"preparo_ritual":{"texto":"No Sul do Brasil e Rio da Prata, há tradição rural-religiosa séria de colher macela na Sexta-Feira da Paixão antes do nascer do sol. A crença popular, ancorada em saber herbalista, diz que a planta colhida nesse dia tem mais propriedades medicinais. Há base parcialmente verificável: no Hemisfério Sul, a Sexta-Feira Santa cai no final de março ou início de abril, quando a macela está em plena floração e concentração máxima de princípios ativos. A tradição herbalista codificou como ritual religioso o que o herbalismo técnico reconhece como colheita em momento ótimo. Travesseiros de macela seca colhida nesse dia são guardados por famílias gaúchas e uruguaias como objeto de cuidado — aromatizam o quarto, são usados sobre o ventre em cólicas digestivas, e funcionam como amuleto de proteção da saúde da família.","titulo":"Preparo ritual · Colheita da Sexta-Feira Santa"},"schema_version":"1.1","nome_cientifico":"Achyrocline satureioides (Lam.) DC.","perfil_sensorial":{"tatil":"Corpo médio. Adstringência discreta, persistência aromática média. O amargor é mais redondo que o da carqueja — estrutura mais harmônica, com volta doce no final.","gustativo":[{"dimensao":"Amargo","observacao":"Amargor aromático médio, diferente do amargor cortante da carqueja","intensidade":"2/3"},{"dimensao":"Doce","observacao":"Residual, sutil — nuance floral-solar","intensidade":"1/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Baixa","molecula":"Traços de terpenos aromáticos","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Baixa-moderada","molecula":"Taninos e flavonoides","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: floral-solar com nuance herbácea quente","descricao_integrada":"A macela é a ponte sensorial entre a camomila europeia e a carqueja pampeana. Do lado da camomila, herda o amargor floral suave e a aceitação sensorial ampla. Do lado da carqueja, herda a intensidade aromática e a presença herbácea que marca a boca. É uma infusão que o Sul brasileiro poderia ter exportado ao mundo no lugar da camomila alemã, se a história comercial tivesse sido outra. Ao beber macela, registra-se simultaneamente a tradição europeia do \"floral que acalma\" e a tradição sulamericana do \"amargo que faz bem\". A planta equilibra essas duas identidades farmacopeicas em um perfil sensorial próprio — e é por isso que o nome popular \"camomila-nacional\" é preciso: ela cumpre a mesma função doméstica da camomila com personalidade declaradamente brasileira.","olfativo_descritores":["Camomila rústica","Mel de campo seco","Flor seca aquecida ao sol","Feno maduro","Leve nota resinosa"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografia oficial de Achyrocline satureioides","Simões et al. — Plantas da Medicina Popular no Rio Grande do Sul (UFRGS, 5ª ed., 2018)","Salgueiro et al. — Achyrocline satureioides: a review on its pharmacological and anti-inflammatory properties (Rev Bras Farmacogn, 2016)","Grassi-Zampieron et al. — Evaluation of the antimicrobial activity of Achyrocline satureioides (Braz J Microbiol, 2010)"],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Dispepsia funcional","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Cólica digestiva leve","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Ansiedade leve pós-refeição","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Antimicrobiano tópico","populacao":"Uso externo"}],"interacoes":[{"label":"Sedativos e benzodiazepínicos","texto":"potencialização leve"},{"label":"Anticoagulantes","texto":"cautela — cumarinas em traços"},{"label":"Hipoglicemiantes","texto":"potencialização possível em diabéticos"}],"dose_maxima":"Conforme a monografia: 150 ml do infuso (1,5 g de sumidades floridas secas), 2 a 3 vezes ao dia, logo após o preparo. Uso continuado tolerável em adultos saudáveis.","alerta_critico":null,"acoes_principais":["Antidispéptico — ação monografada","Antiespasmódico digestivo","Anti-inflamatório","Ansiolítico leve","Colagogo e colerético suave","Hipoglicemiante leve (estudos preliminares)","Antimicrobiano (ação documentada contra Staphylococcus aureus)"],"contraindicacoes":["Alergia conhecida à família Asteraceae (inclui camomila, calêndula, arnica)","Em uso concomitante com sedativos (monitorar — efeito aditivo leve)","Gestantes: usar com cautela em doses baixas; evitar uso continuado","Crianças abaixo de 12 anos: preferir orientação profissional"],"efeitos_adversos":"Em doses recomendadas: muito raros. Em alérgicos à Asteraceae: prurido, urticária.","componentes_ativos":[{"label":"Flavonoides (quercetina, luteolina, 3-O-metilquercetina, achyrobichalcona)","texto":"Princípios ativos principais — responsáveis pela ação anti-inflamatória, antiespasmódica e ansiolítica leve"},{"label":"Óleo essencial (cariofileno, alfa-pineno, limoneno)","texto":"Contribui para o aroma e tem ação antimicrobiana"},{"label":"Ácidos fenólicos (cafeico, clorogênico)","texto":"Antioxidantes"},{"label":"Cumarinas","texto":"Em traços — contribuem para o aroma característico e têm leve ação vasoativa"},{"label":"Taninos","texto":"Adstringência"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"8280f339-88a0-4d8b-8ed5-0a0569daac08","slug":"andiroba","herb_id":null,"herb_latin_name":"Carapa guianensis","schema_version":"1.1","ficha":{"slug":"andiroba","cultura":{"brasil":"A andiroba é um dos produtos âncora da bioeconomia amazônica — cadeia produtiva que envolve mais de 30.000 famílias extrativistas no estado do Pará. Marcas de cosméticos como Natura, O Boticário e exportadoras para Europa e Japão integram o óleo de andiroba em linhas de repelentes naturais, cremes e velas aromáticas.","historia":"O óleo de andiroba é provavelmente o primeiro produto de biocosmética amazônica exportado sistematicamente para a Europa — velas de andiroba eram manufaturadas no Pará colonial para exportação, valorizadas por repelir insetos naturalmente.  Comunidades ribeirinhas e quilombolas do estuário amazônico desenvolveram ao longo de séculos um sistema produtivo complexo: coleta de frutos caídos, fermentação em água, extração a quente do óleo. Esse processo, chamado \"tiragem da andiroba\", é hoje reconhecido como tecnologia tradicional protegida.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O escudo da floresta — óleo amargo que repele insetos, cura inflamações e alimenta economias familiares ribeirinhas há séculos.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Colheita de sementes: janeiro–abril (pico de frutificação)","status_anvisa":"Uso tradicional reconhecido. Óleo cosmético regulamentado.","eixo_botanico_tpc":"Fitoterápico tradicional amazônico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Andiroba","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Andiroba · carapa · iandirova · nandiroba (tupi)","Crab oil (inglês/caribenho) · Huile de carapa (francês)","Bastardcedar (inglês técnico)"],"parte_usada":"Óleo extraído das sementes (pressão a frio); casca em decocção; folhas em cataplasma.","tipo_botanico":"Óleo de semente medicinal; decocção de casca","nome_cientifico":"Carapa guianensis Aubl.","familia_botanica":"Meliaceae (família do mogno, da cedrela)"},"caracterizacao":{"aroma":"","notas":"","intensidade":"","cor_da_infusao":"","bioma_de_origem":"Amazônia úmida de várzea e terra firme. Também encontrada no Pará, Maranhão, Amapá e Guianas.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Carapa guianensis Aubl.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Anti-inflamatório (inibição de prostaglandinas)","Repelente natural de insetos (limonóides amargos)","Antitumoral (pesquisas preliminares — andirobin, methyl angolensate)","Antipirético","Antiparasitário (verminose, leishmaniose)","Cicatrizante (uso tópico)","Larvicida (Aedes aegypti) — uso em saúde pública comunitária","Componentes ativos:","Contraindicações: Gestação (abortivo em doses altas documentado em animais). Lactação — cautela. Crianças: uso tópico seguro; interno apenas com orientação."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"LIMONÓIDES (gedunin, angolensato)","texto":"Anti-inflamatório, antimalárico, antitumoral"},{"label":"ANDIROBIN","texto":"Antiparasitário, inseticida natural"},{"label":"ÁCIDOS OLEICO E ESTEÁRICO","texto":"Nutritivo e emoliente (óleo)"},{"label":"METHYL ANGOLENSATE","texto":"Pesquisado como antimalárico"},{"label":"TRITERPENOS","texto":"Anti-inflamatório sistêmico"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"b439d40d-8619-49f0-b23f-05d83d8d85bf","slug":"muirapuama","herb_id":null,"herb_latin_name":"Ptychopetalum olacoides","schema_version":"1.1","ficha":{"slug":"muirapuama","cultura":{"brasil":"A muirapuama é, junto com a catuaba e o guaraná, a tríade dos adaptógenos amazônicos masculinos mais exportados. A França e a Alemanha são os maiores mercados europeus de extrato de muirapuama — onde circula amplamente em fitoterápicos OTC para \"vitalidade e libido\". O Brasil exporta quase toda sua produção como matéria-prima semi-processada, sem capturar o valor agregado do produto final.","historia":"A muirapuama chegou à Europa no final do século XIX como \"afrodisíaco amazônico\" — os primeiros relatos de uso terapêutico europeu datam de 1925 (British Herbal Pharmacopoeia, edição antiga). Tornou-se ingrediente de fórmulas de \"tonificantes nervosos\" em farmácias francesas e inglesas das décadas de 1930–1950.  Na Amazônia, é usada por diversas etnias indígenas como tônico masculino, mas também como planta de força para caçadores e guerreiros — a denominação \"potency wood\" reflete essa herança.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção suave ou maceração em água fria (12h) — esta última preserva melhor alcaloides polares.","quantidade":"2–5 g de casca ou raiz seca para 250 ml.","reinfusoes":"","combina_com":"Catuaba · Guaraná · Pfaffia (para blends tônicos masculinos) · Ginseng asiático (blend adaptogênico global)","melhor_momento":"Manhã ou início de tarde. Evitar à noite (estimulante leve).","tempo_de_infusao":"","temperatura_ideal":"95–98 °C (decocção leve)."},"tagline":"A madeira da potência — adaptógeno amazônico que a neurociência redescobriu como protetor cognitivo e tonificante do sistema nervoso.","receitas":[],"regulacao":{"status_ema":"Não monografado. Amplamente vendido na Europa como suplemento.","status_fda":"","sazonalidade":"Colheita de raiz/casca: ano todo; preferência período seco","status_anvisa":"Uso tradicional reconhecido. Não está no Formulário de Fitoterápicos.","eixo_botanico_tpc":"Fitoterápico tradicional amazônico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Muirapuama","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Muirapuama · muirapuaminha · potency wood · pau-potência","Marapuama (variante ortográfica) · capi-catingaíba (PA)","Potency wood / muira puama (inglês europeu — uso amplamente difundido em fitoterápicos europeus)"],"parte_usada":"Raiz e casca do caule, secas.","tipo_botanico":"Tônico nervoso / adaptógeno herbal","nome_cientifico":"Ptychopetalum olacoides Benth.","familia_botanica":"Olacaceae"},"caracterizacao":{"aroma":"Madeira seca tropical, resina sutil, fundo de baunilha silvestre.","notas":"","intensidade":"3/5 — presença mediana, uso regular possível.","cor_da_infusao":"Marrom-dourado claro a âmbar. #8B5E3C","bioma_de_origem":"Amazônia — floresta de terra firme, preferência por solos bem drenados. Amazonas, Pará, Rondônia.","sabor_dominante":"Amargo-resinoso leve, terroso-amadeirado, levemente adstringente. Mais palatável que andiroba — admite consumo regular.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Ptychopetalum olacoides Benth.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Disfunção sexual masculina (libido)","populacao":"Waynberg et al., 2000"},{"evidencia":"Preliminar","indicacao":"Déficit cognitivo leve","populacao":"Figueiró et al., 2011"},{"evidencia":"Tradicional forte","indicacao":"Fadiga nervosa, neurastenia","populacao":"Farmacopeias europeias antigas"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Adaptógeno — modulação do eixo HPA (hipotálamo-hipófise-adrenal)","Nootrópico — inibição de acetilcolinesterase (melhora memória colinérgica)","Afrodisíaco (aumento de libido documentado em modelos clínicos)","Tônico nervoso — neuroproteção contra estresse oxidativo","Antidepressivo leve (modulação dopaminérgica)","Anti-inflamatório (triterpenos)","Componentes ativos:","Indicações com evidência:","Contraindicações: Gestação e lactação — ausência de dados de segurança. Crianças — não recomendado. Hipertensão não controlada — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"LUPEOL (triterpeno)","texto":"Anti-inflamatório, adaptogênico"},{"label":"ÁCIDO OLEANÓLICO","texto":"Neuroprotetor, antioxidante"},{"label":"PTYCHOPETALINA (alcaloide)","texto":"Inibição de AChE — ação nootrópica"},{"label":"BETA-SITOSTEROL","texto":"Anti-inflamatório"},{"label":"ÁCIDOS GRAXOS","texto":"Nutritivo, emoliente"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"233cb828-0af9-416a-a268-dd026faf5aeb","slug":"aroeira","herb_id":null,"herb_latin_name":"Myracrodruon urundeuva","schema_version":"1.1","ficha":{"slug":"aroeira","cultura":{"brasil":"A aroeira ilustra um paradoxo central da fitoterapia brasileira: uma planta com evidência clínica forte, monografia oficial na Farmacopeia Brasileira e décadas de pesquisa universitária que ainda enfrenta barreiras de acesso no sistema de saúde pública. O SUS inclui a aroeira na RENISUS (Relação Nacional de Plantas Medicinais de Interesse ao SUS), mas a cadeia de fornecimento regulamentado ainda é incipiente.","historia":"A aroeira-do-sertão é uma das espécies mais antigas da farmacopeia nordestina. Curandeiros, benzedeiras e parteiras do sertão nordestino usam a casca de aroeira há séculos para tratar \"inflamação de boca\", \"corrimento\" e \"ferida que não sara\". Esses usos, documentados pela medicina popular desde o século XVIII, foram sistematicamente validados por pesquisadores brasileiros a partir dos anos 1990.  A UFRN (Universidade Federal do Rio Grande do Norte) possui um dos maiores portfólios de pesquisa clínica com aroeira do mundo — mais de 40 publicações em periódicos internacionais indexados.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção.","quantidade":"5 g de casca seca para 500 ml (uso oral); 10 g para uso tópico/bochecho.","reinfusoes":"","combina_com":"","melhor_momento":"Uso medicinal — 2–3x/dia conforme indicação.","tempo_de_infusao":"","temperatura_ideal":"Decocção a 98 °C."},"tagline":"A guardiã da caatinga — adstringente sagrada do sertão nordestino com ação anti-inflamatória oral entre as mais validadas da medicina popular brasileira.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Casca coletada preferencialmente na estação seca","status_anvisa":"Monografia oficial. Indicação: anti-inflamatório e adstringente de mucosas.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Aroeira","usos_topicos":{"evidencia":"","aplicacoes":["Bochecho para gengivite, periodontite e mucosite: Decocção de 5 g/250 ml, morna, bochecho por 30 segundos, 3x ao dia. Evidência clínica forte — ensaios clínicos randomizados brasileiros (UFRN, UFC) demonstraram redução de índice gengival comparável à clorexidina 0,12% com menor efeito colateral de pigmentação.","Banho de assento para cervicite, vaginose, candidíase: Decocção forte (20 g/1L), morna, 15 minutos. Uso tradicional nordestino amplamente documentado. Evidência moderada em estudos in vitro.","Compressa para dermatite e feridas: Decocção resfriada, gaze embebida, 15 min. Ação adstringente-cicatrizante."],"contraindicacoes":""},"identificacao":{"sinonimos":["Aroeira-do-sertão · urundeuva · urunday · aderno (BA)","ATENÇÃO: não confundir com Schinus terebinthifolia (aroeira-mansa/aroeira-da-praia) — espécie diferente, química distinta"],"parte_usada":"Casca do caule (entrecasca), seca e pulverizada.","tipo_botanico":"Fitoterápico adstringente/anti-inflamatório","nome_cientifico":"Myracrodruon urundeuva Allemão (sin.: Astronium urundeuva (Allemão) Engl.)","familia_botanica":"Anacardiaceae (família da manga, do caju, do pistache)"},"caracterizacao":{"aroma":"Madeira seca do sertão, tanino seco, fundo resinoso discreto.","notas":"","intensidade":"4/5 — uso terapêutico, não hedônico.","cor_da_infusao":"Marrom-avermelhado escuro, opaco. #7B3F1E","bioma_de_origem":"Caatinga — característica do bioma, endêmica da região semiárida brasileira (PI, CE, RN, PB, PE, AL, SE, BA, MG, MT, MS).","sabor_dominante":"Intensamente adstringente, amargo seco, terroso. Seca a boca de forma eficiente — uso medicinal declarado.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Myracrodruon urundeuva Allemão (sin.: Astronium urundeuva (Allemão) Engl.)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte — ECR","indicacao":"Gengivite (bochecho)","populacao":"Botelho et al. (UFRN)"},{"evidencia":"Moderada","indicacao":"Candidíase vaginal (tópico)","populacao":"Estudos in vitro e piloto"},{"evidencia":"Forte","indicacao":"Inflamação de mucosa oral","populacao":"Múltiplos estudos nacionais"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Adstringente potente","Anti-inflamatório (mucosa oral e geniturinária)","Antimicrobiano (bactérias gram+ e gram-)","Antifúngico (Candida spp.)","Cicatrizante","Gastroprotetor (uso popular)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação: evitar uso interno (dados insuficientes de segurança)","Hepatopatias graves: cautela com taninos em dose alta","Uso interno prolongado (>4 semanas) sem orientação","Espécie ameaçada: Myracrodruon urundeuva consta na lista de espécies ameaçadas do Brasil (IBAMA). Preferir fornecedores com cultivo sustentável ou certificação de manejo."],"contraindicacoes":["Gestação: evitar uso interno (dados insuficientes de segurança)","Hepatopatias graves: cautela com taninos em dose alta","Uso interno prolongado (>4 semanas) sem orientação","Espécie ameaçada: Myracrodruon urundeuva consta na lista de espécies ameaçadas do Brasil (IBAMA). Preferir fornecedores com cultivo sustentável ou certificação de manejo."],"efeitos_adversos":"","componentes_ativos":[{"label":"TANINOS HIDROLISÁVEIS (galoil-glicoses)","texto":"Adstringência, antimicrobiano, anti-inflamatório"},{"label":"TANINOS CONDENSADOS (procianidinas)","texto":"Anti-inflamatório, antioxidante"},{"label":"FENÓIS TOTAIS","texto":"Antimicrobiano, antifúngico"},{"label":"TERPENÓIDES","texto":"Anti-inflamatório secundário"},{"label":"FLAVONÓIDES (luteolina, quercetina)","texto":"Antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ecc17985-3272-483a-9959-237760919e38","slug":"jurema-preta","herb_id":null,"herb_latin_name":"Mimosa tenuiflora","schema_version":"1.1","ficha":{"slug":"jurema-preta","cultura":{"brasil":"A jurema é objeto de disputas legais e culturais complexas. O culto da jurema foi proibido pelo Estado brasileiro em períodos históricos e hoje é protegido como patrimônio cultural imaterial. A planta navega entre o status de fitoterápico cicatrizante (uso medicinal documentado), patrimônio espiritual indígena e substância psicoativa regulamentada — três categorias que raramente coexistem na mesma espécie.","historia":"A jurema é planta sagrada no Nordeste brasileiro há milênios — artefatos arqueológicos com sementes de jurema foram encontrados em sítios da Tradição Agreste (Pernambuco), datados de 2000–3000 anos. O culto da jurema — sistema espiritual indígena nordestino que incorporou elementos afro-brasileiros — é um dos fenômenos religiosos mais singulares do Brasil, com rituais de uso do \"vinho da jurema\" (bebida ritual da casca da raiz) documentados desde o século XVII.  O tepezcohuite mexicano tornou-se internacionalmente conhecido após a explosão de gás na Cidade do México (1984) — a planta foi usada em massa para tratar queimados, com resultados documentados que geraram interesse científico global.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A árvore da pele e do rito — cicatrizante da caatinga com ação antibacteriana confirmada e história sagrada nos cultos afro-brasileiros.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Colheita de casca: preferência estação seca","status_anvisa":"Uso tópico popular reconhecido. Casca da raiz: contém DMT — substância controlada.","eixo_botanico_tpc":"Fitoterápico tradicional / ritual","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Jurema-Preta","usos_topicos":{"evidencia":"","aplicacoes":["Cicatrizante de queimaduras (uso principal validado): Decocção concentrada de casca do caule, resfriada, lavagem 2–3x ao dia em queimaduras de 1° e 2° grau. Estudos clínicos mexicanos (onde a planta é chamada tepezcohuite e utilizada amplamente em queimaduras pós-erupção vulcânica) demonstraram cicatrização acelerada com redução de infecção secundária.","Xampu e condicionador capilar: Extrato de casca em formulações para dermatite seborreica e calvície (uso popular e cosmético difundido no México e Brasil)."],"contraindicacoes":""},"identificacao":{"sinonimos":["Jurema-preta · jurema-branca (espécie diferente) · tepezcohuite (México)","Mimosa hostilis (sinonímia botânica rejeitada, ainda usada comercialmente)","ATENÇÃO: A casca da raiz contém DMT (N,N-dimetiltriptamina) — substância psicoativa controlada no Brasil e em diversos países. Uso ritual regulamentado exclusivamente no contexto do culto da jurema e religiões afro-brasileiras reconhecidas."],"parte_usada":"Casca da raiz e do caule (uso medicinal); casca da raiz (uso ritual — contém DMT em concentrações variáveis).","tipo_botanico":"Fitoterápico cicatrizante e ritual","nome_cientifico":"Mimosa tenuiflora (Willd.) Poir. (sin.: Mimosa hostilis)","familia_botanica":"Fabaceae / Mimosoideae"},"caracterizacao":{"aroma":"Terra seca, madeira queimada, tanino seco, fundo levemente defumado.","notas":"","intensidade":"","cor_da_infusao":"Marrom-escuro opaco, quase preto em infusões concentradas. #2D1B0E","bioma_de_origem":"Caatinga — espécie característica da região semiárida, adaptada ao clima de extremos.","sabor_dominante":"Amargo-adstringente intenso, tanino pronunciado, fundo terroso de sertão.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Mimosa tenuiflora (Willd.) Poir. (sin.: Mimosa hostilis)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Cicatrizante acelerador de epitelização","Antibacteriano (amplo espectro)","Anti-inflamatório tópico","Antifúngico","Analgésico tópico","Componentes ativos:","Contraindicações: Uso interno da casca da raiz sem contexto ritual/clínico supervisionado — contraindicado (DMT). Gestação — evitar uso interno. Crianças — apenas uso tópico supervisionado."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"TANINOS (13–15% na casca)","texto":"Adstringente, antibacteriano, cicatrizante"},{"label":"SAPONINAS","texto":"Anti-inflamatório, antifúngico"},{"label":"ALCALÓIDES (incluindo DMT na raiz)","texto":"Psicoativo (raiz); modulação nervosa (traços em casca do caule)"},{"label":"LUPEOL, BETA-SITOSTEROL","texto":"Anti-inflamatório"},{"label":"MIRICETINA, NARINGENINA","texto":"Antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"38b72631-e604-4156-80c0-bb0345cc554f","slug":"imburana-de-cheiro","herb_id":null,"herb_latin_name":"Amburana cearensis","schema_version":"1.1","ficha":{"slug":"imburana-de-cheiro","cultura":{"brasil":"","historia":"A imburana é a árvore dos xaropes de farmácia popular nordestina. Qualquer criança criada no interior do Nordeste brasileiro conhece o cheiro inconfundível da imburana — sua casca é vendida em feiras livres de Fortaleza, Recife e Salvador desde o século XIX. Rezadeiras e raizeiros nordestinos usam a casca em garrafadas (preparados compostos de múltiplas ervas em aguardente ou mel) para tratar \"falta de ar\", \"catarro no peito\" e \"tosse danada\".  A madeira da imburana, extraordinariamente aromática, é esculpida artesanalmente em estatuetas, rosários e cachimbos no Vale do Cariri (CE) — ofício transmitido por gerações que transformou o aroma medicinal em produto cultural.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta (preservar cumarina volátil).","quantidade":"2–5 g de casca seca para 250 ml.","reinfusoes":"","combina_com":"Mel · Gengibre · Eucalipto · Hortelã (blends respiratórios) · Canela · Cravo (blends especiados nordestinos)","melhor_momento":"Manhã (respiratório/expectorante) ou à noite (antiespasmódico, sedativo leve).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"O cumaru do sertão — broncodilatador aromático da caatinga com aroma de baunilha e ação comprovada nas vias respiratórias.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Colheita de casca: estação seca (junho–outubro)","status_anvisa":"Uso tradicional reconhecido. Em análise para Formulário de Fitoterápicos.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Imburana-de-Cheiro","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Imburana-de-cheiro · amburana · cumaru-de-cheiro · cumaru-do-ceará","Cerejeira-do-sertão (MG) · louro-do-sertão (BA)","ATENÇÃO: não confundir com Dipteryx odorata (cumaru-verdadeiro), espécie amazônica diferente com aroma similar"],"parte_usada":"Casca do caule, sementes (ambas medicinais); madeira em uso artesanal.","tipo_botanico":"Fitoterápico respiratório / antiespasmódico","nome_cientifico":"Amburana cearensis (Allemão) [A.C.Sm](http://A.C.Sm).","familia_botanica":"Fabaceae / Papilionoideae"},"caracterizacao":{"aroma":"Baunilha madura, canela, cumarina doce — aroma entre baunilha e coumarin (Chanel Nº5). Extraordinariamente agradável para uma casca medicinal.","notas":"","intensidade":"3/5 — palatável, aroma sedutor, amargo discreto.","cor_da_infusao":"Âmbar-dourado, levemente opaco. #C9923A","bioma_de_origem":"Caatinga — espécie da floresta caducifólia sertaneja. Ceará, Pernambuco, Bahia, Minas Gerais.","sabor_dominante":"Doce-balsâmico pronunciado, baunilha e canela, fundo amargo discreto. Uma das poucas ervas da caatinga com perfil hedônico natural.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Amburana cearensis (Allemão) [A.C.Sm](http://A.C.Sm).","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Bronquite aguda e crônica","populacao":"Viana et al. (UFC)"},{"evidencia":"Moderada","indicacao":"Tosse seca espasmódica","populacao":"Pesquisa nordestina"},{"evidencia":"Preliminar","indicacao":"Asma leve (adjuvante)","populacao":"Modelos in vitro e animal"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Broncodilatador (relaxamento musculatura brônquica)","Expectorante (fluidifica muco brônquico)","Antiespasmódico","Analgésico (dores musculares, reumático)","Sedativo leve","Anti-inflamatório das vias respiratórias","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação — cumarina pode ser uterotônica","Hepatopatias — cumarina em dose alta hepatotóxica","Anticoagulados — potencialização (cumarina)","Crianças < 6 anos — evitar uso interno","Espécie ameaçada: Amburana cearensis está na lista de espécies ameaçadas do IBAMA — preferir fornecedores certificados de cultivo."],"contraindicacoes":["Gestação — cumarina pode ser uterotônica","Hepatopatias — cumarina em dose alta hepatotóxica","Anticoagulados — potencialização (cumarina)","Crianças < 6 anos — evitar uso interno","Espécie ameaçada: Amburana cearensis está na lista de espécies ameaçadas do IBAMA — preferir fornecedores certificados de cultivo."],"efeitos_adversos":"","componentes_ativos":[{"label":"CUMARINA (cumarin)","texto":"Broncodilatador, anti-inflamatório, anticoagulante fraco"},{"label":"AMBUROSÍDEO A","texto":"Broncodilatador — mecanismo b2-agonista parcial pesquisado"},{"label":"ISOAMBUROSÍDEO","texto":"Antiespasmódico"},{"label":"ÁCIDO OLEANÓLICO","texto":"Anti-inflamatório"},{"label":"LUPEOL, BETA-SITOSTEROL","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"9b7bc34f-45aa-4bdb-b448-445901420482","slug":"espinheira-santa","herb_id":null,"herb_latin_name":"Maytenus ilicifolia","schema_version":"1.1","ficha":{"slug":"espinheira-santa","cultura":{"brasil":"A espinheira-santa é um dos poucos exemplos de cadeia fitoterápica relativamente estruturada no Brasil — cultivo em sistema agroflorestal no Paraná, padronização de extrato, fitoterápico registrado na ANVISA e uso pelo SUS em algumas redes estaduais. Ainda assim, a maior parte do consumo é de erva solta em farmácia de manipulação ou ervanário — sem controle de qualidade padronizado.","historia":"A espinheira-santa é a erva brasileira com maior número de ensaios clínicos nacionais para indicação gastroprotetora — em grande parte, resultado do Programa CEME (Central de Medicamentos) do governo federal nos anos 1970–1980, que sistematizou a pesquisa de plantas medicinais do SUS.  Usada há séculos no Sul do Brasil (onde crescem populações nativas nas matas de araucária), foi incorporada ao conhecimento popular gaúcho e catarinense como \"remédio da roça\" para \"azia\" e \"dor de estômago\".","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta. Decocção fraca (5 min fervura suave) para uso medicinal mais concentrado.","quantidade":"1–2 colheres de sopa (3–5 g) de folhas secas para 250 ml.","reinfusoes":"","combina_com":"Funcho · Camomila · Alcaçuz · Melissa (blends digestivos suaves)","melhor_momento":"30 minutos antes das refeições (gastroprotetor), 3x ao dia.","tempo_de_infusao":"","temperatura_ideal":"90–95 °C. Não ferver (degrada triterpenos lábeis)."},"tagline":"A protetora do estômago — antiulceroso do cerrado com evidência clínica sólida e uma das monografias mais completas da fitoterapia brasileira.","receitas":[{"nome":"Digestivo Pós-Churrasco","slug":"digestivo-pos-churrasco","proposito":null},{"nome":"Gastrite Acalmada","slug":"gastrite-acalmada","proposito":null}],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas coletadas preferencialmente no período vegetativo ativo","status_anvisa":"Monografia oficial. Indicação: gastrite, úlcera gástrica e duodenal.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Espinheira-Santa","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Espinheira-santa · cancorosa · salva-vida · bálsamo · maiteno (farmacológico)","Cangorosa (Sul do Brasil) · espinheiro-divino","Mata-olho (uso popular RS/SC)"],"parte_usada":"Folhas, preferencialmente adultas, secas.","tipo_botanico":"Fitoterápico gastroprotetor / antiulceroso","nome_cientifico":"Maytenus ilicifolia Mart. ex Reissek","familia_botanica":"Celastraceae (família do espinheiro-da-europa)"},"caracterizacao":{"aroma":"Erval fresco, folha verde levemente amadeirada, fundo de chá-verde.","notas":"","intensidade":"2/5 — infusão relativamente suave, de uso cotidiano possível.","cor_da_infusao":"Verde-amarelado a âmbar-verdoso claro. #B5C96A","bioma_de_origem":"Cerrado (distribuição principal) + Mata Atlântica (RS, SC, PR — grande centro de pesquisa e uso).","sabor_dominante":"Amargo leve a moderado, verde-herbáceo, levemente adstringente, com nota final levemente doce. Mais palatável que outras ervas medicinais — admite uso regular diário.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Maytenus ilicifolia Mart. ex Reissek","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Gastrite e úlcera péptica","populacao":"Souza-Formigoni et al."},{"evidencia":"Moderada","indicacao":"Dispepsia funcional","populacao":"Múltiplos ensaios nacionais"},{"evidencia":"Moderada","indicacao":"Antiácido natural","populacao":"CEME/UFPR"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Antiulceroso (proteção da mucosa gástrica)","Antissecretor gástrico (reduz acidez)","Analgésico gástrico","Anti-inflamatório","Anticancerígeno (pesquisas com maiteansinas — ainda experimental)","Adstringente suave","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação — contraindicada (abortiva em modelos animais com doses altas)","Lactação — cautela (dados insuficientes)","Uso simultâneo com antiácidos: pode reduzir absorção"],"contraindicacoes":["Gestação — contraindicada (abortiva em modelos animais com doses altas)","Lactação — cautela (dados insuficientes)","Uso simultâneo com antiácidos: pode reduzir absorção"],"efeitos_adversos":"","componentes_ativos":[{"label":"MAITEANSINAS (alcalóides)","texto":"Antitumoral (experimental), anti-inflamatório"},{"label":"FRIEDELINA (triterpeno)","texto":"Antiulceroso, analgésico"},{"label":"CANGORÍN (polifenol)","texto":"Antissecretor gástrico"},{"label":"TANINOS TOTAIS","texto":"Adstringente, gastroprotetor"},{"label":"FLAVONÓIDES","texto":"Antioxidante, anti-inflamatório"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"90b2c082-24f4-443e-aa5f-f7e166bbf415","slug":"barbatimao","herb_id":null,"herb_latin_name":"Stryphnodendron adstringens","schema_version":"1.1","ficha":{"slug":"barbatimao","cultura":{"brasil":"","historia":"O barbatimão é a planta do cerrado com maior integração na medicina popular do Centro-Oeste brasileiro. O nome tupi — \"árvore que prende\" — descreve perfeitamente a sensação de sua casca: ela contrai, fecha, sela. Benzedeiras e curandeiros do cerrado goiano e matogrossense usam a casca para \"secar\" feridas desde antes do registro escrito.  Na medicina popular, o barbatimão tem uso dual documentado: cicatrizante de feridas da pele e \"fechador\" ginecológico — o uso em banho de assento para \"apertar\" após parto é prática de parteiras tradicionais de múltiplas regiões do Brasil Central.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"5 g de casca seca para 500 ml (uso externo). Uso interno (oral): 2–3 g/250 ml.","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":"Decocção a 98 °C."},"tagline":"O tanino mais poderoso do cerrado — cicatrizante de alta performance com ação comprovada em curativos e formulações dermatológicas.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Casca coletada no período seco — maior concentração de taninos","status_anvisa":"Monografia oficial. Fitoterápico semi-sólido (pomada) registrado.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Barbatimão","usos_topicos":{"evidencia":"","aplicacoes":["Curativo cicatrizante (uso principal): Decocção concentrada em curativo úmido sobre feridas limpas — evidência clínica forte. Produto fitoterápico semi-sólido (pomada de barbatimão) é o segundo fitoterápico mais vendido em farmácias de manipulação do Brasil.","Bochecho para gengivite e aftas: Decocção 3 g/200 ml, morna, bochecho 30 s, 3x ao dia. Evidência forte — ação adstringente-antimicrobiana das procianidinas.","Banho de assento para vulvovaginites: Decocção fraca, morna, 15 min. Uso popular difundido."],"contraindicacoes":""},"identificacao":{"sinonimos":["Barbatimão · casca-de-barbatimão · ubatimó (tupi: \"árvore que prende\")","Favela · casca-da-virgindade (uso popular)","Stryphnodendron (farmacológico internacional)"],"parte_usada":"Casca do caule (entrecasca), rica em taninos totais (até 25% em peso seco).","tipo_botanico":"Fitoterápico cicatrizante e adstringente","nome_cientifico":"Stryphnodendron adstringens (Mart.) Coville","familia_botanica":"Fabaceae / Mimosoideae"},"caracterizacao":{"aroma":"Tanino seco, madeira cortada, fundo levemente terroso.","notas":"","intensidade":"5/5 — uso 100% medicinal.","cor_da_infusao":"Marrom-avermelhado muito escuro, opaco. #5C2414","bioma_de_origem":"Cerrado — amplamente distribuído no bioma; GO, MT, MS, MG, SP, BA, PI.","sabor_dominante":"Fortíssimamente adstringente — seca completamente a boca. Amargo intenso. Uso medicinal exclusivo — não tem apelo hedônico.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Stryphnodendron adstringens (Mart.) Coville","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Cicatrizante acelerador de epitelização","Adstringente potente","Antimicrobiano (gram+ e gram-)","Antifúngico","Anti-inflamatório local","Hemostático (compressão adstringente)","Componentes ativos:"],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"TANINOS TOTAIS","texto":"18–25% (casca seca) — Adstringência, cicatrizante, antimicrobiano"},{"label":"PROCIANIDINAS (condensados)","texto":"Maioria dos taninos — Anti-inflamatório, antioxidante"},{"label":"GALOIL-GLICOSES (hidrolisáveis)","texto":"Presentes — Antimicrobiano"},{"label":"ÁCIDO GÁLICO","texto":"Produto de hidrólise — Antioxidante, antimicrobiano"},{"label":"SAPONINAS","texto":"Traços — Anti-inflamatório"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"388a250e-2246-492e-a994-0b55a09e82b0","slug":"pata-de-vaca","herb_id":null,"herb_latin_name":"Bauhinia forficata","schema_version":"1.1","ficha":{"slug":"pata-de-vaca","cultura":{"brasil":"A pata-de-vaca é o fitoterápico hipoglicemiante mais consumido no Brasil — estimativas apontam que mais de 15% dos diabéticos brasileiros usam alguma forma de preparado de pata-de-vaca regularmente. Esse dado, levantado em pesquisas de uso popular, revelou um sistema paralelo de manejo do diabetes que opera fora do radar do SUS — motivando décadas de pesquisa universitária para validação e segurança.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples, coberta.","quantidade":"1–2 colheres de sopa (3–5 g) de folhas secas para 250 ml.","reinfusoes":"","combina_com":"Canela · Pata-de-vaca + Insulina-vegetal + Jambolão = blend hipoglicemiante clássico popular","melhor_momento":"30 minutos antes das refeições principais (ação hipoglicemiante prandial).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"A insulina vegetal do cerrado — hipoglicemiante oral com décadas de uso popular e evidência clínica crescente no manejo do diabetes tipo 2.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas coletadas no período vegetativo (setembro–março)","status_anvisa":"Monografia oficial. Indicação: coadjuvante no tratamento do diabetes.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Pata-de-Vaca","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Pata-de-vaca · mororó · casco-de-vaca · unha-de-vaca","Pezuña de vaca (espanhol) · orchid tree leaf (inglês)","ATENÇÃO: Gênero Bauhinia tem centenas de espécies — atividade hipoglicemiante é espécie-específica"],"parte_usada":"Folhas secas (preferencialmente adultas).","tipo_botanico":"Fitoterápico hipoglicemiante / diurético","nome_cientifico":"Bauhinia forficata Link","familia_botanica":"Fabaceae / Caesalpinioideae"},"caracterizacao":{"aroma":"Folha verde seca, herbáceo suave, feno levemente adocicado.","notas":"","intensidade":"2/5 — suave, uso diário viável.","cor_da_infusao":"Verde-amarelado a âmbar claro. #C8B850","bioma_de_origem":"Cerrado, caatinga e mata atlântica — espécie de ampla distribuição.","sabor_dominante":"Levemente amargo, herbáceo-vegetal, levemente adstringente, verde. Palatável — uso cotidiano possível.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Bauhinia forficata Link","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Diabetes mellitus tipo 2 (coadjuvante)","populacao":"Múltiplos ECR nacionais"},{"evidencia":"Preliminar","indicacao":"Hipercolesterolemia","populacao":"Estudos animais e piloto"},{"evidencia":"Tradicional forte","indicacao":"Diurético (retenção hídrica leve)","populacao":"Farmacopeia popular"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Hipoglicemiante (redução de glicemia pós-prandial)","Diurético","Hipolipemiante (redução de colesterol e triglicerídeos)","Anti-inflamatório","Antioxidante","Componentes ativos:","Indicações com evidência:","Contraindicações:","Hipoglicemia — potencialização de hipoglicemiantes orais e insulina","Gestação — dados insuficientes","Monitorar glicemia em diabéticos em uso concomitante de medicamentos","IMPORTANTE: A pata-de-vaca é adjuvante — nunca substituta de medicação antidiabética prescrita. Informar médico sobre uso."],"contraindicacoes":["Hipoglicemia — potencialização de hipoglicemiantes orais e insulina","Gestação — dados insuficientes","Monitorar glicemia em diabéticos em uso concomitante de medicamentos","IMPORTANTE: A pata-de-vaca é adjuvante — nunca substituta de medicação antidiabética prescrita. Informar médico sobre uso."],"efeitos_adversos":"","componentes_ativos":[{"label":"FLAVONÓIDES (quercetina, canferol, miricetina)","texto":"Hipoglicemiante, antioxidante"},{"label":"GLUCOSIL-ISOORIENTINA","texto":"Hipoglicemiante — inibição de alfaglicosidase"},{"label":"LECITINAS","texto":"Regulação metabólica"},{"label":"ÁCIDOS GRAXOS","texto":"Anti-inflamatório"},{"label":"TANINOS","texto":"Adstringente, antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"07462dd6-1186-4e97-afbc-386502547425","slug":"pequi","herb_id":null,"herb_latin_name":"Caryocar brasiliense","schema_version":"1.1","ficha":{"slug":"pequi","cultura":{"brasil":"O pequi é um dos produtos mais promissores da bioeconomia do cerrado para exportação como \"superalimento\" — alto valor de carotenóides, ácido palmitoleico (raro em fontes vegetais) e perfil de marketing exótico-brasileiro. Startups de biocosmética brasileira já exportam óleo de pequi para Europa e Japão em formulações premium de skincare.","historia":"O pequi é o símbolo alimentar do cerrado como o açaí é da Amazônia — não é apenas um alimento, é identidade cultural. O arroz-com-pequi é o prato de festa do interior de Goiás e Minas Gerais. A culinária sertaneja, o cerrado e o pequi são inseparáveis na memória gastronômica do Brasil Central.  O mito indígena kayapó narra que o pequi nasceu do corpo de uma jovem — daí seus espinhos internos (que perfuram quem come com avidez) serem chamados de \"a defesa da moça\". É a planta que ensina a comer com calma.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O ouro do cerrado — fruto-símbolo do bioma que concentra carotenóides, ácidos graxos raros e uma cultura culinária-medicinal única no mundo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutificação: outubro–janeiro","status_anvisa":"Regulado como alimento. Óleo cosmético — regulamentado.","eixo_botanico_tpc":"Alimento funcional / Fitoterápico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Pequi","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Pequi · piqui · souari nut (inglês) · amande du Brésil (francês — incorreto, confunde com castanha-do-pará)"],"parte_usada":"Polpa (alimentar), óleo da polpa e da amêndoa (cosmético e medicinal), folhas (infusão).","tipo_botanico":"Alimento funcional / fitoterápico","nome_cientifico":"Caryocar brasiliense Cambess.","familia_botanica":"Caryocaraceae"},"caracterizacao":{"aroma":"","notas":"","intensidade":"","cor_da_infusao":"","bioma_de_origem":"Cerrado — endêmico do bioma; GO, MG, TO, MT, BA, PI, MA.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Caryocar brasiliense Cambess.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antioxidante potente (beta-caroteno, licopeno, zeaxantina)","Anti-inflamatório (ácido oleico, ácido palmitoleico)","Imunomodulador","Neuroprotetor (carotenóides lipofílicos)","Cardioprotetor (perfil de ácidos graxos)","Componentes ativos:","Contraindicações: Alergia ao fruto (rara). Cálculo renal de oxalato — cautela com consumo excessivo de polpa."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"BETA-CAROTENO","texto":"Alta — óleo de polpa — Antioxidante, pró-vitamina A"},{"label":"LICOPENO","texto":"Presente — Antioxidante, antiproliferativo"},{"label":"ÁCIDO OLEICO (C18:1)","texto":"46–54% do óleo — Cardioprotetor"},{"label":"ÁCIDO PALMITOLEICO (C16:1)","texto":"25–30% — Anti-inflamatório raro"},{"label":"ZEAXANTINA","texto":"Presente — Proteção visual, antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"63b94f2e-15f8-4945-af02-27ae7df42dc2","slug":"erva-mate","herb_id":null,"herb_latin_name":"Ilex paraguariensis","schema_version":"1.1","ficha":{"slug":"erva-mate","cultura":{"brasil":"O Brasil é o segundo maior produtor mundial de erva-mate (atrás da Argentina), com produção concentrada no Paraná, Santa Catarina e Rio Grande do Sul. Mais de 700 municípios brasileiros têm erva-mate como parte de sua história econômica.  A erva-mate está em acelerada internacionalização — nos EUA e Europa, o \"yerba mate\" virou bebida de nicho premium (marcas como Guayakí arrecadam centenas de milhões de dólares com posicionamento de \"energia sustentável\" para millennials). O Brasil, principal produtor histórico, captura fração mínima desse mercado premium global.","historia":"A erva-mate é a única bebida com civilização própria que o Brasil produziu. Os Guaranis a chamavam de \"caá\" — folha divina — e desenvolveram todo um sistema ritual, agrícola e comercial em torno da planta antes da chegada europeia. Os jesuítas, inicialmente avessos (\"bebida do diabo\"), tornaram-se os maiores produtores e comerciantes de erva-mate das Américas no século XVII — as reduções jesuíticas do Rio Grande do Sul e Misiones eram impérios ervateiros.  O chimarrão gaúcho transcendeu a bebida — é símbolo de identidade regional, rito de hospitalidade, marcador social. Recusar um chimarrão oferecido é deselegância grave no interior gaúcho. Aceitar é comunhão.","cerimonial":"A roda de chimarrão — círculo de pessoas passando a cuia de mão em mão, cada um bebendo até secar, devolvendo, aguardando a volta — é uma das cerimônias de comunhão mais democráticas do Brasil. Não tem hierarquia de servir: a cuia circula.","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Limão · Hortelã · Hibisco · Gengibre · Canela (blends de chá-mate) · Frutas cítricas (tererê)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A infusão do Sul do mundo — o único estimulante com civilização própria, da cerimônia gaúcha à produção global de US$ 1 bilhão.","receitas":[{"nome":"Tônico Matinal da Mata","slug":"tonico-matinal-da-mata","proposito":null},{"nome":"Infusão do Atleta","slug":"infusao-do-atleta","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — traditional use. Indicação: fadiga.","status_fda":"GRAS para uso alimentar","sazonalidade":"Colheita ano-todo; melhor qualidade: inverno (maio–agosto)","status_anvisa":"Monografia oficial. Indicações: estimulante, coadjuvante de emagrecimento.","eixo_botanico_tpc":"Phyto-ANVISA + Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Erva-Mate","usos_topicos":{"evidencia":"","aplicacoes":["Tônico capilar: Infusão forte resfriada, aplicada no couro cabeludo — uso popular para queda de cabelo. Evidência preliminar (xantinas estimulam circulação capilar).","Creme anti-aging: Extrato de mate em formulações cosméticas — antioxidante de ORAC elevado. Amplamente usado pela indústria cosmética global."],"contraindicacoes":""},"identificacao":{"sinonimos":["Erva-mate · mate · chimarrão · congonha · ilex","Yerba mate (espanhol) · Maté (francês/inglês)","Caá (guarani: \"folha divina\")"],"parte_usada":"Folhas e ramos finos, secos (canchada = erva-mate verde; tostada = chimarrão mais suave; elaborada = tererê).","tipo_botanico":"Estimulante herbal monografado / alimento funcional","nome_cientifico":"Ilex paraguariensis [A.St](http://A.St).-Hil.","familia_botanica":"Aquifoliaceae (família do azevinho)"},"caracterizacao":{"aroma":"Clorofila fresca, feno, erva cortada (verde) / caramelo-tostado-amadeirado (tostado). Um dos aromas mais complexos do catálogo.","notas":"Cabeça: verde-clorofílico ou tostado | Corpo: vegetal encorpado, umami | Fundo: amargo limpo, adstringência leve | BIOMA: Mata Atlântica — floresta de araucária (RS, SC, PR) e mata atlântica interior (MS, SP). Argentina (Misiones) e Paraguai: maiores produtores mundiais.","intensidade":"3–4/5 (variável por processamento).","cor_da_infusao":"Verde-intenso (chimarrão) a marrom-ouro (tererê, chá-mate). #4A7C3F (chimarrão) / #A67B4B (tostado)","bioma_de_origem":"Mata Atlântica — floresta de araucária (RS, SC, PR) e mata atlântica interior (MS, SP). Argentina (Misiones) e Paraguai: maiores produtores mundiais.","sabor_dominante":"Vegetal-amargo intenso (chimarrão verde) a suave-tostado-herbáceo (mate tostado). Amplo espectro por processamento. Umami discreto em mate envelhecido.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Ilex paraguariensis [A.St](http://A.St).-Hil.","perfil_sensorial":{"tatil":"O chimarrão é a infusão mais encorpada do catálogo sul-americano — corpo denso, quase espesso, que justifica o ritual da cuia e da bomba. A bomba não é apenas filtragem — é a ferramenta que viabiliza uma textura impossível em xícara comum.","gustativo":[{"dimensao":"Doce","observacao":"1/3","intensidade":"0/3"},{"dimensao":"Amargo","observacao":"2/3","intensidade":"3/3"},{"dimensao":"Umami","observacao":"1/3","intensidade":"1/3"},{"dimensao":"Azedo","observacao":"0/3","intensidade":"0/3"},{"dimensao":"Adstringência","observacao":"Baixa","intensidade":"Moderada"}],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte","indicacao":"Fadiga mental e física","populacao":"Múltiplos estudos"},{"evidencia":"Moderada","indicacao":"Coadjuvante de emagrecimento","populacao":"Andersen et al."},{"evidencia":"Moderada","indicacao":"Redução de LDL e colesterol","populacao":"Studinicka et al."},{"evidencia":"Preliminar","indicacao":"Proteção cardiovascular","populacao":"Epidemiologia do Sul do Brasil"}],"interacoes":[{"label":"Anticoagulantes — rutina potencializa levemente","texto":""},{"label":"Outros estimulantes — síndrome de hiperestimulação","texto":""},{"label":"Ferro — taninos reduzem absorção (evitar junto com refeições ricas em ferro)","texto":""}],"dose_maxima":"","acoes_principais":["Estimulante do SNC (cafeína + teobromina)","Termogênico / coadjuvante de controle de peso","Antioxidante (ORAC elevado — superior ao chá-verde em alguns estudos)","Cardioprotetor (redução de LDL oxidado)","Diurético suave","Hepatoprotetor (estudos preliminares)","Imunomodulador (saponinas — mateína)","Componentes ativos:","Indicações com evidência:","Contraindicações: Hipertensão não controlada. Gestação (limitar cafeína total a <200 mg/dia). Gastrite ativa — irritante. Ansiedade — potencialização.","Interações:","Anticoagulantes — rutina potencializa levemente","Outros estimulantes — síndrome de hiperestimulação","Ferro — taninos reduzem absorção (evitar junto com refeições ricas em ferro)"],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"CAFEÍNA","texto":"0,5–1,7% (folha seca) — Estimulante SNC"},{"label":"TEOBROMINA","texto":"0,3–0,5% — Vasodilatação, broncodilatação leve"},{"label":"TEOFILINA","texto":"Traços — Broncodilatação"},{"label":"ÁCIDO CLOROGÊNICO","texto":"Alto — Antioxidante, hipoglicemiante"},{"label":"SAPONINAS (mateína)","texto":"Presente — Imunomodulador, adaptogênico discutido"},{"label":"RUTINA","texto":"Presente — Cardioprotetor, antioxidante vascular"},{"label":"VITAMINAS (C, B1, B2, B6)","texto":"Presentes — Nutritivo"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"009d7666-0e10-403e-8892-468d0055e6a1","slug":"guaco","herb_id":null,"herb_latin_name":"Mikania glomerata","schema_version":"1.1","ficha":{"slug":"guaco","cultura":{"brasil":"O guaco é o fitoterápico respiratório mais vendido em farmácias de manipulação e ervanários brasileiros — o xarope de guaco com mel é presença obrigatória em armários de remédio de famílias do interior de São Paulo, Rio, Minas e Sul do Brasil.  A ANVISA aprovou o xarope de guaco como fitoterápico registrado — um dos poucos produtos fitoterápicos com registro completo e rastreabilidade de cadeia no Brasil.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta. Decocção suave também usada.","quantidade":"2–3 g de folhas secas para 250 ml.","reinfusoes":"","combina_com":"Mel · Limão · Eucalipto · Tomilho · Gengibre (blends respiratórios)","melhor_momento":"3x ao dia em episódios agudos; 2x/dia em uso preventivo.","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"O broncodilatador da floresta — expectorante e antiasmático com monografia oficial e um dos maiores volumes de consumo em fitoterápicos brasileiros.","receitas":[{"nome":"Bronquite do Inverno","slug":"bronquite-do-inverno","proposito":null}],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas coletadas preferentemente no período vegetativo ativo","status_anvisa":"Monografia oficial. Fitoterápico xarope registrado. Indicação: expectorante, broncodilatador.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Guaco","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Guaco · guaco-liso · mikânia · coração-de-jesus · cipó-caatinga","Guaco (uso mantido em espanhol) · climbing hemp weed (inglês)"],"parte_usada":"Folhas secas.","tipo_botanico":"Fitoterápico broncodilatador / expectorante","nome_cientifico":"Mikania glomerata Spreng. (Mikania laevigata também aceita — quimiotipo diferente)","familia_botanica":"Asteraceae (família da camomila, do girassol)"},"caracterizacao":{"aroma":"Cumarina característica (baunilha-coumarin), folha verde, levemente balsâmico.","notas":"","intensidade":"3/5 — medicinal mas tolerável.","cor_da_infusao":"Verde-amarelado a âmbar. #9CB558","bioma_de_origem":"Mata Atlântica — espécie trepadeira de bordas de mata, SE, SP, RJ, PR, RS, SC.","sabor_dominante":"Amargo-herbáceo intenso, levemente resinoso, fundo de cumarina (baunilha amarga). Mais palatável com mel — uso medicinal respiratório.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Mikania glomerata Spreng. (Mikania laevigata também aceita — quimiotipo diferente)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Tosse produtiva","populacao":"ANVISA Formulário Fitoterápico"},{"evidencia":"Moderada","indicacao":"Bronquite aguda","populacao":"Múltiplos ensaios nacionais"},{"evidencia":"Preliminar","indicacao":"Asma leve (adjuvante)","populacao":"Estudos in vitro"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Broncodilatador (relaxamento musculatura brônquica)","Expectorante (fluidifica secreções)","Antiespasmódico brônquico","Anti-inflamatório das vias aéreas","Antialérgico leve (inibição de mediadores)","Antipirético","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação — cumarina uterotônica, evitar","Hepatopatias — cautela com cumarina","Anticoagulados — potencialização (cumarina)","Alergia à família Asteraceae (reação cruzada possível)"],"contraindicacoes":["Gestação — cumarina uterotônica, evitar","Hepatopatias — cautela com cumarina","Anticoagulados — potencialização (cumarina)","Alergia à família Asteraceae (reação cruzada possível)"],"efeitos_adversos":"","componentes_ativos":[{"label":"CUMARINA","texto":"Broncodilatador — mecanismo b2-agonista parcial"},{"label":"ÁCIDO CAURENÓICO (diterpeno)","texto":"Anti-inflamatório, antibacteriano"},{"label":"LACTONAS SESQUITERPÊNICAS","texto":"Anti-inflamatório, antialérgico"},{"label":"SAPONINAS","texto":"Expectorante"},{"label":"FLAVONÓIDES (quercetina, rutina)","texto":"Antioxidante, anti-inflamatório"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ea6c49f4-3554-48a6-b9e3-1b64d6765b57","slug":"pitanga","herb_id":null,"herb_latin_name":"Eugenia uniflora","schema_version":"1.1","ficha":{"slug":"pitanga","cultura":{"brasil":"A pitanga tem potencial de exportação como \"superfruit\" antioxidante quase inexplorado. O licopeno da pitanga vermelha é superior ao do tomate em concentração — dado que, com marketing adequado, justificaria posicionamento premium em mercados europeus e norte-americanos. Hoje, praticamente 100% do consumo é local e informal.","historia":"A pitanga é a fruta da infância do Brasil costeiro — toda casa de interior do Sul e Sudeste tinha (ou tem) um pé de pitanga no quintal. Euclides da Cunha e Carlos Drummond de Andrade a mencionam em textos como símbolo da natureza mineira e carioca. É uma das primeiras frutas que as crianças aprendem a colher — cor vermelha chamar, sabor memorável guardar.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Hibisco · Açaí · Jabuticaba · Maracujá (blends antioxidantes da Mata Atlântica)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A joia vermelha da mata atlântica — antioxidante potente, hipotensora e com perfil sensorial que rivaliza qualquer fruta do hemisfério norte em complexidade aromática.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutificação: setembro–dezembro (principal), com segunda safra em regiões mais quentes","status_anvisa":"Alimento. Folhas: uso tradicional reconhecido.","eixo_botanico_tpc":"Alimento funcional / Fitoterápico","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Pitanga","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Pitanga · pitangueira · cereja-brasileira","Surinam cherry (inglês) · Cerise carée (francês)","Ñangapirí (guarani)"],"parte_usada":"Fruto (alimentar); folhas (infusão medicinal).","tipo_botanico":"Alimento funcional antioxidante / fitoterápico","nome_cientifico":"Eugenia uniflora L.","familia_botanica":"Myrtaceae (família da goiaba, da jabuticaba, do eucalipto)"},"caracterizacao":{"aroma":"","notas":"","intensidade":"4/5 para o fruto; 2/5 para a infusão de folhas.","cor_da_infusao":"","bioma_de_origem":"Mata Atlântica — amplamente distribuída; RS, SC, PR, SP, RJ, MG, BA.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Eugenia uniflora L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antioxidante potente (licopeno + antocianinas)","Antihipertensivo (vasodilator — flavonóides)","Antidiarreico (folhas — taninos)","Hipoglicemiante leve (folhas)","Anti-inflamatório","Antiviral (terpenos — estudos preliminares)","Repelente natural de insetos (óleos essenciais das folhas)","Componentes ativos:","Contraindicações: Sem contraindicações relevantes em uso alimentar. Folhas em decocção: gestação — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"LICOPENO","texto":"Antioxidante, antiproliferativo — concentração superior ao tomate"},{"label":"ANTOCIANINAS (fruto negro)","texto":"Antioxidante, anti-inflamatório"},{"label":"VITAMINA C","texto":"Antioxidante — 30–40 mg/100g"},{"label":"ÓLEOS ESSENCIAIS FOLHAS (mirceno, limoneno)","texto":"Antimicrobiano, repelente"},{"label":"TANINOS (folhas)","texto":"Antidiarreico, adstringente"},{"label":"QUERCETINA, MIRICETINA","texto":"Anti-inflamatório, antihipertensivo"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"d3670f44-8cb9-4d1c-98e0-2b210ddc0f69","slug":"jurubeba","herb_id":null,"herb_latin_name":"Solanum paniculatum","schema_version":"1.1","ficha":{"slug":"jurubeba","cultura":{"brasil":"A jurubeba é o digestivo hepático do interior brasileiro por excelência — tão difundida quanto a carqueja no Sul, mas com perfil geográfico nordestino e sudestino mais marcado. \"Boteco de jurubeba\" — estabelecimentos populares do interior de São Paulo e Minas que servem aperitivo de jurubeba como digestivo pré e pós-refeição — são estabelecimentos que perpetuam uso milenar. O amargo de jurubeba é encontrado em farmácias de manipulação de todo o Sudeste.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção. Maceração alcoólica (tintura) — forma mais eficaz de extração de alcalóides.","quantidade":"3–5 g de frutos secos/raiz para 500 ml.","reinfusoes":"","combina_com":"Carqueja · Boldo · Alcachofra (blends hepáticos)","melhor_momento":"20–30 min antes das refeições (estimula digestão e bílis).","tempo_de_infusao":"","temperatura_ideal":"Decocção a 95 °C."},"tagline":"O guardião do fígado nordestino — digestivo e hepatoprotetor com tradição do interior brasileiro e uso popular que antecede qualquer pesquisa farmacológica.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutos imaturos: ano todo (floração e frutificação contínua)","status_anvisa":"Uso tradicional reconhecido.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Jurubeba","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Jurubeba · jubeba · joá-manso · jaúna","Jurubeba (uso único no Brasil — sem equivalente externo)"],"parte_usada":"Fruto imaturo (principal); raiz; folhas.","tipo_botanico":"Fitoterápico hepático / digestivo amargo","nome_cientifico":"Solanum paniculatum L.","familia_botanica":"Solanaceae (família do tomate, da berinjela, da batata)"},"caracterizacao":{"aroma":"Herbáceo-resinoso, levemente solanáceo.","notas":"","intensidade":"4/5 — uso medicinal declarado.","cor_da_infusao":"Verde-escuro a marrom-oliváceo. #5A7230","bioma_de_origem":"Mata Atlântica, Cerrado, Caatinga — ampla distribuição, especialmente NE e SE do Brasil.","sabor_dominante":"Muito amargo, resinoso-alcaloídico, persistente. Amargura intensa de solanácea — característico e não palatável puro.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Solanum paniculatum L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Colagogo (estimula secreção de bílis)","Hepatoprotetor","Digestivo amargo","Hipoglicemiante","Anti-inflamatório hepático","Diurético suave","Componentes ativos:","Contraindicações: Gestação — alcalóides de solanácea, evitar. Crianças < 6 anos — contraindicado. Hepatite aguda ativa — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"ALCALÓIDES ESTEROÍDICOS (solamargina, solasonina)","texto":"Colagogo, hepatoprotetor"},{"label":"SAPONINAS ESTEROÍDICAS","texto":"Digestivo, hipoglicemiante"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório, antioxidante"},{"label":"FITOSTERÓIS","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"2ca05129-018d-48c0-8308-ae74ef23c69c","slug":"tansagem","herb_id":null,"herb_latin_name":"Plantago major","schema_version":"1.1","ficha":{"slug":"tansagem","cultura":{"brasil":"","historia":"Os povos indígenas das Américas chamavam a tansagem de \"planta do homem branco\" ou \"pegadas do inglês\" — reconhecendo que a planta chegou com os colonizadores europeus e crescia no rastro de seus caminhos. Essa história de invasão biológica silenciosa — a tansagem colonizou as Américas com a mesma eficiência que os humanos — é uma das mais fascinantes da etnobotânica.  Na Europa, a tansagem (plantain) é mencionada nas 10 ervas sagradas dos anglos-saxões e nos escritos de Hildegarda de Bingen como planta universal de cura. É a erva de todos os povos — não tem origem exclusiva, pertence a todos os lugares que habitou.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples coberta.","quantidade":"3–5 g folhas secas/250 ml","reinfusoes":"","combina_com":"Mel · Tomilho · Guaco · Eucalipto (blends respiratórios)","melhor_momento":"3x ao dia em episódios agudos de tosse; qualquer hora para uso tópico.","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 5–8 min coberto | Quantidade: 3–5 g folhas secas/250 ml"},"tagline":"A planta dos caminhos — expectorante e cicatrizante universal que cresceu por todo o mundo nos passos europeus e foi incorporada a todas as farmacopeias tradicionais dos biomas que a recebeu.","receitas":[{"nome":"Alívio de Alergia Sazonal","slug":"alivio-de-alergia-sazonal","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — traditional use para irritação mucosa oral e expectorante.","status_fda":"","sazonalidade":"Disponível o ano todo (planta ruderal perene)","status_anvisa":"Uso tradicional reconhecido.","eixo_botanico_tpc":"Funcional global / Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Tansagem","usos_topicos":{"evidencia":"","aplicacoes":["Cataplasma cicatrizante: Folhas frescas maceradas ou aquecidas, aplicadas diretamente sobre feridas, cortes e picadas de inseto. Uso milenar com evidência moderada.","Bochecho para aftas e gengivite: Infusão forte, morna, 30 s de bochecho 3x ao dia. Anti-inflamatório e cicatrizante de mucosa oral."],"contraindicacoes":""},"identificacao":{"sinonimos":["Tansagem · transagem · plantagem · tranchagem · chapéu-de-couro (confusão)","Plantain (inglês/francês) · Wegerich (alemão) · Llantén (espanhol)","\"Planta branca do homem\" (nomes indígenas das Américas — seguia os colonizadores europeus)"],"parte_usada":"Folhas (principal); sementes (mucilagem laxativa).","tipo_botanico":"Fitoterápico expectorante / cicatrizante / antialérgico","nome_cientifico":"Plantago major L.","familia_botanica":"Plantaginaceae"},"caracterizacao":{"aroma":"Folha verde fresca, herbáceo limpo, levemente terroso.","notas":"","intensidade":"1–2/5 — suave, de uso cotidiano fácil.","cor_da_infusao":"Verde-amarelado pálido. #C8D060","bioma_de_origem":"","sabor_dominante":"Levemente amargo-herbáceo, vegetal fresco, mucilaginoso (folhas frescas). Neutro e inofensivo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Plantago major L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Expectorante (mucilagens)","Cicatrizante (alanthoína)","Antialérgico (inibição de histamina)","Anti-inflamatório","Antimicrobiano","Demulcente (protege mucosas irritadas)","Componentes ativos:","Contraindicações: Praticamente sem contraindicações em doses usuais. Sementes (mucilagem intensa): obstrução intestinal — contraindicado."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"MUCILAGENS (arabinoxilanas)","texto":"Demulcente, expectorante, laxativo suave"},{"label":"ALANTOÍNA","texto":"Cicatrizante, regenerador celular"},{"label":"AUCUBOSÍDEO (iridóide)","texto":"Anti-inflamatório, antialérgico"},{"label":"CATALPOL","texto":"Anti-inflamatório, antioxidante"},{"label":"ÁCIDO CAFEICO","texto":"Antioxidante, anti-inflamatório"},{"label":"ZINCO, SILÍCIO","texto":"Cicatrizante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"29712d86-362a-4fc5-8b3d-c9352bf0ed9a","slug":"solidago","herb_id":null,"herb_latin_name":"Solidago chilensis","schema_version":"1.1","ficha":{"slug":"solidago","cultura":{"brasil":"A solidago sul-americana é prima-irmã da Solidago virgaurea europeia — a \"vara-de-ouro\" das farmacopeias de Hildegarda de Bingen e dos herbalistas ingleses medievais. No Sul do Brasil, a solidago local (chamada popularmente \"arnica-do-brasil\" — o que é botanicamente incorreto) é usada para \"reumatismo\", \"inflamação\" e \"pedra nos rins\" com a mesma lógica da valerosa europeia.  Essa continuidade de uso entre espécies separadas por continentes mas filogeneticamente próximas é um dos fenômenos mais fascinantes da etnobotânica comparada — e uma das histórias que o Ervatório pode narrar de forma única.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta.","quantidade":"2–4 g/250 ml","reinfusoes":"","combina_com":"Cavalinha · Dente-de-leão · Salsaparrilha (blends diuréticos) · Arnica · Sucupira (blends articulares)","melhor_momento":"Manhã e tarde (diurético — evitar à noite). 3x ao dia em tratamento antirreumático.","tempo_de_infusao":"","temperatura_ideal":"90–95 °C | Tempo: 8–10 min coberto | Quantidade: 2–4 g/250 ml"},"tagline":"A reumatismo-da-mata — anti-inflamatório diurético da Mata Atlântica e Pampas com tradição sul-americana robusta e reconhecimento na farmacopeia europeia para seu congênere norte-americano.","receitas":[{"nome":"Compressa Anti-Inflamatória (Uso Externo)","slug":"compressa-anti-inflamatoria-uso-externo","proposito":null}],"regulacao":{"status_ema":"S. virgaurea — monografia HMPC para vias urinárias. S. chilensis: sem monografia.","status_fda":"","sazonalidade":"Floração: novembro–fevereiro (verão sulino)","status_anvisa":"Uso tradicional reconhecido.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Solidago","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Solidago · arnica-do-brasil · arnica-da-praia (confusão popular)","Vara-de-ouro · erva-lanceta","Goldenrod (inglês — nome da espécie norte-americana S. virgaurea)"],"parte_usada":"Partes aéreas com flores, secas.","tipo_botanico":"Fitoterápico diurético / anti-inflamatório / antirreumático","nome_cientifico":"Solidago chilensis Meyen (sin.: Solidago microglossa DC.)","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Herbáceo seco, feno florido, leve resinoso-aromático.","notas":"","intensidade":"2/5 — infusão suave, uso cotidiano possível.","cor_da_infusao":"Amarelo-dourado a âmbar claro. #D4B040","bioma_de_origem":"Mata Atlântica e Pampas — RS, SC, PR, SP, RJ.","sabor_dominante":"Levemente amargo-herbáceo, discretamente resinoso, adstringência muito leve. Palatável.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Solidago chilensis Meyen (sin.: Solidago microglossa DC.)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Infecções urinárias (adjuvante)","populacao":"EMA (S. virgaurea)"},{"evidencia":"Moderada","indicacao":"Cálculo renal (prevenção)","populacao":"Tradição europeia + pesquisa"},{"evidencia":"Tradicional forte","indicacao":"Dor articular reumatoide","populacao":"Farmacopeia popular sulista"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Diurético (aumento de diurese sem depleção de K+)","Anti-inflamatório articular","Antirreumático","Antimicrobiano (infecções urinárias)","Analgésico leve","Antiespasmódico de vias urinárias","Componentes ativos:","Indicações com evidência:","Contraindicações: Edema cardíaco ou renal — contraindicado (diurético intenso). Alergia à família Asteraceae."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"SAPONINAS TRITERPÊNICAS (virgaureasaponinas)","texto":"Diurético, anti-inflamatório"},{"label":"FLAVONÓIDES (rutina, isoramnetina)","texto":"Anti-inflamatório, antioxidante"},{"label":"DITERPENOS (clerodanos)","texto":"Antimicrobiano, anti-inflamatório"},{"label":"ÁCIDO CLOROGÊNICO","texto":"Antioxidante, anti-inflamatório"},{"label":"POLIFENÓIS","texto":"Antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"491900de-d151-4df2-a956-e0fb12e41ea5","slug":"aroeira-mansa","herb_id":null,"herb_latin_name":"Schinus terebinthifolia","schema_version":"1.1","ficha":{"slug":"aroeira-mansa","cultura":{"brasil":"A aroeira-mansa é a erva da Mata Atlântica com maior potencial de dois mercados simultâneos: gastronômico premium (pimenta-rosa) e fitoterápico documentado. A sinergia entre identidade culinária reconhecida globalmente e validação medicinal crescente é o posicionamento ideal para exportação europeia.","historia":"A pimenta-rosa brasileira chegou à alta gastronomia europeia na década de 1980 quando chefs franceses descobriram seu perfil aromático único — a mezcla de pimenta, resina e flor que a pimenta-do-reino nunca teve. Tornou-se ingrediente de alta cozinha de Paris antes de ser reconhecida como planta medicinal brasileira.  A ironia é que a Schinus terebinthifolia é considerada espécie invasora na Flórida (EUA) e no Hawaii — onde foi introduzida como ornamental e se tornou plaga ecológica. A mesma árvore que o Brasil trata como nativa preciosa é erradicada como praga nos EUA.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Cardamomo · Gengibre · Canela · Cravo · Pimenta-do-reino · Mel (blends especiados premium)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A pimenta-rosa da floresta — anti-inflamatória e antisséptica da Mata Atlântica que conquistou a alta gastronomia mundial como especiaria e tem ação medicinal crescentemente documentada.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutificação: agosto–outubro","status_anvisa":"Uso tradicional reconhecido para partes aéreas. Frutos: especiaria alimentar regulamentada.","eixo_botanico_tpc":"Phyto-ANVISA + Especiaria global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Aroeira-Mansa","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Aroeira-mansa · aroeira-da-praia · aroeira-vermelha · pimenta-rosa","Pink pepper / Brazilian pepper (inglês) · Poivre rose (francês)","ATENÇÃO: NÃO confundir com Myracrodruon urundeuva (aroeira-do-sertão) — gênero diferente, química completamente distinta."],"parte_usada":"Frutos secos (pimenta-rosa — uso culinário e medicinal); folhas (infusão); casca.","tipo_botanico":"Fitoterápico anti-inflamatório / especiaria aromática","nome_cientifico":"Schinus terebinthifolia Raddi","familia_botanica":"Anacardiaceae (família da manga, do caju, do pistache)"},"caracterizacao":{"aroma":"Pimenta-rosa fresca, resinoso-balsâmico, cítrico-floral, terebintina suave.","notas":"","intensidade":"3/5 (fruto/pimenta) — 2/5 (infusão de folhas).","cor_da_infusao":"","bioma_de_origem":"Mata Atlântica — amplamente distribuída, especialmente restinga e mata ciliar; RS a CE.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Schinus terebinthifolia Raddi","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Anti-inflamatório (folhas e frutos)","Antimicrobiano (amplo espectro)","Antifúngico","Analgésico leve","Antioxidante","Cicatrizante (uso tópico de extrato)","Componentes ativos:","Contraindicações:","Alergia ao caju ou manga (Anacardiaceae) — reação cruzada possível","Crianças < 6 anos: frutos podem causar irritação gástrica em quantidade","Gestação: uso culinário moderado — ok. Doses medicinais — cautela."],"contraindicacoes":["Alergia ao caju ou manga (Anacardiaceae) — reação cruzada possível","Crianças < 6 anos: frutos podem causar irritação gástrica em quantidade","Gestação: uso culinário moderado — ok. Doses medicinais — cautela."],"efeitos_adversos":"","componentes_ativos":[{"label":"TERPENOS (alfa-pineno, beta-pineno, sabineno)","texto":"Antimicrobiano, anti-inflamatório"},{"label":"SESQUITERPENOS","texto":"Anti-inflamatório, aromático"},{"label":"TANINOS","texto":"Adstringente, antimicrobiano"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório, antioxidante"},{"label":"ÓLEOS ESSENCIAIS VOLÁTEIS","texto":"Antimicrobiano, aromático"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"a6de6b67-d925-4456-9a4d-a3b36c0b3d8f","slug":"valeriana","herb_id":null,"herb_latin_name":"Valeriana officinalis","schema_version":"1.1","ficha":{"slug":"valeriana","cultura":{"brasil":"A valeriana é o fitoterápico sedativo mais vendido em farmácias de manipulação brasileiras — disponível em cápsulas padronizadas, tinturas e chás. O chá é menos popular que as cápsulas justamente pelo aroma desafiador. Para o Ervatório, a narrativa honesta sobre o aroma é mais eficaz que tentar suavizá-lo.","historia":"A valeriana é mencionada por Hipócrates como remédio para insônia. Dioscórides a chama de \"phu\" — interjeição de repulsa ao cheiro. Hildegarda de Bingen usava-a para \"coração perturbado\". Durante a Segunda Guerra Mundial, a valeriana foi distribuída à população civil britânica para tratar ansiedade dos bombardeios — um dos primeiros usos em escala de um fitoterápico para saúde mental coletiva.  O nome \"valeriana\" pode derivar do latim valere (\"estar bem, ter saúde\") — ou da província romana de Valeria. Nenhum dos dois é confirmado — o que é raro para uma erva tão antiga.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Maceração a frio (12h) é o método preferido para preservar valepotriatos e ácido valerênico. Infusão morna como alternativa prática.","quantidade":"2–3 g de raiz seca para 250 ml.","reinfusoes":"","combina_com":"Lúpulo · Passiflora · Melissa · Camomila (blends de sono clássicos europeus e brasileiros)","melhor_momento":"30–60 min antes de dormir. Efeito acumulativo — uso regular (2–4 semanas) produz resultado mais consistente que dose única.","tempo_de_infusao":"","temperatura_ideal":"60–70 °C — nunca ferver (valeriânico se decompõe acima de 80 °C, reduzindo a atividade)."},"tagline":"A sedativa da farmácia europeia — o hipnótico herbal mais vendido do mundo, com evidência clínica sólida para insônia e ansiedade e um perfil olfativo que divide humanidade entre fascínio e repulsa.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — well-established use para insônia.","status_fda":"GRAS para uso alimentar. Suplemento amplamente vendido nos EUA.","sazonalidade":"Raiz colhida no outono (2º ou 3º ano de plantio)","status_anvisa":"Monografia oficial. Indicações: sedativo, ansiolítico, hipnótico.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Valeriana","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Valeriana · valeriana-comum · erva-dos-gatos","Valerian (inglês) · Valériane (francês) · Baldrian (alemão)","Nard sauvage (francês medieval) · \"all-heal\" (inglês medieval)"],"parte_usada":"Raiz e rizoma secos.","tipo_botanico":"Fitoterápico sedativo / hipnótico / ansiolítico","nome_cientifico":"Valeriana officinalis L.","familia_botanica":"Caprifoliaceae / Valerianoideae"},"caracterizacao":{"aroma":"Terroso-musky intenso, isovaleriânico (ácido isovalérico — o mesmo do suor de pés), amadeirado-resinoso. O aroma mais controverso do catálogo — considerado desagradável por muitos, fascinante por alguns.","notas":"","intensidade":"4/5 para sabor e aroma — não é infusão para degustar, é para tomar.","cor_da_infusao":"Marrom-escuro a âmbar opaco. #6B4820","bioma_de_origem":"","sabor_dominante":"Amargo-terroso intenso, resinoso, levemente adocicado ao fundo, persistente. Perfil que divide opiniões radicalmente — poucos amam.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Valeriana officinalis L.","perfil_sensorial":{"tatil":"","gustativo":[{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Amargo","observacao":"Intenso, persistente","intensidade":"3/3"},{"dimensao":"Umami","observacao":"Notas terrosas profundas","intensidade":"1/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Adstringência","observacao":"Discreta","intensidade":"Baixa"}],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Insônia leve a moderada","populacao":"Bent et al. (2006) meta-análise"},{"evidencia":"Moderada","indicacao":"Ansiedade generalizada","populacao":"Andreatini et al. (2002)"},{"evidencia":"Moderada","indicacao":"Dismenorreia","populacao":"Behmanesh et al. (2010)"},{"evidencia":"Preliminar","indicacao":"Síndrome das pernas inquietas","populacao":"Cuellar & Ratcliffe (2009)"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Sedativo / hipnótico (reduz latência de sono)","Ansiolítico (ação GABAérgica + adenosinérgica)","Relaxante muscular","Antiespasmódico","Analgésico leve (dismenorreia)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação e lactação — valepotriatos citotóxicos em modelos animais; evitar","Crianças < 12 anos — sem dados de segurança","Uso concomitante com benzodiazepínicos, álcool — potencialização","Cirurgia — suspender 2 semanas antes (depressor de SNC)","Não dirigir ou operar máquinas pesadas","Efeitos adversos: Sonhos vívidos, cefaleia matinal (\"ressaca\" da valeriana) em doses altas. Efeito paradoxal estimulante em dose baixa."],"contraindicacoes":["Gestação e lactação — valepotriatos citotóxicos em modelos animais; evitar","Crianças < 12 anos — sem dados de segurança","Uso concomitante com benzodiazepínicos, álcool — potencialização","Cirurgia — suspender 2 semanas antes (depressor de SNC)","Não dirigir ou operar máquinas pesadas","Efeitos adversos: Sonhos vívidos, cefaleia matinal (\"ressaca\" da valeriana) em doses altas. Efeito paradoxal estimulante em dose baixa."],"efeitos_adversos":"Sonhos vívidos, cefaleia matinal (\"ressaca\" da valeriana) em doses altas. Efeito paradoxal estimulante em dose baixa.","componentes_ativos":[{"label":"VALEPOTRIATOS (isovalerato, acevaltrato)","texto":"Sedativo, ansiolítico — instáveis, degradam com calor"},{"label":"ÁCIDO VALERÊNICO","texto":"Modulação GABA-A — mais estável que valepotriatos"},{"label":"ÁCIDO ACETOXI-VALERÊNICO","texto":"Sedativo, ansiolítico"},{"label":"ISOVALERATO DE BORNILA","texto":"Sedativo aromático"},{"label":"GLUTAMINA","texto":"Precursora de GABA"},{"label":"LIGNANAS (pinoresinol)","texto":"Sedativas"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ea1acf7c-5936-40ec-9850-73ba201a510b","slug":"lupulo","herb_id":null,"herb_latin_name":"Humulus lupulus","schema_version":"1.1","ficha":{"slug":"lupulo","cultura":{"brasil":"O lúpulo é a erva europeia que chegou ao Brasil pela cultura da cerveja artesanal — e que o mercado de chás funcionais está apenas começando a explorar. A identidade sensorial do lúpulo (o amargor da IPA) abre possibilidades de blends de chá com posicionamento premium masculino absolutamente inéditos.","historia":"O lúpulo é a erva que transformou a cerveja de bebida de sobrevivência em arte. Por milênios, a cerveja era preservada com \"gruit\" — mistura de ervas (losna, mil-folhas, mirto-do-pântano). No século XI, monges beneditinos alemães introduziram o lúpulo como único preservativo e aromatizante — o amargor bacteriostático do humulono eliminava concorrentes. Foi a maior revolução sensorial da história das bebidas fermentadas.  As colhedoras de lúpulo do sudeste da Inglaterra e da Bavária desenvolviam sonolência intensa durante a colheita — os dedos absorviam 2-metil-3-buten-2-ol pelo contato direto com os cones. Esse efeito colateral documentou empiricamente a ação sedativa séculos antes da farmacologia.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta.","quantidade":"1–2 g de estróbilos secos para 250 ml.","reinfusoes":"","combina_com":"Valeriana (clássico sono europeu) · Passiflora · Melissa · Camomila","melhor_momento":"30–60 min antes de dormir. Efeito sedativo mais imediato que valeriana.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (2-metil-3-buten-2-ol sensível ao calor)."},"tagline":"O amargor que acalma — a flor feminina da cerveja artesanal que é simultaneamente um dos sedativos mais eficazes do catálogo e um fitoestrogênio com pesquisa farmacológica crescente.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — well-established use para insônia.","status_fda":"GRAS para uso alimentar (lúpulo em cerveja).","sazonalidade":"Colheita: agosto–setembro (Europa); escassa produção nacional","status_anvisa":"Uso reconhecido.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Lúpulo","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Lúpulo · côdea · cânhamo-bastardo","Hops (inglês) · Houblon (francês) · Hopfen (alemão)","Humulus (farmacológico)"],"parte_usada":"Estróbilos (flores femininas secas — cones de lúpulo).","tipo_botanico":"Fitoterápico sedativo / hipnótico / fitoestrogênico","nome_cientifico":"Humulus lupulus L.","familia_botanica":"Cannabaceae (família da cannabis)"},"caracterizacao":{"aroma":"Resinoso-floral intenso, tropical-frutado (linalol, mirceno), terroso-amadeirado. Aroma extraordinariamente complexo — os cervejeiros artesanais dedicam carreiras a entender as nuances de diferentes variedades de lúpulo.","notas":"","intensidade":"4/5 — amargor dominante. Uso em blends para equilibrar doces.","cor_da_infusao":"Amarelo-âmbar a verde-amarelado. #C8A840","bioma_de_origem":"","sabor_dominante":"Amargo intenso e refinado — o amargor floral da cerveja artesanal IPA. Resinoso, levemente frutado-tropical nas variedades aromáticas, herbal.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Humulus lupulus L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Insônia (especialmente em combinação com valeriana)","populacao":"Müller-Limmroth & Ehrenstein (1977)"},{"evidencia":"Moderada","indicacao":"Ansiedade leve","populacao":"Franco et al. (2012)"},{"evidencia":"Moderada","indicacao":"Sintomas menopáusicos (fogachos)","populacao":"Heyerick et al. (2006) — 8-PN"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Sedativo / hipnótico (ação rápida — 30–60 min)","Ansiolítico","Fitoestrogênico (8-prenilnaringenina — fitoestrogênio mais potente conhecido)","Anti-inflamatório (iso-alfa-ácidos)","Antimicrobiano","Analgésico leve","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação — fitoestrogênico, evitar","Depressão — potencializa sintomas depressivos em uso regular","Condutores — sedativo","Uso concomitante com sedativos e álcool — potencialização"],"contraindicacoes":["Gestação — fitoestrogênico, evitar","Depressão — potencializa sintomas depressivos em uso regular","Condutores — sedativo","Uso concomitante com sedativos e álcool — potencialização"],"efeitos_adversos":"","componentes_ativos":[{"label":"2-METIL-3-BUTEN-2-OL (produto de degradação do humulono)","texto":"Sedativo — modulação GABA"},{"label":"HUMULONA, LUPULONA (alfa e beta-ácidos)","texto":"Antimicrobiano, sedativo, anti-inflamatório"},{"label":"8-PRENILNARINGENINA","texto":"Fitoestrogênio mais potente vegetal conhecido"},{"label":"MIRCENO, LINALOL (OE)","texto":"Sedativo, aromático"},{"label":"XANTUMOL (prenilchalcona)","texto":"Antitumoral (pesquisa extensiva), anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"3830e180-74ea-40c2-ac07-744c72103201","slug":"equinacea","herb_id":null,"herb_latin_name":"Echinacea purpurea","schema_version":"1.1","ficha":{"slug":"equinacea","cultura":{"brasil":"","historia":"A equinácea é a planta medicinal das Grandes Planícies norte-americanas — usada por mais de 14 povos indígenas dos EUA para tratar infecções, venenos de animais e dores de dente. Foi o remédio mais vendido nos EUA no final do século XIX e início do XX antes de ser suplantado pelos antibióticos. Nos anos 1990, ressurgiu como o suplemento mais vendido do mundo — um retorno notável de uma planta relegada pela medicina convencional.  A pesquisa farmacológica moderna confirmou parcialmente o que os Sioux, Cheyenne e Comanche sabiam empiricamente: a equinácea ativa o sistema imune. O mecanismo é diferente do que os ervanários do século XIX imaginavam — mas o resultado prático é similar.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta ou decocção suave.","quantidade":"2–4 g de partes aéreas secas para 250 ml.","reinfusoes":"","combina_com":"Sabugueiro · Gengibre · Própolis · Mel · Limão (blends imunidade)","melhor_momento":"Início de sintomas de resfriado/gripe — 3–4x ao dia por 7–10 dias. Uso preventivo: 3x/semana.","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"O escudo imune da América do Norte — imunoestimulante com o maior número de ensaios clínicos entre todas as ervas do catálogo para prevenção de resfriados, amplamente usado nos hemisférios norte e sul.","receitas":[{"nome":"Sistema Imune","slug":"sistema-imune","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use para gripes e resfriados.","status_fda":"Suplemento amplamente vendido; sem status medicamentoso.","sazonalidade":"Partes aéreas: floração (verão no hemisfério norte)","status_anvisa":"Monografia oficial. Indicações: imunoestimulante, coadjuvante em infecções respiratórias.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Equinácea","usos_topicos":{"evidencia":"","aplicacoes":["Compressa antisséptica (feridas superficiais): Infusão forte resfriada em compressa — antimicrobiano e anti-inflamatório tópico."],"contraindicacoes":""},"identificacao":{"sinonimos":["Equinácea · equinácea-roxa · flor-de-cone-púrpura","Echinacea / Purple coneflower (inglês) · Échinacée (francês)","Sonnenhut (alemão — \"chapéu de sol\")"],"parte_usada":"Partes aéreas (E. purpurea — mais estudada); raiz (E. angustifolia — mais tradicional indígena norte-americana).","tipo_botanico":"Fitoterápico imunoestimulante / imunomodulador","nome_cientifico":"Echinacea purpurea (L.) Moench / E. angustifolia DC. / E. pallida Nutt.","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Herbáceo floral suave, levemente resinoso, feno florido.","notas":"","intensidade":"2/5 — sabor suave, a sensação de formigamento é o marcador sensorial característico.","cor_da_infusao":"Âmbar-rosado a amarelo-dourado. #D4A860","bioma_de_origem":"","sabor_dominante":"Levemente amargo-herbáceo, picante-formigante peculiar na língua (alquilamidas — sensação de formigamento é marcador de qualidade), terroso suave.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Echinacea purpurea (L.) Moench / E. angustifolia DC. / E. pallida Nutt.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Prevenção de resfriados","populacao":"Shah et al. (2007) meta-análise"},{"evidencia":"Moderada","indicacao":"Redução de duração do resfriado","populacao":"Linde et al. (2015) Cochrane"},{"evidencia":"Moderada","indicacao":"Infecções respiratórias altas recorrentes","populacao":"Múltiplos ECR europeus"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Imunoestimulante (ativa macrófagos, NK cells, neutrófilos)","Antiviral (influenza, rinovírus, coronavírus — estudos in vitro)","Antibacteriano","Anti-inflamatório","Cicatrizante (uso tópico)","Adaptógeno leve","Componentes ativos:","Indicações com evidência:","Contraindicações:","Doenças autoimunes — imunoestimulante; contraindica em lúpus, AR, EM","Transplantados — imunomodulação conflita com imunossupressão","Alergia à família Asteraceae (5–10% risco de reação cruzada)","Uso prolongado contínuo (>8 semanas): taquifilaxia — fazer pausas"],"contraindicacoes":["Doenças autoimunes — imunoestimulante; contraindica em lúpus, AR, EM","Transplantados — imunomodulação conflita com imunossupressão","Alergia à família Asteraceae (5–10% risco de reação cruzada)","Uso prolongado contínuo (>8 semanas): taquifilaxia — fazer pausas"],"efeitos_adversos":"","componentes_ativos":[{"label":"ALQUILAMIDAS","texto":"Imunomodulação — CB2, COX-2, NF-κB; responsáveis pelo formigamento"},{"label":"ÁCIDO CHICÓRICO (ácido dicafeoiltartárico)","texto":"Imunoestimulante, antiviral"},{"label":"POLISSACARÍDEOS (arabinogalactanas)","texto":"Ativação de macrófagos"},{"label":"EQUINACOSÍDEO (glicosídeo)","texto":"Antimicrobiano, anti-inflamatório"},{"label":"GLICOPROTEÍNAS","texto":"Imunoestimulantes"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"2659a511-59ee-482f-9bf8-0b7df05a238c","slug":"assa-peixe","herb_id":null,"herb_latin_name":"Vernonia polyanthes","schema_version":"1.1","ficha":{"slug":"assa-peixe","cultura":{"brasil":"O assa-peixe é erva dos brejos e matas de galeria — planta que marca a presença d'água no cerrado e no pantanal. Seu uso popular como expectorante está profundamente integrado à medicina caseira do Brasil Central e Pantaneiro — especialmente em comunidades rurais de MT e MS onde o acesso a serviços de saúde é limitado.  O nome \"assa-peixe\" vem do uso das folhas para defumar e conservar peixe fresco antes de refrigeração — propriedade antimicrobiana dos óleos essenciais aplicada à conserva de alimentos.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta.","quantidade":"2–4 g/250 ml","reinfusoes":"","combina_com":"Mel · Guaco · Eucalipto · Cambará (blends respiratórios pantaneiros)","melhor_momento":"Manhã e tarde em episódios respiratórios.","tempo_de_infusao":"","temperatura_ideal":"90–95 °C | Tempo: 8–10 min coberto | Quantidade: 2–4 g/250 ml"},"tagline":"O expectorante dos brejos — anti-inflamatório respiratório do pantanal e cerrado com tradição popular robusta e ação broncodilatadora confirmada.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Floração: agosto–novembro","status_anvisa":"Uso tradicional reconhecido. RENISUS incluído.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Assa-Peixe","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Assa-peixe · assa-peixe-branco · cambarataia","ATENÇÃO: diversas espécies de Vernonia são chamadas \"assa-peixe\" no Brasil — confirmar espécie."],"parte_usada":"Folhas secas; casca em decocção.","tipo_botanico":"Fitoterápico expectorante / broncodilatador","nome_cientifico":"Vernonia polyanthes Less.","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Herbáceo-resinoso, fundo de caferana, levemente defumado.","notas":"","intensidade":"3/5 — medicinal tolerável.","cor_da_infusao":"Amarelo-esverdeado a âmbar. #B0A840","bioma_de_origem":"Pantanal, Cerrado, Mata Atlântica interior — MT, MS, GO, MG, SP.","sabor_dominante":"Amargo-herbáceo moderado, levemente resinoso, terroso.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Vernonia polyanthes Less.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Expectorante","Broncodilatador leve","Anti-inflamatório das vias aéreas","Antisséptico respiratório","Antipirético","Componentes ativos:","Contraindicações: Alergia à família Asteraceae. Gestação — cautela com lactonas sesquiterpênicas."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"LACTONAS SESQUITERPÊNICAS (vernolina, glaucolídeo)","texto":"Anti-inflamatório, broncodilatador"},{"label":"FLAVONÓIDES (luteolina, apigenina)","texto":"Anti-inflamatório, antioxidante"},{"label":"SAPONINAS","texto":"Expectorante"},{"label":"ÓLEOS ESSENCIAIS","texto":"Antisséptico respiratório"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"63f9ec28-aece-4598-8e39-5cc8c72f2f77","slug":"lippias-brasileiras","herb_id":null,"herb_latin_name":"Lippia alba + Lippia sidoides","schema_version":"1.1","ficha":{"slug":"lippias-brasileiras","cultura":{"brasil":["As lippias brasileiras são embaixadoras da fitoterapia popular nordestina — regionalmente muito mais conhecidas e usadas do que a melissa europeia ou camomila alemã.","A L. sidoides tem pesquisa científica brasileira robusta (UFC, Fiocruz-CE) e presença em políticas públicas de fitoterapia no SUS.","Para o Ervatório, a ficha consolidada destas lippias é oportunidade de visibilizar a fitoterapia nordestina como tradição com base científica e regulatória sólida."],"historia":["Ambas as lippias são plantas da farmácia cabocla nordestina — especialmente ligadas ao sertão semiárido do Nordeste. L. sidoides é endêmica da caatinga e foi uma das plantas pioneiras do programa Farmácia Viva, concebido pelo professor Francisco Abreu Matos na Universidade Federal do Ceará nos anos 1980.","A Farmácia Viva da UFC é referência internacional de fitoterapia popular — modelo replicado em múltiplos estados brasileiros. A L. sidoides virou \"carro-chefe\" desse modelo como fonte de antisséptico oral de baixo custo.","A L. alba tem história mais difusa — presente em quintais de todo o Nordeste, confundida com a melissa europeia na linguagem popular, mas com farmacologia própria documentada."],"cerimonial":"Não há cerimônia codificada. Uso doméstico cotidiano no Nordeste brasileiro, com transmissão geracional de conhecimento herbalista.","curiosidade":"A L. sidoides produz uma quantidade de timol suficiente para que o óleo essencial da planta tenha atividade antimicrobiana comparável aos enxaguantes bucais com clorexidina (Periogard®, Noplak®) — produtos farmacêuticos de prescrição odontológica. O timol é a mesma molécula encontrada em maior concentração na L. sidoides do que no próprio tomilho europeu (Thymus vulgaris, a planta que dá nome à molécula). O semiárido nordestino produz tomilho mais potente que o tomilho mediterrâneo. A caatinga, tão subestimada na cultura botânica brasileira, tem recursos que nenhum terroir europeu consegue igualar."},"preparo":{"metodo":"Infusão coberta para L. alba. Para L. sidoides: infusão para bochecho, ATENÇÃO: NÃO USAR EM INALAÇÕES devido à ação irritante dos componentes voláteis (advertência expressa da monografia).","quantidade":"L. alba: 1 a 3 g/150 ml (uso oral). L. sidoides: 2 a 3 g/150 ml (uso externo bucal)","reinfusoes":"Não recomendado.","combina_com":"L. alba: camomila, lavanda (blend calmante). L. sidoides: uso isolado em bochecho.","melhor_momento":"L. alba: após refeições ou antes de dormir (3 a 4x ao dia). L. sidoides: bochecho 3x ao dia após escovação.","tempo_de_infusao":"10 minutos coberto.","temperatura_ideal":"95 °C."},"tagline":"Duas espécies brasileiras do gênero Lippia — a erva-cidreira-de-arbusto ansiolítica e o alecrim-pimenta antisséptico, ambas oficiais da Anvisa.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Cerrado-Mata Atlântica (Nordeste) + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusões herbais monografadas (duas espécies)"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — duas monografias oficiais"},{"label":"Status EMA","texto":"Sem monografia"}],"metadados":{"nota":"Ficha consolidada que integra L. alba + L. sidoides, dado que compartilham gênero botânico e importância para a Farmácia Viva brasileira, apesar de usos farmacológicos distintos.","autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar — farmacêutico com familiaridade em fitoquímica de Verbenaceae","revisor_cultural":"Sugerido — pesquisador da Farmácia Viva/UFC ou herbalista nordestino","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · ficha consolidada)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia específica.","status_fda":"Sem reconhecimento específico.","sazonalidade":"Colheita contínua em clima semiárido. Concentração ótima de timol na L. sidoides entre julho e setembro (estação seca).","status_anvisa":"Duas monografias oficiais no Formulário de Fitoterápicos (Anvisa, 2011). L. alba: ansiolítico, sedativo leve, antiespasmódico, antidispéptico. L. sidoides: anti-inflamatório e antisséptico da cavidade oral.","eixo_botanico_tpc":"Cerrado-Mata Atlântica (Nordeste) + Phyto-ANVISA","produtor_parceiro":"A definir — parceria com programa Farmácia Viva/UFC e cooperativas agroecológicas do Ceará, Piauí, Pernambuco.","status_japao_china":"Uso restrito.","certificacao_organica":"Produção nordestina crescente, especialmente L. sidoides via programas de Farmácia Viva."},"marketplace":{"formatos":"L. alba: partes aéreas secas, sachê. L. sidoides: folhas secas para bochecho, óleo essencial, fitomedicamentos industriais (enxaguantes).","fornecedores":"Curadoria de produtores nordestinos com tradição e parceria com Farmácia Viva.","faixa_de_preco":"L. alba partes aéreas: R$ 30 a 70 por 100 g. L. sidoides folhas: R$ 40 a 90 por 100 g. Óleo essencial de L. sidoides: valor premium.","disponivel_a_venda":"A definir"},"nome_popular":"Lippias Brasileiras","usos_topicos":{"evidencia":"Forte para L. sidoides em uso oral (bochecho) — monografia específica para antisséptico da cavidade oral. Tradicional para L. alba em aplicações tópicas.","aplicacoes":[{"texto":"USO PRIMÁRIO — infusão padrão morna, bochecho 30 segundos, 3 vezes ao dia após higienização. NÃO ENGOLIR. Pode causar leve sensação de ardor na boca e alterações temporárias no paladar (advertência expressa). Evidência clínica robusta contra flora oral patogênica.","titulo":"Bochecho antisséptico com L. sidoides (uso monografado)"},{"texto":"Infusão fria em compressa nas têmporas. Uso popular.","titulo":"Compressa fria com L. alba para cefaleia"},{"texto":"Infusão diluída em banho morno.","titulo":"Banho aromático com L. alba para relaxamento"}],"contraindicacoes":"L. sidoides: NÃO USAR em inalações (advertência expressa). NÃO ENGOLIR após bochecho. Não aplicar óleo essencial puro na pele."},"docx_filename":"Ficha_Lippias_v11.docx","identificacao":{"slug_url":"lippias","sinonimos":["Lippia alba: erva-cidreira-de-arbusto · lípia · falsa-melissa · cidreira-brava","Lippia sidoides: alecrim-pimenta · alecrim-do-mato · alecrim-de-caboclo","Sinonímia botânica L. alba: Lantana alba Mill., Lantana geminata (Kunth) Spreng.","IMPORTANTE: o nome \"erva-cidreira\" é usado para múltiplas plantas no Brasil. Melissa officinalis (europeia, Lamiaceae), Cymbopogon citratus (capim-limão, Poaceae) e Lippia alba (esta ficha, Verbenaceae) todas são chamadas \"erva-cidreira\" em diferentes regiões."],"parte_usada":"L. alba: partes aéreas secas (1 a 3 g/150 ml, uso interno) · L. sidoides: folhas secas (2 a 3 g/150 ml, uso externo)","nome_popular":"Lippias brasileiras — Erva-cidreira-de-arbusto e Alecrim-pimenta","tipo_botanico":"Arbustos aromáticos, típicos de cerrado e caatinga brasileiros. L. alba mais difundida geograficamente; L. sidoides concentrada no Nordeste.","nome_cientifico":["Lippia alba (Mill.) N.E. Br. ex Britton & P. Wilson","Lippia sidoides Cham."],"familia_botanica":"Verbenaceae"},"caracterizacao":{"aroma":"L. alba: cítrico de limão-galego, floral leve, folha amassada. L. sidoides: intensamente aromático, lembra tomilho e orégano queimados, com toque apimentado.","notas":"L. alba: cabeça cítrica, corpo verde, fundo floral. L. sidoides: cabeça apimentada, corpo fenólico, fundo ardente.","intensidade":"L. alba: 3/5 · L. sidoides: 5/5 aromático (uso externo)","cor_da_infusao":"L. alba: amarelo-esverdeado pálido #D6D58A. L. sidoides: âmbar (uso tópico) #B88745","bioma_de_origem":"Ambas brasileiras. L. alba: ampla distribuição; L. sidoides: endêmica do semiárido nordestino (caatinga).","sabor_dominante":"L. alba: cítrico-herbáceo suave, similar à melissa, com nuance de limão-siciliano. L. sidoides: apimentado-aromático intenso (timol), uso externo (não se bebe).","distribuicao_geografica":["L. alba: todo o Brasil, especialmente Nordeste, Centro-Oeste, Sudeste.","L. sidoides: caatinga nordestina — CE, PI, PE, BA, PB, RN.","L. sidoides é base de pesquisa consolidada na UFC (Farmácia Viva) e projetos de fitoterapia popular do SUS no Nordeste."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Lippia alba + Lippia sidoides","perfil_sensorial":{"tatil":"L. alba: corpo leve, perfil gentil. L. sidoides: ardência bucal por 1-3 minutos (advertência esperada), sensação de boca \"limpa\" após bochecho. Persistência: L. sidoides é a mais alta do catálogo em sensação trigeminal bucal.","gustativo":[{"dimensao":"Doce","observacao":"L. alba tem sutil doçura cítrica. L. sidoides não aplicável (uso externo)","intensidade":"1/3"},{"dimensao":"Amargo","observacao":"Discreto","intensidade":"1/3"},{"dimensao":"Azedo","observacao":"L. alba tem aroma cítrico mas não sabor ácido","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Moderada-alta","molecula":"Timol e carvacrol — sensação de ardor bucal","receptor":"L. sidoides TRPV1 (calor)"},{"ativacao":"Moderada","molecula":"Sensação \"cortante\"","receptor":"L. sidoides TRPA1"},{"ativacao":"Baixa","molecula":"Sensação leve de frescor","receptor":"L. alba TRPM8 (frescor)"},{"ativacao":"Baixa","molecula":"Mínima","receptor":"Adstringência L. alba"}],"olfativo_familia":"L. alba: cítrico-verde (similar ao capim-limão). L. sidoides: fenólico-apimentado (similar ao orégano)","descricao_integrada":"As lippias brasileiras são par complementar do mesmo gênero botânico que demonstra como espécies próximas podem divergir radicalmente em função. A L. alba segue a rota da suavidade — cítrico-calmante como uma melissa tropical, ansiolítico leve pelas mesmas rotas da erva-cidreira europeia. A L. sidoides vai ao extremo oposto — fenólico-intenso como tomilho queimado, antisséptico bucal potente como enxaguante farmacêutico. Sensorialmente, estão em polos opostos. Farmacologicamente, representam o espectro da riqueza química do gênero Lippia brasileiro: os monoterpenos da L. alba acalmam ansiedade; os fenóis da L. sidoides matam bactérias orais. Duas ervas, um gênero, dois usos — toda a versatilidade da flora medicinal nordestina condensada em duas monografias.","olfativo_descritores":["L. alba: Limão-siciliano, melissa, folha verde","L. alba: Nuance cítrica suave","L. sidoides: Tomilho, orégano","L. sidoides: Apimentado penetrante","L. sidoides: Nuance medicinal"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografias oficiais de Lippia alba e Lippia sidoides","Matos — Farmácias Vivas: sistema de utilização de plantas medicinais (UFC)","Lemos et al. — Antimicrobial activity of essential oils of Lippia sidoides (J Ethnopharmacol, 1990)","Oliveira et al. — Lippia sidoides Cham: uma abordagem farmacognóstica (Rev Bras Farmacogn, 2006)"],"evidencia":[{"evidencia":"Moderada","indicacao":"L. alba ansiolítico","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"L. alba antidispéptico","populacao":"Adultos"},{"evidencia":"Forte","indicacao":"L. sidoides antisséptico oral","populacao":"Adultos (bochecho)"},{"evidencia":"Forte","indicacao":"L. sidoides em gengivite","populacao":"Adultos"}],"interacoes":[{"label":"L. alba com anti-hipertensivos","texto":"potencialização leve"},{"label":"L. alba com sedativos","texto":"aditivo"}],"dose_maxima":"L. alba (uso interno): 150 ml do infuso (1 a 3 g), 3 a 4 vezes ao dia. Crianças 3 a 7 anos: 35 ml. 7 a 12 anos: 75 ml. Idosos > 70 anos: 75 ml. L. sidoides (uso externo): bochechos/gargarejos 3 vezes ao dia.","alerta_critico":null,"acoes_principais":["L. alba: Ansiolítico, sedativo leve, antiespasmódico, antidispéptico (monografada)","L. sidoides: Antisséptico e anti-inflamatório da cavidade oral (monografada)","L. sidoides: Antimicrobiano de amplo espectro (ação do timol)"],"contraindicacoes":["L. alba: hipotensão (advertência expressa — pode causar bradicardia e hipotensão em doses altas)","L. sidoides: NÃO USAR EM INALAÇÕES (advertência expressa)","L. sidoides: NÃO ENGOLIR produto após bochecho","Hipersensibilidade a terpenos fenólicos (L. sidoides)"],"efeitos_adversos":"L. alba em doses altas: irritação gástrica, bradicardia, hipotensão. L. sidoides: sensação de ardor na boca e alteração temporária no paladar (advertência expressa, efeito esperado).","componentes_ativos":[{"label":"L. alba: Citral (geranial + neral)","texto":"Aldeído monoterpênico — similar ao do capim-limão, responsável pelo aroma cítrico e ação calmante leve"},{"label":"L. alba: Mirceno, limoneno","texto":"Monoterpenos secundários — potencial ansiolítico"},{"label":"L. sidoides: Timol (até 60% do óleo essencial)","texto":"Fenol monoterpênico — principal antimicrobiano. Atividade comparável aos enxaguantes bucais comerciais com clorexidina."},{"label":"L. sidoides: Carvacrol","texto":"Fenol isômero do timol, ação similar"},{"label":"Flavonoides (ambas)","texto":"Antioxidantes"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"50f2f58f-1aa9-40d6-81bc-e9daae3bbe12","slug":"boldo-baiano","herb_id":null,"herb_latin_name":"Vernonia condensata Baker","schema_version":"1.1","ficha":{"slug":"boldo-baiano","cultura":{"brasil":["O boldo-baiano é ficha que carrega história da diáspora africana na farmácia brasileira. Associada ao Candomblé e à medicina popular afro-nordestina.","Cultivo quase exclusivamente doméstico — em quintais baianos, mineiros, pernambucanos.","Oportunidade editorial para o Ervatório documentar a tradição afro-brasileira sem folclorização."],"historia":["A Vernonia condensata chegou ao Brasil via diáspora africana colonial, provavelmente originária da África Ocidental (Nigéria, Camarões, Congo). Adaptou-se bem ao clima tropical brasileiro e foi incorporada à farmácia afro-brasileira desde o período colonial.","O uso como \"boldo\" popular baiano é séculos anterior à entrada oficial na Farmacopeia Brasileira (2011). Nas comunidades afro-baianas, a planta é chamada \"alumã\" e tem dimensão ritual preservada."],"cerimonial":"Em tradições afro-brasileiras, especialmente no Candomblé baiano, a Vernonia condensata (alumã) tem uso ritual em banhos de descarrego e em preparações medicinais cerimoniais. Essa dimensão é preservada em terreiros específicos.","curiosidade":"Dos três \"boldos\" brasileiros, apenas um (Peumus boldus) é realmente sul-americano nativo. Os outros dois — boldo-brasileiro (Plectranthus barbatus, do leste africano) e boldo-baiano (Vernonia condensata, da África Ocidental) — são plantas africanas naturalizadas no Brasil pela diáspora colonial. A \"brasilidade\" dos boldos brasileiros é, na verdade, africanidade adotada. A história do nome popular no Brasil é inseparável da história africana do país."},"preparo":{"metodo":"Infusão coberta.","quantidade":"Proporção conforme monografia oficial.","reinfusoes":"Não recomendado.","combina_com":"Hortelã, erva-doce (para suavizar amargor).","melhor_momento":"Após refeições.","tempo_de_infusao":"10 minutos coberto.","temperatura_ideal":"95 °C."},"tagline":"O terceiro \"boldo\" brasileiro — folha amarga do quintal nordestino que completa a confusão botânica nacional dos boldos, com monografia oficial própria.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Funcional global (origem africana) + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão herbal monografada"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Sem monografia"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar","revisor_cultural":"Sugerido — herbalista do Candomblé baiano","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco 2)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia.","status_fda":"Sem reconhecimento específico.","sazonalidade":"Folhas colhidas ao longo do ano.","status_anvisa":"Monografia oficial (Anvisa, 2011). Indicação: antidispéptico.","eixo_botanico_tpc":"Funcional global (origem africana) + Phyto-ANVISA","produtor_parceiro":"A definir — parceria com produtores afro-baianos e comunidades quilombolas.","status_japao_china":"Uso restrito.","certificacao_organica":"Produção doméstica em quintais. Produção comercial incipiente."},"marketplace":{"formatos":"Folhas secas, folhas frescas (disponibilidade regional).","fornecedores":"Produção doméstica e familiar principalmente.","faixa_de_preco":"Folhas secas: R$ 25 a 60 por 100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Boldo-Baiano","usos_topicos":{"evidencia":"Limitada para uso tópico.","aplicacoes":[{"texto":"Uso tradicional baiano.","titulo":"Compressa local em dor articular"}],"contraindicacoes":"Uso tópico seguro."},"docx_filename":"Ficha_Boldo_Baiano_v11.docx","identificacao":{"slug_url":"boldo-baiano","sinonimos":["Alumã · figatil · boldo-da-bahia · necroton","ALERTA CRÍTICO DE NOMENCLATURA: o terceiro \"boldo\" brasileiro, junto com Peumus boldus (boldo-do-chile, andino) e Plectranthus barbatus (boldo-brasileiro, africano-domesticado). Os três têm monografias oficiais distintas, indicações parcialmente sobrepostas, e perfis farmacológicos diferentes. A confusão botânica no Brasil é triplo — e a Vernonia condensata é a face menos conhecida dessa tríade."],"parte_usada":"Folhas secas — proporção e detalhes conforme monografia oficial.","nome_popular":"Boldo-baiano","tipo_botanico":"Arbusto perene de 1 a 3 m, com folhas alternas grandes, ovais, amargas ao contato.","nome_cientifico":"Vernonia condensata Baker","familia_botanica":"Asteraceae (família do girassol, calêndula)"},"caracterizacao":{"aroma":"Vegetal-amargo, herbáceo verde.","notas":"Cabeça: vegetal verde · Corpo: amargor · Fundo: adstringência breve","intensidade":"3/5 — moderada.","cor_da_infusao":"Verde-amarelado a âmbar. #C9BE6B","bioma_de_origem":"Planta originária da África tropical, naturalizada no Brasil.","sabor_dominante":"Amargo vegetal pronunciado, sem os aromáticos canforados do Peumus nem a gentileza do Plectranthus. Adstringência moderada.","distribuicao_geografica":["Originária da África Ocidental e Central.","Naturalizada no Brasil desde o período colonial, especialmente na Bahia, Pernambuco, Minas Gerais.","Cultivo doméstico em quintais de todo o Nordeste e Sudeste. Mais rara no Sul."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Vernonia condensata Baker","perfil_sensorial":{"tatil":"Corpo médio. Persistência média.","gustativo":[{"dimensao":"Amargo","observacao":"Pronunciado — sesquiterpenos lactonas","intensidade":"2/3"},{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Baixa","molecula":"Sesquiterpenos suaves","receptor":"TRPA1"},{"ativacao":"Média","molecula":"Taninos moderados","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: vegetal-amargo discreto","descricao_integrada":"O boldo-baiano completa a tríade de plantas brasileiras chamadas \"boldo\" — ao lado do boldo-do-chile (Peumus boldus, andino, farmacologicamente potente) e do boldo-brasileiro (Plectranthus barbatus, africano-domesticado, gentil). A Vernonia condensata é a menos conhecida das três fora do Nordeste, mas é planta comum em quintais baianos, mineiros e pernambucanos, onde cumpre função digestiva similar ao Plectranthus. A monografia oficial reconhece o uso tradicional nacional. Para o Ervatório, a ficha do boldo-baiano é peça essencial do trabalho pedagógico contra a confusão botânica — permitindo que o leitor brasileiro finalmente entenda qual dos três \"boldos\" tem no próprio quintal.","olfativo_descritores":["Folha verde grande amassada","Quintal nordestino","Leve nuance terrosa","Vegetal-amargo","Fundo adstringente"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011)","Alves et al. — Vernonia condensata Baker: a review on ethnomedicinal use and phytochemistry (Rev Bras Plantas Med, 2014)"],"evidencia":[{"evidencia":"Moderada","indicacao":"Dispepsia","populacao":"Adultos"},{"evidencia":"Preliminar","indicacao":"Suporte hepático","populacao":"Adultos"}],"interacoes":[{"label":"Hepatotóxicos","texto":"cautela"}],"dose_maxima":"Conforme monografia.","alerta_critico":null,"acoes_principais":["Antidispéptico","Hepatoativo leve","Anti-inflamatório leve","Cicatrizante tradicional"],"contraindicacoes":["Gestação e lactação: sob orientação","Alergia à família Asteraceae"],"efeitos_adversos":"Raros em doses recomendadas.","componentes_ativos":[{"label":"Sesquiterpenos lactonas (vernolida, glaucolida)","texto":"Responsáveis pelo amargor e pela ação anti-inflamatória"},{"label":"Flavonoides (luteolina, apigenina)","texto":"Antioxidantes"},{"label":"Taninos","texto":"Adstringência"},{"label":"Óleo essencial","texto":"Aromáticos"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"15b8b66e-d390-4a66-86f0-6f1bae34cfae","slug":"chapeu-de-couro","herb_id":null,"herb_latin_name":"Echinodorus macrophyllus (Kunth) Micheli","schema_version":"1.1","ficha":{"slug":"chapeu-de-couro","cultura":{"brasil":["O chapéu-de-couro é exemplo de planta brasileira de habitat especializado (brejos) que entrou na farmacopeia oficial apesar de sua especificidade geográfica.","A distribuição em áreas úmidas faz do chapéu-de-couro termômetro de conservação ambiental — sua abundância indica brejos saudáveis."],"historia":["O chapéu-de-couro é planta da farmacopeia cabocla brasileira, especialmente ligada a áreas de brejos e mata ciliar. Uso tradicional para problemas urinários, gota e reumatismo documentado em múltiplas regiões brasileiras.","A pesquisa científica brasileira sobre Echinodorus macrophyllus consolidou-se nas últimas décadas — Fiocruz e universidades do Sudeste produziram estudos relevantes sobre ação anti-inflamatória."],"cerimonial":"Sem cerimônia codificada. Uso popular específico.","curiosidade":"As folhas do chapéu-de-couro têm aparência anfíbia — folhas submersas são finas e flexíveis, folhas aéreas são grossas e coriáceas. A mesma planta adapta a arquitetura foliar ao meio em que cada folha cresce. É uma das raras plantas em que se pode ver literalmente a adaptação evolutiva em tempo real: folhas de baixo (água) diferentes das folhas de cima (ar), em um único indivíduo."},"preparo":{"metodo":"Infusão coberta.","quantidade":"1 g de folhas secas para 150 ml — proporção oficial (baixa por causa da potência).","reinfusoes":"Não recomendado.","combina_com":"Tradicionalmente usado isolado para ação diurética. Pode combinar com quebra-pedra em casos de litíase urinária.","melhor_momento":"3 vezes ao dia, antes das refeições, conforme monografia.","tempo_de_infusao":"10 minutos coberto.","temperatura_ideal":"95 °C."},"tagline":"Folha larga de brejo brasileiro — diurético e anti-inflamatório oficial, planta de beira de lagoa que cura inflamações urinárias.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Cerrado-Mata Atlântica (áreas alagadas) + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão herbal monografada"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Sem monografia"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar","revisor_cultural":"A designar","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco final)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia.","status_fda":"Sem reconhecimento específico.","sazonalidade":"Colheita de folhas adultas ao longo do ano em áreas alagadas permanentes.","status_anvisa":"Monografia oficial (Anvisa, 2011). Indicação: diurético leve e anti-inflamatório.","eixo_botanico_tpc":"Cerrado-Mata Atlântica (brejos) + Phyto-ANVISA","produtor_parceiro":"A definir — comunidades ribeirinhas e produtores de aquaponia.","status_japao_china":"Uso restrito.","certificacao_organica":"Coleta extrativista em brejos preservados. Cultivo em aquaponia em crescimento."},"marketplace":{"formatos":"Folhas secas, sachê.","fornecedores":"Coleta sustentável ou aquaponia.","faixa_de_preco":"Folhas secas: R$ 30 a 70 por 100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Chapéu-de-Couro","usos_topicos":{"evidencia":"Limitada — uso primordialmente oral.","aplicacoes":[{"texto":"Uso tradicional popular. Evidência limitada.","titulo":"Compressa para edema local"}],"contraindicacoes":"Uso tópico seguro."},"docx_filename":"Ficha_Chapeu_de_Couro_v11.docx","identificacao":{"slug_url":"chapeu-de-couro","sinonimos":["Chapéu-de-couro-verdadeiro · orelha-de-burro · erva-do-brejo","Sinonímia botânica: Alisma macrophyllum Kunth, Echinodorus scaber Rataj","O nome popular vem do formato da folha — larga, áspera e resistente como couro seco."],"parte_usada":"Folhas secas — 1 g para 150 ml, conforme monografia oficial. Proporção baixa por causa da potência.","nome_popular":"Chapéu-de-couro","tipo_botanico":"Erva aquática perene de brejos e margens de lagoas, com folhas grandes cordiformes que saem da água em pecíolos longos. Inflorescências brancas delicadas.","nome_cientifico":"Echinodorus macrophyllus (Kunth) Micheli","familia_botanica":"Alismataceae"},"caracterizacao":{"aroma":"Discreto, vegetal-aquático, com leve toque de brejo.","notas":"Cabeça: vegetal fresco · Corpo: leve amargor · Fundo: terroso-mineral","intensidade":"2/5 — suave.","cor_da_infusao":"Amarelo-palha pálido. #D8CC84","bioma_de_origem":"Áreas alagadas de cerrado e Mata Atlântica brasileira.","sabor_dominante":"Vegetal-amargo leve, com nuance aquática-terrosa, adstringência moderada. Perfil utilitário, não hedônico.","distribuicao_geografica":["Brasil: ampla distribuição em áreas úmidas — MG, SP, RJ, ES, GO, BA, PR, SC, RS.","Cresce em margens de lagoas, brejos, banhados.","Cultivo em aquaponia emergente como planta ornamental-medicinal."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Echinodorus macrophyllus (Kunth) Micheli","perfil_sensorial":{"tatil":"Corpo leve. Persistência baixa. Infusão discreta, funcional.","gustativo":[{"dimensao":"Amargo","observacao":"Leve","intensidade":"1/3"},{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Baixa-média","molecula":"Taninos moderados","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: vegetal-aquática neutra","descricao_integrada":"O chapéu-de-couro é a planta medicinal dos brejos brasileiros — cresce onde poucos ousam explorar, à beira de lagoas e em áreas alagadas. Sua folha larga em forma de coração (cordiforme) é assinatura visual única. Sensorialmente modesta, farmacologicamente precisa: é diurético e anti-inflamatório sério o suficiente para ter monografia oficial, usado com respeito pela medicina popular para problemas urinários e gota há séculos. Para o Ervatório, é ficha que amplia a geografia botânica do catálogo para os ecossistemas úmidos brasileiros, frequentemente invisibilizados na fitoterapia comercial.","olfativo_descritores":["Folha de brejo","Vegetação aquática","Terra alagada","Fundo mineral","Modesto"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografia oficial de Echinodorus macrophyllus","Pinto et al. — Pharmacological properties of Echinodorus macrophyllus (J Ethnopharmacol)"],"evidencia":[{"evidencia":"Moderada","indicacao":"Diurese leve","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Anti-inflamatório urinário","populacao":"Adultos"},{"evidencia":"Moderada tradicional","indicacao":"Suporte em gota (ácido úrico)","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Dispepsia","populacao":"Adultos"}],"interacoes":[{"label":"Anti-hipertensivos","texto":"INTERAÇÃO IMPORTANTE — advertência expressa"},{"label":"Diuréticos farmacêuticos","texto":"potencialização"},{"label":"Digitálicos","texto":"cautela — alteração eletrolítica possível"}],"dose_maxima":"Conforme monografia: 150 ml do infuso (1 g), 3 vezes ao dia, antes das refeições.","alerta_critico":null,"acoes_principais":["Diurético leve — ação monografada","Anti-inflamatório — ação monografada","Antidispéptico","Aperiente","Redutor de ácido úrico (uso tradicional)"],"contraindicacoes":["CONTRAINDICADO em insuficiência renal (advertência expressa)","CONTRAINDICADO em insuficiência cardíaca (advertência expressa)","CONTRAINDICADO em uso concomitante com anti-hipertensivos (advertência expressa)","Gestantes e lactantes: evitar"],"efeitos_adversos":"Em doses usuais: raros. Em doses altas: desequilíbrio eletrolítico, fraqueza.","componentes_ativos":[{"label":"Diterpenos clerodanos","texto":"Princípios ativos principais — ação anti-inflamatória"},{"label":"Flavonoides (luteolina, apigenina)","texto":"Anti-inflamatórios e diuréticos"},{"label":"Alcaloides (echinodorina)","texto":"Ação farmacológica característica do gênero"},{"label":"Taninos","texto":"Adstringência"},{"label":"Saponinas","texto":"Contribuem para ação diurética"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"6d9b8b2b-232d-4271-b748-1697ba3ad980","slug":"erva-de-bicho","herb_id":null,"herb_latin_name":"Polygonum punctatum Elliot","schema_version":"1.1","ficha":{"slug":"erva-de-bicho","cultura":{"brasil":["Planta de coleta familiar em regiões rurais, principalmente no interior Sudeste-Sul e Nordeste. Uso popular maior do que a pesquisa científica."],"historia":["A erva-de-bicho é conhecida da farmácia caboclo-brasileira há séculos. O uso em hemorroidas é tradicional em todas as regiões do Brasil onde a planta ocorre — praticamente em todo o território.","A entrada na Farmacopeia Brasileira (2011) consolidou o uso tradicional para banho de assento."],"cerimonial":"Não tem cerimônia codificada. Uso doméstico utilitário.","curiosidade":"O polygodial da erva-de-bicho brasileira é a mesma molécula que dá sabor picante ao wasabi japonês fresco — duas plantas de continentes diferentes convergindo para a mesma química de defesa. A erva brasileira de várzea e a planta japonesa de montanha, aparentadas no mecanismo de pungência, distantes no território."},"preparo":{"metodo":"Infusão para banho de assento.","quantidade":"3 g de partes aéreas secas para 150 ml (uso externo).","reinfusoes":"N/A.","combina_com":"Uso isolado na monografia oficial.","melhor_momento":"Banho de assento 3 vezes ao dia em crises hemorroidárias.","tempo_de_infusao":"10 minutos.","temperatura_ideal":"95 °C."},"tagline":"Planta das várzeas brasileiras com sabor picante inesperado — \"pimenteira-d'água\" com ação anti-hemorroidal monografada pela Anvisa.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Cerrado-Mata Atlântica (áreas úmidas) + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão herbal monografada (uso externo)"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Sem monografia"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar","revisor_cultural":"A designar","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco 2)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia.","status_fda":"Sem reconhecimento específico.","sazonalidade":"Planta perene de áreas úmidas, colheita ao longo do ano.","status_anvisa":"Monografia oficial (Anvisa, 2011). Indicação: anti-hemorroidal (USO EXTERNO).","eixo_botanico_tpc":"Cerrado-Mata Atlântica (áreas úmidas) + Phyto-ANVISA","produtor_parceiro":"A definir.","status_japao_china":"Uso restrito.","certificacao_organica":"Coleta extrativista em várzeas naturais."},"marketplace":{"formatos":"Partes aéreas secas para banho de assento.","fornecedores":"Coleta extrativista regulamentada.","faixa_de_preco":"Partes aéreas secas: R$ 25 a 60 por 100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Erva-de-Bicho","usos_topicos":{"evidencia":"Moderada para uso externo anti-hemorroidal — ação monografada.","aplicacoes":[{"texto":"USO PRIMÁRIO MONOGRAFADO — infusão morna, 3 vezes ao dia. Ação adstringente e anti-inflamatória local.","titulo":"Banho de assento para hemorroidas"},{"texto":"Uso tradicional nordestino.","titulo":"Compressa para varizes"}],"contraindicacoes":"Uso externo seguro em pele íntegra."},"docx_filename":"Ficha_Erva_de_Bicho_v11.docx","identificacao":{"slug_url":"erva-de-bicho","sinonimos":["Pimenteira-d'água · acataia · catáia · capiçoba · cataia-do-brejo","Sinonímia botânica: Persicaria punctata (Elliott) Small, Polygonum acre Kunth","Nome \"pimenteira-d'água\" reflete a pungência química das folhas — sabor picante similar ao da pimenta, por composto distinto."],"parte_usada":"Partes aéreas secas — 3 g para 150 ml, uso externo (banho de assento), conforme monografia.","nome_popular":"Erva-de-bicho","tipo_botanico":"Erva perene ou anual de 30 a 80 cm, característica de áreas úmidas (brejos, margens de rios, várzeas).","nome_cientifico":"Polygonum punctatum Elliot","familia_botanica":"Polygonaceae (mesma família do ruibarbo, trigo-sarraceno)"},"caracterizacao":{"aroma":"Herbáceo-picante com nuance de brejo.","notas":"Cabeça: picante vegetal · Corpo: herbáceo · Fundo: sensação ardente (via trigeminal)","intensidade":"N/A (uso externo)","cor_da_infusao":"Verde-amarelado a âmbar. #BAB46A","bioma_de_origem":"Áreas úmidas do Brasil — brejos, várzeas, margens de rios em todos os biomas.","sabor_dominante":"USO EXTERNO — se aplicado oralmente (raro), tem perfil picante-ardente característico, similar à pimenta-do-reino mas mais suave.","distribuicao_geografica":["Brasil: ampla ocorrência em todos os estados — onde há água lenta ou parada, há erva-de-bicho.","Américas do Sul, Central e Norte: planta nativa cosmopolita do continente.","Coleta extrativista em várzeas naturais; cultivo comercial limitado."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Polygonum punctatum Elliot","perfil_sensorial":{"tatil":"Aplicação em banho de assento: sensação inicial de leve ardência seguida de alívio pela ação adstringente.","gustativo":[{"dimensao":"Picante (quimossensitivo)","observacao":"Polygodial ativa TRPA1/TRPV1","intensidade":"2/3"},{"dimensao":"Amargo","observacao":"Discreto","intensidade":"1/3"},{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Moderada","molecula":"Polygodial — sensação de ardência leve","receptor":"TRPV1 (calor)"},{"ativacao":"Moderada","molecula":"Polygodial ativa também TRPA1","receptor":"TRPA1"},{"ativacao":"Alta","molecula":"Taninos em concentração relevante","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: herbácea-picante","descricao_integrada":"A erva-de-bicho é planta das margens d'água brasileiras — cresce onde o solo fica encharcado, nas várzeas e brejos que formam as franjas da paisagem tropical. O nome \"pimenteira-d'água\" é precisão botânica: as folhas têm sabor genuinamente picante via polygodial, molécula que ativa os mesmos receptores TRPV1/TRPA1 que a capsaicina e o wasabi. Essa pungência vegetal nasceu como mecanismo de defesa química contra herbívoros — e foi aproveitada pela medicina tradicional brasileira para banho de assento anti-hemorroidal, onde a leve irritação combinada com a ação adstringente dos taninos produz efeito contração-cicatrização. Planta humilde, ficha útil.","olfativo_descritores":["Brejo verde","Folha úmida picante","Ar de várzea","Leve nota pungente","Fundo aquoso"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011)","Facundo et al. — Constituents and pharmacological activity of Polygonum punctatum (Rev Bras Farmacogn, 2005)"],"evidencia":[{"evidencia":"Moderada","indicacao":"Hemorroidas (uso externo)","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Ação adstringente tópica","populacao":"Uso externo"}],"interacoes":[{"label":"Não há interações documentadas em uso externo"}],"dose_maxima":"Uso externo: banho de assento 3 vezes ao dia.","alerta_critico":null,"acoes_principais":["Anti-hemorroidal — ação monografada","Adstringente (taninos)","Hemostático local","Anti-inflamatório","Diurético (uso oral tradicional, não monografado)"],"contraindicacoes":["CONTRAINDICADO em gestantes (advertência expressa da Farmacopeia)","CONTRAINDICADO em lactantes (advertência expressa)","Uso interno não recomendado pela monografia"],"efeitos_adversos":"Raros. Em pele sensível: irritação local.","componentes_ativos":[{"label":"Polygodial","texto":"Sesquiterpeno dialdeído com ação irritante leve (responsável pela pungência) e antimicrobiana"},{"label":"Taninos","texto":"Adstringentes potentes"},{"label":"Flavonoides (rutina, quercetina)","texto":"Ação venotônica e antioxidante"},{"label":"Ácidos orgânicos (cafeico, gálico)","texto":"Antioxidantes"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"e8d1a4c4-37c6-44d7-b92c-4fc1f468c34c","slug":"guacatonga","herb_id":null,"herb_latin_name":"Casearia sylvestris Sw.","schema_version":"1.1","ficha":{"slug":"guacatonga","cultura":{"brasil":["A guaçatonga é uma das ervas brasileiras com maior potencial cientificamente estabelecido mas menor reconhecimento popular e comercial. O Ervatório pode ter papel de divulgação responsável.","Cultivo comercial ainda limitado. Há potencial de produção agroflorestal no Sul/Sudeste."],"historia":["A guaçatonga é planta tradicional de indígenas bugres e kaingang do Sul e Sudeste brasileiros — daí os nomes populares \"erva-de-bugre\" e \"chá-de-bugre\". Era usada para dores de estômago, feridas e como \"chá fortificante\".","No Brasil contemporâneo, a pesquisa científica é concentrada na Unicamp, USP e UFPR. O professor Mario Sérgio Mantovani (USP) publicou trabalhos seminais sobre casearinas nos anos 1990.","A entrada na Farmacopeia Brasileira (2011) consolidou o uso tradicional. Hoje a guaçatonga está em programas estaduais de fitoterapia (São Paulo, Paraná)."],"cerimonial":"Não tem cerimônia codificada formal. Dimensão ritual preservada em comunidades kaingang e caboclas do Sul.","curiosidade":"As casearinas da guaçatonga compartilham estrutura molecular com outros diterpenos antitumorais descobertos em plantas amazônicas. A guaçatonga é uma das plantas mais estudadas por pesquisadores brasileiros de produtos naturais — dezenas de teses de doutorado dedicadas a ela — e ainda assim permanece essencialmente invisível no mercado. O conhecimento científico brasileiro sobre as próprias plantas frequentemente não encontra caminho até o consumidor nacional."},"preparo":{"metodo":"Infusão coberta. Beber 5 minutos após o preparo.","quantidade":"2 a 4 g de folhas secas para 150 ml — proporção da Farmacopeia.","reinfusoes":"Não recomendado.","combina_com":"Espinheira-santa (sinergia gástrica) · Camomila · Hortelã","melhor_momento":"Antes das refeições. 2 a 3 vezes ao dia conforme monografia.","tempo_de_infusao":"5 minutos coberto.","temperatura_ideal":"95 °C."},"tagline":"Erva-de-bugre da Mata Atlântica interior — antiulcerosa nativa brasileira com perfil farmacológico comparável à espinheira-santa, raramente citada fora do meio especializado.","receitas":[],"destaques":[{"label":"Eixo botânico","texto":"Mata Atlântica + Cerrado + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão herbal monografada"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Sem monografia"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar","revisor_cultural":"Sugerido — comunidade kaingang com tradição de uso","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco 2)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia.","status_fda":"Sem reconhecimento específico.","sazonalidade":"Colheita de folhas adultas ao longo do ano.","status_anvisa":"Monografia oficial (Anvisa, 2011). Indicação: antidispéptico.","eixo_botanico_tpc":"Mata Atlântica + Cerrado + Phyto-ANVISA","produtor_parceiro":"A definir.","status_japao_china":"Uso restrito.","certificacao_organica":"Produção incipiente no Sudeste e Sul. Potencial em sistemas agroflorestais."},"marketplace":{"formatos":"Folhas secas, sachê.","fornecedores":"Produtores SP/PR com potencial agroflorestal.","faixa_de_preco":"Folhas secas: R$ 30 a 70 por 100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Guaçatonga","usos_topicos":{"evidencia":"Moderada para uso tópico.","aplicacoes":[{"texto":"Infusão forte em compressa local. Uso tradicional caboclo.","titulo":"Compressa para dores musculares leves"},{"texto":"Infusão morna, 30 segundos.","titulo":"Gargarejo para gengivite"}],"contraindicacoes":"Uso tópico amplamente seguro."},"docx_filename":"Ficha_Guacatonga_v11.docx","identificacao":{"slug_url":"guacatonga","sinonimos":["Erva-de-bugre · erva-de-lagarto · cafezinho-do-mato · chá-de-bugre","Sinonímia botânica: Anavinga samyda C.F. Gaernt., Casearia affinis Gardner in Hooker, Casearia attenuata Rusby","Atenção: \"chá-de-bugre\" é nome compartilhado com Cordia salicifolia, outra planta distinta com uso similar — há confusão comercial frequente."],"parte_usada":"Folhas secas — 2 a 4 g para 150 ml, conforme monografia oficial.","nome_popular":"Guaçatonga","tipo_botanico":"Árvore ou arbusto de 2 a 6 m, amplamente distribuído.","nome_cientifico":"Casearia sylvestris Sw.","familia_botanica":"Salicaceae (nova classificação; antes Flacourtiaceae)"},"caracterizacao":{"aroma":"Herbáceo verde com nuance medicinal, levemente amadeirado.","notas":"Cabeça: herbáceo verde · Corpo: amargor suave · Fundo: adstringência breve","intensidade":"3/5 — moderada, funcional.","cor_da_infusao":"Amarelo-esverdeado a âmbar claro. #C9C77C","bioma_de_origem":"Mata Atlântica e Cerrado brasileiros.","sabor_dominante":"Amargo-aromático moderado, com notas herbáceas e leve adstringência.","distribuicao_geografica":["Brasil: ocorrência ampla em MG, SP, RJ, ES, PR, SC, RS, MS, GO.","Outras regiões da América tropical: Argentina, Paraguai, Bolívia, Caribe.","Cultivo comercial moderado. Coleta extrativista frequente em áreas nativas."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Casearia sylvestris Sw.","perfil_sensorial":{"tatil":"Corpo leve a médio. Persistência média.","gustativo":[{"dimensao":"Amargo","observacao":"Moderado — mais suave que carqueja","intensidade":"2/3"},{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Média","molecula":"Taninos moderados","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: herbácea-verde discreta","descricao_integrada":"A guaçatonga é a irmã menos famosa da espinheira-santa — compartilha o mesmo território geográfico (Mata Atlântica + Cerrado), indicação similar (antidispéptico, protetor gástrico), perfil sensorial parecido. O que a difere é a obscuridade relativa: enquanto a espinheira-santa atingiu fama nacional pelo convênio UFPR e entrou em programas do SUS, a guaçatonga permanece como conhecimento de herbalistas especializados e pesquisadores. As casearinas, diterpenos característicos, têm atividade antitumoral in vitro promissora que pesquisadores brasileiros estudam há décadas — sem que o grande público jamais tenha ouvido falar. Para o Ervatório, a guaçatonga é ficha de valor editorial porque documenta um saber fitoterápico nacional com evidência científica consistente mas invisível comercialmente.","olfativo_descritores":["Folha verde amassada","Mata atlântica","Leve nuance medicinal","Fundo amadeirado","Sutil resinoso"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografia oficial","Basile et al. — Anti-ulcer activity of Casearia sylvestris (J Ethnopharmacol, 1990)","Santos et al. — Antitumor and antinociceptive effects of Casearia sylvestris extract (Phytomedicine, 2007)"],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Dispepsia funcional","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Gastrite leve","populacao":"Adultos"},{"evidencia":"Preliminar-moderada","indicacao":"Úlcera péptica coadjuvante","populacao":"Estudos em andamento"},{"evidencia":"Moderada","indicacao":"Ação antimicrobiana oral","populacao":"Uso tópico"}],"interacoes":[{"label":"Ferro oral","texto":"taninos podem reduzir absorção"},{"label":"Inibidores de bomba de prótons","texto":"possível sinergia"}],"dose_maxima":"Conforme a monografia: 150 ml do infuso (2-4 g de folhas secas), 2 a 3 vezes ao dia, 5 minutos após o preparo.","alerta_critico":null,"acoes_principais":["Antidispéptico — ação monografada","Antiulcerogênico (estudos preliminares robustos)","Anti-inflamatório","Antimicrobiano (especialmente oral)","Antitumoral (casearinas — estudos de bancada promissores)","Cicatrizante de mucosa gástrica"],"contraindicacoes":["CONTRAINDICADO em gestantes (advertência expressa da Farmacopeia)","CONTRAINDICADO em lactantes (advertência expressa)","Crianças abaixo de 12 anos sem orientação"],"efeitos_adversos":"Raros em doses recomendadas.","componentes_ativos":[{"label":"Casearinas (diterpenos clerodanos)","texto":"Compostos característicos do gênero Casearia — com atividade antitumoral documentada em estudos in vitro e in vivo"},{"label":"Taninos","texto":"Adstringência e proteção gástrica"},{"label":"Flavonoides (quercetina, kaempferol, rutina)","texto":"Antioxidantes"},{"label":"Óleo essencial (alfa-humuleno, cariofileno)","texto":"Aromáticos e anti-inflamatórios"},{"label":"Saponinas","texto":"Contribuem para ação digestiva"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"1f37534e-ba60-4644-b623-d829b0074ba1","slug":"quebra-pedra","herb_id":null,"herb_latin_name":"Phyllanthus niruri L.","schema_version":"1.1","ficha":{"slug":"quebra-pedra","cultura":{"brasil":["A quebra-pedra está entre as 10 ervas medicinais mais conhecidas do Brasil popular. Distribuição universal no território nacional.","A pesquisa brasileira é referência internacional para Phyllanthus niruri. Universidades do Sudeste lideraram descobertas sobre ação contra vírus da hepatite B que geraram interesse farmacêutico global."],"historia":["A quebra-pedra é planta de uso caboclo-indígena tradicional em todo o Brasil desde tempos pré-coloniais. Povos tupis-guaranis conheciam-na como planta para \"mal de pedra\" (cálculos urinários). O nome popular em espanhol americano \"chanca-piedra\" (quebra-pedra) atravessou a América do Sul com significado idêntico — evidência de uso tradicional em múltiplas culturas antes do contato europeu.","A pesquisa científica brasileira sobre Phyllanthus niruri intensificou-se nos anos 1980-1990, com trabalhos da USP Ribeirão Preto, UFMG e Fiocruz. A confirmação experimental da ação litolítica e hepatoprotetora consolidou o uso popular.","A monografia oficial na Farmacopeia Brasileira (Formulário, 2011) oficializou a indicação para litíase urinária."],"cerimonial":"Sem cerimônia codificada. Uso doméstico em todo o Brasil.","curiosidade":"A atividade da quebra-pedra contra cálculos renais é explicada por mecanismo elegante: ela não \"dissolve pedras\" literalmente, mas reduz a formação de cristais de oxalato de cálcio (o tipo mais comum de cálculo urinário) pela ação das lignanas e flavonoides da planta. É prevenção molecular — os princípios ativos interferem na nucleação dos cristais no ambiente renal. A sabedoria popular que a nomeou \"quebra-pedra\" descrevia um efeito real, mas por mecanismo diferente do imaginado: não quebra pedras formadas, impede que se formem."},"preparo":{"metodo":"Infusão coberta. Beber 10-15 min após o preparo.","quantidade":"3 g de partes aéreas secas para 150 ml — proporção oficial.","reinfusoes":"Não recomendado.","combina_com":"Uso tradicionalmente isolado para ação litolítica. Pode ser combinado com chapéu-de-couro (diurético) em alguns contextos clínicos.","melhor_momento":"Ao longo do dia, 2 a 3 vezes, conforme a monografia. Importante: manter boa hidratação durante uso.","tempo_de_infusao":"10 a 15 minutos coberto.","temperatura_ideal":"95 °C."},"tagline":"A erva que dissolve cálculos renais — planta pequena de caminho, litolítico oficial da Anvisa, com evidência clínica crescente contra pedras urinárias.","receitas":[{"nome":"Quebra-Pedra do Nordeste","slug":"quebra-pedra-do-nordeste","proposito":null}],"destaques":[{"label":"Eixo botânico","texto":"Cerrado-Mata Atlântica + Phyto-ANVISA"},{"label":"Tipo","texto":"Infusão herbal monografada"},{"label":"Status ANVISA","texto":"Farmacopeia Brasileira — monografia oficial"},{"label":"Status EMA","texto":"Sem monografia específica"}],"metadados":{"autor":"Equipe editorial Ervatório","ultima_revisao":"2026-04-19","data_de_criacao":"2026-04-19","revisor_tecnico":"A designar — farmacêutico com familiaridade em urologia fitoterápica","revisor_cultural":"A designar","status_editorial":"Publicado (Lógica A · Núcleo brasileiro · Bloco final)","versao_do_schema":"1.1","revisor_editorial":"A designar"},"regulacao":{"status_ema":"Sem monografia específica.","status_fda":"Uso como suplemento permitido.","sazonalidade":"Colheita em plena vegetação durante estação chuvosa.","status_anvisa":"Monografia oficial no Formulário de Fitoterápicos (Anvisa, 2011). Indicação: litolítico nos casos de litíase urinária.","eixo_botanico_tpc":"Cerrado-Mata Atlântica + Phyto-ANVISA","produtor_parceiro":"A definir.","status_japao_china":"Uso tradicional em medicina ayurvédica documentado.","certificacao_organica":"Coleta extrativista ou cultivo familiar em todo o Brasil."},"marketplace":{"formatos":"Partes aéreas secas, tintura, extrato seco.","fornecedores":"Ampla disponibilidade brasileira.","faixa_de_preco":"Partes aéreas secas: R$ 20 a 50 por 100 g.","disponivel_a_venda":"A definir"},"nome_popular":"Quebra-Pedra","usos_topicos":{"evidencia":"Limitada — uso primordialmente oral.","aplicacoes":[{"texto":"Uso tradicional caboclo. Evidência popular.","titulo":"Compressa para inflamação local leve"}],"contraindicacoes":"Uso tópico seguro."},"docx_filename":"Ficha_Quebra_Pedra_v11.docx","identificacao":{"slug_url":"quebra-pedra","sinonimos":["Erva-pombinha · saxifrage-do-Brasil · arranca-pedra · chanca-piedra","Sinonímia botânica: Diasperus niruri (L.) Kuntze, Phyllanthus asperulatus Hutch., Phyllanthus filiformis Pavon ex Baillon"],"parte_usada":"Partes aéreas secas — 3 g para 150 ml, conforme monografia oficial.","nome_popular":"Quebra-pedra","tipo_botanico":"Erva anual rasteira de 30 a 60 cm, com folhas alternadas minúsculas e frutos em cápsulas ao longo dos caules. Cresce em terrenos abertos, jardins, pátios.","nome_cientifico":"Phyllanthus niruri L.","familia_botanica":"Phyllanthaceae (antes classificada em Euphorbiaceae)"},"caracterizacao":{"aroma":"Discreto, vegetal-seco, sem aromáticos marcantes.","notas":"Cabeça: vegetal seco · Corpo: amargor leve · Fundo: breve acidez","intensidade":"2/5 — suave, permite uso prolongado.","cor_da_infusao":"Amarelo-esverdeado claro. #CEC978","bioma_de_origem":"Cerrado, Mata Atlântica e bordas urbanas em todo o Brasil tropical.","sabor_dominante":"Amargo-herbáceo suave com leve acidez, pouco aromático, perfil utilitário.","distribuicao_geografica":["Brasil: praticamente todos os estados — uma das plantas medicinais mais difundidas.","Pantropical: presente em todas as regiões tropicais do mundo (América, África, Ásia).","Cresce espontaneamente como erva daninha em áreas urbanas e rurais — sua ubiquidade é uma das razões para o uso popular amplo."]},"preparo_ritual":null,"schema_version":"1.1","nome_cientifico":"Phyllanthus niruri L.","perfil_sensorial":{"tatil":"Corpo leve. Persistência baixa. Infusão utilitária — não se bebe por prazer, bebe-se por função.","gustativo":[{"dimensao":"Amargo","observacao":"Leve","intensidade":"1/3"},{"dimensao":"Azedo","observacao":"Discreto, residual","intensidade":"1/3"},{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Baixa","molecula":"Taninos leves","receptor":"Adstringência"}],"olfativo_familia":"Família aromática: vegetal-seca discreta","descricao_integrada":"A quebra-pedra é uma das ervas mais humildes e mais úteis do catálogo brasileiro. Cresce onde ninguém planta, em pátios de casa, em rachaduras de calçada, em jardins mal cuidados. Seu nome popular é descritivo e preciso: a planta realmente ajuda a dissolver cálculos urinários, fato que a tradição popular sabia séculos antes da pesquisa farmacológica confirmar. O perfil sensorial é propositalmente modesto — quem bebe quebra-pedra não busca experiência aromática, busca efeito fisiológico. A planta não performa, apenas trabalha.","olfativo_descritores":["Vegetal seco","Feno leve","Nuance terrosa","Fundo neutro","Herbáceo modesto"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira — Formulário de Fitoterápicos (Anvisa, 2011), monografia oficial de Phyllanthus niruri","Micali et al. — Cystone, a well-known herbal formulation, in the management of kidney stone disease (J Ayurveda, 2006)","Bagalkotkar et al. — Phytochemicals from Phyllanthus niruri Linn. and their pharmacological properties (J Pharm Pharmacol, 2006)"],"evidencia":[{"evidencia":"Moderada","indicacao":"Litíase urinária (coadjuvante)","populacao":"Adultos com cálculos pequenos"},{"evidencia":"Preliminar promissor","indicacao":"Hepatite B (preliminar)","populacao":"Estudos em andamento"},{"evidencia":"Moderada","indicacao":"Diurético leve","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Suporte hepático","populacao":"Adultos"}],"interacoes":[{"label":"Anti-hipertensivos","texto":"potencialização leve"},{"label":"Hipoglicemiantes","texto":"potencialização"},{"label":"Anticoagulantes","texto":"cautela"},{"label":"Lítio","texto":"alteração possível de excreção"}],"dose_maxima":"Conforme monografia: 150 ml do infuso (3 g), 2 a 3 vezes ao dia, 10-15 min após preparo. Uso de 4 a 6 semanas com reavaliação. Manter hidratação adequada durante tratamento.","alerta_critico":null,"acoes_principais":["Litolítico — ação principal monografada (dissolução de cálculos urinários)","Diurético leve","Anti-inflamatório","Hepatoprotetor","Antiviral (estudos preliminares contra hepatite B)","Hipoglicemiante leve"],"contraindicacoes":["CONTRAINDICADO em gestantes (advertência expressa)","Concentrações acima das recomendadas: diarreia e hipotensão (advertência expressa)","Em cálculos renais muito grandes: uso sob acompanhamento médico (risco de cólica renal se cálculo se mobilizar)","Insuficiência renal grave: cautela"],"efeitos_adversos":"Raros em doses usuais. Doses altas: diarreia, hipotensão.","componentes_ativos":[{"label":"Filantina","texto":"Lignana característica do gênero Phyllanthus — parte da ação hepatoprotetora"},{"label":"Hipofilantina","texto":"Segunda lignana principal"},{"label":"Flavonoides (quercetina, rutina)","texto":"Anti-inflamatórios, diuréticos"},{"label":"Alcaloides (filantina, niruritina)","texto":"Ação farmacológica variada"},{"label":"Ácidos fenólicos (ácido elágico, ácido gálico)","texto":"Antioxidantes"},{"label":"Triterpenos","texto":"Anti-inflamatórios"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"27372100-0517-49eb-a7fb-ac162008927e","slug":"guarana","herb_id":null,"herb_latin_name":"Paullinia cupana","schema_version":"1.1","ficha":{"slug":"guarana","cultura":{"brasil":"O guaraná é o único estimulante de origem 100% brasileira com reconhecimento farmacológico global. É simultaneamente matéria-prima da maior indústria de bebidas do país e produto ritual de um dos povos indígenas mais organizados da Amazônia. Essa tensão entre mercado e território é uma das histórias mais complexas do catálogo — e precisa ser contada com honestidade no Ervatório.","historia":"O guaraná pertence aos Sateré-Mawé desde antes de qualquer registro escrito europeu. O mito de origem do povo narra que a planta nasceu dos olhos de uma criança — daí o fruto bipartido que imita um par de olhos humanos abertos, com pupila escura (semente) sobre esclera branca (arilo). Essa morfologia não é coincidência botânica: é a memória visual de um povo codificada em semente.  Os primeiros registros europeus datam do século XVII (Padre João Felipe Bettendorf, 1669), que descreve os indígenas produzindo \"bastões de caça\" — mistura de sementes torradas e moídas com mandioca, usados como ração de energia concentrada em expedições longas pela floresta.  No século XIX, o guaraná chega ao mercado europeu como \"elixir brasileiro\", produto de farmácias de luxo em Paris e Londres. No Brasil, a marca Guaraná Antarctica (1921) democratizou o ingrediente em bebida carbonatada — o refrigerante mais consumido no país por décadas.","cerimonial":"Entre os Sateré-Mawé, o preparo ritual do guaraná com língua-de-pirarucu (osso de peixe petrificado usado como ralador) é cerimônia de hospitalidade e de passagem. Ralar o bastão é ato de comunhão — quem rala para o outro expressa respeito e cuidado. A bebida resultante não é \"chá\" — é wyra'ó, \"água de vida\". O IPI (Instituto do Patrimônio Histórico e Artístico Nacional) registrou o processo produtivo sateré-mawé como Patrimônio Cultural Imaterial do Brasil em 2008.","curiosidade":""},"preparo":{"metodo":"Infusão simples. No preparo sateré-mawé: bastão (cipó guaraná + pó de semente) ralado em água fria ou morna — método ancestral preservado até hoje.","quantidade":"1–2 g de pó para 150 ml. Preparo indígena tradicional: ralar o bastão seco diretamente na água com língua-de-pirarucu (osso de peixe), sem medida — ritual de exatidão sensorial.","reinfusoes":"1 reinfusão possível, com extração significativamente reduzida.","combina_com":"Cacau · Canela · Gengibre · Pimenta-rosa · Cumaru · Açaí (blend energético amazônico)","melhor_momento":"Manhã (6h–11h) e início de tarde (13h–15h). Evitar após 16h para não comprometer sono. Ideal pré-exercício físico ou intelectual.","tempo_de_infusao":"5–8 minutos (pó fino); 8–12 minutos (grãos ralados no estilo indígena).","temperatura_ideal":"80–90 °C. Evitar ebulição plena — degrada compostos voláteis aromáticos."},"tagline":"O estimulante mais potente da floresta — ocitocina da cafeína brasileira que conquistou o mundo sem perder sua origem indígena.","receitas":[],"regulacao":{"status_ema":"Traditional use. Indicação: fadiga temporária.","status_fda":"GRAS para uso alimentar.","sazonalidade":"Colheita: março–maio (Amazonas); agosto–outubro (Bahia)","status_anvisa":"Monografia oficial. Indicações: coadjuvante no controle de peso; estimulante. RDC 26/2014.","eixo_botanico_tpc":"Phyto-ANVISA + Funcional global","certificacao_organica":""},"marketplace":{"formatos":"Pó (padronizado 4% cafeína), bastão tradicional, extrato seco, cápsula","fornecedores":"Prioridade: cooperativas sateré-mawé de Maués (AM) — rastreabilidade de origem garantida","faixa_de_preco":"Pó convencional: R$ 25–50/100 g. Pó premium Maués orgânico: R$ 80–160/100 g","disponivel_a_venda":"A definir"},"nome_popular":"Guaraná","usos_topicos":{"evidencia":"","aplicacoes":["Máscara capilar estimulante (uso popular): Pó de guaraná misturado com argila e azeite — aplicado no couro cabeludo por 20 minutos. Evidência tradicional para estimular circulação capilar; mecanismo provável: xantinas vasodilatadoras locais.","Gel para olheiras e inchaço periocular: Extrato de guaraná em gel criogênico — vasoconstricção cafeínica. Uso amplamente difundido na indústria cosmética brasileira e europeia.","Esfoliante corporal: Pó de guaraná + óleos vegetais + açúcar — esfoliação mecânica + estimulação circulatória local. Produto popular em spas amazônicos."],"contraindicacoes":""},"identificacao":{"sinonimos":["Guaraná-do-brasil · uaraná · waraná (língua sateré-mawé)","Guarana (inglês/francês/espanhol) · Guaraná-Samen (alemão)","ATENÇÃO: distinguir de Paullinia yoco, espécie colombiana com usos semelhantes mas alcaloides distintos"],"parte_usada":"Sementes maduras, secas e torradas; casca do fruto em uso tradicional indígena.","tipo_botanico":"Estimulante herbal monografado","nome_cientifico":"Paullinia cupana Kunth var. sorbilis (Mart.) Ducke","familia_botanica":"Sapindaceae (família do lichia e do olho-de-gato)"},"caracterizacao":{"aroma":"Cacau torrado, terra úmida de floresta, amadeirado defumado leve, fundo de canela sutil.","notas":"Cabeça: cacau torrado · amargo limpo | Corpo: terroso denso · amadeirado | Fundo: adstringência suave · leve canela | BIOMA: Amazônia central. Nativo da bacia amazônica, concentrado no estado do Amazonas e Pará. | DISTRIBUIÇÃO GEOGRÁFICA:","intensidade":"4/5 — infusão de presença marcante. Não é fundo de xícara — é protagonista.","cor_da_infusao":"Marrom-âmbar intenso a castanho escuro, opaco. #5C3317","bioma_de_origem":"Amazônia central. Nativo da bacia amazônica, concentrado no estado do Amazonas e Pará.","sabor_dominante":"Intenso, amargo pronunciado, terroso-cacauado, com toque levemente adstringente e notas de chocolate amargo. Perfil masculino e robusto — não é infusão de aceitação universal.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Paullinia cupana Kunth var. sorbilis (Mart.) Ducke","perfil_sensorial":{"tatil":"Corpo médio a encorpado. Adstringência presente e limpa — contrai levemente as mucosas sem ser agressiva. Persistência média-alta. Guaraná não é infusão que passa — fica. A sensação de \"acordar\" não é imediata: a matriz de taninos atrasa a absorção da cafeína, que chega de forma escalonada. Isso é o que diferencia o guaraná do café espresso: não é pico e queda — é rampa longa e sustentada. O corpo sensorial diz isso antes que a bioquímica confirme.","gustativo":[{"dimensao":"Doce","observacao":"Ausente na infusão pura","intensidade":"0/3"},{"dimensao":"Amargo","observacao":"Dominante — cafeína + taninos","intensidade":"3/3"},{"dimensao":"Umami","observacao":"Leve, proveniente de aminoácidos livres","intensidade":"1/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Salgado","observacao":"Ausente","intensidade":"0/3"}],"trigeminal":[{"ativacao":"Ausente","molecula":"—","receptor":"TRPM8 (frescor)"},{"ativacao":"Baixa","molecula":"Capsaicinoides traços","receptor":"TRPV1 (calor)"},{"ativacao":"Ausente","molecula":"—","receptor":"TRPA1"},{"ativacao":"Alta","molecula":"Taninos condensados","receptor":"Adstringência"}],"olfativo_familia":"- Cacau amargo torrado","descricao_integrada":"","olfativo_descritores":["Cacau amargo torrado","Terra úmida de floresta após chuva","Amadeirado defumado","Canela sutil no fundo","Resina seca"]},"acoes_e_seguranca":{"fontes":["Farmacopeia Brasileira 6ª Ed. — monografia Paullinia cupana","EMA/HMPC — Assessment report on Paullinia cupana Kunth, semen (2013)","Haskell CF et al. — The effects of a single dose of a 75 mg dose of guarana on cognitive performance (Psychopharmacology, 2007)","Schimpl FC et al. — Guarana: Revisiting a highly caffeinated plant from the Amazon (J Ethnopharmacol, 2013)","IDAM — Instituto de Desenvolvimento Agropecuário do Amazonas — Perfil do guaraná de Maués"],"evidencia":[{"evidencia":"Forte","indicacao":"Fadiga mental e física","populacao":"Adultos"},{"evidencia":"Moderada","indicacao":"Melhora de atenção e memória","populacao":"Adultos jovens"},{"evidencia":"Moderada (associado)","indicacao":"Coadjuvante de emagrecimento","populacao":"Adultos com IMC ≥ 25"},{"evidencia":"Moderada","indicacao":"Melhora de desempenho físico","populacao":"Atletas"}],"interacoes":[{"label":"ANTICOAGULANTES (varfarina)","texto":"potencialização antiagregante — monitorar"},{"label":"OUTROS ESTIMULANTES (efedrina, sinefrina)","texto":"risco de síndrome de hiperestimulação"},{"label":"ANTIDEPRESSIVOS IMAO","texto":"contraindicado — risco de crise hipertensiva"},{"label":"LÍTIO","texto":"aumenta excreção renal de lítio — reduz nível sérico"},{"label":"Efeitos adversos","texto":"Taquicardia, tremores finos, insônia, cefaleia de rebote, irritação gástrica em doses altas ou jejum."},{"label":"Dose máxima","texto":"3 g/dia de pó padronizado (equivalente a ~75 mg cafeína/g). OMS: cafeína total ≤ 400 mg/dia para adultos saudáveis."}],"dose_maxima":"3 g/dia de pó padronizado (equivalente a ~75 mg cafeína/g). OMS: cafeína total ≤ 400 mg/dia para adultos saudáveis.","acoes_principais":["Estimulante do SNC (cafeína + teobromina + teofilina)","Nootrópico — melhora atenção, memória de trabalho e velocidade de processamento","Termogênico — aumenta taxa metabólica basal","Antioxidante (taninos, saponinas)","Adaptógeno leve (ação moduladora de cortisol discutida)","Vasodilatador periférico (xantinas)","Antiplaquetário fraco","Componentes ativos:","A matriz de taninos do guaraná é responsável pela liberação mais lenta de cafeína comparada ao café — fenômeno de \"liberação estendida\" natural.","Indicações com evidência:","Contraindicações:","Hipertensão arterial não controlada","Arritmias cardíacas","Ansiedade generalizada e síndrome do pânico","Gravidez e lactação (cafeína atravessa placenta e leite)","Insônia","Gastrite ativa (irritante gástrico)","Interações:","ANTICOAGULANTES (varfarina): potencialização antiagregante — monitorar","OUTROS ESTIMULANTES (efedrina, sinefrina): risco de síndrome de hiperestimulação","ANTIDEPRESSIVOS IMAO: contraindicado — risco de crise hipertensiva","LÍTIO: aumenta excreção renal de lítio — reduz nível sérico","Efeitos adversos: Taquicardia, tremores finos, insônia, cefaleia de rebote, irritação gástrica em doses altas ou jejum.","Dose máxima: 3 g/dia de pó padronizado (equivalente a ~75 mg cafeína/g). OMS: cafeína total ≤ 400 mg/dia para adultos saudáveis."],"contraindicacoes":["Hipertensão arterial não controlada","Arritmias cardíacas","Ansiedade generalizada e síndrome do pânico","Gravidez e lactação (cafeína atravessa placenta e leite)","Insônia","Gastrite ativa (irritante gástrico)","Interações:","ANTICOAGULANTES (varfarina): potencialização antiagregante — monitorar","OUTROS ESTIMULANTES (efedrina, sinefrina): risco de síndrome de hiperestimulação","ANTIDEPRESSIVOS IMAO: contraindicado — risco de crise hipertensiva","LÍTIO: aumenta excreção renal de lítio — reduz nível sérico","Efeitos adversos: Taquicardia, tremores finos, insônia, cefaleia de rebote, irritação gástrica em doses altas ou jejum.","Dose máxima: 3 g/dia de pó padronizado (equivalente a ~75 mg cafeína/g). OMS: cafeína total ≤ 400 mg/dia para adultos saudáveis."],"efeitos_adversos":"Taquicardia, tremores finos, insônia, cefaleia de rebote, irritação gástrica em doses altas ou jejum.","componentes_ativos":[{"label":"CAFEÍNA","texto":"2,5–5% (> que café torrado) — Estimulante SNC — bloqueia adenosina"},{"label":"TEOBROMINA","texto":"0,02–0,17% — Vasodilatação, broncodilatação leve"},{"label":"TEOFILINA","texto":"Traços — Broncodilatação, estimulação cardíaca"},{"label":"TANINOS (catequinas, epicatequinas)","texto":"5–12% — Antioxidantes, adstringência, modula absorção de cafeína"},{"label":"SAPONINAS","texto":"0,5% — Adaptogênico, anti-inflamatório"},{"label":"XANTOSINAS","texto":"Presentes — Precursoras de purinas"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"0ea950c5-5bfc-4d28-b2de-f85d69e5b307","slug":"erva-de-lagarto","herb_id":null,"herb_latin_name":"Cissampelos ovalifolia","schema_version":"1.1","ficha":{"slug":"erva-de-lagarto","cultura":{"brasil":"A erva-de-lagarto é um dos exemplos mais claros de conhecimento fitoterápico pantaneiro que permanece quase inteiramente fora dos circuitos acadêmicos e comerciais. Usada por pescadores, peões de fazenda e ribeirinhos do Pantanal para \"dor nas costas\", \"puxado\" (lesão muscular) e \"febre\" — com alcalóides que justificam farmacologicamente esses usos. A ausência de pesquisa universitária não é ausência de evidência — é ausência de pesquisadores nesse território.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção (alcalóides extraídos melhor por calor).","quantidade":"2–4 g de folhas/raiz secas para 250 ml.","reinfusoes":"","combina_com":"Sucupira · Gengibre · Cúrcuma (blends anti-inflamatórios)","melhor_momento":"2–3x ao dia em uso terapêutico de dor.","tempo_de_infusao":"","temperatura_ideal":"Decocção a 95 °C."},"tagline":"O analgésico esquecido do pantanal — planta trepadeira de uso popular difundido entre comunidades ribeirinhas para dores musculares e articulares, com alcalóides de ação confirmada.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo; raiz coletada no período seco","status_anvisa":"Uso popular reconhecido","eixo_botanico_tpc":"Fitoterápico tradicional regional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Erva-de-Lagarto","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Erva-de-lagarto · buta-branca · orelha-de-onça (regional)","Relacionada ao gênero que inclui Cissampelos pareira — planta de uso medicinal amplamente distribuída nas Américas tropicais"],"parte_usada":"Folhas e raiz, secas.","tipo_botanico":"Fitoterápico analgésico / anti-inflamatório / antiespasmódico","nome_cientifico":"Cissampelos ovalifolia DC.","familia_botanica":"Menispermaceae (família do curare)"},"caracterizacao":{"aroma":"Herbáceo-resinoso, amadeirado suave.","notas":"","intensidade":"3/5 — medicinal, uso regular possível com orientação.","cor_da_infusao":"Marrom-amarelado a âmbar. #A88840","bioma_de_origem":"Pantanal e Cerrado — MT, MS, GO; também presente na Mata Atlântica.","sabor_dominante":"Amargo-alcaloídico moderado, resinoso, persistente. Medicinal declarado.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Cissampelos ovalifolia DC.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Analgésico (alcalóides isoquinolínicos)","Anti-inflamatório","Antiespasmódico muscular","Diurético leve","Antipirético","Componentes ativos:","⚠️ ATENÇÃO: A família Menispermaceae inclui espécies produtoras de curare (veneno de flecha). C. ovalifolia em doses medicinas usuais é segura, mas doses altas de alcalóides isoquinolínicos podem ter ação curare-like (bloqueio neuromuscular). Uso interno apenas em infusão fraca e doses controladas.","Contraindicações: Gestação — alcalóides isoquinolínicos, evitar. Miastenia gravis — contraindicado. Uso de relaxantes musculares farmacológicos — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"ALCALÓIDES ISOQUINOLÍNICOS (hayatina, hayatinina)","texto":"Analgésico, antiespasmódico, relaxante muscular"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório, antioxidante"},{"label":"TANINOS","texto":"Adstringente"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ec735e6e-622b-4e98-b55a-4db716bbfc5f","slug":"rosa-mosqueta","herb_id":null,"herb_latin_name":"Rosa canina","schema_version":"1.1","ficha":{"slug":"rosa-mosqueta","cultura":{"brasil":"","historia":"Durante a Segunda Guerra Mundial, quando o bloqueio alemão interrompeu importações de frutas cítricas para a Grã-Bretanha, o governo britânico organizou campanhas nacionais de coleta de rosa-mosqueta silvestre para produção de xarope vitamínico para crianças. Estimativas indicam que mais de 450 toneladas de pseudo-frutos foram coletados em 1941 por voluntários civis — uma das histórias mais tocantes de etnobotânica de emergência da história.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção suave.","quantidade":"3–5 g de pseudo-frutos secos para 250 ml.","reinfusoes":"","combina_com":"Hibisco · Flor de laranjeira · Camomila · Mel · Canela (blends florais vitamínicos)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"A rosa medicinal — o fruto mais rico em vitamina C das plantas temperadas, com ação articular documentada e história que vai de remédio de guerra a cosmético premium global.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use para vitamina C.","status_fda":"","sazonalidade":"Pseudo-frutos: setembro–novembro (Europa)","status_anvisa":"Uso reconhecido.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Rosa-Mosqueta","usos_topicos":{"evidencia":"","aplicacoes":["Óleo de semente (anti-aging, cicatrizante): Óleo de sementes de R. rubiginosa (prensagem a frio) — altíssima concentração de ácido linolênico (ω-3) e ácido trans-retinoico natural. Evidência moderada-forte para redução de manchas, cicatrizes e rugas."],"contraindicacoes":""},"identificacao":{"sinonimos":["Rosa-mosqueta · rosa-canina · escaramujo","Rosehip (inglês) · Cynorrhodon (francês) · Hagebutte (alemão)","Rosa silvestre / mosqueta (espanhol)"],"parte_usada":"Pseudo-frutos secos (quadril/coxinho — \"hip\"), despolpados das sementes; óleo das sementes (cosmético); pétalas (aromáticas).","tipo_botanico":"Fitoterápico vitamínico / articular / cosmético","nome_cientifico":"Rosa canina L. (rosa-silvestre europeia) / Rosa rubiginosa L. (rosa-mosqueta andina — principal para óleo cosmético)","familia_botanica":"Rosaceae"},"caracterizacao":{"aroma":"Frutal-rosáceo suave, tanino seco, levemente herbáceo.","notas":"","intensidade":"2/5 — suave e agradável.","cor_da_infusao":"Vermelho-rosado a âmbar. #D84858","bioma_de_origem":"","sabor_dominante":"Ácido-frutado suave, levemente adstringente, framboesa-rosácea, discretamente doce.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Rosa canina L. (rosa-silvestre europeia) / Rosa rubiginosa L. (rosa-mosqueta andina — principal para óleo cosmético)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Osteoartrite (dor e mobilidade)","populacao":"Winther et al. (2005) — GOPO"},{"evidencia":"Moderada","indicacao":"Artrite reumatoide","populacao":"Christensen et al. (2008)"},{"evidencia":"Forte","indicacao":"Deficiência de vitamina C","populacao":"EMA"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Vitamina C excepcional (pseudo-fruto seco: até 400 mg/100g — 5x a laranja)","Anti-inflamatório articular (GOPO — galactolipídeo específico)","Antioxidante","Cardioprotetor","Diurético suave","Cosmético regenerador (óleo de semente)","Componentes ativos:","Indicações com evidência:"],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"VITAMINA C","texto":"Antioxidante, imunidade, colágeno"},{"label":"GOPO (galactolipídeo)","texto":"Anti-inflamatório articular documentado"},{"label":"BETA-CAROTENO","texto":"Antioxidante, pró-vitamina A"},{"label":"LICOPENO","texto":"Antioxidante"},{"label":"PECTINAS","texto":"Prebiótico, hipoglicemiante leve"},{"label":"ÁCIDO LINOLÊNICO (óleo semente)","texto":"Anti-inflamatório, regenerador cutâneo"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"b4529916-1073-4c9a-aa9f-d4c58002b6b7","slug":"maracuja","herb_id":null,"herb_latin_name":"Passiflora edulis","schema_version":"1.1","ficha":{"slug":"maracuja","cultura":{"brasil":"O Brasil é o maior produtor mundial de maracujá — mais de 600.000 toneladas por ano (dado IBGE). O fruto é amplamente consumido como suco e sobremesa. As folhas, abundantíssimas na produção agrícola como subproduto, são raramente aproveitadas farmacologicamente — enorme oportunidade de cadeia circular.","historia":"Os missionários jesuítas que chegaram ao Brasil nos séculos XVI-XVII viram na flor do maracujá uma narrativa da Paixão de Cristo: as 10 pétalas como os dez apóstolos (excluindo Judas e Pedro), os filamentos como a coroa de espinhos, os cinco estames como as cinco chagas. Batizaram a planta de \"flos passionis\" — flor da paixão. Esse batismo europeu-cristão de uma planta indígena brasileira é um dos documentos mais reveladores do choque de cosmovisões na colonização.  Para os Tupi, o maracujá era \"murucuja\" — planta de curativo e alimento, sem carga simbólica cristã.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples, coberta.","quantidade":"1–2 colheres de sopa (3–5 g) de folhas secas para 250 ml.","reinfusoes":"1–2 possíveis.","combina_com":"Camomila (clássico ansiolítico) · Melissa · Lavanda · Valeriana · Erva-cidreira · Flor de laranjeira · Mel","melhor_momento":"Final de tarde e noite (30–60 min antes de dormir). Uso diurno leve possível para ansiedade.","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"A flor da paixão ansiolítica — sedativo suave com validação científica, perfil sensorial extraordinário e carga simbólica que vai da flor da cruz à farmácia natural.","receitas":[{"nome":"Infusão do Sono Pampeano","slug":"infusao-do-sono-pampeano","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC para P. incarnata — well-established use. P. edulis em avaliação.","status_fda":"GRAS (P. edulis como alimento)","sazonalidade":"Folhas disponíveis o ano todo (cultivo perene)","status_anvisa":"Monografia oficial. Indicação: ansiolítico e sedativo leve.","eixo_botanico_tpc":"Phyto-ANVISA + Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Maracujá","usos_topicos":{"evidencia":"","aplicacoes":["Compressa calmante (uso popular): Infusão forte resfriada, gaze, 15 min sobre têmporas ou nuca em cefaleia tensional. Evidência exclusivamente tradicional."],"contraindicacoes":""},"identificacao":{"sinonimos":["Maracujá · flor-da-paixão · maracujá-azedo (fruto)","Passion flower (inglês) · Passiflore (francês) · Granadilla (espanhol)","ATENÇÃO: P. edulis (maracujá-azedo brasileiro) e P. incarnata (maypop norte-americano) têm alcaloides diferentes — as monografias internacionais são principalmente para P. incarnata"],"parte_usada":"Folhas e ramos finos secos (parte aérea).","tipo_botanico":"Fitoterápico ansiolítico / sedativo suave","nome_cientifico":"Passiflora edulis Sims / Passiflora incarnata L. (espécie norte-americana — mais monografada internacionalmente)","familia_botanica":"Passifloraceae"},"caracterizacao":{"aroma":"Flor tropical discreta, folha verde, levemente frutado (traços).","notas":"Cabeça: floral discreto | Corpo: herbáceo neutro | Fundo: leve amargor suave | BIOMA: Mata Atlântica e Cerrado — cultivado em todo o Brasil tropical; maior produtor mundial.","intensidade":"1–2/5 — infusão muito suave. Perfil amistoso.","cor_da_infusao":"Verde-amarelado pálido a âmbar claro. #D4C86A","bioma_de_origem":"Mata Atlântica e Cerrado — cultivado em todo o Brasil tropical; maior produtor mundial.","sabor_dominante":"Levemente amargo-herbáceo, verde, discreto. Neutro no fundo — não impõe sabor, aceita misturas.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Passiflora edulis Sims / Passiflora incarnata L. (espécie norte-americana — mais monografada internacionalmente)","perfil_sensorial":{"tatil":"","gustativo":[{"dimensao":"Doce","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Amargo","observacao":"Discreto, agradável","intensidade":"1/3"},{"dimensao":"Umami","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Azedo","observacao":"Ausente","intensidade":"0/3"},{"dimensao":"Adstringência","observacao":"Traços","intensidade":"Muito baixa"}],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Ansiedade generalizada leve","populacao":"Akhondzadeh et al."},{"evidencia":"Moderada","indicacao":"Insônia leve","populacao":"Ngan & Conduit, 2011"},{"evidencia":"Moderada","indicacao":"Abstinência de opioide (adjuvante)","populacao":"Akhondzadeh et al."}],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico suave (ação GABAérgica)","Sedativo leve (indutor de sono)","Antiespasmódico","Antidepressivo leve (estudos preliminares)","Analgésico suave (mecanismo central)","Hipotensor leve","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação — cautela (alcaloides harmana)","Uso concomitante com benzodiazepínicos — potencialização","Uso concomitante com IMAO — contraindicado (beta-carbolinas)","Não dirigir veículos após doses mais altas"],"contraindicacoes":["Gestação — cautela (alcaloides harmana)","Uso concomitante com benzodiazepínicos — potencialização","Uso concomitante com IMAO — contraindicado (beta-carbolinas)","Não dirigir veículos após doses mais altas"],"efeitos_adversos":"","componentes_ativos":[{"label":"CRISINA (flavonoide)","texto":"Agonista parcial GABA-A — ansiolítico"},{"label":"VITEXINA, ISOVITEXINA","texto":"Sedativo, ansiolítico"},{"label":"ORIENTINA","texto":"Anti-inflamatório, antioxidante"},{"label":"HARMANA (alcaloide)","texto":"Inibição leve de MAO-A"},{"label":"PASSIFLORINA","texto":"Sedativa"},{"label":"BETA-CARBOLINAS","texto":"Ação GABAérgica"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:30:21.416273+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"5201ec3d-9d49-41dc-b24b-971b5e36253f","slug":"sabugueiro","herb_id":null,"herb_latin_name":"Sambucus nigra","schema_version":"1.1","ficha":{"slug":"sabugueiro","cultura":{"brasil":"Praticamente desconhecido na medicina popular brasileira — chegou como suplemento importado nos anos 2010 com o boom das \"imunidades naturais\" durante e após a pandemia de COVID-19. O Ervatório tem oportunidade de contextualizar o sabugueiro dentro de sua narrativa europeia genuína, diferenciando-o do marketing pandêmico oportunista.","historia":"O sabugueiro é a árvore-farmácia do folclore europeu pré-cristão — em toda a Europa há tradição de que ao pé do sabugueiro habitam espíritos protetores. Cortar um sabugueiro sem pedir permissão era tabu em toda a Europa setentrional e central. Hipócrates chamava-o de \"farmácia do médico da aldeia\". John Evelyn (séc. XVII) escreveu que se todos os usos medicinais do sabugueiro fossem enumerados, precisaria-se de um livro.  O xarope de sabugueiro (elderberry syrup) é o remédio de inverno mais tradicional da Europa — de Portugal à Noruega. O registro arqueológico mais antigo de uso de sabugueiro como alimento data de 5.000 a.C. (Itália, pré-histórico).","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Equinácea · Gengibre · Canela · Mel · Própolis · Hibisco","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A farmácia da floresta europeia — antiviral de frutas escuras com ação confirmada contra influenza, imunidade robusta e história que atravessa da Europa pré-cristã ao laboratório de Harvard.","receitas":[{"nome":"Sistema Imune","slug":"sistema-imune","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — traditional use para gripes e resfriados.","status_fda":"GRAS para uso alimentar (frutos cozidos).","sazonalidade":"Flores: maio–junho. Frutos: agosto–setembro (Europa).","status_anvisa":"Uso reconhecido. Suplemento amplamente comercializado.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Sabugueiro","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Sabugueiro · saúco · sanguinho-de-água (confusão)","Elder / Elderberry / Elderflower (inglês) · Sureau (francês) · Holunder (alemão)","Bozur (esloveno — planta mais importante do folclore esloveno)","ATENÇÃO: frutos crus contêm sambunigrina (cianogênico) — sempre cozinhar ou secar antes de consumir."],"parte_usada":"Flores secas (anti-inflamatório, diaforético); frutos maduros secos (antiviral, antioxidante).","tipo_botanico":"Fitoterápico antiviral / imunomodulador / antioxidante","nome_cientifico":"Sambucus nigra L.","familia_botanica":"Adoxaceae (antes Caprifoliaceae)"},"caracterizacao":{"aroma":"","notas":"","intensidade":"2/5 (flores) — 3/5 (frutos).","cor_da_infusao":"","bioma_de_origem":"","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Sambucus nigra L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Influenza (redução duração e gravidade)","populacao":"Zakay-Rones et al. (2004)"},{"evidencia":"Moderada","indicacao":"Resfriado comum (duração)","populacao":"Tiralongo et al. (2016)"},{"evidencia":"Moderada","indicacao":"Imunidade geral","populacao":"Kong (2009)"}],"interacoes":[],"dose_maxima":"","acoes_principais":[],"contraindicacoes":["Frutos crus — sambunigrina (cianogênico): sempre cozinhar ou usar secos certificados","Doenças autoimunes — imunomodulador; cautela","Gestação — dados insuficientes para doses terapêuticas"],"efeitos_adversos":"","componentes_ativos":[{"label":"ANTOCIANINAS (cianidina-3-glucosídeo, cianidina-3-sambubiosídeo)","texto":"Antiviral, antioxidante"},{"label":"SAMBUCOL (fração polissacarídica padronizada)","texto":"Inibição de neuraminidase viral"},{"label":"ÁCIDO CLOROGÊNICO","texto":"Antiviral, antioxidante"},{"label":"RUTINA, ISOQUERCETINA","texto":"Anti-inflamatório, antioxidante"},{"label":"LECTINAS (flores)","texto":"Imunomodulador"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"d764530b-b079-49d6-9da8-e56c187fb09f","slug":"tomilho","herb_id":null,"herb_latin_name":"Thymus vulgaris","schema_version":"1.1","ficha":{"slug":"tomilho","cultura":{"brasil":"","historia":"O timol do tomilho foi o principal antisséptico clínico antes da era dos antibióticos — o Listerine original continha timol como princípio ativo (ainda contém). Hospitais europeus do século XIX usavam vapores de tomilho para \"purificar o ar\" das enfermarias — empirismo que a farmacologia confirmou: timol é bactericida de amplo espectro. Os egípcios usavam timol no processo de mumificação — preservativo antimicrobiano natural.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta.","quantidade":"1–2 g de partes aéreas secas para 250 ml.","reinfusoes":"","combina_com":"Mel · Limão · Gengibre · Sabugueiro · Guaco · Eucalipto (blends respiratórios)","melhor_momento":"3x ao dia em episódios respiratórios agudos.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (timol volátil — não ferver)."},"tagline":"O antisséptico aromático do mediterrâneo — expectorante e antimicrobiano de primeira linha com evidência clínica para bronquite aguda superior a muitos fármacos convencionais.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — well-established use para bronquite e tosse.","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo (cultivo perene)","status_anvisa":"Monografia oficial. Indicações: expectorante, antisséptico respiratório.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Tomilho","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Tomilho · tomilho-comum · tomilho-vulgar","Thyme (inglês) · Thym (francês) · Thymian (alemão)","Timo (italiano/espanhol)"],"parte_usada":"Partes aéreas (folhas e flores), frescas ou secas.","tipo_botanico":"Fitoterápico expectorante / antimicrobiano / antisséptico","nome_cientifico":"Thymus vulgaris L.","familia_botanica":"Lamiaceae"},"caracterizacao":{"aroma":"Timol pungente e quente, herbal-mediterrâneo intenso, carvacrol, leve floral.","notas":"","intensidade":"3–4/5 — aromático dominante.","cor_da_infusao":"Verde-amarelado a âmbar. #C8B04A","bioma_de_origem":"","sabor_dominante":"Aromático-herbáceo quente, levemente picante, timol característico, levemente amargo, persistente e aquecedor.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Thymus vulgaris L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte","indicacao":"Bronquite aguda","populacao":"ECR alemão: não-inferior a ambroxol"},{"evidencia":"Forte","indicacao":"Tosse produtiva","populacao":"EMA — well-established use"},{"evidencia":"Moderada","indicacao":"Infecções respiratórias altas","populacao":"Studiengruppe Thymiantropfen"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Expectorante (fluidifica muco brônquico)","Antisséptico respiratório (timol — antimicrobiano de mucosas)","Antitussígeno","Broncodilatador leve","Antimicrobiano potente (timol — bactérias e fungos)","Anti-inflamatório","Antioxidante","Componentes ativos:","Indicações com evidência:","Contraindicações:","Alergia às Lamiaceae","Gestação em doses de OE — timol emenagogo; infusão segura moderadamente","Hipotireoidismo — cautela em uso regular intenso"],"contraindicacoes":["Alergia às Lamiaceae","Gestação em doses de OE — timol emenagogo; infusão segura moderadamente","Hipotireoidismo — cautela em uso regular intenso"],"efeitos_adversos":"","componentes_ativos":[{"label":"TIMOL","texto":"20–54% do OE — Antimicrobiano potente, expectorante, antisséptico"},{"label":"CARVACROL","texto":"1–10% do OE — Antimicrobiano, anti-inflamatório"},{"label":"P-CIMENO","texto":"Presente — Antimicrobiano"},{"label":"ÁCIDO ROSMARÍNICO","texto":"Presente — Antioxidante, anti-inflamatório"},{"label":"TIMOSINA","texto":"Flavonoide — presente — Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"d5c97d17-2204-48ff-a31d-ffabbeb7ff12","slug":"erva-de-sao-joao","herb_id":null,"herb_latin_name":"Hypericum perforatum","schema_version":"1.1","ficha":{"slug":"erva-de-sao-joao","cultura":{"brasil":"","historia":"A erva-de-são-joão floresce exatamente em torno do solstício de verão do hemisfério norte — 24 de junho, Dia de São João. Essa coincidência fenológica foi interpretada por todas as culturas europeias como signo sagrado: a planta que floresce no dia mais longo do ano traz a luz para a escuridão interior. O simbolismo antidepressivo estava incorporado ao nome antes que qualquer farmacologista identificasse a hiperforina.  A Alemanha tem os ensaios clínicos mais rigorosos com hipérico do mundo — e é o país onde o produto é prescrito como antidepressivo de primeira linha em depressão leve. A Deutsche Gesellschaft für Psychiatrie recomenda hipérico como alternativa aos ISRS para depressão leve-moderada com perfil de segurança favorável — desde que excluídas as interações medicamentosas.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta (hipericina levemente fotossensível — não expor ao sol direto após preparo).","quantidade":"2–4 g/250 ml","reinfusoes":"","combina_com":"Melissa · Lavanda · Camomila (blends de equilíbrio emocional)","melhor_momento":"Manhã e tarde — uso regular por 4–6 semanas para efeito antidepressivo.","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 8–10 min coberto | Quantidade: 2–4 g/250 ml"},"tagline":"O antidepressivo herbal da Europa — o único fitoterápico com eficácia demonstrada em depressão leve a moderada comparável à dos fármacos convencionais, e o exemplo mais citado de interações medicamentosas entre plantas e fármacos.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — well-established use para depressão leve.","status_fda":"","sazonalidade":"Floração: junho–julho (Europa) — colheita em floração plena","status_anvisa":"Monografia oficial. Interações listadas obrigatoriamente na bula.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Erva-de-São-João","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Erva-de-são-joão · hipérico · erva-furada · hipericão","St. John's wort (inglês) · Millepertuis (francês) · Johanniskraut (alemão)"],"parte_usada":"Sumidades floridas (planta em flor), secas — parte aérea com flores amarelas.","tipo_botanico":"Fitoterápico antidepressivo / ansiolítico / antiviral","nome_cientifico":"Hypericum perforatum L.","familia_botanica":"Hypericaceae (antes Clusiaceae)"},"caracterizacao":{"aroma":"Herbáceo suave, levemente resinoso-balsâmico, feno florido.","notas":"","intensidade":"2/5 — suave, uso cotidiano possível.","cor_da_infusao":"Amarelo-ouro a avermelhado (hipericina cora levemente). #D4A040","bioma_de_origem":"","sabor_dominante":"Levemente amargo-adstringente, resinoso, herbáceo suave, levemente balsâmico. Palatável.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Hypericum perforatum L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte","indicacao":"Depressão leve a moderada","populacao":"Linde et al. (2008) Cochrane"},{"evidencia":"Moderada","indicacao":"Ansiedade generalizada leve","populacao":"Volz et al. (2002)"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Antidepressivo (inibição recaptação serotonina, dopamina, norepinefrina)","Ansiolítico","Antiviral (hipericina — especialmente HIV e herpes in vitro)","Anti-inflamatório","Neuroprotetor","Componentes ativos:","Indicações com evidência:","⚠️ INTERAÇÕES CRÍTICAS — HIPERFORINA:","Anticoncepcionais orais — reduz eficácia (gravidez não planejada documentada)","Antiretrovirais (HIV) — reduz nível sérico drasticamente","Ciclosporina (transplantes) — rejeição de órgão documentada","Varfarina — reduz anticoagulação","Digoxina — reduz nível sérico","Antidepressivos ISRS — síndrome serotoninérgica","Contraindicações:","Depressão severa — eficácia insuficiente; risco de suicídio","Qualquer medicamento metabolizado pelo CYP3A4 — interação provável","Fototoxicidade — hipericina aumenta sensibilidade ao UV (evitar sol intenso)"],"contraindicacoes":["Depressão severa — eficácia insuficiente; risco de suicídio","Qualquer medicamento metabolizado pelo CYP3A4 — interação provável","Fototoxicidade — hipericina aumenta sensibilidade ao UV (evitar sol intenso)"],"efeitos_adversos":"","componentes_ativos":[{"label":"HIPERICINA, PSEUDOHIPERICINA","texto":"Antidepressivo (mecanismo discutido), antiviral"},{"label":"HIPERFORINA","texto":"Principal antidepressivo — inibição recaptação de monoaminas; indutor potente de CYP3A4"},{"label":"AMENTOFLAVONA","texto":"Anti-inflamatório, ansiolítico"},{"label":"QUERCETINA, RUTINA","texto":"Antioxidante, anti-inflamatório"},{"label":"XANTONA","texto":"Inibição de MAO-A e MAO-B (fraca)"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"70b7c898-d15b-48ba-a558-22b1d2b75eda","slug":"dente-de-leao","herb_id":null,"herb_latin_name":"Taraxacum officinale","schema_version":"1.1","ficha":{"slug":"dente-de-leao","cultura":{"brasil":"","historia":"O dente-de-leão é a erva-daninha mais farmacologicamente rica dos quintais do mundo — e a mais perseguida pelos jardineiros. A ironia de gastar horas arrancando plantas com vitaminas, minerais, prebióticos e ação hepática documentada para que o gramado fique \"limpo\" é uma metáfora sobre o que a modernidade perdeu na relação com a natureza.  Toda criança do mundo soprou as sementes-paraquedas do dente-de-leão e fez um pedido. Essa memória afetiva universal é uma das histórias mais lindas do catálogo — a erva que nenhuma criança tem medo, que todos conhecem, que todos pisoteiam e que cuida do fígado.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Chicória · Alcachofra · Carqueja · Boldo (blends hepáticos) · Mel (adoça o amargo)","melhor_momento":"Manhã (hepático/digestivo). Moderado à tarde (diurético).","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A erva daninha que é uma farmácia — diurético, hepático e nutritivo de distribuição global que cresce em quintais do mundo inteiro e é subutilizado por todos.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use para digestivo e diurético.","status_fda":"","sazonalidade":"Disponível o ano todo (perene)","status_anvisa":"Uso reconhecido. Folhas: alimento. Raiz: uso medicinal.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Dente-de-Leão","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Dente-de-leão · amargão · taraxaco","Dandelion (inglês) · Pissenlit (francês — \"mija-na-cama\") · Löwenzahn (alemão — \"dente de leão\")"],"parte_usada":"Raiz (hepático/digestivo); folhas (diurético/nutritivo); flores (antioxidante/alimentar).","tipo_botanico":"Fitoterápico diurético / hepático / nutritivo","nome_cientifico":"Taraxacum officinale F.H.Wigg. (complexo de espécies)","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Terroso-amargo, raiz torrada, levemente caramelado (raiz torrada).","notas":"","intensidade":"3/5 — amargo assertivo, digestivo.","cor_da_infusao":"Marrom-escuro (raiz torrada) a âmbar (raiz crua). #7A5030","bioma_de_origem":"","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Taraxacum officinale F.H.Wigg. (complexo de espécies)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Diurético (folhas — aumento de diurese sem depleção de K+, ao contrário de diuréticos farmacológicos)","Colagogo/colerético (raiz — estimula bílis)","Hepatoprotetor","Prebiótico (inulina — substrato para bifidobactérias)","Hipoglicemiante leve","Antioxidante","Nutritivo excepcional (folhas: vitaminas A, C, K, ferro, cálcio)","Componentes ativos:","Contraindicações: Cálculo biliar — colagogo, pode precipitar cólica. Alergia à Asteraceae. Gestação — cautela com raiz em dose alta."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"SESQUITERPENOS AMARGOS (taraxacina, taraxacerina)","texto":"Raiz — Digestivo amargo, colagogo"},{"label":"INULINA","texto":"Raiz — Prebiótico, hipoglicemiante leve"},{"label":"TARAXASTEROL","texto":"Raiz — Anti-inflamatório, hepatoprotetor"},{"label":"ÁCIDO CAFEOILQUÍNICO","texto":"Folhas/raiz — Antioxidante, hepatoprotetor"},{"label":"VITAMINA A (beta-caroteno)","texto":"Folhas — Antioxidante, nutritivo"},{"label":"VITAMINA C","texto":"Folhas — Antioxidante, imunidade"},{"label":"FERRO, CÁLCIO, POTÁSSIO","texto":"Folhas — Nutritivo"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ff9bfe8e-b0eb-4af1-95f4-f14db1f9708e","slug":"alcachofra","herb_id":null,"herb_latin_name":"Cynara scolymus","schema_version":"1.1","ficha":{"slug":"alcachofra","cultura":{"brasil":"","historia":"A alcachofra foi considerada afrodisíaco na Roma Antiga — Plínio a descreve como alimento de luxo das elites romanas. Na Renascença italiana, Catarina de Médici era consumidora tão entusiasta de alcachofra que escandalizou a corte francesa por comer \"tanto quanto um homem\". A passagem de alimento erótico a fitoterápico hepático é uma das mais curiosas da história botânica.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta.","quantidade":"2–4 g folhas secas/250 ml","reinfusoes":"","combina_com":"Dente-de-leão · Boldo · Carqueja · Funcho · Alcaçuz (adoça o amargo)","melhor_momento":"20–30 min antes das refeições (hepático/colagogo) — 2–3x ao dia.","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 8–10 min coberto | Quantidade: 2–4 g folhas secas/250 ml"},"tagline":"O cardoprotetor hepático — o fitoterápico com a melhor evidência clínica para proteção do fígado e melhora de dislipidemias entre todas as ervas do catálogo, com uma das farmacologias mais elegantes da fitoterapia europeia.","receitas":[{"nome":"Emagrecimento Cerradão","slug":"emagrecimento-cerradao","proposito":null},{"nome":"Hepatoprotetor do Sertão","slug":"hepatoprotetor-do-sertao","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use para dispepsia e dislipidemia.","status_fda":"","sazonalidade":"Folhas: período vegetativo ativo","status_anvisa":"Monografia oficial. Indicações: colagogo, hepatoprotetor.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Alcachofra","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Alcachofra · alcachofra-de-cabeça","Artichoke (inglês) · Artichaut (francês) · Artischocke (alemão)"],"parte_usada":"Folhas (uso medicinal — não o fruto/flor que se come).","tipo_botanico":"Fitoterápico hepatoprotetor / colagogo / hipolipemiante","nome_cientifico":"Cynara scolymus L. / Cynara cardunculus var. scolymus","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Herbáceo amargo, levemente alcaloídico, terroso-vegetal.","notas":"","intensidade":"4/5 — amargo intenso, uso medicinal declarado.","cor_da_infusao":"Verde-escuro a verde-amarelado. #6A9030","bioma_de_origem":"","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Cynara scolymus L. / Cynara cardunculus var. scolymus","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Dislipidemia (redução LDL)","populacao":"Wider et al. (2013) Cochrane"},{"evidencia":"Forte","indicacao":"Dispepsia funcional","populacao":"EMA — well-established use"},{"evidencia":"Moderada","indicacao":"Hepatoproteção","populacao":"Múltiplos ECR europeus"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Hepatoprotetor (proteção e regeneração hepatocelular)","Colagogo/colerético (estimula produção e fluxo de bílis)","Hipolipemiante (reduz colesterol LDL e total)","Antioxidante (ORAC elevado)","Diurético","Digestivo amargo","Componentes ativos:","Indicações com evidência:","Contraindicações: Obstrução biliar — colagogo intenso, contraindicado. Alergia às Asteraceae."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"ÁCIDO CLOROGÊNICO","texto":"Hepatoprotetor, antioxidante, hipolipemiante"},{"label":"CINARINA","texto":"Colagogo, hipolipemiante, hepatoprotetor — composto-chave"},{"label":"LUTEOLINA, APIGENINA","texto":"Anti-inflamatório, antioxidante"},{"label":"CINAROPICRINA (lactona sesquiterpênica)","texto":"Digestivo amargo, anti-inflamatório"},{"label":"ÁCIDO CAFEICO","texto":"Antioxidante, hepatoprotetor"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"d0474dda-e5a7-4dfe-b497-b368830a0aa7","slug":"salvia","herb_id":null,"herb_latin_name":"Salvia officinalis","schema_version":"1.1","ficha":{"slug":"salvia","cultura":{"brasil":"","historia":"\"Cur moriatur homo cui salvia crescit in horto?\" — \"Por que morreria um homem cujo jardim tem sálvia?\" — provérbio latino medieval que captura a reputação absoluta da sálvia na medicina europeia por séculos. A Escola Médica de Salerno (séc. XI) a listou como erva universal — cura de tudo. Shakespeare menciona sálvia. Hildegarda de Bingen dedica páginas extensas a ela.  A pesquisa moderna encontrou mecanismo nootrópico na sálvia (inibição de acetilcolinesterase) que está sendo avaliado para Alzheimer precoce — mais um caso em que a medicina medieval intuiu um mecanismo farmacológico que a ciência demoraria 800 anos para nomear.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"1–2 g/250 ml","reinfusoes":"","combina_com":"Alecrim · Tomilho · Limão · Mel (blends mediterrâneos)","melhor_momento":"Manhã (cognitivo/antisséptico oral) ou tarde (antisuorífico para menopausa).","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (cânfora volátil)."},"tagline":"A sábia da Idade Média — a erva que curava tudo segundo os medievais, com ação antimicrobiana, menopausal e cognitiva entre as mais bem documentadas das Lamiaceae.","receitas":[{"nome":"Garganta-Boa (Bochecho)","slug":"garganta-boa-bochecho","proposito":null},{"nome":"Menopausa Equilibrada","slug":"menopausa-equilibrada","proposito":null},{"nome":"Clareza e Memória","slug":"clareza-e-memoria","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use para aftas, sudorese, boca seca.","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo","status_anvisa":"Uso reconhecido.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Sálvia","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Sálvia · sálvia-oficial · salva (Portugal)","Sage (inglês) · Sauge (francês) · Salbei (alemão)","Salvare (latim — \"salvar\") — origem do nome"],"parte_usada":"Folhas frescas ou secas.","tipo_botanico":"Fitoterápico antimicrobiano / antisuorífico / cognitivo","nome_cientifico":"Salvia officinalis L.","familia_botanica":"Lamiaceae"},"caracterizacao":{"aroma":"Cânfora-herbal quente, mediterrâneo profundo, levemente amadeirado, floresta seca.","notas":"","intensidade":"3/5 — aromático presente, palatável.","cor_da_infusao":"Verde-cinza a âmbar. #A8A840","bioma_de_origem":"","sabor_dominante":"Aromático-herbáceo quente e amargo, levemente mentolado, cânfora discreta, persistente e complexo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Salvia officinalis L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antimicrobiano (boca, garganta — bochecho)","Antisuorífico (reduz sudorese excessiva — ação única documentada)","Cognitivo (inibição de AChE — melhora memória)","Anti-inflamatório","Estrogênico fraco (fogachos na menopausa)","Antioxidante (ácido carnósico)","Componentes ativos:","⚠️ CÂNFORA: Neurotóxica em doses altas de óleo essencial. Infusão em doses usuais: segura. Óleo essencial de sálvia: contraindicado para uso interno.","Contraindicações:","Gestação — cânfora, tujona (traços) — evitar doses elevadas; uso culinário seguro","Epilepsia — cânfora pró-convulsivante","Amamentação — reduz produção de leite (antisuorífico — útil no desmame)"],"contraindicacoes":["Gestação — cânfora, tujona (traços) — evitar doses elevadas; uso culinário seguro","Epilepsia — cânfora pró-convulsivante","Amamentação — reduz produção de leite (antisuorífico — útil no desmame)"],"efeitos_adversos":"","componentes_ativos":[{"label":"CÂNFORA","texto":"Antimicrobiano, estimulante — neurotóxico em dose alta"},{"label":"ÁCIDO ROSMARÍNICO","texto":"Antioxidante, anti-inflamatório"},{"label":"ÁCIDO URSÓLICO","texto":"Anti-inflamatório, antimicrobiano"},{"label":"DITERPENOS (carnosol, ácido carnósico)","texto":"Antioxidante, nootrópico"},{"label":"FLAVONÓIDES (luteolina)","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"f88d274d-1eb2-4314-85eb-4bd27a31b98e","slug":"boldo-do-chile","herb_id":null,"herb_latin_name":"Peumus boldus","schema_version":"1.1","ficha":{"slug":"boldo-do-chile","cultura":{"brasil":"O boldo é o fitoterápico mais vendido no Brasil — disparado. \"Chá de boldo para ressaca\" é prática universal na cultura brasileira — presente em botecos, festas, famílias. O volume de consumo é inversamente proporcional ao nível de informação sobre uso correto: a maioria das pessoas que toma boldo não sabe da limitação de tempo de infusão, da dose máxima, nem da diferença entre boldo-do-chile e boldo-brasileiro. O Ervatório tem responsabilidade pedagógica específica com o boldo — é a erva que mais precisa de ficha detalhada no Brasil.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples coberta.","quantidade":"1–2 g de folhas secas para 250 ml. Dose baixa é essencial.","reinfusoes":"","combina_com":"Alcachofra · Carqueja · Dente-de-leão · Funcho","melhor_momento":"20–30 min antes das refeições — 2–3x ao dia.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (boldina sensível ao calor intenso)."},"tagline":"O fígado da América do Sul — digestivo hepático sul-americano com a maior penetração de mercado de qualquer fitoterápico no Brasil e na América Latina, com eficácia sólida e riscos subnotificados.","receitas":[{"nome":"Hepatoprotetor do Sertão","slug":"hepatoprotetor-do-sertao","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — traditional use para dispepsia.","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo","status_anvisa":"Monografia oficial. Indicações: colagogo, digestivo. Alerta de uso correto obrigatório.","eixo_botanico_tpc":"Funcional global (Sul-Americano)","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Boldo-do-Chile","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Boldo · boldo-do-chile · boldo-verdadeiro","Boldo (inglês/francês) · Boldo del Chile (espanhol)","ATENÇÃO: \"boldo-brasileiro\" é Plectranthus barbatus — espécie completamente diferente, familia diferente, química diferente."],"parte_usada":"Folhas secas.","tipo_botanico":"Fitoterápico hepático / colagogo / digestivo","nome_cientifico":"Peumus boldus Molina","familia_botanica":"Monimiaceae"},"caracterizacao":{"aroma":"Resinoso-mentolado intenso, cânfora, herbal robusto, levemente eucaliptoide.","notas":"","intensidade":"4/5 — presença dominante.","cor_da_infusao":"Verde-escuro a âmbar-esverdeado. #6A8028","bioma_de_origem":"","sabor_dominante":"Intensamente amargo, resinoso-alcaloídico, persistente. Amargor denso e complexo — um dos mais ricos do catálogo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Peumus boldus Molina","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Colagogo/colerético (maior indutor de fluxo biliar entre os fitoterápicos hepáticos)","Hepatoprotetor (boldina — antioxidante hepático)","Digestivo amargo","Diurético","Antiespasmódico","Componentes ativos:","⚠️ ATENÇÃO — BOLDINA:","Contraindicações:","Obstrução biliar — colagogo intenso, contraindicado","Gestação — boldina hepatotóxica e possivelmente teratogênica em doses altas","Hepatite aguda — pode agravar; usar apenas na fase crônica/manutenção","Ascaridol (OE) — hepatotóxico em dose alta"],"contraindicacoes":["Obstrução biliar — colagogo intenso, contraindicado","Gestação — boldina hepatotóxica e possivelmente teratogênica em doses altas","Hepatite aguda — pode agravar; usar apenas na fase crônica/manutenção","Ascaridol (OE) — hepatotóxico em dose alta"],"efeitos_adversos":"","componentes_ativos":[{"label":"BOLDINA (alcaloide aporfínico)","texto":"Colagogo potente, hepatoprotetor, antioxidante"},{"label":"ISOBOLDINA","texto":"Colagogo"},{"label":"NORISOCORYDINA","texto":"Antiespasmódico"},{"label":"ÓLEOS ESSENCIAIS (ascaridol, p-cimeno)","texto":"Aromático, antimicrobiano"},{"label":"FLAVONÓIDES","texto":"Antioxidante"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"7c426171-5142-4afa-af60-ce4fa8844523","slug":"funcho","herb_id":null,"herb_latin_name":"Foeniculum vulgare","schema_version":"1.1","ficha":{"slug":"funcho","cultura":{"brasil":"","historia":"O funcho era a planta do herói grego — Prometeu, na mitologia, roubou o fogo dos deuses escondendo-o em um caule de funcho (pelo interior esponjoso e combustível lento). O festival de Maratona, onde Fídípides correu 42 km para anunciar a vitória grega, aconteceu num campo de funcho — \"marathon\" vem do grego para funcho (marathron).  Em Roma, os gladiadores comiam funcho antes dos combates — estamina e digestão. Na Índia, sementes de funcho são mastigadas após as refeições em restaurantes como digestivo e refrescante bucal — prática que persiste em restaurantes indianos no mundo inteiro.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão de sementes levemente maceradas, coberta.","quantidade":"1–2 colheres de chá (2–5 g) de sementes para 250 ml.","reinfusoes":"","combina_com":"Camomila · Melissa · Anis · Alcaçuz · Gengibre (blends digestivos)","melhor_momento":"Pós-refeições (digestivo/carminativo). Ideal para bebês com cólica (dose muito diluída).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"O digestivo de todos os continentes — antiespasmódico com uso medicinal em 6.000 anos de história, presente em todas as tradições culinárias e medicinais do mundo mediterrâneo e tropical.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — well-established use para flatulência.","status_fda":"","sazonalidade":"Sementes maduras: verão-outono","status_anvisa":"Monografia oficial. Indicações: carminativo, antiespasmódico digestivo.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Funcho","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Funcho · erva-doce · anis-falso (confusão)","Fennel (inglês) · Fenouil (francês) · Fenchel (alemão) · Hinojo (espanhol)","ATENÇÃO: \"erva-doce\" no Brasil refere-se tanto ao funcho (F. vulgare) quanto ao anis-estrelado (Illicium verum) — sabores similares, plantas distintas."],"parte_usada":"Frutos (sementes) secos; folhas (uso culinário).","tipo_botanico":"Fitoterápico digestivo / carminativo / antiespasmódico","nome_cientifico":"Foeniculum vulgare Mill.","familia_botanica":"Apiaceae (família do coentro, da cenoura, do anis)"},"caracterizacao":{"aroma":"Anis-doce característico (trans-anetol), levemente mentolado-fresco, feno adocicado.","notas":"","intensidade":"3/5 — aromático presente e agradável.","cor_da_infusao":"Amarelo-pálido a âmbar claro. #E8D878","bioma_de_origem":"","sabor_dominante":"Doce-anis intenso e redondo, levemente licoroso, fresco, aromático. Um dos sabores mais imediatamente agradáveis do catálogo digestivo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Foeniculum vulgare Mill.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Cólica infantil (lactentes)","populacao":"Alexandrovich et al. (2003)"},{"evidencia":"Forte","indicacao":"Flatulência e distensão abdominal","populacao":"EMA — well-established use"},{"evidencia":"Moderada","indicacao":"Síndrome do intestino irritável (adjuvante)","populacao":"Múltiplos estudos"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Carminativo (elimina gases intestinais — principal indicação)","Antiespasmódico intestinal","Expectorante (fluidifica muco brônquico)","Galactogogo (estimula produção de leite — uso tradicional; evidência fraca)","Antimicrobiano leve","Anti-inflamatório","Estrogênico fraco (anetol)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Alergia a Apiaceae (cenoura, aipo, coentro) — reação cruzada possível","Gestação em doses altas (OE) — estrogênico; infusão em dose culinária: segura","Câncer hormônio-dependente — cautela com estrogênio vegetal"],"contraindicacoes":["Alergia a Apiaceae (cenoura, aipo, coentro) — reação cruzada possível","Gestação em doses altas (OE) — estrogênico; infusão em dose culinária: segura","Câncer hormônio-dependente — cautela com estrogênio vegetal"],"efeitos_adversos":"","componentes_ativos":[{"label":"TRANS-ANETOL","texto":"60–75% do OE — Carminativo, antiespasmódico, estrogênico fraco"},{"label":"FENCONA","texto":"12–22% do OE — Aromático, expectorante"},{"label":"ESTRAGOL","texto":"2–5% — Aromático (potencialmente genotóxico em doses altas)"},{"label":"ÁCIDO CLOROGÊNICO","texto":"Presente — Antioxidante"},{"label":"FLAVONÓIDES (quercetina, kemferol)","texto":"Presentes — Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"9e64f3e4-bf92-489a-967d-312171a5e184","slug":"calendula","herb_id":null,"herb_latin_name":"Calendula officinalis","schema_version":"1.1","ficha":{"slug":"calendula","cultura":{"brasil":"A calêndula é o fitoterápico tópico mais vendido em farmácias de manipulação do Brasil — pomadas, cremes, géis e óleos. A pomada de calêndula tem registro na ANVISA como produto fitoterápico — um dos poucos no catálogo com produto semi-industrializado regulamentado para uso externo. Paralelamente ao produto farmacêutico, a calêndula é cultivada em quintais de Norte a Sul para preparo caseiro de óleos e compressas.","historia":"A calêndula recebeu o nome Calendula por florescer ao início de cada mês (calendas romanas) — ou quase. Médicos romanos a usavam em quase toda ferida de guerra. Durante a Guerra Civil Americana e a Primeira Guerra Mundial, calêndula foi usada extensivamente em campos de batalha para tratar feridas — evidência empírica de cicatrização acelerada que médicos militares documentaram e a pesquisa moderna confirmou.  Na tradição da medicina popular europeia e brasileira, a calêndula é a erva da pele — sem concorrência para uso externo. Mães brasileiras aplicam \"pomatinha de calêndula\" em bebês há gerações.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Camomila · Lavanda · Malva (blends cicatrizantes)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A flor que cura feridas — cicatrizante e anti-inflamatória tópica com a melhor evidência do catálogo para uso dermatológico, reconhecida por todas as farmacopeias do mundo.","receitas":[{"nome":"Garganta-Boa (Bochecho)","slug":"garganta-boa-bochecho","proposito":null},{"nome":"Compressa Anti-Inflamatória (Uso Externo)","slug":"compressa-anti-inflamatoria-uso-externo","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use para cicatrização.","status_fda":"","sazonalidade":"Floração: primavera-verão. No Brasil (RS/SC): setembro–março.","status_anvisa":"Monografia oficial. Produto tópico registrado. Indicação: cicatrizante, anti-inflamatório.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Calêndula","usos_topicos":{"evidencia":"","aplicacoes":["Cicatrizante de feridas e queimaduras: Compressa de infusão forte ou aplicação de óleo/pomada — evidência clínica forte para aceleração de epitelização.","Dermatite atópica e eczema: Creme ou óleo de calêndula — redução de prurido e inflamação. Estudos compararam favoravelmente à hidrocortisona 0,5% para dermatite leve.","Mucosite oral por quimioterapia: Bochecho de infusão forte 3x/dia — ensaio clínico polonês mostrou superioridade à solução salina na redução de mucosite.","Fissura de mamilo (amamentação): Lanolina + calêndula vs lanolina pura — calêndula reduziu dor e curou mais rapidamente em ECR."],"contraindicacoes":""},"identificacao":{"sinonimos":["Calêndula · maravilha · bem-me-quer · marigold-de-pote","Calendula / Marigold (inglês) · Souci (francês) · Ringelblume (alemão)","ATENÇÃO: não confundir com Tagetes spp. (cravo-de-defunto) — frequentemente chamados de \"marigold\" em inglês."],"parte_usada":"Flores liguladas (pétalas) e flores tubulosas, secas.","tipo_botanico":"Fitoterápico cicatrizante tópico / anti-inflamatório","nome_cientifico":"Calendula officinalis L.","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Floral-resinoso quente, levemente caramelado, herbáceo-amarelado.","notas":"","intensidade":"2/5 (interno) — uso principal tópico.","cor_da_infusao":"Amarelo-ouro intenso a laranja. #E8A030 — segunda cor mais vibrante do catálogo, após o hibisco.","bioma_de_origem":"","sabor_dominante":"Levemente amargo-floral, adstringente suave, discretamente resinoso. Agradável.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Calendula officinalis L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Cicatrizante (aceleração de epitelização)","Anti-inflamatório tópico (inibição de COX e LOX)","Antimicrobiano tópico","Antifúngico","Antiedematoso","Imunomodulador (uso interno)","Antiespasmódico (dismenorreia — uso interno)","Componentes ativos:","Contraindicações: Alergia à família Asteraceae — reação cruzada documentada. Gravidez: uso tópico moderado seguro; uso interno — dados insuficientes."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"TRITERPENOS (alfa e beta-amirina, oleanolato, ursolato)","texto":"Cicatrizante, anti-inflamatório"},{"label":"FLAVONÓIDES (isorhamnetina, narcissina)","texto":"Anti-inflamatório, antioxidante"},{"label":"CAROTENÓIDES (luteína, zeaxantina, beta-caroteno)","texto":"Antioxidante, cicatrizante, cor vibrante"},{"label":"POLISSACARÍDEOS","texto":"Imunomodulador"},{"label":"SAPONINAS","texto":"Anti-inflamatório, antifúngico"},{"label":"ÁCIDOS HIDROXICINÂMICOS","texto":"Antioxidante, antimicrobiano"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"119eaf66-80a9-45a3-9a49-992a6718ad1a","slug":"malva","herb_id":null,"herb_latin_name":"Malva sylvestris","schema_version":"1.1","ficha":{"slug":"malva","cultura":{"brasil":"A malva é a erva de quintal mais confiável para aftas e inflamações de garganta — \"chazinho de malva com mel\" é o primeiro recurso em qualquer casa brasileira para \"dor de garganta das crianças\". Sua suavidade e segurança tornam-na a erva anti-inflamatória de mucosa mais adequada para crianças e idosos. Para o Ervatório, a malva representa o princípio de que eficácia não precisa ser amarga, intensa ou dramática — às vezes a suavidade é a ação terapêutica.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta. Maceração a frio (12h): extrai mais mucilagem.","quantidade":"2–4 g flores+folhas secas para 250 ml.","reinfusoes":"","combina_com":"Camomila · Calêndula · Alcaçuz · Funcho (blends mucosa)","melhor_momento":"Qualquer hora; especialmente para afecções agudas de mucosa.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (mucilagens sensíveis ao calor excessivo)."},"tagline":"A demulcente universal — mucilaginosa de inflamações de mucosa com uma das distribuições geográficas mais amplas do catálogo, cultivada em quintais desde o Mediterrâneo até o Sul do Brasil.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use para inflamação de mucosa oral e tosse.","status_fda":"","sazonalidade":"Flores e folhas no período de floração — primavera-verão","status_anvisa":"Monografia oficial. Indicações: anti-inflamatório de mucosas, expectorante.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Malva","usos_topicos":{"evidencia":"","aplicacoes":["Bochecho para aftas, gengivite, mucosite: Infusão morna, bochecho 30 s, 3–4x ao dia. Demulcente que forma filme protetor sobre a mucosa irritada.","Compressa para furúnculos e pele irritada: Cataplasma de folhas maceradas aquecidas — anti-inflamatório e emoliente tópico.","Colírio leve (tradicional): Infusão muito fraca e filtrada, resfriada — uso popular para conjuntivite leve (cautela: contaminação)."],"contraindicacoes":""},"identificacao":{"sinonimos":["Malva · malva-silvestre · malva-alta","Mallow (inglês) · Mauve (francês) · Malve (alemão)"],"parte_usada":"Flores e folhas, secas.","tipo_botanico":"Fitoterápico demulcente / anti-inflamatório de mucosas","nome_cientifico":"Malva sylvestris L.","familia_botanica":"Malvaceae (família do hibisco, do algodão, do quiabo)"},"caracterizacao":{"aroma":"Herbáceo neutro suave, floral discreto.","notas":"","intensidade":"1/5 — a infusão mais suave do catálogo. Alta aceitação universal.","cor_da_infusao":"Verde-pálido a lilás discreto (flores). #D0C8E0","bioma_de_origem":"","sabor_dominante":"Mucilaginoso e levemente adocicado, herbáceo suave, neutro — a infusão mais suave e mais \"escorregadia\" do catálogo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Malva sylvestris L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Demulcente (forma filme protetor em mucosas irritadas)","Anti-inflamatório de mucosas (oral, respiratória, digestiva, urogenital)","Expectorante (mucilagens fluidificam muco)","Emoliente tópico","Laxativo leve (mucilagens)","Antitussígeno suave","Componentes ativos:","Contraindicações: Praticamente sem contraindicações em doses usuais. Laxativa em doses altas — cautela em intestino sensível."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"MUCILAGENS (polissacarídeos)","texto":"Demulcente, expectorante, laxativo leve"},{"label":"ANTOCIANINAS (flores)","texto":"Antioxidante, anti-inflamatório"},{"label":"ÁCIDOS FENÓLICOS (rosmarínico, clorogênico)","texto":"Antioxidante, anti-inflamatório"},{"label":"FLAVONÓIDES (hipolaetina-glicosídeo)","texto":"Anti-inflamatório"},{"label":"TANINOS","texto":"Adstringente, antimicrobiano"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"59b436f1-9a86-4f41-91df-41461ea64258","slug":"cavalinha","herb_id":null,"herb_latin_name":"Equisetum arvense","schema_version":"1.1","ficha":{"slug":"cavalinha","cultura":{"brasil":"","historia":"A cavalinha é um fóssil vivo — os Equisetum do Carbonífero tinham 30 metros de altura e constituíam florestas que hoje são carvão mineral. A espécie atual é praticamente idêntica às que os dinossauros comiam. Essa continuidade evolutiva de 400 milhões de anos é a história mais longa do catálogo — e é contada pela própria planta em cada articulação de seu caule.  Os Romanos usavam o caule seco de cavalinha como lixa para polir metais — a sílica abrasiva do exoesqueleto da planta é a mesma que fortalece cabelos e unhas quando consumida como infusão.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção. Não infusão — sílica requer calor sustentado.","quantidade":"3–5 g de partes aéreas secas para 500 ml.","reinfusoes":"","combina_com":"Cavalinha + Solidago + Rompe-pedra = blend diurético clássico","melhor_momento":"Manhã e tarde (diurético).","tempo_de_infusao":"","temperatura_ideal":"95 °C (sílica extrai melhor por decocção)."},"tagline":"A planta do silício — o ser vivo mais antigo do catálogo (precursora dos dinossauros) com a maior concentração de silício orgânico do reino vegetal e ação diurética documentada.","receitas":[{"nome":"Circulação nas Pernas","slug":"circulacao-nas-pernas","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — traditional use para diurético.","status_fda":"","sazonalidade":"Partes aéreas: primavera-verão","status_anvisa":"Monografia oficial. Indicações: diurético, coadjuvante em cálculo renal.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Cavalinha","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Cavalinha · erva-canudo · rabo-de-cavalo","Horsetail (inglês) · Prêle (francês) · Schachtelhalm (alemão)"],"parte_usada":"Partes aéreas estéreis (caule verde articulado), secas.","tipo_botanico":"Fitoterápico diurético / remineralizante / fortalecedor do tecido conjuntivo","nome_cientifico":"Equisetum arvense L. / E. hyemale L. (Brasil)","familia_botanica":"Equisetaceae (família evolutivamente isolada — sem parentes próximos entre angiospermas)"},"caracterizacao":{"aroma":"Herbáceo simples e suave, levemente mineral.","notas":"","intensidade":"1/5 — a infusão mais neutra do catálogo. Zero resistência sensorial.","cor_da_infusao":"Verde-amarelado pálido. #D4DC88","bioma_de_origem":"","sabor_dominante":"Levemente amargo-herbáceo, mineral, grama seca, praticamente neutro. Muito palatável.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Equisetum arvense L. / E. hyemale L. (Brasil)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Diurético (aumento de diurese)","Remineralizante (sílica orgânica — colágeno, osso, cabelo, unhas)","Hemostático leve (sílica + taninos)","Anti-inflamatório (saponinas)","Antirreumático (diurético)","Fortalecedor de tecido conjuntivo (colágeno)","Componentes ativos:","Contraindicações:","Edema cardíaco ou renal grave — diurético; cautela","Uso prolongado (>6 semanas): depleção de tiamina (vitamina B1) — suplementar","Gestação — evitar (diurético)","Espécie confusa: E. palustre (cavalinha-dos-pântanos) é tóxica — confirmar espécie"],"contraindicacoes":["Edema cardíaco ou renal grave — diurético; cautela","Uso prolongado (>6 semanas): depleção de tiamina (vitamina B1) — suplementar","Gestação — evitar (diurético)","Espécie confusa: E. palustre (cavalinha-dos-pântanos) é tóxica — confirmar espécie"],"efeitos_adversos":"","componentes_ativos":[{"label":"SÍLICA ORGÂNICA (ácido monosilícico, silicatos)","texto":"5–8% da matéria seca — Remineralizante, fortalecedor do tecido conjuntivo"},{"label":"SAPONINAS (equisetonina)","texto":"Presente — Diurético, anti-inflamatório"},{"label":"FLAVONÓIDES (isoquercetina, quercetina)","texto":"Presentes — Antioxidante, anti-inflamatório"},{"label":"TANINOS","texto":"Presentes — Hemostático, antimicrobiano"},{"label":"ÁCIDO CAFEICO","texto":"Presente — Antioxidante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"3d131461-8a3e-4d83-bf54-e4275adc4a36","slug":"gengibre-japones","herb_id":null,"herb_latin_name":"Alpinia officinarum","schema_version":"1.1","ficha":{"slug":"gengibre-japones","cultura":{"brasil":"","historia":"Hildegarda de Bingen (séc. XII) dedicou páginas extensas à galanga — \"specia vitae\" — prescrevendo-a para coração fraco, febre e pestilência. Na Europa medieval, a galanga era tão valiosa quanto a pimenta. Na culinária do Sudeste Asiático, a galanga é o rizoma que define o sabor do tom kha gai (sopa tailandesa de leite de coco) e do rendang indonésio. É a especiaria que, diz-se, o gengibre teria se tivesse nascido num jardim mais elegante.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção suave.","quantidade":"3–5 g/250 ml (rizoma fresco ou seco)","reinfusoes":"","combina_com":"Capim-limão · Gengibre · Cúrcuma · Coco · Limão-capim (blends asiáticos)","melhor_momento":"Pós-refeições ou qualquer hora como especiaria.","tempo_de_infusao":"","temperatura_ideal":"90–95 °C | Tempo: 10 min | Quantidade: 3–5 g/250 ml (rizoma fresco ou seco)"},"tagline":"O gengibre real da Ásia — a especiaria do Sudeste Asiático que Hildegarda de Bingen chamava de \"a especiaria da vida\" e que a gastronomia tailandesa e indonésia tornaram indispensável ao mundo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"GRAS para uso alimentar","sazonalidade":"Colheita: 10–12 meses após plantio","status_anvisa":"Uso alimentar.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Gengibre-Japonês","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Galanga · galangal · gengibre-tailandês · gengibre-menor","Galangal (inglês) · Galanga (francês/espanhol)","Kha (tailandês) · Laos (indonésio/holandês)","\"Spice of life\" — Hildegarda de Bingen (séc. XII)"],"parte_usada":"Rizoma fresco ou seco.","tipo_botanico":"Fitoterápico digestivo / anti-inflamatório / especiaria aromática","nome_cientifico":"Alpinia officinarum Hance (galanga-menor) / Alpinia galanga (L.) Willd. (galanga-maior — culinária tailandesa)","familia_botanica":"Zingiberaceae (família do gengibre, da cúrcuma)"},"caracterizacao":{"aroma":"Cítrico-floral-pimentado, pinho e eucalipto leve, mais refinado que o gengibre.","notas":"","intensidade":"3/5 — presença aromática elegante.","cor_da_infusao":"Amarelo-pálido a âmbar claro. #E0C860","bioma_de_origem":"","sabor_dominante":"Pimentado-cítrico fresco com nota de pinho e mentol. Mais floral e cítrico que o gengibre, menos terroso, mais elegante.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Alpinia officinarum Hance (galanga-menor) / Alpinia galanga (L.) Willd. (galanga-maior — culinária tailandesa)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Digestivo carminativo","Anti-inflamatório (galanginais)","Antimicrobiano","Antifúngico","Antinauseante","Imunomodulador leve","Componentes ativos:","Contraindicações: Gestação em doses altas — cautela. Uso culinário: seguro."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"GALANGINAIS (diterpenos)","texto":"Anti-inflamatório, antimicrobiano"},{"label":"1'S-1'-ACETOXICHAVICOL ACETATO","texto":"Antimicrobiano, antifúngico potente"},{"label":"KAEMPFEROL, GALANGINA (flavonóides)","texto":"Anti-inflamatório, antioxidante"},{"label":"ÓLEOS ESSENCIAIS (eugenol, cineol)","texto":"Digestivo, antimicrobiano"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"b0f13139-c9aa-40a1-949f-f8b48ea92c0e","slug":"tulsi","herb_id":null,"herb_latin_name":"Ocimum tenuiflorum","schema_version":"1.1","ficha":{"slug":"tulsi","cultura":{"brasil":"","historia":"O tulsi é a planta mais sagrada do hinduísmo — mais sagrada que o próprio Ganges para muitos hindus. Em toda casa hindu há uma planta de tulsi no pátio ou na janela — regada diariamente como devoção, não como jardinagem. Vishnu (deus preservador) usa uma guirlanda de tulsi; a planta é chamada de Vishnupriya — \"a amada de Vishnu\".  A separação entre medicamento e sagrado não existe no tulsi — é ao mesmo tempo oração, proteção, remédio e comida. Para o Ervatório, o tulsi representa a fronteira mais fascinante entre etnobotânica, religião e farmacologia.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"3–5 g/250 ml","reinfusoes":"","combina_com":"Gengibre · Cardamomo · Mel · Limão · Ashwagandha (blends adaptogênicos)","melhor_momento":"Manhã (adaptogênico — ativador) e tarde (imunomodulador).","tempo_de_infusao":"","temperatura_ideal":"85–90 °C | Tempo: 5–8 min coberto | Quantidade: 3–5 g/250 ml"},"tagline":"O sagrado da Índia — adaptógeno ayurvédico que os indianos chamam de \"rainha das ervas\" e que a ciência ocidental começa a reconhecer como um dos adaptógenos mais completos entre todas as plantas do catálogo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo (cultivo perene tropical)","status_anvisa":"Uso alimentar. Crescente no mercado de suplementos.","eixo_botanico_tpc":"Funcional global / Ayurveda","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Tulsi","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Tulsi · tulasi · manjericão-sagrado","Holy basil (inglês) · Basilic sacré (francês)","\"Rainha das ervas\" (Ayurveda) · \"A incomparável\" (hinduísmo)","ATENÇÃO: diferente do manjericão comum (O. basilicum) — perfil de óleos essenciais e ação adaptogênica distintos."],"parte_usada":"Folhas, flores e sementes, frescas ou secas.","tipo_botanico":"Adaptógeno / imunomodulador / ansiolítico","nome_cientifico":"Ocimum tenuiflorum L. (sin.: O. sanctum L.)","familia_botanica":"Lamiaceae (família do manjericão, da sálvia)"},"caracterizacao":{"aroma":"Eugenol-florido, levemente apimentado-canela, herbal-quente. Extraordinariamente aromático.","notas":"","intensidade":"3/5 — aromático agradável.","cor_da_infusao":"Verde-pálido a âmbar-verdoso. #B8C850","bioma_de_origem":"","sabor_dominante":"Aromático-floral complexo, notas de cravo, canela, pimenta, manjericão — mais especiado que o manjericão comum. Picante suave, herbáceo quente.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Ocimum tenuiflorum L. (sin.: O. sanctum L.)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Estresse e adaptação","populacao":"Bhattacharyya et al. (2008)"},{"evidencia":"Moderada","indicacao":"Ansiedade e cognição","populacao":"Bhattacharyya et al. (2012)"},{"evidencia":"Moderada","indicacao":"Diabetes tipo 2 (adjuvante)","populacao":"Agrawal et al. (1996)"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Adaptógeno (modulação do eixo HPA — cortisol)","Ansiolítico / antidepressivo leve","Imunomodulador","Anti-inflamatório","Antidiabético (inibição de alfaglicosidase)","Antimicrobiano potente (eugenol)","Protetor cardiovascular","Neuroprotetor","Componentes ativos:","Indicações com evidência:","Contraindicações: Anticoagulados — eugenol tem efeito antiagregante. Gestação em doses medicinais — evitar."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"EUGENOL","texto":"Antimicrobiano, anti-inflamatório, adaptogênico"},{"label":"URSOLIC ACID","texto":"Anti-inflamatório, adaptogênico, antitumoral"},{"label":"ROSMARINIC ACID","texto":"Antioxidante, anti-inflamatório"},{"label":"BETA-CARYOPHYLLENE","texto":"Anti-inflamatório, ansiolítico (CB2)"},{"label":"OCIMUMOSÍDEOS A e B","texto":"Adaptogênicos — redução de cortisol"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"e405842d-48b1-4d24-8e4d-8db836698079","slug":"ashwagandha","herb_id":null,"herb_latin_name":"Withania somnifera","schema_version":"1.1","ficha":{"slug":"ashwagandha","cultura":{"brasil":"","historia":"O ashwagandha é descrito nos textos ayurvédicos Charaka Samhita (séc. I–II d.C.) como rasayana — erva de rejuvenescimento. A palavra rasayana significa \"caminho da essência\" — ervas que restauram a vitalidade fundamental. O Charaka Samhita descreve o ashwagandha como dando força de cavalo — consistente com o nome (\"cheiro de cavalo\").  O paradoxo do ashwagandha é ser simultaneamente energizante (tônico muscular, testosterona) e sedativo (somnifera — induz sono). A resolução farmacológica: é adaptogênico — normaliza o que está desequilibrado. Em estressado e exausto, acalma. Em sedentário e depletado, tonifica.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção suave. Tradição ayurvédica: \"Ashwagandha milk\" — pó + leite quente + mel + ghee.","quantidade":"3–5 g de pó de raiz seca para 250 ml","reinfusoes":"","combina_com":"Leite/leite vegetal · Mel · Cúrcuma · Canela · Tulsi (blends adaptogênicos)","melhor_momento":"Noite (adaptogênico-relaxante; somnifera = \"que induz sono\").","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 10–15 min | Quantidade: 3–5 g de pó de raiz seca para 250 ml"},"tagline":"O ginseng indiano — adaptógeno ayurvédico com o maior portfólio de ensaios clínicos modernos entre todos os adaptógenos do catálogo, de cortisol à testosterona.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Raiz colhida 8–12 meses após plantio","status_anvisa":"Suplemento alimentar. Extratos padronizados amplamente vendidos.","eixo_botanico_tpc":"Funcional global / Ayurveda","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Ashwagandha","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Ashwagandha · ginseng-indiano · cereja-de-inverno","Ashwagandha (inglês/português) · Indian ginseng · Wintercherry","Withania (farmacológico)","\"Ashwa\" = cavalo, \"gandha\" = cheiro (sânscrito) — \"cheiro de cavalo\""],"parte_usada":"Raiz seca (principal); folhas (uso secundário).","tipo_botanico":"Adaptógeno / tônico / nootrópico","nome_cientifico":"Withania somnifera (L.) Dunal","familia_botanica":"Solanaceae (família do tomate, da berinjela)"},"caracterizacao":{"aroma":"Terroso-leitoso, levemente solanáceo, amadeirado.","notas":"","intensidade":"3/5 — medicinal, palatável.","cor_da_infusao":"Marrom-amarelado a âmbar. #C0902A","bioma_de_origem":"","sabor_dominante":"Amargo-terroso moderado, levemente leitoso e adocicado ao fundo, resinoso. Único no catálogo — inconfundível.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Withania somnifera (L.) Dunal","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte","indicacao":"Estresse e ansiedade","populacao":"Chandrasekhar et al. (2012)"},{"evidencia":"Moderada","indicacao":"Insônia","populacao":"Langade et al. (2019)"},{"evidencia":"Moderada","indicacao":"Força muscular e recuperação","populacao":"Wankhede et al. (2015)"},{"evidencia":"Moderada","indicacao":"Testosterona masculina","populacao":"Ambiye et al. (2013)"},{"evidencia":"Preliminar","indicacao":"Função tireoidiana (hipotireoidismo)","populacao":"Sharma et al. (2018)"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Adaptógeno (redução de cortisol, modulação HPA)","Ansiolítico / sedativo leve (somnifera — indutor de sono)","Tônico muscular (aumento de força e massa magra — estudos atletas)","Imunomodulador","Neuroprotetor (witaferinas — proteção contra neurodegenarção)","Anabolizante leve (aumento de testosterona — estudos masculinos)","Antidiabético (sensibilizador de insulina)","Cardioprotetor (redução de LDL)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Doenças autoimunes — imunomodulador","Hipertireoidismo — estimula tireóide","Gestação — alcalóides, evitar","Transplantados — imunomodulação"],"contraindicacoes":["Doenças autoimunes — imunomodulador","Hipertireoidismo — estimula tireóide","Gestação — alcalóides, evitar","Transplantados — imunomodulação"],"efeitos_adversos":"","componentes_ativos":[{"label":"WITANOLÍDEOS (witaferina A, witanolido D)","texto":"Adaptogênico, imunomodulador, anti-inflamatório, antitumoral"},{"label":"ALCALÓIDES (somnifério, anaferina)","texto":"Sedativo, ansiolítico"},{"label":"SAPONINAS ESTEROÍDICAS","texto":"Anabolizante, adaptogênico"},{"label":"WITANOLÍDEOS GLICOSILADOS","texto":"Imunomodulador, neuroprotetor"},{"label":"POLISSACARÍDEOS","texto":"Imunomodulador"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"d0a6f5a1-5865-4ea8-90dd-d851d66ccd2c","slug":"ginseng-asiatico","herb_id":null,"herb_latin_name":"Panax ginseng","schema_version":"1.1","ficha":{"slug":"ginseng-asiatico","cultura":{"brasil":"","historia":"O ginseng é a planta mais cara da história medicinal — raízes com mais de 100 anos de cultivo selvagem atingem dezenas de milhares de dólares em leilões coreanos. A China imperial criou rotas comerciais exclusivas de ginseng; guerras foram travadas por territórios onde crescia Panax ginseng selvagem.  O nome \"ginseng\" vem do mandarim rén shēn — \"raiz de homem\" — pela forma anthropomórfica característica das raízes mais velhas, que parecem figuras humanas com braços e pernas. Essa similaridade visual entre a raiz e o corpo humano foi interpretada como signo de que a planta curava o ser humano inteiro — Panax vem do grego \"tudo-cura\" (pan = tudo, akos = remédio). É a única planta cujo nome botânico afirma explicitamente curar tudo.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção suave.","quantidade":"2–3 g/250 ml","reinfusoes":"","combina_com":"Ginkgo · Schisandra · Ashwagandha · Mel · Canela (blends adaptogênicos premium)","melhor_momento":"Manhã (tônico/energético). Evitar à noite.","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 15–20 min (raiz dura — decocção) | Quantidade: 2–3 g/250 ml"},"tagline":"A raiz da imortalidade — o adaptógeno mais famoso do mundo, com 5.000 anos de uso documentado na medicina chinesa e coreana e o maior volume de pesquisas clínicas entre todas as plantas do catálogo.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — well-established use para fadiga.","status_fda":"GRAS para uso alimentar. Suplemento amplamente vendido.","sazonalidade":"Raiz colhida após mínimo 4–6 anos (comercial); 10+ anos (premium)","status_anvisa":"Monografia oficial. Indicações: tônico geral, adaptógeno, coadjuvante em fadiga.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Ginseng-Asiático","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Ginseng · ginseng-asiático · ginseng-coreano · ginseng-chinês","Asian ginseng (inglês) · Ginseng (universal — emprestado do chinês)","Renshen (chinês — \"raiz de homem\" — pela forma antropomórfica)","DISTINÇÃO: Panax ginseng (asiático) ≠ Panax quinquefolius (americano) ≠ Eleutherococcus senticosus (ginseng-siberiano — não é Panax)"],"parte_usada":"Raiz (6+ anos de cultivo para uso medicinal premium).","tipo_botanico":"Adaptógeno / tônico geral / nootrópico","nome_cientifico":"Panax ginseng C.A.Mey.","familia_botanica":"Araliaceae"},"caracterizacao":{"aroma":"Terroso-amadeirado, levemente resinoso, raiz seca com fundo de caramelo suave.","notas":"","intensidade":"3/5 — complexidade elegante.","cor_da_infusao":"Amarelo-ouro pálido a âmbar. #D4B848","bioma_de_origem":"","sabor_dominante":"Amargo-adocicado complexo, levemente terroso, resinoso suave, amadeirado. O amargo do ginseng é diferente de todos os outros — tem dulçor intrínseco que equilibra.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Panax ginseng C.A.Mey.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Fadiga física e mental","populacao":"Reay et al. (2005, 2006)"},{"evidencia":"Moderada","indicacao":"Disfunção erétil","populacao":"Jang et al. (2008) meta-análise"},{"evidencia":"Moderada","indicacao":"Memória e cognição","populacao":"Geng et al. (2010)"},{"evidencia":"Moderada","indicacao":"Imunidade (gripes)","populacao":"McElhaney et al. (2006)"},{"evidencia":"Moderada","indicacao":"Diabetes tipo 2 (adjuvante)","populacao":"Vuksan et al. (2000)"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Adaptógeno (modulação HPA, HPTA)","Nootrópico (melhora memória, concentração, velocidade de processamento)","Tônico sexual (disfunção erétil — evidência moderada-forte)","Imunomodulador","Cardioprotetor","Antidiabético","Anticancerígeno (pesquisa extensiva — ginsenóides)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Hipertensão — estimulante cardiovascular","Doenças autoimunes — imunomodulador","Gestação — dados insuficientes","Insônia — estimulante","Uso concomitante com warfarina — reduz eficácia anticoagulante"],"contraindicacoes":["Hipertensão — estimulante cardiovascular","Doenças autoimunes — imunomodulador","Gestação — dados insuficientes","Insônia — estimulante","Uso concomitante com warfarina — reduz eficácia anticoagulante"],"efeitos_adversos":"","componentes_ativos":[{"label":"GINSENÓIDES (Rb1, Rg1, Rg3, Re...)","texto":"Adaptogênico, nootrópico, imunomodulador — família exclusiva do gênero Panax"},{"label":"POLISSACARÍDEOS (ginsanas)","texto":"Imunomodulador, hipoglicemiante"},{"label":"PEPTÍDEOS","texto":"Imunomodulador"},{"label":"ÁCIDO PANTOTENOICO","texto":"Nutritivo, energético"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"92844751-2e2d-4950-8d79-870462c690f1","slug":"ginkgo","herb_id":null,"herb_latin_name":"Ginkgo biloba","schema_version":"1.1","ficha":{"slug":"ginkgo","cultura":{"brasil":"","historia":"O ginkgo sobreviveu à extinção em massa do Permiano (252 Ma), à do Cretáceo (66 Ma), à Glaciação do Pleistoceno — e à bomba atômica de Hiroshima. Seis ginkgos cresciam a menos de 2 km do hipocentro da bomba. Enquanto tudo ao redor foi destruído, as seis árvores rebrotaram na primavera seguinte — sem mutações detectadas. Hoje são chamadas de \"ginkgos de Hiroshima\" e protegidas como patrimônio da paz.  O ginkgo crescia apenas na China por dezenas de milhões de anos — salvo da extinção pelos monges budistas que o cultivavam em mosteiros como árvore sagrada. Chegou ao Ocidente em 1730 (Jardim Botânico de Utrecht). Hoje é a árvore ornamental mais plantada em calçadas de cidades europeias e norte-americanas.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"2–3 g/250 ml","reinfusoes":"","combina_com":"Ginseng · Melissa · Alecrim (blends cognitivos)","melhor_momento":"Manhã e tarde — uso regular (4–6 semanas) para efeito nootrópico.","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 8–10 min | Quantidade: 2–3 g/250 ml"},"tagline":"A árvore dos 270 milhões de anos — o único sobrevivente de uma linha evolutiva inteira, com a mais robusta evidência de qualquer fitoterápico para circulação cerebral e memória.","receitas":[{"nome":"Clareza e Memória","slug":"clareza-e-memoria","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use para distúrbios cognitivos.","status_fda":"","sazonalidade":"Folhas colhidas no verão (máxima concentração de flavonóides)","status_anvisa":"Monografia oficial. Extrato padronizado EGb761.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Ginkgo","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Ginkgo · ginkgo-biloba · nogueira-do-japão","Ginkgo / Maidenhair tree (inglês) · Ginkgo (universal)","Yín xìng (chinês — \"damasco prateado\")"],"parte_usada":"Folhas verdes secas (extrato padronizado EGb761 — referência clínica).","tipo_botanico":"Fitoterápico nootrópico / vasodilatador cerebral / antioxidante","nome_cientifico":"Ginkgo biloba L.","familia_botanica":"Ginkgoaceae (família isolada — único membro vivo da divisão Ginkgophyta)"},"caracterizacao":{"aroma":"Herbáceo neutro, levemente resinoso.","notas":"","intensidade":"2/5 — suave.","cor_da_infusao":"Amarelo-pálido a âmbar claro. #E0CC78","bioma_de_origem":"","sabor_dominante":"Levemente amargo-herbáceo, adstringente suave, neutro. Não é infusão de apreciação — é fitoterápico de uso sistemático.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Ginkgo biloba L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Demência (incluindo Alzheimer precoce)","populacao":"Cochrane — Birks & Grimley (2009)"},{"evidencia":"Moderada-forte","indicacao":"Claudicação intermitente","populacao":"EMA — well-established use"},{"evidencia":"Moderada","indicacao":"Zumbido (tinnitus)","populacao":"Drew & Davies (2001)"},{"evidencia":"Moderada","indicacao":"Déficit cognitivo leve","populacao":"Múltiplos ECR europeus"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Vasodilatador cerebral (aumenta fluxo sanguíneo cerebral)","Nootrópico (melhora memória e concentração)","Antioxidante de alta capacidade (neutraliza radicais livres cerebrais)","Antiagregante plaquetário","Neuroprotetor (proteção contra isquemia)","Melhora da circulação periférica (claudicação intermitente)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Anticoagulados — antiagregante plaquetário (risco de sangramento)","Pré-cirurgia — suspender 2 semanas","Anticonvulsivantes — pode reduzir limiar convulsivo (bilobalídeo)","Gestação — dados insuficientes"],"contraindicacoes":["Anticoagulados — antiagregante plaquetário (risco de sangramento)","Pré-cirurgia — suspender 2 semanas","Anticonvulsivantes — pode reduzir limiar convulsivo (bilobalídeo)","Gestação — dados insuficientes"],"efeitos_adversos":"","componentes_ativos":[{"label":"FLAVONÓIDES GINKGOIDES (quercetina, kaempferol, isorhamnetina)","texto":"24% — Antioxidante, vasodilatador"},{"label":"TERPENÓIDES (ginkgolídeos A, B, C, J)","texto":"6% — Antiagregante (antagonista PAF), vasodilatador"},{"label":"BILOBALÍDEO","texto":"2,6% — Neuroprotetor, anticonvulsivante"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"913f8afe-7eb8-4363-bad9-bb53931cd238","slug":"schisandra","herb_id":null,"herb_latin_name":"Schisandra chinensis","schema_version":"1.1","ficha":{"slug":"schisandra","cultura":{"brasil":"","historia":"A schisandra é o adaptógeno dos pilotos soviéticos — extensivamente pesquisada pelo Instituto Botânico de Vladivostok durante a Guerra Fria como \"agente farmacológico de estado\" para aumentar performance cognitiva, resistência à fadiga e capacidade de recuperação em condições extremas. Pilotos da força aérea soviética recebiam extratos de schisandra em missões de alta demanda. A farmacologia adaptogênica como campo científico foi em grande parte desenvolvida pelos soviéticos em torno dessa planta e do ginseng-siberiano.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção suave (frutos duros).","quantidade":"3–5 g frutos secos/250 ml","reinfusoes":"","combina_com":"Ginseng · Ashwagandha · Mel · Hibisco (blends adaptogênicos)","melhor_momento":"Manhã (adaptogênico/energético).","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 10–15 min | Quantidade: 3–5 g frutos secos/250 ml"},"tagline":"A baga dos cinco sabores — adaptógeno chinês único com a distinção de ativar os cinco gostos simultaneamente e uma farmacologia hepatoprotetora entre as mais potentes do catálogo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutos: agosto–outubro (China/Rússia)","status_anvisa":"Suplemento alimentar.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Schisandra","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Schisandra · esquizandra · baga-dos-cinco-sabores","Five-flavor berry (inglês) · Wǔ wèi zǐ (chinês — \"baga dos cinco sabores\")"],"parte_usada":"Frutos secos.","tipo_botanico":"Adaptógeno / hepatoprotetor / nootrópico","nome_cientifico":"Schisandra chinensis (Turcz.) Baill.","familia_botanica":"Schisandraceae"},"caracterizacao":{"aroma":"Frutado-ácido, levemente resinoso, frutas vermelhas ácidas.","notas":"","intensidade":"4/5 — experiência sensorial intensa e única.","cor_da_infusao":"Vermelho-rosado a rubi. #C04858","bioma_de_origem":"","sabor_dominante":"Extraordinário — aciona os cinco gostos simultaneamente: doce, azedo, amargo, salgado e picante. Experiência sensorial única no catálogo — e provavelmente no mundo vegetal.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Schisandra chinensis (Turcz.) Baill.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Hepatite viral (adjuvante)","populacao":"Pesquisa chinesa e russa"},{"evidencia":"Moderada","indicacao":"Fadiga e desempenho atlético","populacao":"Panossian & Wikman (2009)"},{"evidencia":"Moderada","indicacao":"Estresse adaptogênico","populacao":"Tradição soviética + pesquisa moderna"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Adaptógeno (modulação HPA e cortisol)","Hepatoprotetor potente (lignanas — proteção hepática documentada em hepatite)","Nootrópico (melhora de reflexos e concentração — pesquisa russa extensiva)","Antioxidante","Imunomodulador","Antiestressante","Afrodisíaco (uso tradicional chinês)","Componentes ativos:","Indicações com evidência:","Contraindicações: Gestação — levemente uterotônico. Uso de medicamentos metabolizados por CYP (indutor moderado). Epilepsia — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"LIGNANAS (esquizandrina, gomisin, deoxi-esquizandrina)","texto":"Hepatoprotetor, adaptogênico, nootrópico"},{"label":"ÁCIDOS ORGÂNICOS (cítrico, málico, tartárico)","texto":"Acidez característica, digestivo"},{"label":"VITAMINA C","texto":"Antioxidante"},{"label":"ÓLEOS ESSENCIAIS","texto":"Aromático, antimicrobiano"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"ea4da73c-d96b-4654-b259-07f417ade05a","slug":"canela-de-ema","herb_id":null,"herb_latin_name":"Eryngium ebracteatum","schema_version":"1.1","ficha":{"slug":"canela-de-ema","cultura":{"brasil":"A canela-de-ema é uma das ervas dos campos sulinos que encarna a farmácia viva dos pampas gaúchos — junto com a macela, o alecrim-de-campanha e a carqueja, forma o núcleo da fitoterapia popular dos campos abertos do Rio Grande do Sul. Usada por curandeiros gaúchos e uruguaios para \"limpar o sangue\" e tratar \"pedra no rim\" — usos que refletem o mecanismo diurético-depurativo documentado.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples coberta. Decocção de raiz para uso mais concentrado.","quantidade":"3–5 g de partes aéreas secas para 250 ml.","reinfusoes":"","combina_com":"Cavalinha · Solidago · Rompe-pedra (blends diuréticos)","melhor_momento":"Manhã e tarde (diurético — evitar à noite).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"O diurético dos campos — herbácea espinhosa dos pampas sulinos com tradição gaúcha de depuração renal e sanguínea que a ciência começa a confirmar.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Floração: outubro–fevereiro","status_anvisa":"Uso popular reconhecido","eixo_botanico_tpc":"Fitoterápico tradicional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Canela-de-Emã","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Canela-de-ema · caraguatá-miúdo · congonha-do-campo","Eryngo (inglês — gênero) · cardo corredor (espanhol)","ATENÇÃO: \"canela-de-ema\" pode designar diversas espécies de Eryngium no Brasil — confirmar espécie por região."],"parte_usada":"Partes aéreas secas; raiz (uso mais concentrado).","tipo_botanico":"Fitoterápico diurético / depurativo","nome_cientifico":"Eryngium ebracteatum Lam. / Eryngium paniculatum Cav. & Dombey ex F.Delaroche","familia_botanica":"Apiaceae (família da cenoura, do funcho, do coentro)"},"caracterizacao":{"aroma":"Campo seco do pampa, herbáceo suave, leve resinoso.","notas":"","intensidade":"2/5 — suave, de uso cotidiano possível.","cor_da_infusao":"Verde-amarelado a âmbar claro. #C0B84A","bioma_de_origem":"Pampas — campos sulinos do RS, SC, PR; também campos da Argentina e Uruguai.","sabor_dominante":"Levemente amargo-herbáceo, levemente adstringente, terroso sutil.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Eryngium ebracteatum Lam. / Eryngium paniculatum Cav. & Dombey ex F.Delaroche","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Diurético","Depurativo (estimula eliminação de toxinas via renal)","Anti-inflamatório leve","Antirreumático (associado ao diurético)","Expectorante leve","Componentes ativos:","Contraindicações: Edema cardíaco ou renal grave — cautela. Gestação — dados insuficientes."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"SAPONINAS","texto":"Diurético, expectorante"},{"label":"FLAVONÓIDES (luteolina, apigenina)","texto":"Anti-inflamatório, antioxidante"},{"label":"FENILPROPANÓIDES","texto":"Anti-inflamatório"},{"label":"ÓLEOS ESSENCIAIS","texto":"Aromático, diurético"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"7837f65f-b7fc-497a-9f04-b680823f19ec","slug":"alecrim-de-campanha","herb_id":null,"herb_latin_name":"Baccharis dracunculifolia","schema_version":"1.1","ficha":{"slug":"alecrim-de-campanha","cultura":{"brasil":"O alecrim-de-campanha é a planta brasileira que mais claramente ilustra a sinergia entre fitoterapia e apiterapia — a erva e a própolis são o mesmo produto em formas diferentes, mediadas pela abelha. Essa história de co-evolução entre planta, inseto e medicina humana é uma das mais belas do catálogo.  O Japão é o maior comprador de própolis verde brasileira do mundo — e grande parte da pesquisa sobre artepilina C e Baccharis dracunculifolia foi publicada por universidades japonesas (Univ. Gifu, Meijo) que identificaram o potencial imunomodulador. Brasil produziu, Japão pesquisou, Europa comprou. Ciclo clássico de conhecimento botânico brasileiro.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta.","quantidade":"2–3 g de ramos finos secos para 250 ml.","reinfusoes":"","combina_com":"Própolis (amplifica) · Mel · Tomilho · Gengibre (blends imunidade)","melhor_momento":"Manhã (antioxidante/imunidade) ou qualquer hora.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (resinas voláteis — não ferver)."},"tagline":"O alecrim do cerrado e dos pampas — fonte das própolis verde brasileira, antioxidante e anti-inflamatório com uma das histórias de sinergia abelha-planta mais fascinantes da botânica brasileira.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Floração: outubro–fevereiro (pico de coleta pelas abelhas)","status_anvisa":"Uso tradicional reconhecido. Própolis verde: regulada como produto apícola.","eixo_botanico_tpc":"Phyto-ANVISA + Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Alecrim-de-Campanha","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Alecrim-de-campanha · alecrim-do-campo · vassoura-de-botão · carquejinha (confusão)","Rosemary bush (inglês informal) — pelo aroma similar ao alecrim europeu"],"parte_usada":"Partes aéreas (folhas e ramos finos), secas.","tipo_botanico":"Fitoterápico anti-inflamatório / antioxidante / matéria-prima de própolis verde","nome_cientifico":"Baccharis dracunculifolia DC.","familia_botanica":"Asteraceae"},"caracterizacao":{"aroma":"Própolis verde, resinoso-balsâmico intenso, herbáceo quente, leve eucalipto. Aroma extraordinariamente próximo da própolis verde brasileira — porque é sua fonte.","notas":"","intensidade":"3/5 — aromático intenso.","cor_da_infusao":"Verde-dourado a âmbar-esverdeado. #A0A830","bioma_de_origem":"Pampas, Cerrado, Mata Atlântica — amplamente distribuído; RS, SC, PR, SP, MG, GO.","sabor_dominante":"Levemente amargo-resinoso, aromático-herbáceo, com nota de própolis verde. Diferente do alecrim europeu mas evocativo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Baccharis dracunculifolia DC.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Anti-inflamatório potente (artepilina C)","Antioxidante de alta capacidade","Antimicrobiano","Imunomodulador","Antitumoral (artepilina C — pesquisa extensiva japonesa)","Antifúngico","Componentes ativos:","CONEXÃO PRÓPOLIS VERDE:","Contraindicações: Alergia à própolis ou ao gênero Baccharis. Alergia à família Asteraceae."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"ARTEPILINA C (ácido 3,5-diprenyl-4-hydroxycinnamic)","texto":"Anti-inflamatório, antitumoral, imunomodulador — composto-chave da própolis verde"},{"label":"ÁCIDO P-CUMÁRICO","texto":"Antioxidante, antimicrobiano"},{"label":"DITERPENOS (clerodanos)","texto":"Anti-inflamatório"},{"label":"FLAVONÓIDES","texto":"Antioxidante"},{"label":"RESINAS TERPÊNICAS","texto":"Antimicrobiano (coletadas pelas abelhas)"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"713f12e0-bf9a-44fc-8c0c-905afeba0639","slug":"poejo","herb_id":null,"herb_latin_name":"Mentha pulegium","schema_version":"1.1","ficha":{"slug":"poejo","cultura":{"brasil":"","historia":"O poejo é uma das ervas mais antigas da Europa mediterrânea — citado por Plínio, Dioscórides e Hildegarda. Na tradição europeia, era o abortivo herbal de uso popular — seu uso para \"provocar a regra\" (emenagogo) atravessou séculos de medicina popular feminina, frequentemente sem que as mulheres que o usavam soubessem o risco de hepatotoxicidade.  No Sul do Brasil, chegou com imigrantes italianos e portugueses e foi incorporado à medicina de quintal como \"poejo para cólica\" — uso digestivo que é distinto e mais seguro que o uso emenagogo.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"1–2 g de folhas secas para 250 ml (dose baixa — respeitar limite).","reinfusoes":"","combina_com":"","melhor_momento":"Pós-refeições (digestivo) ou em dismenorreia.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (pulegona volátil — não ferver)."},"tagline":"A hortelã dos nervos — aromática europeia naturalizada nos pampas com ação antiespasmódica documentada e reputação de emenagogas que merece clareza científica.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — uso externo somente (repelente). Uso interno: não recomendado.","status_fda":"","sazonalidade":"Partes aéreas: floração (primavera-verão sulino)","status_anvisa":"Não monografado. Óleo essencial: proibido para uso interno.","eixo_botanico_tpc":"Funcional global / uso tradicional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Poejo","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Poejo · poejo-da-europa · mentastro · erva-de-são-lourenço","Pennyroyal (inglês) · Pouliot (francês) · Poleo (espanhol)"],"parte_usada":"Partes aéreas frescas ou secas.","tipo_botanico":"Fitoterápico aromático / antiespasmódico / emenagogo","nome_cientifico":"Mentha pulegium L.","familia_botanica":"Lamiaceae (família da hortelã, do alecrim, da sálvia)"},"caracterizacao":{"aroma":"Menta pungente-quente, pulegona característica — mais agreste e intenso que qualquer outra menta.","notas":"","intensidade":"4/5 — aroma e sabor dominantes.","cor_da_infusao":"Verde-pálido a âmbar esverdeado. #B0C850","bioma_de_origem":"","sabor_dominante":"Mentolado intenso, mais picante e menos fresco que a hortelã-pimenta, levemente amargo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Mentha pulegium L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antiespasmódico digestivo","Emenagogo (estimula menstruação)","Carminativo","Antimicrobiano","Expectorante leve","Repelente de insetos (uso externo — pulegona)","Componentes ativos:","⚠️ ATENÇÃO — PULEGONA:","Contraindicações:","Gestação — contraindicado (abortivo comprovado em doses moderadas)","Lactação — evitar","Crianças — contraindicado","Hepatopatias e nefropatias — contraindicado","Óleo essencial interno — contraindicado em qualquer dose"],"contraindicacoes":["Gestação — contraindicado (abortivo comprovado em doses moderadas)","Lactação — evitar","Crianças — contraindicado","Hepatopatias e nefropatias — contraindicado","Óleo essencial interno — contraindicado em qualquer dose"],"efeitos_adversos":"","componentes_ativos":[{"label":"PULEGONA","texto":"60–90% do óleo essencial — Antiespasmódico, emenagogo, hepatotóxico em dose alta"},{"label":"ISOMENTONA","texto":"Presente — Aromático, carminativo"},{"label":"MENTOL","texto":"Traços — Frescor, antisséptico"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"2c03362d-0c89-453a-8101-f18292f1031a","slug":"espinheira-gaucha","herb_id":null,"herb_latin_name":"Maytenus dasyclada","schema_version":"1.1","ficha":{"slug":"espinheira-gaucha","cultura":{"brasil":"A espinheira-gaúcha é o equivalente regional da espinheira-santa (M. ilicifolia) para os gaúchos do Rio Grande do Sul — endêmica dos campos e bosques nativos do estado, usada pela medicina popular gaúcha para \"azia\" e \"gastrite\" com a mesma lógica da espinheira-santa mais famosa. A diferença entre as duas espécies é geograficamente marcada: M. ilicifolia no Cerrado e Mata Atlântica interior; M. dasyclada nos pampas sulinos. Para o Ervatório, a narrativa da especificidade regional é o diferencial.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta. Idêntico à espinheira-santa.","quantidade":"3–5 g/250 ml","reinfusoes":"","combina_com":"Camomila · Funcho · Melissa (blends digestivos)","melhor_momento":"30 min antes das refeições (gastroprotetor).","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 5–10 min coberto | Quantidade: 3–5 g/250 ml"},"tagline":"A prima sulina da espinheira-santa — gastroprotetor endêmico dos campos do Rio Grande do Sul com ação documentada e identidade regional forte.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo","status_anvisa":"Uso tradicional reconhecido — mesmo grupo de Maytenus monografados","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Espinheira-Gaúcha","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Espinheira-gaúcha · cancorosa-gaúcha · espinheira-do-sul","Relacionada à espinheira-santa (M. ilicifolia) — mesmo gênero, química similar"],"parte_usada":"Folhas secas.","tipo_botanico":"Fitoterápico gastroprotetor / antiulceroso","nome_cientifico":"Maytenus dasyclada Mart.","familia_botanica":"Celastraceae"},"caracterizacao":{"aroma":"Erval fresco, folha verde amadeirada.","notas":"","intensidade":"2/5 — suave, uso cotidiano possível.","cor_da_infusao":"Verde-amarelado a âmbar claro. #B8C460","bioma_de_origem":"Pampas e Mata Atlântica interior — endêmica do RS, ocorrência em SC e PR.","sabor_dominante":"Amargo leve, herbáceo-verde, levemente adstringente. Perfil similar à espinheira-santa (M. ilicifolia) mas levemente mais amargo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Maytenus dasyclada Mart.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Gastroprotetor (proteção da mucosa gástrica)","Antiulceroso","Analgésico gástrico","Anti-inflamatório digestivo","Componentes ativos:","Contraindicações: Gestação — contraindicada (mesmas precauções que M. ilicifolia). Lactação — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"FRIEDELINA (triterpeno)","texto":"Antiulceroso, analgésico"},{"label":"MAITEANSINAS","texto":"Anti-inflamatório, antitumoral (experimental)"},{"label":"TANINOS","texto":"Gastroprotetor, adstringente"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"e0ec73f3-1fe7-4635-a858-749b9dc4aabf","slug":"sete-sangrias","herb_id":null,"herb_latin_name":"Cuphea carthagenensis","schema_version":"1.1","ficha":{"slug":"sete-sangrias","cultura":{"brasil":"A sete-sangrias ocupa o mesmo nicho que a espinheira-santa para o estômago — mas para a pressão arterial. É o \"chá pra abaixar a pressão\" do interior nordestino e sulista. O nome \"sete-sangrias\" refere-se ao uso popular histórico de sangrias terapêuticas — a planta substitui a sangria como forma de \"aliviar a pressão\". Metáfora que revela mais sobre a história da medicina popular do que qualquer dado farmacológico.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples.","quantidade":"3–5 g/250 ml","reinfusoes":"","combina_com":"Maracujá · Melissa · Capim-limão (blends cardio-calmantes)","melhor_momento":"Manhã e tarde (antihipertensivo — monitorar PA).","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 5–8 min | Quantidade: 3–5 g/250 ml"},"tagline":"A antihipertensiva do campo — erva dos pastos que cuida do coração com tradição nordestina e sulista e mecanismo vasodilatador comprovado.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Partes aéreas: colheita no período vegetativo","status_anvisa":"Uso tradicional reconhecido. RENISUS incluída.","eixo_botanico_tpc":"Phyto-ANVISA","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Sete-Sangrias","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Sete-sangrias · sete-sangues · coerana","Guanxuma (confusão regional)"],"parte_usada":"Partes aéreas (folhas e ramos finos), secas.","tipo_botanico":"Fitoterápico antihipertensivo / diurético","nome_cientifico":"Cuphea carthagenensis (Jacq.) J.F.Macbr.","familia_botanica":"Lythraceae (família da romã, da mangava-brava)"},"caracterizacao":{"aroma":"Campo aberto, herbáceo simples, feno.","notas":"","intensidade":"2/5 — suave, uso cotidiano possível.","cor_da_infusao":"Verde-amarelado a âmbar. #C0B840","bioma_de_origem":"Pampas, Mata Atlântica, Caatinga — ruderal de distribuição ampla.","sabor_dominante":"Amargo-herbáceo suave, levemente adstringente, vegetal.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Cuphea carthagenensis (Jacq.) J.F.Macbr.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antihipertensivo (vasodilatação periférica)","Diurético","Hipoglicemiante leve","Anti-inflamatório","Antioxidante","Componentes ativos:","Contraindicações: Hipotensão — potencialização. Uso concomitante com anti-hipertensivos — monitorar. Gestação — cautela."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"FLAVONÓIDES (vitexina, isovitexina)","texto":"Vasodilatador, antihipertensivo"},{"label":"TANINOS","texto":"Adstringente, antioxidante"},{"label":"SAPONINAS","texto":"Diurético"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"f7ed3ad4-b4e9-4109-bc5c-8c09b5821d30","slug":"bocaiuva","herb_id":null,"herb_latin_name":"Acrocomia aculeata","schema_version":"1.1","ficha":{"slug":"bocaiuva","cultura":{"brasil":"A bocaiuva é o fruto-símbolo do Mato Grosso do Sul — objeto de festival anual em Miranda (MS) e ingrediente de pratos típicos pantaneiros (sorvete, pamonha, cupcake de bocaiuva). É o \"açaí do Pantanal\" — com potencial de exportação como superalimento ainda quase inexplorado.  A EMBRAPA e universidades do MS investem na industrialização da bocaiuva como alternativa à macaúba (espécie irmã) no mercado de biocombustíveis e alimentos funcionais. O desafio é o mesmo de outros produtos da bioeconomia brasileira: transformar matéria-prima extrativista em produto de valor agregado com identidade de origem.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A palmeira nutritiva do pantanal — fruto com perfil lipídico excepcional, antioxidante máximo entre as palmeiras brasileiras e potencial de exportação como \"superalimento pantaneiro\" ainda inexplorado.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutificação: junho–setembro (Pantanal/MS)","status_anvisa":"Alimento. Óleo: em processo de regulamentação como ingrediente.","eixo_botanico_tpc":"Alimento funcional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Bocaiuva","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Bocaiuva · bocaiúva · macaúba · macaíba (variantes regionais)","Macaw palm (inglês) · Mocaya (espanhol sul-americano)","Mbocayá (guarani — \"palmeira espinhenta\")"],"parte_usada":"Polpa do fruto (óleo e farinha); amêndoa (óleo de amendoa de bocaiuva); palmito (alimentar).","tipo_botanico":"Alimento funcional / óleo nutritivo","nome_cientifico":"Acrocomia aculeata (Jacq.) Lodd. ex Mart.","familia_botanica":"Arecaceae (palmeiras)"},"caracterizacao":{"aroma":"Coco tropical, palmeira, levemente frutado.","notas":"","intensidade":"3/5 — sabor agradável e marcante.","cor_da_infusao":"","bioma_de_origem":"Pantanal e Cerrado — MT, MS, GO, MG, SP; toda a América tropical.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Acrocomia aculeata (Jacq.) Lodd. ex Mart.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Antioxidante potente (carotenóides — superior ao dendê)","Nutritivo excepcional (perfil lipídico, proteína, fibra)","Cardioprotetor (ácido oleico e laurico)","Energético de baixo índice glicêmico","Anti-inflamatório (ácidos graxos)","Componentes ativos:","Contraindicações: Sem contraindicações relevantes. Moderação em dietas com restrição de gorduras saturadas (ácido láurico)."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"BETA-CAROTENO (óleo de polpa)","texto":"Superior ao dendê — Antioxidante, pró-vitamina A"},{"label":"ÁCIDO OLEICO (C18:1)","texto":"50–60% (óleo amêndoa) — Cardioprotetor"},{"label":"ÁCIDO LÁURICO (C12:0)","texto":"40–50% (óleo amêndoa) — Antimicrobiano, energético"},{"label":"TOCOFERÓIS (vitamina E)","texto":"Altos — Antioxidante"},{"label":"PROTEÍNA","texto":"11–13% (farinha) — Nutritivo"},{"label":"FIBRAS","texto":"15–20% (farinha) — Prebiótico, saciedade"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"20c5cb67-c58e-4598-a52e-2047e0324d64","slug":"raiz-de-bugre","herb_id":null,"herb_latin_name":"Cordia ecalyculata","schema_version":"1.1","ficha":{"slug":"raiz-de-bugre","cultura":{"brasil":"A raiz-de-bugre (mais conhecida pelo nome comercial \"chá-de-bugre\") é um dos fitoterápicos emagrecedores mais vendidos em farmácias de manipulação e ervanários brasileiros — produto que navega entre a tradição popular do pantanal e a indústria de suplementos para perda de peso. Sua eficácia emagrecedora direta é controversa; a ação diurética é confirmada. O marketing de \"queimador de gordura natural\" extrapola a evidência disponível.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples.","quantidade":"3–5 g/250 ml","reinfusoes":"","combina_com":"Guaraná · Chá-verde · Hibisco (blends termogênicos/emagrecedores)","melhor_momento":"Manhã e tarde (diurético/termogênico — evitar à noite).","tempo_de_infusao":"","temperatura_ideal":"90 °C | Tempo: 8 min | Quantidade: 3–5 g/250 ml"},"tagline":"O diurético-emagrecedor do pantanal — termogênico natural com tradição popular para controle de peso e ação diurética documentada.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Folhas disponíveis o ano todo","status_anvisa":"Uso tradicional reconhecido. Atenção para claims de emagrecimento não validados.","eixo_botanico_tpc":"Fitoterápico tradicional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Raiz-de-Bugre","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Raiz-de-bugre · café-do-mato · louro-mole","Chá-de-bugre (nome comercial difundido)"],"parte_usada":"Folhas secas.","tipo_botanico":"Fitoterápico diurético / coadjuvante de emagrecimento","nome_cientifico":"Cordia ecalyculata Vell.","familia_botanica":"Boraginaceae (família da borragem, do confrei)"},"caracterizacao":{"aroma":"Herbáceo suave, levemente tostado, feno.","notas":"","intensidade":"2/5 — suave, uso cotidiano fácil.","cor_da_infusao":"Marrom-claro a âmbar. #C09050","bioma_de_origem":"Pantanal, Cerrado, Mata Atlântica — MT, MS, GO, MG, SP, PR.","sabor_dominante":"Levemente amargo-herbáceo, discreto, vegetal. Bastante palatável — lembra levemente o café muito fraco.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Cordia ecalyculata Vell.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Diurético","Termogênico leve (allanthoína + metilxantinas traços)","Supressor de apetite leve (anedótico — mecanismo não elucidado)","Anti-inflamatório","Antioxidante","Componentes ativos:","Contraindicações: Edema cardíaco ou renal — cautela. Gestação — diurético, evitar. Hipertensão — monitorar."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"ALANTOÍNA","texto":"Cicatrizante, diurético leve"},{"label":"METILXANTINAS (traços)","texto":"Termogênico, diurético"},{"label":"TANINOS","texto":"Adstringente, antioxidante"},{"label":"FLAVONÓIDES","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"a0732f07-faee-4972-9a21-c2261ff3d8ae","slug":"velame-pantaneiro","herb_id":null,"herb_latin_name":"Croton urucurana","schema_version":"1.1","ficha":{"slug":"velame-pantaneiro","cultura":{"brasil":"O velame-pantaneiro é o sangue-de-dragão brasileiro — menos famoso internacionalmente que o Croton lechleri peruano (que domina o mercado global de \"dragon's blood\"), mas com química similar e disponibilidade muito maior no Brasil Central. Comunidades ribeirinhas do Pantanal usam o látex vermelho para cicatrizar feridas de pesca, cortes de palheta de cana e úlceras de pés em terrenos alagados — uso que o Ervatório pode documentar e valorizar como conhecimento territorial único.","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O sangue-de-dragão brasileiro — cicatrizante poderoso do pantanal com látex vermelho que imita e supera em alguns aspectos a resina sul-americana mais famosa do mundo.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Látex coletado o ano todo; pico após chuvas","status_anvisa":"Uso popular reconhecido","eixo_botanico_tpc":"Fitoterápico tradicional","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Velame-Pantaneiro","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Velame-pantaneiro · urucurana · sangue-de-drago (regional)","RELAÇÃO: análogo funcional ao sangue-de-dragão amazônico (Croton lechleri) e ao peruano (Croton draconoides) — mesma família, química similar."],"parte_usada":"Látex do caule (resina vermelha — \"sangue-de-dragão brasileiro\"); casca; folhas.","tipo_botanico":"Fitoterápico cicatrizante / anti-inflamatório / antiviral","nome_cientifico":"Croton urucurana Baill.","familia_botanica":"Euphorbiaceae (família da mamona, da mandioca)"},"caracterizacao":{"aroma":"","notas":"","intensidade":"5/5 — medicinal absoluto.","cor_da_infusao":"","bioma_de_origem":"Pantanal e Cerrado — beira de rios e matas de galeria; MT, MS, GO, SP, MG.","sabor_dominante":"","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Croton urucurana Baill.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Cicatrizante acelerador de epitelização","Anti-inflamatório tópico","Antiviral","Antimicrobiano","Adstringente hemostático","Componentes ativos:","Contraindicações: Uso interno em doses altas — evitar (látex de Croton pode ser irritante de mucosa gástrica). Gestação — evitar uso interno. Uso tópico: verificar alergia prévia."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"TASPINA (alcaloide)","texto":"Cicatrizante — estimula migração de fibroblastos"},{"label":"SP-303 (proantocianidina)","texto":"Antiviral (VSR, rotavírus, influenza)"},{"label":"CATEQUINAS OLIGOMÉRICAS","texto":"Antioxidante, antimicrobiano"},{"label":"RESINAS TERPÊNICAS","texto":"Cicatrizante, adstringente"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"db79b604-5a26-4ef4-a644-cc83f1120dc0","slug":"gengibre","herb_id":null,"herb_latin_name":"Zingiber officinale","schema_version":"1.1","ficha":{"slug":"gengibre","cultura":{"brasil":"O Brasil cultiva gengibre desde o período colonial — introduzido pelos portugueses no séc. XVI. Hoje, o Espírito Santo é o maior produtor nacional (especialmente municípios de Domingos Martins e Santa Maria de Jetibá). O gengibre capixaba tem qualidade reconhecida no mercado nacional e potencial de exportação para a Europa como ingrediente premium.","historia":"O gengibre é a planta medicinal com maior presença simultânea em sistemas médicos distintos: Ayurveda (vishvabheshaja — \"universal medicine\"), Medicina Tradicional Chinesa (sheng jiang — fresco / gan jiang — seco), Medicina Unani, Medicina Greco-romana (Dioscórides), Medicina Medieval Europeia (Hildegarda). Não há civilização com tradição herbalista que não tenha incorporado o gengibre.  O comércio de gengibre foi, junto com a pimenta-do-reino, um dos motores econômicos que financiou as navegações europeias. Marco Polo descreveu regiões produtoras de gengibre no sudeste asiático como destino prioritário de rotas comerciais.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Limão · Mel · Cúrcuma · Canela · Cardamomo · Pimenta-rosa · Capim-limão · Hibisco — gengibre combina com tudo.","melhor_momento":"Manhã (digestivo ativador), pós-refeições (antiemético), pré-exercício (anti-inflamatório/termogênico).","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O rei dos digestivos — a raiz mais estudada do mundo, presente em todas as tradições medicinais do planeta, com evidência clínica que rivaliza com fármacos modernos em náusea e anti-inflamação.","receitas":[{"nome":"Antiflatulência Clássica","slug":"antiflatulencia-classica","proposito":null},{"nome":"Sistema Imune","slug":"sistema-imune","proposito":null},{"nome":"Circulação nas Pernas","slug":"circulacao-nas-pernas","proposito":null},{"nome":"Infusão do Atleta","slug":"infusao-do-atleta","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use para náusea.","status_fda":"GRAS para uso alimentar","sazonalidade":"Colheita: 8–10 meses após plantio; ES: novembro–março","status_anvisa":"Monografia oficial. Indicações: náusea, digestivo, anti-inflamatório.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Gengibre","usos_topicos":{"evidencia":"","aplicacoes":["Compressas quentes para articulações: Decocção concentrada em compressa morna — melhora circulação local e reduz dor articular.","Massagem anti-inflamatória: Óleo de gengibre (infusão em azeite) — massagem em musculatura dolorida."],"contraindicacoes":""},"identificacao":{"sinonimos":["Gengibre · ginger (inglês) · gingembre (francês) · ingwer (alemão) · jengibre (espanhol)","Adrak (hindi — fresco) · sonth (hindi — seco)"],"parte_usada":"Rizoma fresco ou seco.","tipo_botanico":"Fitoterápico antiemético / anti-inflamatório / digestivo","nome_cientifico":"Zingiber officinale Roscoe","familia_botanica":"Zingiberaceae (família da cúrcuma, do cardamomo)"},"caracterizacao":{"aroma":"Cítrico-picante fresco (fresco) / amadeirado-quente-especiado (seco). Um dos aromas mais reconhecíveis do mundo.","notas":"","intensidade":"4/5 — presença dominante. Modula todos os blends.","cor_da_infusao":"Amarelo-ouro pálido a âmbar. #D4A030","bioma_de_origem":"","sabor_dominante":"Picante-quente intenso (gingeróis), levemente doce, cítrico, pimentado. Perfil expansivo e aquecedor. Fresco: picante fresco-cítrico. Seco: picante quente-defumado (shogaóis dominam).","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Zingiber officinale Roscoe","perfil_sensorial":{"tatil":"","gustativo":[{"dimensao":"Doce","observacao":"Presente como nota de fundo","intensidade":"1/3"},{"dimensao":"Amargo","observacao":"Discreto","intensidade":"1/3"},{"dimensao":"Umami","observacao":"Notas terrosas profundas","intensidade":"1/3"},{"dimensao":"Azedo","observacao":"Ausente (leve cítrico em fresco)","intensidade":"0/3"},{"dimensao":"Picante (TRPV1)","observacao":"Gingeróis — receptor de calor","intensidade":"Alta"},{"dimensao":"Adstringência","observacao":"Traços","intensidade":"Baixa"}],"trigeminal":[{"ativacao":"Alta","molecula":"Gingeróis — queimação quente","receptor":"TRPV1 (calor)"},{"ativacao":"Muito leve traço","molecula":"Zingerone","receptor":"TRPM8 (frescor)"},{"ativacao":"Baixa","molecula":"Resinas","receptor":"Adstringência"}],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte","indicacao":"Náusea e vômito da gravidez","populacao":"Cochrane Review 2014"},{"evidencia":"Forte","indicacao":"Náusea pós-cirúrgica","populacao":"Múltiplos ECR"},{"evidencia":"Forte","indicacao":"Enjoo de movimento","populacao":"Ernst & Pittler, 2000"},{"evidencia":"Moderada","indicacao":"Dor na osteoartrite joelho","populacao":"Altman & Marcussen, 2001"},{"evidencia":"Moderada","indicacao":"Dismenorreia","populacao":"Shahrami et al., 2015"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Antiemético (náusea e vômito de qualquer etiologia)","Anti-inflamatório (inibição de COX-1, COX-2 e LOX — duplo)","Termogênico","Digestivo (estimula motilidade e secreções)","Analgésico","Antioxidante (ORAC elevado)","Imunomodulador","Antidiabético leve (sensibilizador de insulina)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Cálculo biliar — estimula bile; pode precipitar cólica","Anticoagulados — inibição plaquetária (moderada)","Pré-cirurgia — suspender 2 semanas antes"],"contraindicacoes":["Cálculo biliar — estimula bile; pode precipitar cólica","Anticoagulados — inibição plaquetária (moderada)","Pré-cirurgia — suspender 2 semanas antes"],"efeitos_adversos":"","componentes_ativos":[{"label":"GINGERÓIS (6-, 8-, 10-gingerol)","texto":"Anti-inflamatório, antiemético, termogênico, TRPV1"},{"label":"SHOGAÓIS (forma seca/aquecida)","texto":"Mais potentes que gingeróis — anti-inflamatório, antiemético"},{"label":"PARADOL","texto":"Termogênico, antioxidante"},{"label":"ZINGERONE","texto":"Anti-inflamatório suave, aromático"},{"label":"ÓLEOS ESSENCIAIS (zingibereno, bisaboleno)","texto":"Aromático, antimicrobiano"},{"label":"RESINAS (oleo-resina)","texto":"Anti-inflamatório"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"791185f1-9ce7-45c2-a7b9-f45531c63a05","slug":"curcuma","herb_id":null,"herb_latin_name":"Curcuma longa","schema_version":"1.1","ficha":{"slug":"curcuma","cultura":{"brasil":"","historia":"A cúrcuma é simultaneamente espécia, corante, cosmético, remédio e símbolo espiritual — uma das poucas plantas que as 5 maiores civilizações do mundo (indiana, chinesa, árabe, europeia medieval, brasileira popular) incorporaram em seus sistemas de significados sem reserva.  Na Índia, a pasta de cúrcuma no rosto da noiva antes do casamento é ritual de proteção e beleza (haldi ceremony) — uma das tradições nupciais mais antigas do mundo. Na medicina ayurvédica, a cúrcuma é \"varinha de condão\" herbal — usada para quase tudo.  No mundo ocidental, a \"curcuma latte\" e o \"golden milk\" tornaram-se fenômenos de wellness na última década — impulsionando pesquisa que confirmou parcialmente o que a Ayurveda sabia há 5.000 anos.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Gengibre · Pimenta-preta · Canela · Mel · Leite de coco (golden milk) · Capim-limão (chá anti-inflamatório)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O ouro anti-inflamatório da Ásia — a planta mais estudada da medicina integrativa moderna, com mais de 10.000 publicações científicas e curcumina como um dos princípios ativos mais pesquisados do mundo.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use","status_fda":"GRAS para uso alimentar","sazonalidade":"Colheita: 8–9 meses após plantio","status_anvisa":"Uso reconhecido. Indicações: digestivo, anti-inflamatório.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Cúrcuma","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Cúrcuma · açafrão-da-terra · açafrão-da-índia · gengibre-amarelo","Turmeric (inglês) · Curcuma (francês/espanhol) · Kurkuma (alemão)","Haldi (hindi) · Haridra (sânscrito — \"a amarela\")"],"parte_usada":"Rizoma seco e pulverizado (cúrcuma em pó); rizoma fresco.","tipo_botanico":"Fitoterápico anti-inflamatório / hepatoprotetor / antioxidante","nome_cientifico":"Curcuma longa L.","familia_botanica":"Zingiberaceae"},"caracterizacao":{"aroma":"Terroso-quente, amadeirado-apimentado, leve cítrico-floral, característico e inconfundível.","notas":"","intensidade":"3/5 — sabor moderado, cor espetacular.","cor_da_infusao":"Amarelo-ouro intenso a laranja-dourado. #E8A820 — pigmento de amarelo mais intenso do catálogo.","bioma_de_origem":"","sabor_dominante":"Terroso-amargo suave, levemente picante-apimentado, nota de mostarda, fundo de madeira. A curcumina é pouco solúvel em água — infusão aquosa extrai menos curcumina que leite ou óleo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Curcuma longa L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Osteoartrite (dor articular)","populacao":"Belcaro et al., 2010"},{"evidencia":"Moderada","indicacao":"Colite ulcerativa (manutenção)","populacao":"Hanai et al., 2006"},{"evidencia":"Moderada","indicacao":"Depressão (adjuvante)","populacao":"Sanmukhani et al., 2014"},{"evidencia":"Moderada","indicacao":"Síndrome metabólica","populacao":"Múltiplos ECR"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Anti-inflamatório potente (inibição NF-κB, COX-2, TNF-alfa)","Antioxidante de alta capacidade","Hepatoprotetor (proteção e regeneração hepática)","Neuroprotetor (curcumina atravessa barreira hematoencefálica)","Antidepressivo (pesquisa crescente — modulação serotonina/dopamina)","Antidiabético (sensibilizador de insulina)","Antitumoral (pesquisa extensiva — múltiplas vias)","Gastroprotetor (antiulceroso leve)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Cálculo biliar — colagogo intenso; pode precipitar cólica","Anticoagulados — cautela (inibição plaquetária)","Pré-cirurgia — suspender 2 semanas antes","Gestação em doses altas — emenagogo leve (uso culinário: seguro)"],"contraindicacoes":["Cálculo biliar — colagogo intenso; pode precipitar cólica","Anticoagulados — cautela (inibição plaquetária)","Pré-cirurgia — suspender 2 semanas antes","Gestação em doses altas — emenagogo leve (uso culinário: seguro)"],"efeitos_adversos":"","componentes_ativos":[{"label":"CURCUMINA","texto":"2–5% do rizoma seco — Anti-inflamatório máximo, antioxidante, antitumoral"},{"label":"DEMETOXICURCUMINA","texto":"Presente — Anti-inflamatório"},{"label":"BISDEMETOXICURCUMINA","texto":"Presente — Anti-inflamatório"},{"label":"AR-TURMERONA (óleo essencial)","texto":"Alto — Antimicrobiano, neuroprotetor"},{"label":"TURMERONA ALFA E BETA","texto":"Presentes — Anti-inflamatório, neuroprotetor"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"25befbbd-48d9-4789-8936-90460e55866a","slug":"melissa","herb_id":null,"herb_latin_name":"Melissa officinalis","schema_version":"1.1","ficha":{"slug":"melissa","cultura":{"brasil":"A confusão entre melissa e Lippia alba (erva-cidreira brasileira) é provavelmente o equívoco botânico mais comum na fitoterapia popular brasileira. São plantas distintas, com química diferente, de famílias diferentes — mas ambas têm aroma cítrico-limão e uso ansiolítico. O Ervatório tem responsabilidade específica de esclarecer essa distinção e apresentar a melissa europeia em seus próprios termos.","historia":"A melissa é a erva dos apicultores — o nome latino \"melissa\" vem do grego para \"abelha\". Apicultores medievais europeus esfregavam melissa nas colmeias para atrair enxames e acalmar as abelhas antes de manejar. Paracelso chamou a melissa de \"elixir da vida\". O licor Carmelite Water (Eau de Mélisse des Carmes), produzido por monges carmelitas desde 1611, foi o primeiro produto farmacêutico comercial a base de melissa — e ainda é vendido na Europa como digestivo.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta, imprescindível.","quantidade":"2–4 g de folhas secas para 250 ml (folhas frescas: 5–8 g).","reinfusoes":"1 possível.","combina_com":"Camomila (clássico absoluto) · Maracujá · Lavanda · Hortelã · Valeriana · Flor de laranjeira · Mel","melhor_momento":"Final de tarde ou noite (ansiolítico/sedativo). Também excelente para uso diurno suave.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (citral e linalol muito voláteis — nunca ferver)."},"tagline":"A erva do coração tranquilo — ansiolítica europeia que chegou ao Brasil como \"erva-cidreira\" e conquistou definitivamente o catálogo mundial de calmantes.","receitas":[{"nome":"Infusão do Sono Pampeano","slug":"infusao-do-sono-pampeano","proposito":null},{"nome":"Infusão da Cólica Menstrual","slug":"infusao-da-colica-menstrual","proposito":null},{"nome":"Gastrite Acalmada","slug":"gastrite-acalmada","proposito":null},{"nome":"Infusão da Tarde do Cerrado","slug":"infusao-da-tarde-do-cerrado","proposito":null},{"nome":"Mente Serena","slug":"mente-serena","proposito":null},{"nome":"Menopausa Equilibrada","slug":"menopausa-equilibrada","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use para insônia e ansiedade.","status_fda":"GRAS para uso alimentar","sazonalidade":"Folhas colhidas antes da floração — primavera/início de verão","status_anvisa":"Monografia oficial. Indicações: ansiolítico, sedativo, antiespasmódico.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Melissa","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Melissa · erva-cidreira-europeia · cidreira-verdadeira · balsamita","Lemon balm (inglês) · Mélisse (francês) · Zitronenmelisse (alemão)","ATENÇÃO: no Brasil \"erva-cidreira\" geralmente refere-se à Lippia alba — melissa (Melissa officinalis) é a erva-cidreira europeia, planta diferente."],"parte_usada":"Folhas frescas ou secas (antes da floração — maior concentração de óleos essenciais).","tipo_botanico":"Fitoterápico ansiolítico / sedativo / antiviral","nome_cientifico":"Melissa officinalis L.","familia_botanica":"Lamiaceae"},"caracterizacao":{"aroma":"Limão-bálsamo fresco e elegante, floral-menta leve, mel cru, erval fresco. Um dos aromas mais agradáveis do catálogo.","notas":"","intensidade":"1–2/5 — infusão suave e agradável. Alta aceitação universal.","cor_da_infusao":"Verde-pálido a amarelo-verdoso. #DCE870","bioma_de_origem":"","sabor_dominante":"Cítrico-limão suave e fresco, levemente herbáceo, discretamente floral, leve amargo gentil.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Melissa officinalis L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Ansiedade e estresse","populacao":"Kennedy et al., 2004"},{"evidencia":"Moderada","indicacao":"Insônia leve","populacao":"Cerny & Schmid, 1999"},{"evidencia":"Forte","indicacao":"Herpes labial (uso tópico)","populacao":"Wölbling & Leonhardt, 1994"},{"evidencia":"Preliminar","indicacao":"Déficit cognitivo leve (Alzheimer early)","populacao":"Akhondzadeh et al., 2003"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico suave (inibição de GABA-transaminase — mantém GABA mais tempo disponível)","Sedativo leve (indutor de sono)","Antiviral (especialmente herpes labial)","Antiespasmódico digestivo","Antidepressivo leve","Cognitivo — melhora de memória em estudos piloto","Componentes ativos:","Indicações com evidência:","Contraindicações: Hipotireoidismo — melissa pode reduzir função tireoidiana levemente em doses altas. Uso concomitante com sedativos — potencialização leve."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"CITRAL (geranial + neral)","texto":"Ansiolítico, antiviral, aromático"},{"label":"ÁCIDO ROSMARÍNICO","texto":"Inibição de enzima de degradação do GABA, antioxidante, antiviral"},{"label":"LINALOL","texto":"Sedativo, ansiolítico"},{"label":"CITRONELAL","texto":"Ansiolítico, aromático"},{"label":"ÁCIDOS HIDROXICINÂMICOS","texto":"Antiviral (herpes), antioxidante"},{"label":"FLAVONÓIDES (luteolina, apigenina)","texto":"Ansiolítico, anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"9b0426df-cb53-4eed-8276-030c3245571c","slug":"hortela-pimenta","herb_id":null,"herb_latin_name":"Mentha ×","schema_version":"1.1","ficha":{"slug":"hortela-pimenta","cultura":{"brasil":"","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"1–2 g de folhas secas para 250 ml (poderoso em aroma).","reinfusoes":"","combina_com":"Camomila (contraste frescor-calma) · Melissa · Limão · Gengibre · Canela · Erva-mate","melhor_momento":"Pós-refeições (digestivo), início de tarde (energizante cognitivo).","tempo_de_infusao":"","temperatura_ideal":"80–85 °C (mentol é extremamente volátil — água mais quente destrói o aroma)."},"tagline":"A menta que dominou o mundo — a mais importante das mentas por hibridação acidental, com ação farmacológica em praticamente todos os sistemas do organismo.","receitas":[{"nome":"Digestivo Pós-Churrasco","slug":"digestivo-pos-churrasco","proposito":null},{"nome":"Tônico Matinal da Mata","slug":"tonico-matinal-da-mata","proposito":null},{"nome":"Emagrecimento Cerradão","slug":"emagrecimento-cerradao","proposito":null},{"nome":"Bronquite do Inverno","slug":"bronquite-do-inverno","proposito":null},{"nome":"Quebra-Pedra do Nordeste","slug":"quebra-pedra-do-nordeste","proposito":null},{"nome":"Infusão da Tarde do Cerrado","slug":"infusao-da-tarde-do-cerrado","proposito":null},{"nome":"Antiflatulência Clássica","slug":"antiflatulencia-classica","proposito":null},{"nome":"Menopausa Equilibrada","slug":"menopausa-equilibrada","proposito":null},{"nome":"Alívio de Alergia Sazonal","slug":"alivio-de-alergia-sazonal","proposito":null},{"nome":"Clareza e Memória","slug":"clareza-e-memoria","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use.","status_fda":"GRAS","sazonalidade":"","status_anvisa":"Monografia oficial.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Hortelã-Pimenta","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Hortelã-pimenta · hortelã-japonesa · menta","Peppermint (inglês) · Menthe poivrée (francês) · Pfefferminze (alemão)"],"parte_usada":"Folhas e sumidades floridas secas.","tipo_botanico":"Fitoterápico digestivo / antiespasmódico / analgésico","nome_cientifico":"Mentha × piperita L. (híbrido natural de M. aquatica × M. spicata)","familia_botanica":"Lamiaceae"},"caracterizacao":{"aroma":"Menta fresca intensa, eucalipto suave, cânfora leve. Inconfundível e universal.","notas":"","intensidade":"4/5 — presença dominante no blend.","cor_da_infusao":"Verde-pálido a amarelo-verdoso. #C8DC78","bioma_de_origem":"","sabor_dominante":"Mentolado intenso, fresco-gélido, levemente adocicado, pimentado leve no fundo. Frescor que persiste por minutos — TRPM8 ativado intensamente.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Mentha × piperita L. (híbrido natural de M. aquatica × M. spicata)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte","indicacao":"Síndrome do intestino irritável","populacao":"Cochrane Review 2014"},{"evidencia":"Forte","indicacao":"Cefaleia tensional (tópico)","populacao":"Göbel et al., 1994"},{"evidencia":"Moderada","indicacao":"Dispepsia funcional","populacao":"Rich et al., 2017"},{"evidencia":"Moderada","indicacao":"Náusea (aromaterapia)","populacao":"Lua & Zakaria, 2012"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Antiespasmódico intestinal (síndrome do intestino irritável)","Carminativo (elimina gases)","Analgésico (cefaleia — uso tópico)","Descongestionante nasal (inalação)","Colerético suave","Antimicrobiano","Cognitivo — alerta e concentração (aromaterapia)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Crianças < 2 anos — mentol pode causar apneia reflexa","Menores de 6 anos — evitar inalação de óleo essencial no rosto","Refluxo gastroesofágico — mentol relaxa esfíncter inferior do esôfago","Cálculo biliar — colagogo, cautela"],"contraindicacoes":["Crianças < 2 anos — mentol pode causar apneia reflexa","Menores de 6 anos — evitar inalação de óleo essencial no rosto","Refluxo gastroesofágico — mentol relaxa esfíncter inferior do esôfago","Cálculo biliar — colagogo, cautela"],"efeitos_adversos":"","componentes_ativos":[{"label":"MENTOL","texto":"35–55% do óleo — TRPM8, analgésico, descongestionante, antiespasmódico"},{"label":"MENTONA","texto":"10–30% — Aromático, antiespasmódico"},{"label":"MENTOFURANO","texto":"Presente — Potencialmente hepatotóxico em doses altas"},{"label":"ISOMENTONA","texto":"Presente — Aromático"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"8ee92309-6851-457e-8beb-79b0af0577d9","slug":"hibisco","herb_id":null,"herb_latin_name":"Hibiscus sabdariffa","schema_version":"1.1","ficha":{"slug":"hibisco","cultura":{"brasil":"O hibisco passou de produto rural nordestino quase desconhecido no Sudeste a fenômeno nacional de vendas em farmácias, supermercados e aplicativos de delivery em menos de 10 anos (2012–2022). O \"chá de hibisco para emagrecer\" — marketing que extrapola a evidência — impulsionou adoção que expôs milhões de brasileiros a uma planta com ação hipotensora real, sem que soubessem.","historia":"O hibisco é simultaneamente planta do nordeste brasileiro, da África Ocidental, do Egito, do México e do Sudeste Asiático — toda cultura tropical tem sua própria história com o hibisco. O Bissap senegalês, o Agua de Jamaica mexicano, o Karkade egípcio e a vinagreira nordestina são o mesmo ingrediente com narrativas de origem completamente diferentes.  No Brasil, o hibisco chegou no contexto da diáspora africana — as populações negras trazidas como escravizadas trouxeram o hábito do hibisco como bebida e alimento. A vinagreira nordestina (hibisco cozido com arroz e carne-de-sol) é um dos pratos mais antigos do Nordeste — de origem afro-indígena.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão quente ou cold brew.","quantidade":"2–3 g de cálices secos para 250 ml.","reinfusoes":"1–2 possíveis.","combina_com":"Gengibre · Canela · Maracujá · Capim-limão · Hortelã · Açaí · Pitanga — hibisco combina com quase tudo como base colorida.","melhor_momento":"Qualquer hora. Cold brew: excelente bebida de verão e hidratação.","tempo_de_infusao":"","temperatura_ideal":"95–100 °C (ácidos orgânicos e antocianinas resistem à ebulição)."},"tagline":"O rubí vegetal — cálice ácido-vermelho do nordeste e do mundo, com ação hipotensora entre as mais documentadas de qualquer fitoterápico e um dos maiores fenômenos de mercado de chás dos últimos 20 anos.","receitas":[{"nome":"Circulação nas Pernas","slug":"circulacao-nas-pernas","proposito":null},{"nome":"Antioxidante do Fim de Tarde","slug":"antioxidante-do-fim-de-tarde","proposito":null}],"regulacao":{"status_ema":"","status_fda":"GRAS para uso alimentar","sazonalidade":"Colheita: 5–6 meses após plantio; NE: junho–setembro","status_anvisa":"Uso reconhecido. Indicação: diurético, antioxidante.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Hibisco","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Hibisco · vinagreira · caruru-azedo · quiabo-de-angola · rosela","Hibiscus tea (inglês) · Bissap (África Ocidental) · Agua de Jamaica (México) · Karkade (Egito/Sudão)"],"parte_usada":"Cálices (sépalas carnosas) secos — não são flores; são os envoltórios carnosos do fruto.","tipo_botanico":"Fitoterápico antihipertensivo / antioxidante / diurético","nome_cientifico":"Hibiscus sabdariffa L.","familia_botanica":"Malvaceae (família do algodão, do quiabo)"},"caracterizacao":{"aroma":"Floral-frutado-ácido, hibisco fresco, framboesa e cranberry selvagem.","notas":"Cabeça: ácido-floral vívido | Corpo: frutal-cranberry | Fundo: tanino suave, leve adstringência | DISTRIBUIÇÃO NO BRASIL: Nordeste (maior produtor — PE, CE, BA, PB); introduzido da África, naturalizado.","intensidade":"3/5 — perfil definido e elegante.","cor_da_infusao":"Vermelho-rubi intenso a carmim — a cor mais espetacular do catálogo. #C01830","bioma_de_origem":"","sabor_dominante":"Ácido-cítrico intenso e limpo, levemente floral-frutal, tanino suave no fundo. Um dos perfis mais refrescantes do catálogo — o azedo perfeito.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Hibiscus sabdariffa L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Hipertensão arterial leve-moderada","populacao":"McKay et al., 2010"},{"evidencia":"Moderada","indicacao":"Dislipidemia (LDL)","populacao":"Gurrola-Díaz et al., 2010"},{"evidencia":"Moderada","indicacao":"Proteção hepática","populacao":"Chang et al., 2014"},{"evidencia":"Preliminar","indicacao":"Emagrecimento (adjuvante)","populacao":"Estudos piloto"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Antihipertensivo (inibição ECA — similar ao mecanismo de captopril)","Antioxidante (antocianinas de alto ORAC)","Diurético","Hipolipemiante (redução de LDL e colesterol total)","Hepatoprotetor","Anti-inflamatório","Antiobésico leve (inibição de lipase pancreática)","Componentes ativos:","Indicações com evidência:","Contraindicações:","Anti-hipertensivos — potencialização (monitorar PA)","Gestação — emenagogo em doses altas; uso moderado tolerado","Lítio — interfere na excreção renal","Cloroquina — reduz biodisponibilidade"],"contraindicacoes":["Anti-hipertensivos — potencialização (monitorar PA)","Gestação — emenagogo em doses altas; uso moderado tolerado","Lítio — interfere na excreção renal","Cloroquina — reduz biodisponibilidade"],"efeitos_adversos":"","componentes_ativos":[{"label":"ANTOCIANINAS (delfinidina-3-glucosídeo, cianidina-3-glucosídeo)","texto":"Alta — Antioxidante, antihipertensivo, anti-inflamatório"},{"label":"ÁCIDOS ORGÂNICOS (cítrico, tartárico, málico, hibísico)","texto":"Alta — Acidez característica, diurético"},{"label":"ÁCIDO HIBÍSICO (lactona de ácido)","texto":"Específico do hibisco — Antihipertensivo — inibição ECA"},{"label":"PROTOCATECUICO (polifenol)","texto":"Presente — Hepatoprotetor, antioxidante"},{"label":"QUERCETINA, MIRICETINA","texto":"Presentes — Anti-inflamatório, antioxidante"},{"label":"PECTINAS (mucilagens)","texto":"Presentes — Hipolipemiante, antiobésico"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"4701db64-aead-43bb-be31-fbbe9b787955","slug":"canela-do-ceilao","herb_id":null,"herb_latin_name":"Cinnamomum verum","schema_version":"1.1","ficha":{"slug":"canela-do-ceilao","cultura":{"brasil":"","historia":"A canela custou mais que ouro em peso por séculos. As rotas da canela do Ceilão (hoje Sri Lanka) foram segredo de estado guardado por comerciantes árabes por centenas de anos. A Portugal dos séculos XV e XVI construiu seu império colonial em parte para controlar o comércio de canela — Vasco da Gama chegou à Índia em 1498 exatamente buscando essa rota.  O paradoxo: o Brasil, que foi colonizado em parte pela mesma lógica das especiarias, tornou-se um dos maiores consumidores mundiais de canela — mas importa praticamente toda a canela que consome, sem cultivar em escala comercial.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção suave (pau) ou infusão (pó).","quantidade":"1 pau pequeno (1–2 g) ou 1 colher de chá de pó por 250 ml.","reinfusoes":"","combina_com":"Gengibre · Cúrcuma · Cardamomo · Cravo · Mel · Maçã · Laranja · Cacau — canela é o especiado universal.","melhor_momento":"Pós-refeições (antidiabético prandial) — 3x ao dia.","tempo_de_infusao":"","temperatura_ideal":"95 °C (canela resiste ao calor — aldeído cinâmico estável)."},"tagline":"A especiaria que moveu a história — antidiabética, antisséptica e cardioprotetora com mais de 4.000 anos de uso documentado em todas as civilizações que a conheceram.","receitas":[{"nome":"Antiflatulência Clássica","slug":"antiflatulencia-classica","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — traditional use para dispepsia.","status_fda":"","sazonalidade":"","status_anvisa":"Monografia oficial. Indicação: digestivo, antisséptico.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Canela-do-Ceilão","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Canela-do-ceilão · canela-verdadeira · canela-de-veiga","Ceylon cinnamon (inglês) · Cannelle de Ceylan (francês)","ATENÇÃO: C. verum (Ceilão) ≠ C. cassia (China — canela-da-china) — a canela-da-china tem cumarina em concentrações 70x maiores. A maioria da canela vendida no Brasil é C. cassia — mais barata, mais picante, mais risco de hepatotoxicidade em uso regular intenso."],"parte_usada":"Casca interna seca (canela-do-ceilão); óleos essenciais.","tipo_botanico":"Fitoterápico antidiabético / antisséptico / antioxidante","nome_cientifico":"Cinnamomum verum J.Presl (sin.: C. zeylanicum Blume)","familia_botanica":"Lauraceae (família do louro, do abacate)"},"caracterizacao":{"aroma":"Doce-especiado-quente, aldeído cinâmico característico, baunilha suave, madeira aquecida.","notas":"","intensidade":"3–4/5 — presença marcante mas harmonizável.","cor_da_infusao":"Âmbar-marrom quente. #C88840","bioma_de_origem":"","sabor_dominante":"Doce-picante quente, complexo, levemente floral, amadeirado-especiado. C. verum: mais suave, floral, complexa. C. cassia: mais intensa, picante, menos nuances.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Cinnamomum verum J.Presl (sin.: C. zeylanicum Blume)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Diabetes tipo 2 (adjuvante)","populacao":"Khan et al., 2003"},{"evidencia":"Moderada","indicacao":"Síndrome metabólica","populacao":"Qin et al., 2010"},{"evidencia":"Moderada","indicacao":"Infecções respiratórias (via aromática)","populacao":"Pesquisas em aromaterapia"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Antidiabético (mimetiza insulina, melhora sensibilidade)","Antimicrobiano potente (aldeído cinâmico)","Antifúngico","Antioxidante","Anti-inflamatório","Cardioprotetor (redução de LDL)","Antiespasmódico digestivo","Estimulante da circulação","Componentes ativos:","Indicações com evidência:","Contraindicações:","C. cassia em uso diário intenso — risco de hepatotoxicidade por cumarina; preferir C. verum","Anticoagulados — potencialização (cumarina)","Gestação em doses altas — emenagogo","Hepatopatias — C. cassia contraindicada"],"contraindicacoes":["C. cassia em uso diário intenso — risco de hepatotoxicidade por cumarina; preferir C. verum","Anticoagulados — potencialização (cumarina)","Gestação em doses altas — emenagogo","Hepatopatias — C. cassia contraindicada"],"efeitos_adversos":"","componentes_ativos":[{"label":"ALDEÍDO CINÂMICO (cinnamaldeído)","texto":"Antimicrobiano, antifúngico, antidiabético (principal)"},{"label":"EUGENOL","texto":"Anti-inflamatório, antimicrobiano, analgésico"},{"label":"CUMARINA (C. verum — baixa; C. cassia — alta)","texto":"Anticoagulante, broncodilatador"},{"label":"PROCIANIDINAS (tipo A)","texto":"Antidiabético — mimetismo de insulina"},{"label":"POLÍMEROS TIPO A DE PROCIANIDINAS","texto":"Sensibilizador de insulina"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"b02e6933-0b3a-45ac-8b63-9d78cf51afd5","slug":"alcacuz","herb_id":null,"herb_latin_name":"Glycyrrhiza glabra","schema_version":"1.1","ficha":{"slug":"alcacuz","cultura":{"brasil":"","historia":"O alcaçuz é a erva mais doce da história da medicina — adoçante natural antes do açúcar, preservativo de alimentos antes da refrigeração, remédio antes da farmacologia. Alexandre Magno distribuía palitos de raiz de alcaçuz para suas tropas para suportar longas marchas — hidratação e energia. Os faraós do Egito foram enterrados com alcaçuz (encontrado na tumba de Tutancâmon). Confúcio recomendava alcaçuz como tônico diário.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Decocção suave (raiz dura). Pó: infusão 5–8 min.","quantidade":"1–3 g de raiz seca para 250 ml","reinfusoes":"","combina_com":"Funcho · Camomila · Espinheira-santa · Alcachofra · Gengibre — alcaçuz é o adoçante natural e harmonizador de blends amargos.","melhor_momento":"30 min antes das refeições (gastroprotetor) ou como adoçante de blends amargos.","tempo_de_infusao":"","temperatura_ideal":"95 °C | Tempo: 10–15 min | Quantidade: 1–3 g de raiz seca para 250 ml"},"tagline":"O adoçante medicinal do mundo antigo — 50x mais doce que o açúcar, com ação gastroprotetora excepcional, reputação milenar e farmacologia que ainda surpreende.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — well-established use para gastrite e tosse.","status_fda":"","sazonalidade":"","status_anvisa":"Monografia oficial. Indicações: gastroprotetor, expectorante.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Alcaçuz","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Alcaçuz · alcaçuz-da-europa · regaliz · palito-doce","Liquorice (inglês) · Réglisse (francês) · Lakritz (alemão) · Regaliz (espanhol)","Gan cao (chinês — \"erva doce\") — um dos mais usados na MTC"],"parte_usada":"Raiz e rizoma, secos.","tipo_botanico":"Fitoterápico gastroprotetor / expectorante / adoçante","nome_cientifico":"Glycyrrhiza glabra L.","familia_botanica":"Fabaceae / Papilionoideae"},"caracterizacao":{"aroma":"Doce-anisado-balsâmico, feno adocicado, madeira curada.","notas":"","intensidade":"3/5 — doçura marcante; volume de sabor distinto.","cor_da_infusao":"Marrom-amarelado a âmbar-mel. #C89A38","bioma_de_origem":"","sabor_dominante":"Doce intenso e peculiar (glicirrizina — 50x açúcar), levemente anis, fundo de madeira doce. Doçura longa, persistente, diferente de qualquer outra.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Glycyrrhiza glabra L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Gastroprotetor (proteção e cicatrização da mucosa gástrica)","Antiulceroso (H. pylori — ação documentada)","Expectorante e demulcente (vias respiratórias)","Anti-inflamatório (glicirretínico — similar à cortisona)","Adoçante natural (uso em formulações)","Antiviral (hepatite C, HIV — pesquisa)","Hepatoprotetor","Componentes ativos:","⚠️ ATENÇÃO — PSEUDOHIPERALDOSTERONISMO:","Contraindicações:","Hipertensão arterial — contraindicado em uso regular","Hipocalemia — potencializa perda de potássio","Corticoides — sinergismo","Gestação — estrogênico fraco em doses altas","Insuficiência cardíaca e renal — retenção de sódio"],"contraindicacoes":["Hipertensão arterial — contraindicado em uso regular","Hipocalemia — potencializa perda de potássio","Corticoides — sinergismo","Gestação — estrogênico fraco em doses altas","Insuficiência cardíaca e renal — retenção de sódio"],"efeitos_adversos":"","componentes_ativos":[{"label":"GLICIRRIZINA (glicirrizato de amônio)","texto":"2–9% da raiz seca — Adoçante, anti-inflamatório, antiviral, gastroprotetor"},{"label":"ÁCIDO GLICIRRETÍNICO (produto de hidrólise)","texto":"— — Anti-inflamatório tipo corticoide, antiulceroso"},{"label":"FLAVONÓIDES (liquiritigenina, isoliquiritigenina)","texto":"Presentes — Antiulceroso, estrogênico fraco"},{"label":"GLABRIDINA","texto":"Presente — Antimicrobiano, antioxidante, clareador de pele"},{"label":"CHALCONAS","texto":"Presentes — Antimicrobiano"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"0991c494-322d-4567-8e89-b09b2baf173a","slug":"lavanda","herb_id":null,"herb_latin_name":"Lavandula angustifolia","schema_version":"1.1","ficha":{"slug":"lavanda","cultura":{"brasil":"A lavanda no Brasil é produto cultural e turístico antes de fitoterápico — os campos de lavanda de Cunha (SP) e Gramado (RS) são destinos de turismo rural consolidados. O consumo de chá de lavanda é crescente no mercado premium, associado a rituais de bem-estar e meditação.","historia":"A lavanda é a planta do Provence francês como a camomila é da Europa central — identidade de paisagem e cultura. Os campos violeta de lavanda da Provença são uma das imagens mais reproduzidas da Europa. A perfumaria europeia moderna nasceu em Grasse (França) em torno do cultivo de lavanda.  Na Idade Média, a lavanda era erva profilática da peste — sachês de lavanda usados no pescoço para \"proteger o ar\". Médicos que tratavam pestilentos usavam máscaras em bico de pássaro recheadas de lavanda e outras ervas aromáticas. Profilaxia infundada, mas o linalol tem atividade antimicrobiana documentada.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta, preferível em bule de cerâmica (retém aroma).","quantidade":"1–2 g de flores secas para 250 ml. Dose baixa — aroma intenso.","reinfusoes":"","combina_com":"Camomila (clássico absoluto) · Melissa · Maracujá · Rosa · Mel · Flor de laranjeira — lavanda é sempre coadjuvante aromático nobre.","melhor_momento":"Noite — 30 min antes de dormir. Ritual do sono.","tempo_de_infusao":"","temperatura_ideal":"80–85 °C (linalol e acetato de linalila muito voláteis)."},"tagline":"A flor da serenidade — ansiolítica aromática europeia com a relação mais documentada entre aroma e sistema nervoso de qualquer planta do catálogo.","receitas":[{"nome":"Mente Serena","slug":"mente-serena","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — well-established use (Silexan, OE oral)","status_fda":"GRAS para uso alimentar","sazonalidade":"Floração: novembro–janeiro (RS/SC em altitude)","status_anvisa":"Uso reconhecido. Silexan: não registrado no Brasil.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Lavanda","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Lavanda · lavanda-inglesa · espigo (Portugal)","Lavender (inglês) · Lavande (francês) · Lavendel (alemão)","True lavender / English lavender (diferente da L. stoechas — menos estudada)"],"parte_usada":"Flores secas; óleo essencial (uso aromaterápico e tópico).","tipo_botanico":"Fitoterápico ansiolítico / sedativo / aromaterápico","nome_cientifico":"Lavandula angustifolia Mill. (sin.: L. officinalis Chaix)","familia_botanica":"Lamiaceae"},"caracterizacao":{"aroma":"Floral-frutado-herbal — o aroma mais reconhecível de bem-estar do mundo. Linalol + acetato de linalila = fórmula da calma.","notas":"","intensidade":"2/5 (sabor) — 5/5 (aroma). A erva de maior gap entre experiência gustativa e olfativa do catálogo.","cor_da_infusao":"Roxo-acinzentado pálido a âmbar rosado. #C8A8C0","bioma_de_origem":"","sabor_dominante":"Floral intenso, levemente herbáceo, discretamente amargo. Palatabilidade dividida — aroma é muito superior ao sabor.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Lavandula angustifolia Mill. (sin.: L. officinalis Chaix)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Forte","indicacao":"Ansiedade (oral — Silexan)","populacao":"Kasper et al., 2014"},{"evidencia":"Moderada","indicacao":"Insônia (aromaterapia)","populacao":"Lewith et al., 2005"},{"evidencia":"Moderada","indicacao":"Cefaleia (tópico)","populacao":"Sasannejad et al., 2012"},{"evidencia":"Moderada","indicacao":"Agitação em Alzheimer (aromaterapia)","populacao":"Holmes et al., 2002"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico (modulação GABA e glutamato)","Sedativo / indutor de sono","Analgésico (cefaleia, dor menstrual)","Antiespasmódico","Antibacteriano (óleo essencial)","Neuroprotetor (linalol — antiglutamatérgico)","Componentes ativos:","Indicações com evidência:","Silexan: extrato oral padronizado de lavanda — medicamento registrado na Alemanha para ansiedade generalizada.","Contraindicações: Prepúberes masculinos — uso de óleo essencial em doses altas associado a ginecomastia (efeito estrogênico leve — caso reportado). Uso tópico irrestrito."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"LINALOL","texto":"25–45% do OE — Ansiolítico, sedativo, analgésico, antiglutamatérgico"},{"label":"ACETATO DE LINALILA","texto":"25–47% do OE — Ansiolítico, sedativo (efeito sinérgico com linalol)"},{"label":"OCIMENO","texto":"Presente — Aromático, anti-inflamatório"},{"label":"CÂNFORA","texto":"Traços — Estimulante leve (antagoniza sedação em excesso)"},{"label":"ÁCIDO ROSMARÍNICO","texto":"Presente — Antioxidante, anti-inflamatório"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"12f3ea3e-a8a3-496a-bfa2-5d5ee57e18ef","slug":"capim-limao","herb_id":null,"herb_latin_name":"Cymbopogon citratus","schema_version":"1.1","ficha":{"slug":"capim-limao","cultura":{"brasil":"","historia":"","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta.","quantidade":"2–5 g de folhas secas ou 3–6 folhas frescas para 250 ml.","reinfusoes":"1–2 possíveis.","combina_com":"Melissa · Gengibre · Hibisco · Hortelã · Lavanda · Limão · Mel — universalmente compatível.","melhor_momento":"Qualquer hora — especialmente tarde e noite.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (citral volátil — não ferver)."},"tagline":"A capineira aromática — gramínea tropical de aromas cítricos com ação ansiolítica documentada, antimicrobiana e anti-inflamatória, cultivada em todo o Brasil e profundamente enraizada na culinária asiática global.","receitas":[{"nome":"Infusão do Sono Pampeano","slug":"infusao-do-sono-pampeano","proposito":null},{"nome":"Infusão da Cólica Menstrual","slug":"infusao-da-colica-menstrual","proposito":null},{"nome":"Infusão da Tarde do Cerrado","slug":"infusao-da-tarde-do-cerrado","proposito":null},{"nome":"Calmante Infantil (6 meses+)","slug":"calmante-infantil-6-meses","proposito":null}],"regulacao":{"status_ema":"","status_fda":"GRAS para uso alimentar","sazonalidade":"Disponível o ano todo (cultivo perene)","status_anvisa":"Uso reconhecido. Indicação: sedativo, ansiolítico.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Capim-Limão","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Capim-limão · capim-santo · erva-cidreira-do-campo · cidró","Lemongrass (inglês) · Citronnelle (francês) · Zitronengras (alemão)","Sereh (indonésio/malaio) · Takrai (tailandês)"],"parte_usada":"Folhas frescas ou secas (partes aéreas).","tipo_botanico":"Fitoterápico aromático / ansiolítico / anti-inflamatório","nome_cientifico":"Cymbopogon citratus (DC.) Stapf","familia_botanica":"Poaceae (gramíneas — família do arroz, do milho)"},"caracterizacao":{"aroma":"Limão fresco concentrado, cítrico-terpênico, leve floral-verde. Citral puro — um dos aromas mais alegres do catálogo.","notas":"","intensidade":"2/5 — suave a moderado, perfil agradabilíssimo.","cor_da_infusao":"Amarelo-pálido a dourado claro. #E8DC78","bioma_de_origem":"","sabor_dominante":"Cítrico-limão limpo e vívido, levemente herbáceo-grama, muito fresco. Mais nítido que melissa ou erva-cidreira.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Cymbopogon citratus (DC.) Stapf","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico leve (citral — modulação GABA)","Antiespasmódico","Anti-inflamatório","Antimicrobiano","Antifúngico","Diurético suave","Repelente de insetos (citronelal)","Analgésico leve","Componentes ativos:","Contraindicações: Gestação em doses altas de óleo essencial — citral emenagogo. Infusão: moderada é segura."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"CITRAL (geranial + neral)","texto":"60–80% do OE — Ansiolítico, antimicrobiano, antifúngico"},{"label":"MIRCENO","texto":"5–15% — Anti-inflamatório, analgésico"},{"label":"LIMONENO","texto":"Presente — Antimicrobiano, antidepressivo leve"},{"label":"GERANIOL","texto":"Presente — Antimicrobiano, aromático"},{"label":"CITRONELAL","texto":"Traços — Repelente, ansiolítico"}]}},"status":"published","active":true,"created_by":"3b8150ec-669e-4a14-bfec-a3e21f0bd066","created_at":"2026-04-22T02:02:14.606427+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"c50b89f9-f2e2-4640-bb51-e821fb663227","slug":"alecrim","herb_id":null,"herb_latin_name":"Salvia rosmarinus","schema_version":"1.1","ficha":{"slug":"alecrim","cultura":{"brasil":"O alecrim é a erva aromática mais cultivada em quintais urbanos brasileiros — depois do manjericão. Presente na culinária, na cosmética, nos chás e nos jardins. É a erva que o brasileiro mais conhece e menos usa farmacologicamente.","historia":"\"Onde o alecrim cresce, a mulher governa a casa\" — provérbio mediterrâneo que expressa a relação entre alecrim e poder doméstico feminino na cultura europeia. Shakespeare pôs alecrim para Ofélia (\"alecrim, para lembrança\") — associação entre a planta e a memória que a ciência moderna confirmou bioquimicamente.  Os gregos usavam coroas de alecrim no cabelo durante exames — acreditando que melhorava a memória. Pesquisa moderna com o componente 1,8-cineol mostra que inalação de alecrim aumenta velocidade e acurácia em testes de memória. Shakespeare e os gregos estavam certos.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão coberta.","quantidade":"1–2 g de ramos secos para 250 ml.","reinfusoes":"","combina_com":"Sálvia · Tomilho · Lavanda · Limão · Mel · Gengibre — mediterrâneo puro.","melhor_momento":"Manhã e início de tarde (estimulante cognitivo). Evitar à noite.","tempo_de_infusao":"","temperatura_ideal":"85–90 °C (cânfora e borneol voláteis — não ferver)."},"tagline":"A memória aromática do Mediterrâneo — estimulante cognitivo, antioxidante e antimicrobiano com ação sobre memória e concentração entre as mais bem documentadas de qualquer erva do catálogo.","receitas":[{"nome":"Mente Serena","slug":"mente-serena","proposito":null},{"nome":"Antioxidante do Fim de Tarde","slug":"antioxidante-do-fim-de-tarde","proposito":null},{"nome":"Alívio de Alergia Sazonal","slug":"alivio-de-alergia-sazonal","proposito":null},{"nome":"Clareza e Memória","slug":"clareza-e-memoria","proposito":null}],"regulacao":{"status_ema":"Monografia HMPC — traditional use.","status_fda":"GRAS","sazonalidade":"Disponível o ano todo (cultivo perene)","status_anvisa":"Monografia oficial. Indicações: digestivo, estimulante.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Alecrim","usos_topicos":{"evidencia":"","aplicacoes":["Tônico capilar (queda de cabelo): Infusão forte resfriada aplicada no couro cabeludo — estudos compararam favorável ao minoxidil em queda androgenética (estudo 2015, ISRN Dermatology).","Repelente de insetos (uso externo): Óleos do alecrim em formulações — comprovado repelente de Aedes aegypti em estudos nacionais."],"contraindicacoes":""},"identificacao":{"sinonimos":["Alecrim · rosmaninho (Portugal)","Rosemary (inglês) · Romarin (francês) · Rosmarin (alemão)","\"Ros maris\" (latim medieval — \"orvalho do mar\") — cresce em penhascos costeiros do Mediterrâneo"],"parte_usada":"Partes aéreas (folhas e ramos finos), frescas ou secas.","tipo_botanico":"Fitoterápico estimulante cognitivo / antioxidante / antimicrobiano","nome_cientifico":"Salvia rosmarinus Spenn. (renomeado em 2017; sin.: Rosmarinus officinalis L.)","familia_botanica":"Lamiaceae"},"caracterizacao":{"aroma":"Resinoso-herbáceo-cânfora, mediterrâneo puro — pinho, eucalipto, erval quente. Um dos aromas mais imediatamente reconhecíveis do mundo.","notas":"","intensidade":"4/5 — presença aromática dominante.","cor_da_infusao":"Verde-amarelado a âmbar. #B8B040","bioma_de_origem":"","sabor_dominante":"Resinoso-aromático intenso, levemente amargo-herbáceo, cânfora suave, pimentado discreto.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Salvia rosmarinus Spenn. (renomeado em 2017; sin.: Rosmarinus officinalis L.)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Melhora de memória e cognição","populacao":"Moss et al., 2012 (aromaterapia)"},{"evidencia":"Moderada","indicacao":"Queda de cabelo androgenética","populacao":"Panahi et al., 2015"},{"evidencia":"Forte","indicacao":"Antioxidante sistêmico","populacao":"Múltiplos estudos"},{"evidencia":"Preliminar","indicacao":"Alzheimer (adjuvante, inalação)","populacao":"Estudos piloto"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Estimulante cognitivo (melhora memória e concentração — inalação e oral)","Inibidor de acetilcolinesterase (mecanismo similar ao Alzheimer farmacológico)","Antioxidante de alta capacidade (ácido rosmarínico — um dos maiores ORAC do catálogo)","Antimicrobiano potente","Hepatoprotetor","Anti-inflamatório","Estimulante circulatório","Componentes ativos:","Indicações com evidência:","Contraindicações:","Epilepsia — cânfora pró-convulsivante em doses altas de óleo essencial","Gestação em doses de OE — emenagogo; infusão: segura moderadamente","Hipertensão — estimulante circulatório; cautela em dose alta"],"contraindicacoes":["Epilepsia — cânfora pró-convulsivante em doses altas de óleo essencial","Gestação em doses de OE — emenagogo; infusão: segura moderadamente","Hipertensão — estimulante circulatório; cautela em dose alta"],"efeitos_adversos":"","componentes_ativos":[{"label":"ÁCIDO ROSMARÍNICO","texto":"Antioxidante máximo, anti-inflamatório, inibidor de AChE"},{"label":"ÁCIDO CARNÓSICO","texto":"Antioxidante, nootrópico, neuroprotetor"},{"label":"CARNOSOL","texto":"Antitumoral, anti-inflamatório, antioxidante"},{"label":"CÂNFORA (OE)","texto":"Estimulante SNC, descongestionante"},{"label":"1,8-CINEOL (eucaliptol)","texto":"Cognitivo — melhora memória (estudos de aromaterapia)"},{"label":"BORNEOL","texto":"Antimicrobiano, estimulante circulatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"7003c679-1aa1-4b43-8324-9a85850bdd6d","slug":"cardamomo","herb_id":null,"herb_latin_name":"Elettaria cardamomum","schema_version":"1.1","ficha":{"slug":"cardamomo","cultura":{"brasil":"O cardamomo chegou ao Brasil via culinária árabe (comunidade libanesa e síria em SP) e via Ayurveda (comunidade indiana). Hoje é ingrediente de blends de chai premium que proliferam em cafeterias e lojas de chá. O Ervatório pode posicioná-lo como ponte entre tradição oriental e sophistication brasileira.","historia":"O cardamomo é mencionado nos textos cuneiformes babilônicos (3.000 a.C.) como especiaria de jardins reais. Os gregos importavam cardamomo da Índia via rota árabe — Dioscórides o descreve como digestivo e afrodisíaco. Os vikings escandinavos comercializavam cardamomo na Europa do Norte no séc. X — levado por rotas comerciais árabes até o Báltico. Por isso o cardamomo é ingrediente obrigatório nos bolos natalinos escandinavos: uma herança de rotas comerciais medievais.  No mundo árabe, o café ao cardamomo (qahwa) é símbolo de hospitalidade — servido em xícara pequena sem alça durante negociações e recepções. Recusar é descortesia grave. O cardamomo neutraliza a amargura do café e adiciona aroma que os árabes associam a generosidade e status.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão de sementes levemente maceradas — essencial triturar para liberar óleos. Decocção suave para extração máxima.","quantidade":"3–5 sementes esmagadas para 250 ml (ou 0,5–1 g de sementes moídas).","reinfusoes":"","combina_com":"Canela · Gengibre · Cravo · Pimenta-rosa · Mel · Leite de coco · Cacau · Café (chai e blends orientais)","melhor_momento":"Pós-refeições (digestivo) ou manhã (tônico energizante).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C (1,8-cineol estável)."},"tagline":"A rainha das especiarias — o aromático mais caro do mundo por peso (após açafrão e baunilha), digestivo de elite com ação cardioprotetora e um perfil sensorial que nenhum outro vegetal replica.","receitas":[],"regulacao":{"status_ema":"","status_fda":"GRAS para uso alimentar","sazonalidade":"Colheita: outubro–fevereiro (Guatemala) / agosto–novembro (Índia)","status_anvisa":"Uso alimentar reconhecido. Especiaria regulamentada.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Cardamomo","usos_topicos":{"evidencia":"","aplicacoes":["Antisséptico bucal natural: Mastigar 2–3 sementes após refeições — antimicrobiano oral, eliminação de mau hálito. Prática milenar indiana com base farmacológica (1,8-cineol + terpineol contra S. mutans e C. albicans).","Inalação aromática: Sementes trituradas em vapor — descongestionante nasal, broncodilatação leve."],"contraindicacoes":""},"identificacao":{"sinonimos":["Cardamomo · cardamom · eleitária","Cardamom (inglês) · Cardamome (francês) · Kardamom (alemão)","Elaichi (hindi) · Hel (árabe) · Kakule (turco)","DISTINÇÃO: E. cardamomum (cardamomo-verde / cardamomo-verdadeiro) ≠ Amomum subulatum (cardamomo-preto — sabor mais robusto, menos elegante)"],"parte_usada":"Sementes (dentro das cápsulas verdes) — as sementes são o concentrado de aroma; as cápsulas têm aroma mais suave.","tipo_botanico":"Especiaria aromática / digestivo / cardioprotetor","nome_cientifico":"Elettaria cardamomum (L.) Maton","familia_botanica":"Zingiberaceae (família do gengibre, da cúrcuma, da galanga)"},"caracterizacao":{"aroma":"1,8-cineol (eucalipto) + acetato de terpenila (floral-frutado) + linalol (floral-lavanda) + limoneno (cítrico). Aroma de perfume de alta costura nascido numa semente.","notas":"Cabeça: floral-cítrico vívido | Corpo: eucaliptoide-mentolado | Fundo: amadeirado-apimentado quente | DISTRIBUIÇÃO: Originário do sudoeste da Índia (Ghats Ocidentais). Maior produtor: Guatemala. Índia: segundo produtor. Brasil: cultivo experimental no AM, PA.","intensidade":"4/5 — aromático dominante que transforma qualquer blend.","cor_da_infusao":"Amarelo-pálido a dourado. #ECD878","bioma_de_origem":"","sabor_dominante":"Floral-cítrico-eucaliptoide-apimentado — o sabor mais complexo e multidimensional do catálogo. Doce floral, cítrico fresco, eucalipto mentolado, picante quente, amadeirado seco — tudo simultaneamente. Impossível de comparar com qualquer outra coisa.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Elettaria cardamomum (L.) Maton","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada","indicacao":"Hipertensão arterial","populacao":"Verma et al. (2009) — 3 meses de extrato"},{"evidencia":"Moderada","indicacao":"Síndrome metabólica (fibrinólise)","populacao":"Poonam Verma, 2009"},{"evidencia":"Forte (uso tradicional)","indicacao":"Flatulência e dispepsia","populacao":"EMA referência indireta"},{"evidencia":"Forte","indicacao":"Mau hálito","populacao":"Farmacologia oral — múltiplos estudos"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Carminativo (elimina gases — ação mais rápida do catálogo)","Antiespasmódico digestivo","Antimicrobiano bucal e digestivo","Cardioprotetor (redução de PA em hipertensos — estudos clínicos indianos)","Broncodilatador leve (1,8-cineol)","Afrodisíaco (tradição ayurvédica — mecanismo não elucidado farmacologicamente)","Antioxidante","Diurético suave","Componentes ativos:","Indicações com evidência:","Contraindicações: Cálculo biliar — estimula contração vesicular. Gestação em doses de OE."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"1,8-CINEOL (eucaliptol)","texto":"20–45% do OE — Broncodilatador, antimicrobiano, descongestionante"},{"label":"ACETATO DE ALFA-TERPENILA","texto":"30–40% do OE — Aromático floral, carminativo"},{"label":"LINALOL","texto":"1–5% — Ansiolítico, aromático"},{"label":"SABINENO","texto":"Presente — Antimicrobiano"},{"label":"LIMONENO","texto":"Presente — Antimicrobiano, digestivo"},{"label":"METIL-EUGENOL","texto":"Traços — Aromático, anestésico local"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"bda7f6ed-be14-4f02-b8e7-cac6f1685316","slug":"cravo-da-india","herb_id":null,"herb_latin_name":"Syzygium aromaticum","schema_version":"1.1","ficha":{"slug":"cravo-da-india","cultura":{"brasil":"A Bahia produz cravo desde o séc. XVIII — introduzido pelos portugueses que quebraram o monopólio holandês levando mudas do Oriente para o Brasil colonial. Hoje, Valença e municípios do sul da Bahia são os maiores produtores nacionais, com exportação para Europa e EUA.","historia":"O cravo causou a primeira globalização do mundo moderno. O arquipélago das Molucas (atual Indonésia) era o único lugar do mundo onde o cravo crescia — e o controle dessa produção foi o objetivo das primeiras expedições portuguesas, espanholas e holandesas ao Oriente. A VOC (Companhia das Índias Orientais Holandesa) manteve monopólio absoluto do cravo por um século, exterminando populações inteiras de ilhas que tentaram vender cravo a outros compradores.  O cheiro de cravo nos bairros de Valença (BA) durante a colheita é uma das experiências sensoriais mais marcantes do interior baiano — e lembra que o Brasil produz o mesmo cravo que moveu impérios no século XVI.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Infusão simples.","quantidade":"2–3 botões para 250 ml (pouco — muito poderoso).","reinfusoes":"","combina_com":"Canela · Cardamomo · Gengibre · Pimenta · Laranja · Cacau · Mel (chai, blends especiados quentes)","melhor_momento":"Pós-refeições (digestivo/antisséptico oral) ou quando necessário (dor dental emergencial).","tempo_de_infusao":"","temperatura_ideal":"90–95 °C."},"tagline":"O dente sem dor — o botão floral que anestesiou dentes por séculos antes da lidocaína, com o mais alto ORAC de qualquer especiaria e eugenol como molécula de referência farmacológica.","receitas":[],"regulacao":{"status_ema":"Monografia HMPC — traditional use para dor dental e antisséptico oral.","status_fda":"GRAS para uso alimentar. OE: semi-regulado (potencialmente tóxico).","sazonalidade":"Colheita: agosto–novembro (BA)","status_anvisa":"Monografia oficial. Indicações: antisséptico oral, analgésico.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Cravo-da-Índia","usos_topicos":{"evidencia":"","aplicacoes":["Analgésico dental emergencial: 1 gota de óleo essencial de cravo ou botão macerado aplicado diretamente na gengiva ao redor do dente com dor — anestesia local por eugenol. Evidência clínica forte — eugenol é ingrediente do cimento dental provisório da odontologia.","Antisséptico bucal: Infusão forte (3 botões/100 ml) como bochecho — antimicrobiano contra S. mutans, C. albicans, H. pylori oral.","Repelente de insetos tópico: Óleo essencial diluído (2% em óleo carreador) — proteção eficaz contra mosquitos."],"contraindicacoes":""},"identificacao":{"sinonimos":["Cravo · cravo-da-índia · cravo-de-especiaria","Clove (inglês) · Clou de girofle (francês) · Gewürznelke (alemão)","Lavang (hindi) · Qaranful (árabe)"],"parte_usada":"Botões florais secos (o \"cravo\" comercial) — colhidos antes da abertura; óleos essenciais.","tipo_botanico":"Fitoterápico analgésico / antimicrobiano / antioxidante","nome_cientifico":"Syzygium aromaticum (L.) Merr. & L.M.Perry (sin.: Eugenia caryophyllus)","familia_botanica":"Myrtaceae (família da goiaba, da pitanga, do eucalipto)"},"caracterizacao":{"aroma":"Eugenol dominante — floral-apimentado-madeira, cravado, baunilha aquecida. Aroma que define o Natal europeu e o Natal brasileiro.","notas":"","intensidade":"5/5 — a presença mais assertiva do catálogo. Domina qualquer blend.","cor_da_infusao":"Marrom-escuro a âmbar-avermelhado. #7A3820","bioma_de_origem":"","sabor_dominante":"Eugenol puro — quente, apimentado-floral intenso, anestésico local leve (dormência da mucosa oral), amadeirado profundo. O sabor mais imediatamente intenso do catálogo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Syzygium aromaticum (L.) Merr. & L.M.Perry (sin.: Eugenia caryophyllus)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Analgésico tópico (eugenol — anestesia local)","Antimicrobiano potente (bactérias, fungos, vírus)","Antioxidante máximo (ORAC mais alto de qualquer especiaria)","Anti-inflamatório","Antiespasmódico digestivo","Antifúngico (eugenol contra Candida)","Antiparasitário","Componentes ativos:","ORAC: O cravo tem o ORAC mais alto registrado entre especiarias — 290.000 µmol TE/100g. Para referência: mirtilo selvagem tem ~9.500. O cravo é 30x mais antioxidante que o mirtilo por peso.","⚠️ EUGENOL — HEPATOTÓXICO EM DOSE ALTA:","Contraindicações:","Anticoagulados — eugenol antiagregante","Hepatopatias — hepatotóxico em doses altas","Gestação em doses medicinais altas","Crianças: OE contraindicado; infusão fraca: segura moderadamente"],"contraindicacoes":["Anticoagulados — eugenol antiagregante","Hepatopatias — hepatotóxico em doses altas","Gestação em doses medicinais altas","Crianças: OE contraindicado; infusão fraca: segura moderadamente"],"efeitos_adversos":"","componentes_ativos":[{"label":"EUGENOL","texto":"72–90% do OE — Analgésico local, antimicrobiano, anti-inflamatório, antioxidante"},{"label":"ACETATO DE EUGENILA","texto":"5–15% — Antimicrobiano, aromático"},{"label":"BETA-CARIOFILENO","texto":"5–12% — Anti-inflamatório, CB2"},{"label":"ALFA-HUMULENO","texto":"2% — Anti-inflamatório"},{"label":"GALOIL-GLICOSES (taninos)","texto":"Presentes — Antioxidante máximo"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"30c47993-5e4e-4846-9496-2f9ff8d7e8a6","slug":"pimenta-preta","herb_id":null,"herb_latin_name":"Piper nigrum","schema_version":"1.1","ficha":{"slug":"pimenta-preta","cultura":{"brasil":"","historia":"A pimenta-do-reino foi moeda de troca na Europa medieval — \"pagar em espécie\" (in specie) referia-se literalmente a pagar em pimenta. Quando os visigodos sitiaram Roma em 408 d.C., exigiram 3.000 libras de pimenta como resgate. Rotas comerciais que garantiam acesso à pimenta definiram o mapa político do mundo mediterrâneo por séculos.  A busca por uma rota direta às especiarias (pimenta, cravo, noz-moscada) financiou Vasco da Gama, Colombo e Cabral — todas as grandes navegações do século XV e XVI foram em parte motivadas pela pimenta-do-reino. O Brasil foi \"descoberto\" em rota para as especiarias.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Cúrcuma (obrigatório para eficácia) · Gengibre · Canela · Cardamomo · Mel (chai)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A especiaria que comprou civilizações — o potenciador universal que faz tudo melhor, com piperina aumentando a biodisponibilidade de outros princípios ativos em até 2.000%.","receitas":[],"regulacao":{"status_ema":"","status_fda":"GRAS","sazonalidade":"Colheita principal: abril–agosto (Espírito Santo — maior produtor nacional)","status_anvisa":"Uso alimentar. Piperina: pesquisada como potenciador farmacológico.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Pimenta-Preta","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Pimenta-preta · pimenta-do-reino · pimenta-negra","Black pepper (inglês) · Poivre noir (francês) · Schwarzer Pfeffer (alemão)","Kali mirch (hindi) · Filfil aswad (árabe)"],"parte_usada":"Frutos em diferentes estágios de maturação (pimenta-preta = verde colhido e seco; branca = madura sem casca; verde = fresca; vermelha = completamente madura).","tipo_botanico":"Especiaria / potenciador de biodisponibilidade / digestivo","nome_cientifico":"Piper nigrum L.","familia_botanica":"Piperaceae (família das pimentas)"},"caracterizacao":{"aroma":"Pimentado-amadeirado, pinho-resina, floral discreto (linalol), madeira tropical.","notas":"","intensidade":"4/5 — picante dominante.","cor_da_infusao":"Âmbar-castanho. #9A7040","bioma_de_origem":"","sabor_dominante":"Picante-quente penetrante (piperina — TRPV1), amadeirado-terroso profundo, levemente floral na pimenta fresca, notas de madeira defumada seca.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Piper nigrum L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Potenciador de biodisponibilidade (piperina — inibe metabolização intestinal de outros compostos)","Termogênico (TRPV1 — gera calor)","Digestivo (estimula secreções gástricas)","Antimicrobiano","Antioxidante","Anti-inflamatório","Neuroprotetor (piperina — antidepressivo em modelos animais)","Componentes ativos:","PIPERINA E BIODISPONIBILIDADE:","Curcumina: +2.000% (estudo Shoba et al., 1998)","Coenzima Q10: +30%","Beta-caroteno: +60%","Vitamina B6: +20%","Selênio: +30%","Contraindicações: Gastrite ativa e úlcera péptica — irritante. Gestação em doses altas — emenagogo leve."],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"PIPERINA","texto":"Potenciador de biodisponibilidade (inibe CYP3A4, P-gp), termogênico, TRPV1"},{"label":"CHAVICINA","texto":"Isômero da piperina — picante"},{"label":"ÓLEOS ESSENCIAIS (beta-cariofileno, limoneno, mirceno)","texto":"Antimicrobiano, anti-inflamatório"},{"label":"PIPERIDINA","texto":"Alcaloide — estimulante SNC leve"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"2c8eaa0d-9d48-49ae-984d-a8b3f776a288","slug":"acafrao-verdadeiro","herb_id":null,"herb_latin_name":"Crocus sativus","schema_version":"1.1","ficha":{"slug":"acafrao-verdadeiro","cultura":{"brasil":"Quase 100% do \"açafrão\" vendido no Brasil é cúrcuma — a confusão de nomes é generalizada. Açafrão verdadeiro (Crocus sativus) é produto de importação rara, consumido apenas em restaurantes de culinária persa, árabe, espanhola (paella) e indiana. O Ervatório tem responsabilidade específica de fazer essa distinção com clareza.","historia":"O açafrão é a especiaria cultivada mais cara do mundo porque não pode ser mecanizada — cada flor de Crocus sativus produz 3 estigmas que devem ser colhidos à mão, nas primeiras horas da manhã, por mãos humanas que não amassem os filamentos. Uma hora de trabalho produz ~3 gramas de açafrão. É trabalho humano condensado em aroma.  O açafrão aparece em afrescos minoicos de Creta (~1.700 a.C.), na Ilíada de Homero, nos textos persas mais antigos, no Cântico dos Cânticos bíblico, nos papiros médicos egípcios. É possivelmente a especiaria com mais menções em literatura histórica de qualquer civilização — e todas as menções são de reverência.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"Maceração a frio ou morna como pré-preparo + adição a leite ou infusão.","quantidade":"3–6 filamentos por 250 ml (0,02–0,04 g).","reinfusoes":"","combina_com":"Leite/leite de coco · Mel · Cardamomo · Canela · Água de rosas (blends persas/indianos)","melhor_momento":"Noite (antidepressivo/sedativo) ou manhã (tônico).","tempo_de_infusao":"","temperatura_ideal":"70–80 °C — não ferver (crocina degradada acima de 90 °C)."},"tagline":"O ouro vermelho do mundo — a especiaria mais cara do planeta, com ação antidepressiva comparável a fluoxetina em ensaios clínicos e uma das histórias de cultivo mais antigas da civilização.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Floração: outubro–novembro (Iran, Espanha, Caxemira)","status_anvisa":"Uso alimentar. Sem monografia medicinal.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Açafrão-Verdadeiro","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Açafrão-verdadeiro · açafrão-do-oriente","Saffron (inglês) · Safran (francês/alemão) · Azafrán (espanhol)","Zafaran (árabe — origem do nome) · Kesar (hindi)","ATENÇÃO: \"açafrão-da-terra\" ou \"açafrão\" no Brasil quase sempre = cúrcuma (Curcuma longa) — especiaria completamente diferente."],"parte_usada":"Estigmas secos (os três filamentos vermelhos por flor — colhidos à mão).","tipo_botanico":"Especiaria antidepressiva / antioxidante / afrodisíaca","nome_cientifico":"Crocus sativus L.","familia_botanica":"Iridaceae (família da íris)"},"caracterizacao":{"aroma":"Terra molhada (geosmina), mel, flores secas, leve iodado-marinho. Aroma que evoca paisagens inteiras.","notas":"","intensidade":"4/5 — presença aromática única, não replicável.","cor_da_infusao":"Amarelo-ouro intensíssimo a laranja-dourado. #E8A010 — corante natural mais intenso do catálogo.","bioma_de_origem":"","sabor_dominante":"Mel-metálico peculiar, levemente amargo, terroso-aromático profundo, com nota de terra molhada e mel exótico. Inconfundível — impossível de imitar.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Crocus sativus L.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[{"evidencia":"Moderada-forte","indicacao":"Depressão leve a moderada","populacao":"Hausenblas et al. (2013) meta-análise"},{"evidencia":"Moderada","indicacao":"Disfunção sexual por antidepressivos","populacao":"Kashani et al. (2013)"},{"evidencia":"Moderada","indicacao":"Dismenorreia","populacao":"Agha-Hosseini et al. (2008)"},{"evidencia":"Preliminar","indicacao":"Doença de Alzheimer (progrssão)","populacao":"Akhondzadeh et al. (2010)"}],"interacoes":[],"dose_maxima":"","acoes_principais":["Antidepressivo (inibição recaptação serotonina e dopamina — comparável à fluoxetina em estudos)","Ansiolítico","Afrodisíaco (documentado em estudos clínicos — melhora disfunção sexual induzida por antidepressivos)","Antioxidante (crocina — antioxidante hidrossolúvel único)","Neuroprotetor","Cardioprotetor","Antiespasmódico menstrual","Componentes ativos:","Indicações com evidência:","Contraindicações:","Gestação em doses medicinais — emenagogo e uterotônico (doses culinárias: seguras)","Anticoagulados — antiagregante plaquetário fraco","Doses > 5 g: tóxicas (tontura, xerostomia, vômitos) — improvável pelo custo"],"contraindicacoes":["Gestação em doses medicinais — emenagogo e uterotônico (doses culinárias: seguras)","Anticoagulados — antiagregante plaquetário fraco","Doses > 5 g: tóxicas (tontura, xerostomia, vômitos) — improvável pelo custo"],"efeitos_adversos":"","componentes_ativos":[{"label":"CROCINA (diglicosídeo de crocetina)","texto":"Antidepressivo, antioxidante, neuroprotetor, corante"},{"label":"CROCETINA","texto":"Cardioprotetor, neuroprotetor, antiproliferativo"},{"label":"SAFRANAL","texto":"Ansiolítico, antidepressivo, aromático"},{"label":"PICOCROCINA","texto":"Amargo característico, precursora do safranal"},{"label":"KAEMPFEROL","texto":"Antioxidante, anti-inflamatório"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"e4c2c46f-0696-4199-adee-8252b2a2fd77","slug":"baunilha","herb_id":null,"herb_latin_name":"Vanilla planifolia","schema_version":"1.1","ficha":{"slug":"baunilha","cultura":{"brasil":"A maior parte da \"baunilha\" consumida no Brasil é vanilina sintética (produto petroquímico) — sem a complexidade aromática da baunilha natural. O Brasil tem potencial de cultivo no AM e PA que quase não foi explorado.","historia":"A baunilha é a única especiaria nativa das Américas que conquistou o mundo inteiro — cravo e pimenta vieram da Ásia, canela do Ceilão, cardamomo da Índia. A baunilha saiu do México com os astecas que a usavam no xocolatl (chocolate) e chegou à Europa com Hernán Cortés em 1520.  O desafio da baunilha é a polinização — sua flor tem barreira física entre antera e estigma que impede autopolinização. No México, uma abelha nativa (Eulaema) realiza a polinização. Fora do México, sem esse inseto, a polinização é manual — cada flor, aberta apenas um dia, polinizada à mão. Em Madagascar (maior produtor mundial), centenas de agricultores polinizam à mão cada flor da produção. É o trabalho humano mais delicado da agricultura global.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"Cacau · Canela · Cardamomo · Leite de coco · Mel · Cúrcuma · Açafrão (blends premium quentes)","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"A orquídea do México — o único membro da família das orquídeas com uso alimentar global, com farmacologia de vanilina que vai muito além do aroma e uma história de cultivo artesanal extraordinária.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Cura das favas: 3–6 meses após colheita","status_anvisa":"Uso alimentar. Vanilina sintética: amplamente regulada.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Baunilha","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Baunilha · baunilha-do-méxico · vanila","Vanilla (inglês/francês/espanhol/alemão — universalmente emprestado do náhuatl tlilxochitl)","Tlilxochitl (náhuatl — \"flor preta\")"],"parte_usada":"Vagens (favas) curadas — o processo de cura (fermentação enzimática) produz a vanilina e todos os compostos aromáticos. Vagem verde não tem aroma.","tipo_botanico":"Especiaria aromática / ansiolítica / antioxidante","nome_cientifico":"Vanilla planifolia Andrews (sin.: V. fragrans)","familia_botanica":"Orchidaceae (orquídeas — família mais diversa das angiospermas)"},"caracterizacao":{"aroma":"Vanilina intensa (doce-floral-cremoso), heliotropina, coumarina leve, âmbar-madeira.","notas":"","intensidade":"3/5 — doce dominante, aromático sedante.","cor_da_infusao":"Âmbar-dourado pálido. #E0C878","bioma_de_origem":"","sabor_dominante":"Doce-cremoso suave, floral-amadeirado, vanilina quente, levemente defumado-curado. O doce mais reconhecível e amado do mundo.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Vanilla planifolia Andrews (sin.: V. fragrans)","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":["Ansiolítico leve (vanilina — modulação GABAérgica)","Antioxidante (vanilina — captadora de radicais livres)","Antimicrobiano (vanilina — conservante natural)","Anti-inflamatório","Neuroprotetor (estudos preliminares com vanilina)","Componentes ativos:","Contraindicações: Alergia à baunilha (rara). Sem contraindicações