ue,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"},{"id":"55fe3832-adcc-4973-add1-7b26b2a6cd09","slug":"noz-moscada","herb_id":null,"herb_latin_name":"Myristica fragrans","schema_version":"1.1","ficha":{"slug":"noz-moscada","cultura":{"brasil":"","historia":"A noz-moscada foi o centro de uma das maiores atrocidades do colonialismo europeu. As Ilhas Banda (Indonésia) eram as únicas produtoras mundiais de noz-moscada. Em 1621, a VOC holandesa, para manter o monopólio, massacrou quase toda a população das Ilhas Banda — de ~15.000 habitantes, restaram ~1.000. Um genocídio pela noz-moscada.  Na Inglaterra do séc. XVII–XVIII, a noz-moscada era misturada ao ponche e ao vinho quente dos aristocratas — acreditava-se que prevenia a praga. O interesse médico era real: em doses culinárias, tem ação antimicrobiana.","cerimonial":"","curiosidade":""},"preparo":{"metodo":"","quantidade":"","reinfusoes":"","combina_com":"","melhor_momento":"","tempo_de_infusao":"","temperatura_ideal":""},"tagline":"O alucinógeno da cozinha — a especiaria mais dual do catálogo, que em doses culinárias é nutritiva e aromática e em doses \"medicinais\" populares é tóxica e psicoativa, com farmacologia que explica ambos.","receitas":[],"regulacao":{"status_ema":"","status_fda":"","sazonalidade":"Frutos: colhidos maduros — Indonésia, Grenada","status_anvisa":"Uso alimentar. Sem monografia medicinal.","eixo_botanico_tpc":"Funcional global","certificacao_organica":""},"marketplace":{"formatos":"","fornecedores":"","faixa_de_preco":"","disponivel_a_venda":""},"nome_popular":"Noz-moscada","usos_topicos":{"evidencia":"","aplicacoes":[],"contraindicacoes":""},"identificacao":{"sinonimos":["Noz-moscada · nó-moscada","Nutmeg (inglês) · Noix de muscade (francês) · Muskatnuss (alemão)","Jaiphal (hindi) · Jouza tib (árabe)"],"parte_usada":"Semente seca ralada (nó-moscada); arilo vermelho da semente (macis — especiaria mais cara e suave).","tipo_botanico":"Especiaria aromática / digestivo / neurotóxica em doses altas","nome_cientifico":"Myristica fragrans Houtt.","familia_botanica":"Myristicaceae"},"caracterizacao":{"aroma":"Quente-especiado-amadeirado com nota de baunilha-cânfora. Profundo e sofisticado.","notas":"","intensidade":"3–4/5 — especiaria de presença marcante.","cor_da_infusao":"Âmbar-marrom quente. #C08838","bioma_de_origem":"","sabor_dominante":"Quente-apimentado-amadeirado, leve doce-baunilha, complexo e profundo. Reconhecível imediatamente em qualquer preparação.","distribuicao_geografica":[]},"schema_version":"1.1","nome_cientifico":"Myristica fragrans Houtt.","perfil_sensorial":{"tatil":"","gustativo":[],"trigeminal":[],"olfativo_familia":"","descricao_integrada":"","olfativo_descritores":[]},"acoes_e_seguranca":{"fontes":[],"evidencia":[],"interacoes":[],"dose_maxima":"","acoes_principais":[],"contraindicacoes":[],"efeitos_adversos":"","componentes_ativos":[{"label":"MIRISTICINA","texto":"4–8% do OE — Inseticida, sedativo leve; precursora de MMDA (anfetamina psicoativa) no metabolismo humano"},{"label":"ELEMICINA","texto":"0,2–2% — Psicoativa em doses altas"},{"label":"SAFROL","texto":"Traços — Carcinogênico em doses altas — limitado pela EFSA"},{"label":"EUGENOL","texto":"5–15% — Antimicrobiano, analgésico"},{"label":"MIRISTATO DE TRIMETILA","texto":"Presente — Sedativo"}]}},"status":"published","active":true,"created_by":null,"created_at":"2026-05-04T15:47:29.835697+00:00","updated_at":"2026-07-23T03:43:19.557795+00:00"}]$seed$::jsonb
