},{"id":"7d6cd75a-63e5-496a-8642-4cc08afa0370","name":"Taiwan — High Mountain Oolongs","description":"Ali Shan, Li Shan, Pinglin. Visitas a produtores independentes. Degustação de altitude. 8 pessoas máx.","category":"Viagens","price":8900,"unit":"5 dias/pessoa","icon":"🏔","supplier":"Tea Travels","stock":"in","image_url":null,"active":true,"created_by":null,"created_at":"2026-05-03T06:03:19.379385+00:00","updated_at":"2026-05-03T06:03:19.379385+00:00","source":"legacy","slug_ficha":null,"fornecedor_id_ref":null,"certificacoes":[],"origem_geografica":null,"observacao_cultural":null,"is_test":true,"images":[],"supplier_id":null,"weight_grams":100},{"id":"4a1f420e-9c59-414d-b6c8-6079f389ef64","name":"Darjeeling — Colheita First Flush","description":"Participação na colheita em fazenda histórica. Processamento artesanal. Degustação de 15 lotes diferentes.","category":"Viagens","price":9800,"unit":"6 dias/pessoa","icon":"🌱","supplier":"Tea Travels","stock":"in","image_url":null,"active":true,"created_by":null,"created_at":"2026-05-03T06:03:19.379385+00:00","updated_at":"2026-05-03T06:03:19.379385+00:00","source":"legacy","slug_ficha":null,"fornecedor_id_ref":null,"certificacoes":[],"origem_geografica":null,"observacao_cultural":null,"is_test":true,"images":[],"supplier_id":null,"weight_grams":100},{"id":"af612d52-3def-4b43-bd1c-c5f500522ff1","name":"Japão — Rota do Chá Kyoto-Uji","description":"Visita às plantações de Uji, cerimônia Urasenke, mercado Nishiki, chashitsu histórico. Guia especializado.","category":"Viagens","price":12500,"unit":"7 dias/pessoa","icon":"🗾","supplier":"Tea Travels","stock":"in","image_url":null,"active":true,"created_by":null,"created_at":"2026-05-03T06:03:19.379385+00:00","updated_at":"2026-05-03T06:03:19.379385+00:00","source":"legacy","slug_ficha":null,"fornecedor_id_ref":null,"certificacoes":[],"origem_geografica":null,"observacao_cultural":null,"is_test":true,"images":[],"supplier_id":null,"weight_grams":100},{"id":"f3725931-505f-4143-aa