ELSE
  INSERT INTO public.admin_blends
  SELECT * FROM jsonb_populate_recordset(
    NULL::public.admin_blends,
    $seed$[{"id":"8630252e-530d-4880-8c91-963eb77c2b47","slug":"infusao-do-sono-pampeano","blend_id":1,"nome":"Infusão do Sono Pampeano","proposito":null,"momento":null,"evidencia":"Moderada. Todos os quatro ingredientes têm indicação \"ansiolítico e sedativo leve\" na Farmacopeia Brasileira.","fonte":"Farmacopeia Brasileira — *Melissa officinalis*, *Cymbopogon citratus*, *Passiflora incarnata*, *Matricaria chamomilla*.","conteudo_markdown":"Infusão do Sono Pampeano\r\n\r\n**Propósito funcional:** Ansiolítico e indutor leve de sono.\r\n**Momento do dia:** Noite, 45–60 min antes de dormir.\r\n\r\n**Proporções**\r\n- 2 partes melissa (*Melissa officinalis*) · folhas e sumidades floridas secas\r\n- 2 partes capim-limão (*Cymbopogon citratus*) · folhas secas\r\n- 1 parte maracujá (*Passiflora incarnata*) · folhas secas\r\n- 1 parte camomila (*Matricaria chamomilla*) · inflorescências secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá do blend para 150 ml de água a 90–95 °C. Cobrir a xícara por 5–10 minutos. Coar e beber morno.\r\n\r\n**Evidência:** Moderada. Todos os quatro ingredientes têm indicação \"ansiolítico e sedativo leve\" na Farmacopeia Brasileira.\r\n\r\n**Advertências:** Não usar em gestantes, lactantes ou alérgicos à família Asteraceae (camomila). Potencialização de sedativos prescritos.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Melissa officinalis*, *Cymbopogon citratus*, *Passiflora incarnata*, *Matricaria chamomilla*.\r\n\r\n---","ervas_referenciadas":["melissa","capim-limao","maracuja","camomila"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"7ed7375f-6e1f-4417-9db5-4f20544dce0f","slug":"digestivo-pos-churrasco","blend_id":2,"nome":"Digestivo Pós-Churrasco","proposito":null,"momento":null,"evidencia":"Moderada-forte. Espinheira-santa é antidispéptico, antiácido e protetor da mucosa gástrica (Farmacopeia); hortelã-pimenta é antiespasmódica e antiflatulenta; erva-doce é antidispéptica e carminativa.","fonte":"Farmacopeia Brasileira — *Maytenus ilicifolia*, *Mentha × piperita*, *Pimpinella anisum*.","conteudo_markdown":"Digestivo Pós-Churrasco\r\n\r\n**Propósito funcional:** Antidispéptico e antiespasmódico, para refeições pesadas.\r\n**Momento do dia:** Após as refeições, especialmente as de carne.\r\n\r\n**Proporções**\r\n- 3 partes espinheira-santa (*Maytenus ilicifolia*) · folhas secas\r\n- 2 partes hortelã-pimenta (*Mentha × piperita*) · folhas secas\r\n- 1 parte erva-doce (*Pimpinella anisum*) · frutos (sementes) secos, levemente amassados antes do uso\r\n\r\n**Preparo**\r\nInfusão. Amassar ligeiramente os frutos de erva-doce imediatamente antes do preparo. 1 colher de chá para 150 ml de água a 95 °C. Cobrir por 10 minutos.\r\n\r\n**Evidência:** Moderada-forte. Espinheira-santa é antidispéptico, antiácido e protetor da mucosa gástrica (Farmacopeia); hortelã-pimenta é antiespasmódica e antiflatulenta; erva-doce é antidispéptica e carminativa.\r\n\r\n**Advertências:** Não usar em gestantes e lactantes (espinheira-santa). Não usar em casos de refluxo gastroesofágico grave (hortelã-pimenta pode agravar).\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Maytenus ilicifolia*, *Mentha × piperita*, *Pimpinella anisum*.\r\n\r\n---","ervas_referenciadas":["espinheira-santa","hortela-pimenta"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"67ee077d-4f17-4543-8e2f-9e92e6b1599b","slug":"clareza-e-memoria","blend_id":22,"nome":"Clareza e Memória","proposito":null,"momento":null,"evidencia":"Moderada. Alecrim tem evidência preliminar em memória de trabalho (estudos pequenos com inalação e ingestão). Sálvia tem evidência moderada para cognição em adultos jovens saudáveis. Ginkgo tem monografia EMA em distúrbios cognitivos leves.","fonte":"Mars (2006) — *Brain Power Tea* adaptado.","conteudo_markdown":"Clareza e Memória\r\n\r\n**Propósito funcional:** Tonificante cognitivo leve. Concentração para estudos e trabalho.\r\n**Momento do dia:** Manhã e meio da tarde, não após as 17h.\r\n\r\n**Proporções**\r\n- 2 partes alecrim · folhas secas\r\n- 1 parte sálvia · folhas secas\r\n- 1 parte hortelã-pimenta · folhas secas\r\n- ½ parte ginkgo · folhas secas *(opcional — ver advertências)*\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 200 ml de água a 95 °C. Cobrir por 7 min.\r\n\r\n**Evidência:** Moderada. Alecrim tem evidência preliminar em memória de trabalho (estudos pequenos com inalação e ingestão). Sálvia tem evidência moderada para cognição em adultos jovens saudáveis. Ginkgo tem monografia EMA em distúrbios cognitivos leves.\r\n\r\n**Advertências:** Ginkgo potencializa anticoagulantes — **não usar** em pessoas em uso de varfarina, aspirina em dose profilática ou cirurgia nas próximas 2 semanas. Sálvia contém tujona. Gestantes: evitar alecrim em dose alta.\r\n\r\n**Fonte:** Mars (2006) — *Brain Power Tea* adaptado.\r\n\r\n---\r\n\r\n# Anexo · Índice por propósito funcional\r\n\r\nPara alimentar a Roda dos Chás, os blends podem ser agrupados por categoria funcional:\r\n\r\n| Categoria | Blends |\r\n|---|---|\r\n| **Sono & calma** | 1 · Sono Pampeano · 14 · Mente Serena · 20 · Menopausa Equilibrada |\r\n| **Digestivo** | 2 · Pós-Churrasco · 4 · Cerradão · 7 · Hepatoprotetor · 10 · Gastrite · 12 · Tarde do Cerrado · 13 · Antiflatulência |\r\n| **Energia & foco** | 3 · Matinal da Mata · 18 · Atleta · 22 · Clareza e Memória |\r\n| **Feminino** | 9 · Cólica Menstrual · 20 · Menopausa |\r\n| **Respiratório** | 6 · Bronquite · 15 · Imune · 21 · Alergia Sazonal |\r\n| **Tópicos (uso externo)** | 5 · Garganta-Boa (bochecho) · 11 · Compressa Anti-Inflamatória |\r\n| **Específicos** | 8 · Quebra-Pedra · 19 · Calmante Infantil |\r\n| **Antioxidantes / cotidianos** | 17 · Fim de Tarde · 16 · Circulação |\r\n\r\n# Anexo · Relação blend × erva (para sistema de busca reverso)\r\n\r\nQuando um usuário tem uma erva em casa e quer saber em que blends ela aparece:\r\n\r\n| Erva | Blends |\r\n|---|---|\r\n| **Camomila** | 1 · 5 · 9 · 10 · 14 · 19 |\r\n| **Melissa** | 1 · 9 · 10 · 12 · 14 · 20 |\r\n| **Capim-limão** | 1 · 9 · 12 · 19 |\r\n| **Espinheira-santa** | 2 · 10 |\r\n| **Hortelã-pimenta** | 2 · 3 · 4 · 6 · 8 · 12 · 13 · 20 · 21 · 22 |\r\n| **Erva-doce** | 2 · 7 · 9 · 13 · 19 |\r\n| **Erva-mate** | 3 · 18 |\r\n| **Carqueja** | 4 |\r\n| **Alcachofra** | 4 · 7 |\r\n| **Calêndula** | 5 · 11 |\r\n| **Sálvia** | 5 · 20 · 22 |\r\n| **Guaco** | 6 |\r\n| **Boldo-do-chile** | 7 |\r\n| **Quebra-pedra** | 8 |\r\n| **Maracujá** | 1 |\r\n| **Arnica brasileira** | 11 |\r\n| **Canela** | 13 |\r\n| **Gengibre** | 13 · 15 · 16 · 18 |\r\n| **Lavanda** | 14 |\r\n| **Alecrim** | 14 · 17 · 21 · 22 |\r\n| **Equinácea** | 15 |\r\n| **Sabugueiro** | 15 |\r\n| **Hibisco** | 16 · 17 |\r\n| **Cavalinha** | 16 |\r\n| **Chá verde** | 17 |\r\n| **Urtiga** | 21 |\r\n| **Tanchagem** | 21 |\r\n| **Ginkgo** | 22 |\r\n\r\n# Anexo · Notas editoriais\r\n\r\n**Sobre \"usos não aprovados\":** Esta biblioteca limita-se às indicações documentadas na Farmacopeia Brasileira (ANVISA, 2011) e em monografias EMA/HMPC. Usos populares não monografados (ex.: \"chá de X para pressão alta\") não aparecem, por rigor do Teste 2 do Manifesto.\r\n\r\n**Sobre gestação e lactação:** Na dúvida, a regra é **não usar**. Apenas os blends 12, 15 e 17 poderiam ser considerados relativamente seguros em gestantes; ainda assim, recomenda-se orientação profissional para qualquer uso sistemático nessa fase.\r\n\r\n**Sobre crianças:** Exceto o blend 19 (especificamente formulado com dose reduzida para uso pediátrico sob orientação), nenhum outro blend é indicado para menores de 12 anos sem orientação profissional.\r\n\r\n**Sobre duração de uso:** Nenhum blend desta biblioteca é indicado para uso crônico (> 30 dias contínuos). Fitoterapia não é reposição de terapia medicamentosa de uso contínuo.\r\n\r\n---\r\n\r\n## Próxima iteração (v1.1)\r\n\r\nFicam para a versão seguinte desta biblioteca:\r\n\r\n1. Blends com ervas amazônicas não listadas na Farmacopeia (açaí, guaraná da Amazônia fresco, cupuaçu) — exigem fontes primárias adicionais\r\n2. Blends sazonais — infusões temáticas para solstícios, equinócios, datas ritualísticas\r\n3. Blends de terroir específico — valorizando produtores parceiros do Vale do Ribeira e comunidades tradicionais\r\n4. Blends esportivos com protocolo de dosagem pré/durante/pós-treino\r\n5. Blends de cerimônia para o Clube das Chazerias (foco em experiência compartilhada, não em função terapêutica individual)\r\n\r\n---\r\n\r\n*Ervatório · Biblioteca de Blends v1.0 · Abril 2026*\r\n*Fontes: Farmacopeia Brasileira, Formulário de Fitoterápicos (Anvisa, 2011) · Brigitte Mars, Healing Herbal Teas (2006) · monografias EMA/HMPC quando aplicável.*","ervas_referenciadas":["alecrim","salvia","hortela-pimenta","ginkgo"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"ac488f7b-6151-48a2-885f-1f5c5364a534","slug":"tonico-matinal-da-mata","blend_id":3,"nome":"Tônico Matinal da Mata","proposito":null,"momento":null,"evidencia":"Moderada para mate; moderada para hortelã como antiespasmódico digestivo; tradicional para associação com limão-siciliano.","fonte":"Mars (2006) para *Ilex paraguariensis*; Farmacopeia Brasileira — *Mentha × piperita*.","conteudo_markdown":"Tônico Matinal da Mata\r\n\r\n**Propósito funcional:** Estimulante suave, antioxidante. Alternativa botânica ao café da manhã.\r\n**Momento do dia:** Manhã, antes ou durante o café.\r\n\r\n**Proporções**\r\n- 3 partes erva-mate (*Ilex paraguariensis*) · folhas secas tostadas\r\n- 1 parte hortelã (*Mentha × piperita*) · folhas secas\r\n- 1 parte casca de limão-siciliano seca *(aromático — não medicinal)*\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá bem cheia para 200 ml de água a 80 °C (mate não tolera água fervente plena — destrói clorofila e concentra amargor). Infundir por 5 minutos. Pode ser reinfundido 2 vezes.\r\n\r\n**Evidência:** Moderada para mate; moderada para hortelã como antiespasmódico digestivo; tradicional para associação com limão-siciliano.\r\n\r\n**Advertências:** Contém cafeína natural. Não usar em pessoas com ansiedade, hipertensão, arritmias, gastrite ou úlcera ativa. Evitar após as 16h em sensíveis ao estímulo.\r\n\r\n**Fonte:** Mars (2006) para *Ilex paraguariensis*; Farmacopeia Brasileira — *Mentha × piperita*.\r\n\r\n---","ervas_referenciadas":["erva-mate","hortela-pimenta"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"2564d1c5-8abb-4173-999b-0fc76973d2aa","slug":"emagrecimento-cerradao","blend_id":4,"nome":"Emagrecimento Cerradão","proposito":null,"momento":null,"evidencia":"Moderada. Carqueja e alcachofra têm indicação antidispéptica na Farmacopeia; ambas estimulam a produção de bile (ação colagoga / colerética).","fonte":"Farmacopeia Brasileira — *Baccharis trimera*, *Cynara scolymus*, *Mentha × piperita*.","conteudo_markdown":"Emagrecimento Cerradão\r\n\r\n**Propósito funcional:** Coadjuvante em dietas. Hepatoprotetor, antidispéptico, diurético leve.\r\n**Momento do dia:** Antes do almoço e antes do jantar.\r\n\r\n**Proporções**\r\n- 2 partes carqueja (*Baccharis trimera*) · partes aéreas secas\r\n- 2 partes alcachofra (*Cynara scolymus*) · folhas secas\r\n- 1 parte hortelã-pimenta (*Mentha × piperita*) · folhas secas *(para tornar o sabor aceitável)*\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 150 ml de água a 95 °C. Cobrir por 10 minutos. Sabor marcadamente amargo — a amargura é parte da ação colagoga.\r\n\r\n**Evidência:** Moderada. Carqueja e alcachofra têm indicação antidispéptica na Farmacopeia; ambas estimulam a produção de bile (ação colagoga / colerética).\r\n\r\n**Advertências:** Contraindicado para pessoas com cálculos biliares, obstrução dos ductos biliares, em uso de anticoagulantes, gestantes, lactantes, hipertensos (carqueja pode causar hipotensão), diabéticos em tratamento medicamentoso. **Uso somente com acompanhamento profissional.**\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Baccharis trimera*, *Cynara scolymus*, *Mentha × piperita*.\r\n\r\n---","ervas_referenciadas":["carqueja","alcachofra","hortela-pimenta"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"1c9bfb1d-9a26-4a44-bd29-6371d1adf639","slug":"garganta-boa-bochecho","blend_id":5,"nome":"Garganta-Boa (Bochecho)","proposito":null,"momento":null,"evidencia":"Moderada. Calêndula é anti-inflamatória e cicatrizante (Farmacopeia, uso externo); camomila é anti-inflamatória em afecções da cavidade oral (Farmacopeia, uso externo); sálvia é tradicionalmente usada para mucosa oral (Mars).","fonte":"Farmacopeia Brasileira — *Calendula officinalis*, *Matricaria chamomilla*. Mars (2006) para *Salvia officinalis*.","conteudo_markdown":"Garganta-Boa (Bochecho)\r\n\r\n**Propósito funcional:** Anti-inflamatório para mucosa oral e garganta. Aplicação tópica.\r\n**Momento do dia:** Conforme necessidade, 3 vezes ao dia.\r\n\r\n**Proporções**\r\n- 2 partes calêndula (*Calendula officinalis*) · flores secas\r\n- 2 partes camomila (*Matricaria chamomilla*) · inflorescências secas\r\n- 1 parte sálvia (*Salvia officinalis*) · folhas secas\r\n\r\n**Preparo**\r\nInfusão forte (dobrar a dose): 2 colheres de chá para 150 ml de água a 95 °C. Cobrir por 10 minutos. Deixar amornar. **Bochechar e/ou gargarejar** por 30–60 segundos, 3 vezes ao dia, após escovar os dentes. **Não engolir.**\r\n\r\n**Evidência:** Moderada. Calêndula é anti-inflamatória e cicatrizante (Farmacopeia, uso externo); camomila é anti-inflamatória em afecções da cavidade oral (Farmacopeia, uso externo); sálvia é tradicionalmente usada para mucosa oral (Mars).\r\n\r\n**Advertências:** Uso externo apenas. Contraindicado para alérgicos à família Asteraceae.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Calendula officinalis*, *Matricaria chamomilla*. Mars (2006) para *Salvia officinalis*.\r\n\r\n---","ervas_referenciadas":["calendula","camomila","salvia"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"7f7edcc7-c4c9-4271-a38d-47da20cfd047","slug":"bronquite-do-inverno","blend_id":6,"nome":"Bronquite do Inverno","proposito":null,"momento":null,"evidencia":"Moderada. Guaco é expectorante e broncodilatador na Farmacopeia Brasileira, com monografia específica.","fonte":"Farmacopeia Brasileira — *Mikania glomerata*, *Mentha × piperita*.","conteudo_markdown":"Bronquite do Inverno\r\n\r\n**Propósito funcional:** Expectorante e broncodilatador leve. Coadjuvante em quadros respiratórios.\r\n**Momento do dia:** 3 vezes ao dia durante crise.\r\n\r\n**Proporções**\r\n- 3 partes guaco (*Mikania glomerata*) · folhas secas\r\n- 1 parte hortelã-pimenta (*Mentha × piperita*) · folhas secas\r\n- 1 parte casca de laranja seca *(aromático)*\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 150 ml de água a 95 °C. Cobrir por 10 minutos. Beber morno, 3 vezes ao dia durante o episódio, por até 7 dias.\r\n\r\n**Evidência:** Moderada. Guaco é expectorante e broncodilatador na Farmacopeia Brasileira, com monografia específica.\r\n\r\n**Advertências:** Não usar em gestantes, lactantes ou em uso de anticoagulantes (guaco contém cumarinas, que potencializam varfarina). Suspender em caso de sangramento espontâneo. Não usar por mais de 7 dias consecutivos sem reavaliação.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Mikania glomerata*, *Mentha × piperita*.\r\n\r\n---","ervas_referenciadas":["guaco","hortela-pimenta"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"59b02485-5025-426e-a899-afd96258f03f","slug":"hepatoprotetor-do-sertao","blend_id":7,"nome":"Hepatoprotetor do Sertão","proposito":null,"momento":null,"evidencia":"Moderada. Boldo e alcachofra têm indicação antidispéptica e colagoga/colerética na Farmacopeia.","fonte":"Farmacopeia Brasileira — *Peumus boldus*, *Cynara scolymus*, *Pimpinella anisum*.","conteudo_markdown":"Hepatoprotetor do Sertão\r\n\r\n**Propósito funcional:** Antidispéptico e suporte à função hepática.\r\n**Momento do dia:** Antes das refeições.\r\n\r\n**Proporções**\r\n- 2 partes boldo-do-chile (*Peumus boldus*) · folhas secas\r\n- 2 partes alcachofra (*Cynara scolymus*) · folhas secas\r\n- 1 parte erva-doce (*Pimpinella anisum*) · frutos secos\r\n\r\n**Preparo**\r\nInfusão **sem abafar** (boldo exige xícara descoberta — óleos essenciais voláteis muito ativos amargam se mantidos cobertos). 1 colher de chá para 150 ml de água a 90 °C. Infundir por 10 minutos sem tampa. Coar.\r\n\r\n**Evidência:** Moderada. Boldo e alcachofra têm indicação antidispéptica e colagoga/colerética na Farmacopeia.\r\n\r\n**Advertências:** Contraindicado para cálculos biliares, obstrução dos ductos biliares, doenças hepáticas severas, gestantes, lactantes, em uso de anticoagulantes. Não exceder a dosagem — boldo contém ascaridol e pode ser hepatotóxico em doses altas.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Peumus boldus*, *Cynara scolymus*, *Pimpinella anisum*.\r\n\r\n---","ervas_referenciadas":["boldo-do-chile","alcachofra"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"7ec90d37-a58d-4d00-ab08-eddf76bf7b69","slug":"quebra-pedra-do-nordeste","blend_id":8,"nome":"Quebra-Pedra do Nordeste","proposito":null,"momento":null,"evidencia":"Moderada. Quebra-pedra tem indicação litolítica na Farmacopeia Brasileira.","fonte":"Farmacopeia Brasileira — *Phyllanthus niruri*, *Mentha × piperita*.","conteudo_markdown":"Quebra-Pedra do Nordeste\r\n\r\n**Propósito funcional:** Litolítico coadjuvante em litíase urinária. Diurético suave.\r\n**Momento do dia:** 2–3 vezes ao dia, longe das refeições.\r\n\r\n**Proporções**\r\n- 3 partes quebra-pedra (*Phyllanthus niruri*) · partes aéreas secas\r\n- 1 parte hortelã (*Mentha × piperita*) · folhas secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá do blend para 150 ml de água a 95 °C. Cobrir por 10 minutos.\r\n\r\n**Evidência:** Moderada. Quebra-pedra tem indicação litolítica na Farmacopeia Brasileira.\r\n\r\n**Advertências:** Não usar em gestantes. Concentrações acima da recomendada podem causar diarreia e hipotensão. **Uso apenas sob orientação médica** em casos confirmados de litíase — nefrolitíase é condição que exige diagnóstico profissional.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Phyllanthus niruri*, *Mentha × piperita*.\r\n\r\n---","ervas_referenciadas":["quebra-pedra","hortela-pimenta"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"71254bd3-2b62-45c5-ab84-6aaf0498ae2c","slug":"infusao-da-colica-menstrual","blend_id":9,"nome":"Infusão da Cólica Menstrual","proposito":null,"momento":null,"evidencia":"Moderada. Camomila e capim-limão têm indicação antiespasmódica; melissa é antiespasmódica e ansiolítica; erva-doce é antidispéptica (ajuda com inchaço menstrual).","fonte":"Farmacopeia Brasileira — *Matricaria chamomilla*, *Melissa officinalis*, *Pimpinella anisum*, *Cymbopogon citratus*.","conteudo_markdown":"Infusão da Cólica Menstrual\r\n\r\n**Propósito funcional:** Antiespasmódico para dismenorreia. Calmante leve.\r\n**Momento do dia:** Início dos sintomas; até 3 vezes ao dia.\r\n\r\n**Proporções**\r\n- 2 partes camomila (*Matricaria chamomilla*) · inflorescências secas\r\n- 2 partes melissa (*Melissa officinalis*) · folhas secas\r\n- 1 parte erva-doce (*Pimpinella anisum*) · frutos secos\r\n- 1 parte capim-limão (*Cymbopogon citratus*) · folhas secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 150 ml de água a 90–95 °C. Cobrir por 10 minutos.\r\n\r\n**Evidência:** Moderada. Camomila e capim-limão têm indicação antiespasmódica; melissa é antiespasmódica e ansiolítica; erva-doce é antidispéptica (ajuda com inchaço menstrual).\r\n\r\n**Advertências:** Alergia à família Asteraceae (camomila). Potencialização de sedativos.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Matricaria chamomilla*, *Melissa officinalis*, *Pimpinella anisum*, *Cymbopogon citratus*.\r\n\r\n---","ervas_referenciadas":["camomila","melissa","capim-limao"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"7996a50c-0448-4fab-9929-93a004214bc3","slug":"gastrite-acalmada","blend_id":10,"nome":"Gastrite Acalmada","proposito":null,"momento":null,"evidencia":"Moderada. Espinheira-santa é antidispéptica, antiácida e protetora da mucosa gástrica (Farmacopeia). Camomila e melissa adicionam ação antiespasmódica e ansiolítica — útil em gastrites com componente emocional.","fonte":"Farmacopeia Brasileira — *Maytenus ilicifolia*, *Melissa officinalis*, *Matricaria chamomilla*.","conteudo_markdown":"Gastrite Acalmada\r\n\r\n**Propósito funcional:** Protetor da mucosa gástrica em episódios de gastrite, refluxo leve e indigestão.\r\n**Momento do dia:** 30 min antes das refeições e antes de dormir.\r\n\r\n**Proporções**\r\n- 3 partes espinheira-santa (*Maytenus ilicifolia*) · folhas secas\r\n- 2 partes melissa (*Melissa officinalis*) · folhas secas\r\n- 1 parte camomila (*Matricaria chamomilla*) · inflorescências secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 150 ml de água a 95 °C. Cobrir por 10 minutos. Beber morno.\r\n\r\n**Evidência:** Moderada. Espinheira-santa é antidispéptica, antiácida e protetora da mucosa gástrica (Farmacopeia). Camomila e melissa adicionam ação antiespasmódica e ansiolítica — útil em gastrites com componente emocional.\r\n\r\n**Advertências:** Não usar em gestantes, lactantes ou alérgicos à Asteraceae. Se sintomas persistirem além de 2 semanas, buscar avaliação médica — pode mascarar patologia mais séria.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Maytenus ilicifolia*, *Melissa officinalis*, *Matricaria chamomilla*.\r\n\r\n---","ervas_referenciadas":["espinheira-santa","melissa","camomila"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"1b00d570-472a-4abd-8957-aac0b9937195","slug":"compressa-anti-inflamatoria-uso-externo","blend_id":11,"nome":"Compressa Anti-Inflamatória (Uso Externo)","proposito":null,"momento":null,"evidencia":"Moderada. Arnica brasileira tem indicação anti-inflamatória em contusões, equimoses e hematomas na Farmacopeia (uso externo, compressa). Calêndula é anti-inflamatória e cicatrizante (Farmacopeia, uso externo).","fonte":"Farmacopeia Brasileira — *Solidago microglossa*, *Calendula officinalis*.","conteudo_markdown":"Compressa Anti-Inflamatória (Uso Externo)\r\n\r\n**Propósito funcional:** Anti-inflamatório tópico para contusões, hematomas e distensões.\r\n**Momento do dia:** 2–3 vezes ao dia na área afetada.\r\n\r\n**Proporções**\r\n- 3 partes arnica brasileira (*Solidago microglossa*) · partes aéreas secas\r\n- 2 partes calêndula (*Calendula officinalis*) · flores secas\r\n\r\n**Preparo**\r\nInfusão forte. 2 colheres de chá para 150 ml de água a 95 °C. Cobrir por 15 minutos. Deixar amornar. Embeber gaze ou pano limpo. Aplicar em compressa por 15–20 minutos sobre a região, 2–3 vezes ao dia.\r\n\r\n**Evidência:** Moderada. Arnica brasileira tem indicação anti-inflamatória em contusões, equimoses e hematomas na Farmacopeia (uso externo, compressa). Calêndula é anti-inflamatória e cicatrizante (Farmacopeia, uso externo).\r\n\r\n**Advertências:** **Uso externo apenas.** Não aplicar sobre lesões abertas. Não usar por mais de 7 dias consecutivos. Pode provocar reações alérgicas com formação de vesículas. Alérgicos à Asteraceae contraindicados.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Solidago microglossa*, *Calendula officinalis*.\r\n\r\n---","ervas_referenciadas":["solidago","calendula"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"21ed5c30-5d14-4576-ad4a-b5fdc0e2abe4","slug":"infusao-da-tarde-do-cerrado","blend_id":12,"nome":"Infusão da Tarde do Cerrado","proposito":null,"momento":null,"evidencia":"Moderada. Todos os três ingredientes têm indicação antiespasmódica e ansiolítica leve na Farmacopeia Brasileira. Combinação clássica da medicina popular brasileira para relaxamento pós-refeição.","fonte":"Farmacopeia Brasileira — *Cymbopogon citratus*, *Melissa officinalis*, *Mentha × piperita*.","conteudo_markdown":"Infusão da Tarde do Cerrado\r\n\r\n**Propósito funcional:** Relaxante digestivo pós-almoço. Uso cotidiano.\r\n**Momento do dia:** Após o almoço ou no meio da tarde.\r\n\r\n**Proporções**\r\n- 2 partes capim-limão (*Cymbopogon citratus*) · folhas secas\r\n- 2 partes melissa (*Melissa officinalis*) · folhas secas\r\n- 1 parte hortelã-pimenta (*Mentha × piperita*) · folhas secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 150 ml de água a 90 °C. Cobrir por 5–7 minutos.\r\n\r\n**Evidência:** Moderada. Todos os três ingredientes têm indicação antiespasmódica e ansiolítica leve na Farmacopeia Brasileira. Combinação clássica da medicina popular brasileira para relaxamento pós-refeição.\r\n\r\n**Advertências:** Não usar em casos de refluxo gastroesofágico grave (hortelã). Potencialização de sedativos.\r\n\r\n**Fonte:** Farmacopeia Brasileira — *Cymbopogon citratus*, *Melissa officinalis*, *Mentha × piperita*.\r\n\r\n---\r\n\r\n# 🌍 Blends de Tradição Internacional\r\n\r\nReceitas adaptadas de Brigitte Mars (*Healing Herbal Teas*, 2006), com nomenclatura recriada em português brasileiro, proporções simplificadas e advertências checadas contra a Farmacopeia Brasileira quando o ingrediente é monografado aqui.\r\n\r\n---","ervas_referenciadas":["capim-limao","melissa","hortela-pimenta"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"3ec3e76a-2bd6-482f-a678-2bd8d0dc7862","slug":"antiflatulencia-classica","blend_id":13,"nome":"Antiflatulência Clássica","proposito":null,"momento":null,"evidencia":"Moderada. Hortelã é antiespasmódica e antiflatulenta; canela é aperiente, antiespasmódica e antiflatulenta; erva-doce é antidispéptica; gengibre é antidispéptico e anti-inflamatório (todos na Farmacopeia Brasileira).","fonte":"Mars (2006) — *Antiflatulence Tea*. Validação: Farmacopeia Brasileira para os quatro ingredientes.","conteudo_markdown":"Antiflatulência Clássica\r\n\r\n**Propósito funcional:** Carminativo — alívio de gases e inchaço.\r\n**Momento do dia:** Após refeições que causem desconforto.\r\n\r\n**Proporções**\r\n- 2 partes hortelã-pimenta · folhas secas\r\n- 1 parte canela · casca seca em lasca\r\n- 1 parte erva-doce · frutos secos\r\n- 1 parte gengibre · rizoma seco\r\n\r\n**Preparo**\r\nDecocção leve. Colocar canela e gengibre em 200 ml de água fervente, deixar ferver em fogo baixo por 3 min. Desligar, acrescentar hortelã e erva-doce, cobrir por 7 min. Coar.\r\n\r\n**Evidência:** Moderada. Hortelã é antiespasmódica e antiflatulenta; canela é aperiente, antiespasmódica e antiflatulenta; erva-doce é antidispéptica; gengibre é antidispéptico e anti-inflamatório (todos na Farmacopeia Brasileira).\r\n\r\n**Advertências:** Não usar em gestantes (canela, gengibre em altas doses). Evitar em refluxo gastroesofágico grave.\r\n\r\n**Fonte:** Mars (2006) — *Antiflatulence Tea*. Validação: Farmacopeia Brasileira para os quatro ingredientes.\r\n\r\n---","ervas_referenciadas":["hortela-pimenta","canela-do-ceilao","gengibre"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"a4d6ca28-412c-4e84-8757-9efc1e10d976","slug":"mente-serena","blend_id":14,"nome":"Mente Serena","proposito":null,"momento":null,"evidencia":"Moderada. Melissa e camomila com indicação ansiolítica na Farmacopeia; lavanda é tradicional para ansiedade (monografia EMA/HMPC); alecrim é tonificante cognitivo leve (tradicional, Mars).","fonte":"Mars (2006) — adaptação de *Sleep Tea*. Farmacopeia Brasileira — *Melissa officinalis*, *Matricaria chamomilla*.","conteudo_markdown":"Mente Serena\r\n\r\n**Propósito funcional:** Ansiolítico suave. Clareza mental sem estímulo.\r\n**Momento do dia:** Qualquer hora, especialmente em momentos de tensão.\r\n\r\n**Proporções**\r\n- 2 partes melissa · folhas e sumidades floridas secas\r\n- 2 partes camomila · inflorescências secas\r\n- 1 parte lavanda · flores secas\r\n- 1 parte alecrim · folhas secas *(em quantidade pequena — o alecrim é estimulante cognitivo leve)*\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 150 ml de água a 90 °C. Cobrir por 7–10 min.\r\n\r\n**Evidência:** Moderada. Melissa e camomila com indicação ansiolítica na Farmacopeia; lavanda é tradicional para ansiedade (monografia EMA/HMPC); alecrim é tonificante cognitivo leve (tradicional, Mars).\r\n\r\n**Advertências:** Alergia à Asteraceae (camomila). Gestantes: evitar alecrim em dose elevada.\r\n\r\n**Fonte:** Mars (2006) — adaptação de *Sleep Tea*. Farmacopeia Brasileira — *Melissa officinalis*, *Matricaria chamomilla*.\r\n\r\n---","ervas_referenciadas":["melissa","camomila","lavanda","alecrim"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"8fed5c70-0749-48bb-bf1a-469884de7121","slug":"sistema-imune","blend_id":15,"nome":"Sistema Imune","proposito":null,"momento":null,"evidencia":"Moderada para equinácea (imunomoduladora, tradição europeia e indígena norte-americana); moderada para sabugueiro em resfriado comum (evidência clínica em estudos pequenos).","fonte":"Mars (2006) — *Cold and Flu Tea* adaptado. Complemento Farmacopeia para gengibre.","conteudo_markdown":"Sistema Imune\r\n\r\n**Propósito funcional:** Coadjuvante em episódios virais leves — coriza, resfriado, garganta irritada.\r\n**Momento do dia:** 3 vezes ao dia no início dos sintomas.\r\n\r\n**Proporções**\r\n- 2 partes equinácea · raízes e folhas secas\r\n- 1 parte gengibre · rizoma seco\r\n- 1 parte sabugueiro · frutos secos (elderberry)\r\n- 1 parte casca de laranja seca\r\n\r\n**Preparo**\r\nDecocção mista. Equinácea e gengibre: decocção em 200 ml de água fervente por 5 min. Desligar, acrescentar sabugueiro e laranja, cobrir por 10 min. Coar.\r\n\r\n**Evidência:** Moderada para equinácea (imunomoduladora, tradição europeia e indígena norte-americana); moderada para sabugueiro em resfriado comum (evidência clínica em estudos pequenos).\r\n\r\n**Advertências:** Contraindicado para pessoas com doenças autoimunes (lúpus, esclerose múltipla, artrite reumatoide). Não usar por mais de 10 dias consecutivos. Gestantes: apenas sob orientação.\r\n\r\n**Fonte:** Mars (2006) — *Cold and Flu Tea* adaptado. Complemento Farmacopeia para gengibre.\r\n\r\n---","ervas_referenciadas":["equinacea","gengibre","sabugueiro"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"15302c57-5613-46a8-87ab-2d77eaa25dc7","slug":"circulacao-nas-pernas","blend_id":16,"nome":"Circulação nas Pernas","proposito":null,"momento":null,"evidencia":"Moderada para cavalinha como diurético suave (monografia EMA); tradicional para hibisco (pressão leve, efeito diurético suave).","fonte":"Mars (2006) — *Circulation Tea* adaptado.","conteudo_markdown":"Circulação nas Pernas\r\n\r\n**Propósito funcional:** Coadjuvante para sensação de pernas pesadas, retenção leve.\r\n**Momento do dia:** Tarde, após períodos longos em pé ou sentado.\r\n\r\n**Proporções**\r\n- 2 partes hibisco · cálices secos\r\n- 1 parte gengibre · rizoma seco\r\n- 1 parte cavalinha · partes aéreas secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 200 ml de água a 95 °C. Cobrir por 10 min.\r\n\r\n**Evidência:** Moderada para cavalinha como diurético suave (monografia EMA); tradicional para hibisco (pressão leve, efeito diurético suave).\r\n\r\n**Advertências:** Não usar em gestantes, lactantes ou em uso de anticoagulantes. Cavalinha não deve ser usada por mais de 4 semanas consecutivas (alcaloides).\r\n\r\n**Fonte:** Mars (2006) — *Circulation Tea* adaptado.\r\n\r\n---","ervas_referenciadas":["hibisco","gengibre","cavalinha"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"9055b5ed-d918-4802-9f94-924f4732b18a","slug":"antioxidante-do-fim-de-tarde","blend_id":17,"nome":"Antioxidante do Fim de Tarde","proposito":null,"momento":null,"evidencia":"Moderada. Chá verde é rico em catequinas antioxidantes (EGCG, evidência forte em laboratório; moderada clínica); hibisco é rico em antocianinas; alecrim contém ácido carnósico (antioxidante potente).","fonte":"Mars (2006) — *Antioxidant Tea* adaptado.","conteudo_markdown":"Antioxidante do Fim de Tarde\r\n\r\n**Propósito funcional:** Antioxidante. Uso cotidiano como ritual sensorial.\r\n**Momento do dia:** Final de tarde, entre 16h e 18h.\r\n\r\n**Proporções**\r\n- 2 partes chá verde (*Camellia sinensis*) · folhas secas\r\n- 1 parte hibisco · cálices secos\r\n- 1 parte casca de limão-siciliano seca\r\n- ½ parte alecrim · folhas secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 200 ml de água a **75 °C** (nunca mais quente — chá verde queima e amarga acima de 80 °C). Infundir por 2–3 minutos. Reinfundível 2 vezes.\r\n\r\n**Evidência:** Moderada. Chá verde é rico em catequinas antioxidantes (EGCG, evidência forte em laboratório; moderada clínica); hibisco é rico em antocianinas; alecrim contém ácido carnósico (antioxidante potente).\r\n\r\n**Advertências:** Chá verde contém cafeína — evitar após 17h em sensíveis ao estímulo. Evitar em pessoas com anemia ferropriva (polifenóis reduzem absorção de ferro quando tomado com refeição).\r\n\r\n**Fonte:** Mars (2006) — *Antioxidant Tea* adaptado.\r\n\r\n---","ervas_referenciadas":["cha-verde-matcha","hibisco","alecrim"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"9a1540b9-da89-4fda-a5e2-c60280c77d27","slug":"infusao-do-atleta","blend_id":18,"nome":"Infusão do Atleta","proposito":null,"momento":null,"evidencia":"Moderada. Erva-mate tem cafeína, teobromina e teofilina — estimulante com curva de liberação mais suave que o café. Gengibre tem propriedades anti-inflamatórias e antieméticas.","fonte":"Mars (2006) — *Athlete's Tea* adaptado.","conteudo_markdown":"Infusão do Atleta\r\n\r\n**Propósito funcional:** Estimulante para endurance. Pré ou durante atividade física prolongada.\r\n**Momento do dia:** 30 min antes de atividade física longa.\r\n\r\n**Proporções**\r\n- 2 partes erva-mate · folhas secas tostadas\r\n- 1 parte gengibre · rizoma seco\r\n- 1 parte casca de laranja seca\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá bem cheia para 250 ml de água a 80 °C. Infundir por 5 min. Pode ser consumido frio.\r\n\r\n**Evidência:** Moderada. Erva-mate tem cafeína, teobromina e teofilina — estimulante com curva de liberação mais suave que o café. Gengibre tem propriedades anti-inflamatórias e antieméticas.\r\n\r\n**Advertências:** Não usar em cardiopatas, hipertensos descontrolados, pessoas com arritmias. Contém cafeína.\r\n\r\n**Fonte:** Mars (2006) — *Athlete's Tea* adaptado.\r\n\r\n---","ervas_referenciadas":["erva-mate","gengibre"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"13c3700a-3560-406d-a1bf-9c0ffce19a84","slug":"calmante-infantil-6-meses","blend_id":19,"nome":"Calmante Infantil (6 meses+)","proposito":null,"momento":null,"evidencia":"Moderada. Camomila é indicada para cólica em lactentes na Farmacopeia e tem evidência clínica moderada. Erva-doce é tradicionalmente indicada para cólica infantil.","fonte":"Mars (2006) — *Baby Calm Tea* adaptado. Farmacopeia Brasileira — *Matricaria chamomilla*, *Pimpinella anisum*, *Cymbopogon citratus*.","conteudo_markdown":"Calmante Infantil (6 meses+)\r\n\r\n**Propósito funcional:** Cólica e irritabilidade em bebês (6+ meses) e crianças pequenas, sob orientação pediátrica.\r\n**Momento do dia:** Até 2 vezes ao dia conforme necessidade.\r\n\r\n**Proporções**\r\n- 2 partes camomila · inflorescências secas\r\n- 2 partes erva-doce · frutos secos\r\n- 1 parte capim-limão · folhas secas\r\n\r\n**Preparo**\r\nInfusão fraca. ½ colher de chá para 150 ml de água a 90 °C. Cobrir por 5 min. **Servir morno** (nunca quente). Oferecer em quantidade pequena (30–50 ml por vez para bebês; 100 ml para crianças maiores).\r\n\r\n**Evidência:** Moderada. Camomila é indicada para cólica em lactentes na Farmacopeia e tem evidência clínica moderada. Erva-doce é tradicionalmente indicada para cólica infantil.\r\n\r\n**Advertências:** **Usar apenas sob orientação pediátrica.** Não usar em bebês menores de 6 meses. Alergia à Asteraceae contraindica. Não substitui leite materno ou fórmula.\r\n\r\n**Fonte:** Mars (2006) — *Baby Calm Tea* adaptado. Farmacopeia Brasileira — *Matricaria chamomilla*, *Pimpinella anisum*, *Cymbopogon citratus*.\r\n\r\n---","ervas_referenciadas":["camomila","capim-limao"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"e9574d73-2768-43cf-a1aa-32bb1993d432","slug":"menopausa-equilibrada","blend_id":20,"nome":"Menopausa Equilibrada","proposito":null,"momento":null,"evidencia":"Moderada para sálvia em fogachos menopausais (monografia EMA/HMPC, estudos clínicos pequenos); moderada para melissa em insônia e ansiedade.","fonte":"Mars (2006) — *Menopause Tea* adaptado.","conteudo_markdown":"Menopausa Equilibrada\r\n\r\n**Propósito funcional:** Coadjuvante para fogachos, irritabilidade e insônia leve no climatério.\r\n**Momento do dia:** 2 vezes ao dia — manhã e início da noite.\r\n\r\n**Proporções**\r\n- 2 partes sálvia · folhas secas\r\n- 2 partes melissa · folhas secas\r\n- 1 parte hortelã · folhas secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 200 ml de água a 95 °C. Cobrir por 10 min.\r\n\r\n**Evidência:** Moderada para sálvia em fogachos menopausais (monografia EMA/HMPC, estudos clínicos pequenos); moderada para melissa em insônia e ansiedade.\r\n\r\n**Advertências:** Não usar em gestantes, lactantes ou em epilepsia (sálvia contém tujona, neurotóxica em altas doses crônicas). Não usar por mais de 4 semanas consecutivas sem reavaliação.\r\n\r\n**Fonte:** Mars (2006) — *Menopause Tea* adaptado.\r\n\r\n---","ervas_referenciadas":["salvia","melissa","hortela-pimenta"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"},{"id":"1d3a9851-566b-4984-a75a-cc46f90ad1fe","slug":"alivio-de-alergia-sazonal","blend_id":21,"nome":"Alívio de Alergia Sazonal","proposito":null,"momento":null,"evidencia":"Moderada para urtiga em rinite alérgica (monografia EMA/HMPC; estudos clínicos pequenos com resultados positivos). Tanchagem tem indicação expectorante e anti-inflamatória na Farmacopeia Brasileira.","fonte":"Mars (2006) — *Allergy Relief Tea* adaptado.","conteudo_markdown":"Alívio de Alergia Sazonal\r\n\r\n**Propósito funcional:** Coadjuvante em rinite alérgica e crises de hay fever.\r\n**Momento do dia:** 2–3 vezes ao dia durante o período de pólens.\r\n\r\n**Proporções**\r\n- 2 partes urtiga · folhas secas\r\n- 1 parte tanchagem · folhas secas\r\n- 1 parte alecrim · folhas secas\r\n- 1 parte hortelã-pimenta · folhas secas\r\n\r\n**Preparo**\r\nInfusão. 1 colher de chá para 200 ml de água a 95 °C. Cobrir por 10 min.\r\n\r\n**Evidência:** Moderada para urtiga em rinite alérgica (monografia EMA/HMPC; estudos clínicos pequenos com resultados positivos). Tanchagem tem indicação expectorante e anti-inflamatória na Farmacopeia Brasileira.\r\n\r\n**Advertências:** Não usar em pessoas com retenção de líquidos por insuficiência cardíaca ou renal. Urtiga pode interagir com anti-hipertensivos e diuréticos.\r\n\r\n**Fonte:** Mars (2006) — *Allergy Relief Tea* adaptado.\r\n\r\n---","ervas_referenciadas":["tansagem","alecrim","hortela-pimenta"],"schema_version":"1.0","status":"published","active":true,"created_by":null,"created_at":"2026-04-22T03:41:56.134907+00:00","updated_at":"2026-07-23T03:41:36.751107+00:00"}]$seed$::jsonb
  );
  RAISE NOTICE 'admin_blends: % linhas semeadas', 22;
END IF;
END $do$;

