DO $do$
BEGIN
IF (SELECT count(*) FROM public.admin_recommendation_vectors) > 0 THEN
  RAISE NOTICE 'admin_recommendation_vectors já populada — seed ignorado';
ELSE
  INSERT INTO public.admin_recommendation_vectors
